[3393] = {name = "Receta: poción de resistencia a la magia menor", additional_info = "Requiere Alquimia (110)\n[q2]Uso: Te enseña a hacer una poción de resistencia a la magia menor.\nPoción de resistencia a la magia menor\nNecesitas ser de nivel 12\n[q2]Uso: Aumenta tu resistencia a todos los tipos de magia 25 p. durante 3 min. (2 Min Reutilización)\nRequiere Marregal (3), Acérita salvaje , Vial vacío"},
[3394] = {name = "Receta: Elixir de resistencia al veneno", additional_info = "Requiere Alquimia (120)\n[q2]Uso: Te enseña a hacer un elixir de resistencia al veneno.\nElixir de resistencia al veneno\nNecesitas ser de nivel 14\n[q2]Uso: Quien la ingiere se curará de hasta cuatro venenos hasta el nivel 60. (3 Seg Reutilización)\nRequiere Glándula de veneno grande , Hierba cardenal , Vial emplomado"},
[3395] = {name = "[q2]Receta: poción de invulnerabilidad limitada", additional_info = "Requiere Alquimia (250)\n[q2]Uso: Te enseña a hacer una poción de invulnerabilidad limitada.\nPoción de invulnerabilidad limitada\nNecesitas ser de nivel 45\n[q2]Uso: Otorga inmunidad a los ataques físicos durante los siguientes 6 s a quien lo ingiere. (2 Min Reutilización)\nRequiere Carolina (2), Champiñón fantasma , Vial de cristal"},
[3396] = {name = "[q2]Receta: elixir de agilidad inferior", additional_info = "Requiere Alquimia (140)\n[q2]Uso: Te enseña a hacer un elixir de Agilidad inferior.\nElixir de agilidad inferior\nNecesitas ser de nivel 18\n[q2]Uso: Aumenta 8 p. la agilidad durante 1 h. (3 Seg Reutilización)\nRequiere Acérita salvaje , Cardopresto , Vial emplomado"},
