[4408] = {name = "[q2]Esquema: ardilla mecánica", additional_info = "Requiere Ingeniería (75)\n[q2]Uso: Te enseña a hacer una ardilla mecánica.\nCaja de ardilla mecánica\nSe liga al usarlo\n[q2]Uso: Crea una ardilla mecánica que te sigue adonde vayas. Haz clic con el botón derecho del ratón para invocar y retirar a tu ardilla.\nRequiere Modulador de cobre , Puñado de tornillos de cobre , Barra de cobre , Malaquita (2)"},
[4409] = {name = "[q2]Esquema: carga de seforio pequeña", additional_info = "Requiere Ingeniería (100)\n[q2]Uso: Te enseña a hacer una carga de seforio pequeña.\nRequiere Ingeniería (100)\n[q2]Uso: Hace explotar las cerraduras de puertas simples.\nRequiere Pólvora burda (2), Modulador de cobre , Cuero ligero , Agua de manantial refrescante"},
[4410] = {name = "[q2]Esquema: gafas de las Sombras", additional_info = "Requiere Ingeniería (120)\n[q2]Uso: Te enseña a hacer gafas de las Sombras.\n[q2]Gafas de las Sombras\nSe liga al equiparlo\n{Cabeza} {Tela}\n31 armadura\n+5 intelecto\n+6 espíritu\nDurabilidad 40 / 40\nRequiere Ingeniería (120)\nRequiere Cuero medio (4), Gema de las Sombras (2)"},
[4411] = {name = "[q2]Esquema: deflector de llamas", additional_info = "Requiere Ingeniería (125)\n[q2]Uso: Te enseña a hacer un deflector de llamas.\nDeflector de llamas\nNecesitas ser de nivel 15\n[q2]Uso: Amortigua 500 p. de daño de Fuego. Dura 1 min. (15 Min Reutilización)\n5 cargas\nRequiere Cacharros zumbones de bronce , Glándula de llamas pequeña"},
[4412] = {name = "[q2]Esquema: rifle de vista lunar", additional_info = "Requiere Ingeniería (145)\n[q2]Uso: Te enseña a hacer un rifle de vista lunar.\n[q2]Rifle de vista lunar\nSe liga al equiparlo\n{A distancia} {Arma de fuego}\n{14 - 26 p. de daño} {Velocidad 1.70}\n(11.76 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 24\nRequiere Tubo de bronce (3), Cacharros zumbones de bronce (3), Surtido pesado , Piedra lunar inferior (2)"},
[4413] = {name = "[q2]Esquema: rayo descombobulador", additional_info = "Requiere Ingeniería (160)\n[q2]Uso: Te enseña a hacer un rayo descombobulador.\nRayo descombobulador\n[q2]Uso: Transforma al objetivo en un Gnomo paria, reduce 40 p. su daño cuerpo a cuerpo y con hechizos, y reduce un 20% su índice de movimiento durante 12 s. (1 Min Reutilización)\n5 cargas\nRequiere Cacharros zumbones de bronce (3), Paño de seda (2), Jade , Tubo de bronce"},
[4414] = {name = "[q2]Esquema: mortero de bronce portátil", additional_info = "Requiere Ingeniería (165)\n[q2]Uso: Te enseña a hacer un mortero de bronce portátil.\nMortero de bronce portátil\nRequiere Ingeniería (165)\n[q2]Uso: Inflige 85 to 115 p. de daño de Fuego y aturde a los objetivos durante 2 s en un radio de 5 m. Cualquier daño anulará el efecto. (1 Min Reutilización)\n8 cargas\nRequiere Tubo de bronce (4), Tornapunta de hierro , Pólvora potente (4), Cuero medio (4)"},
[4415] = {name = "[q3]Esquema: monóculo de artesano", additional_info = "Requiere Ingeniería (185)\n[q2]Uso: Te enseña a hacer un monóculo de artesano.\n[q2]Monóculo de artesano\nSe liga al equiparlo\n{Cabeza} {Tela}\n40 armadura\n+15 intelecto\nDurabilidad 45 / 45\nNecesitas ser de nivel 32\nRequiere Ingeniería (185)\nRequiere Cuero pesado (6), Citrino (2)"},
[4416] = {name = "[q2]Esquema: mina terrestre goblin", additional_info = "Requiere Ingeniería (195)\n[q2]Uso: Te enseña a hacer una mina terrestre goblin.\nMina terrestre goblin\nRequiere Ingeniería (195)\n[q2]Uso: Deja la mina terrestre goblin en el suelo. Cuando una criatura hostil pase cerca de ella, la mina explotará y causará 394 to 506 p. de daño de Fuego. La mina dura 1 min. (1 Min Reutilización)\nRequiere Pólvora potente (3), Barra de hierro (2), Girocronátomo"},
[4417] = {name = "[q2]Esquema: carga de seforio grande", additional_info = "Requiere Ingeniería (200)\n[q2]Uso: Te enseña a hacer una carga de seforio grande.\nRequiere Ingeniería (200)\n[q2]Uso: Hace explotar las cerraduras de cofres bien cerrados.\nRequiere Pólvora sólida (2), Cuero pesado (2), Agua de manantial refrescante"},
