[7085] = {name = "[q2]Patrón: sobrehombros azur", additional_info = "Requiere Sastrería (190)\n[q2]Uso: Te enseña a confeccionar sobrehombros azur.\n[q2]Sobrehombros azur\nSe liga al equiparlo\n{Hombro} {Tela}\n38 armadura\n+5 aguante\nDurabilidad 45 / 45\nNecesitas ser de nivel 33\n[q2]Equipar: Aumenta hasta 13 p. el daño que infligen los hechizos y efectos de Escarcha.\nRequiere Madeja de paño de seda (6), Escama naga (2), Tinte azul (2), Hilo de seda (2)"},
[7086] = {name = "[q2]Patrón: cinturón de seda terránea", additional_info = "Requiere Sastrería (195)\n[q2]Uso: Te enseña a confeccionar un cinturón de seda terránea.\n[q2]Cinturón de seda terránea\nSe liga al equiparlo\n{Cintura} {Tela}\n29 armadura\n+8 aguante\n+8 espíritu\nDurabilidad 25 / 25\nNecesitas ser de nivel 34\nRequiere Madeja de paño de seda (5), Tierra elemental (4), Cuero pesado (4), Hebilla de hierro , Hilo de seda (2)"},
[7087] = {name = "Patrón: capa de seda carmesí", additional_info = "Requiere Sastrería (180)\n[q2]Uso: Te enseña a confeccionar una capa de seda carmesí.\n[q2]Capa de seda carmesí\nSe liga al equiparlo\nEspalda\n24 armadura\n+3 aguante\n+7 resistencia a Fuego\nNecesitas ser de nivel 31\nRequiere Madeja de paño de seda (5), Tinte rojo (2), Aceite de Fuego (2), Hilo de seda"},
[7088] = {name = "Patrón: toga de seda carmesí", additional_info = "Requiere Sastrería (205)\n[q2]Uso: Te enseña a confeccionar una toga de seda carmesí.\n[q2]Toga de seda carmesí\nSe liga al equiparlo\n{Pecho} {Tela}\n54 armadura\n+15 intelecto\n+6 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 36\nRequiere Madeja de paño de seda (8), Fuego elemental (4), Poción de maná (2), Tinte rojo (4), Hilo de seda"},
[7089] = {name = "Patrón: capa de seda azur", additional_info = "Requiere Sastrería (175)\n[q2]Uso: Te enseña a confeccionar una capa de seda azur.\n[q2]Capa de seda azur\nSe liga al equiparlo\nEspalda\n23 armadura\n+3 espíritu\nNecesitas ser de nivel 30\n[q2]Equipar: Aumenta hasta 10 p. el daño que infligen los hechizos y efectos de Escarcha.\nRequiere Madeja de paño de seda (3), Tinte azul (2), Hilo refinado (2)"},
