[9293] = {name = "[q2]Receta: poción de resistencia a la magia", additional_info = "Requiere Alquimia (210)\n[q2]Uso: Te enseña a hacer una poción de resistencia a la magia.\nPoción de resistencia a la magia\nNecesitas ser de nivel 32\n[q2]Uso: Aumenta tu resistencia a todos los tipos de magia 50 p. durante 3 min. (2 Min Reutilización)\nRequiere Mostacho de Khadgar , Loto cárdeno , Vial de cristal"},
[9294] = {name = "[q2]Receta: poción de atriplex salvaje", additional_info = "Requiere Alquimia (225)\n[q2]Uso: Te enseña a hacer una poción de atriplex salvaje.\nPoción de atriplex salvaje\nNecesitas ser de nivel 35\n[q2]Uso: Restaura 1 to 1500 p. de salud y 1 to 1500 p. de maná. (2 Min Reutilización)\nRequiere Atriplex salvaje , Loto cárdeno , Vial de cristal"},
[9295] = {name = "[q2]Receta: poción de invisibilidad", additional_info = "Requiere Alquimia (235)\n[q2]Uso: Te enseña a hacer una poción de invisibilidad.\nPoción de invisibilidad\nNecesitas ser de nivel 37\n[q2]Uso: Da a quien lo ingiere invisibilidad durante 18 s. (10 Min Reutilización)\nRequiere Champiñón fantasma , Solea , Vial de cristal"},
[9296] = {name = "[q2]Receta: ofrenda de Arthas", additional_info = "Requiere Alquimia (240)\n[q2]Uso: Te enseña a hacer una ofrenda de Arthas.\nOfrenda de Arthas\nNecesitas ser de nivel 38\n[q2]Uso: Aumenta 10 p. la resistencia a las Sombras. Si un enemigo ataca a quien la bebe, el atacante tiene una probabilidad del 30% de quedar afectado por una enfermedad que aumenta 8 p. el daño que recibe durante 3 min. Dura 30 min. (Probabilidad de que accione: 30%) (3 Seg Reutilización)\nRequiere Lágrimas de Arthas , Carolina , Vial de cristal"},
[9297] = {name = "[q2]Receta: elixir de visión onírica", additional_info = "Requiere Alquimia (240)\n[q2]Uso: Te enseña a hacer un elixir de visión onírica.\nElixir de Visión onírica\nNecesitas ser de nivel 38\n[q2]Uso: Te da una Visión onírica a través de la cual puedes explorar áreas demasiado peligrosas para explorarlas personalmente. (3 Seg Reutilización)\nRequiere Loto cárdeno (3), Vial de cristal"},
[9298] = {name = "[q2]Receta: elixir de gigantes", additional_info = "Requiere Alquimia (245)\n[q2]Uso: Te enseña a hacer un elixir de gigantes.\nElixir de gigantes\nNecesitas ser de nivel 38\n[q2]Uso: Aumenta 25 p. tu fuerza durante 1 h. (3 Seg Reutilización)\nRequiere Solea , Gromsanguina , Vial de cristal"},
[9299] = {name = "Combinación de la caja fuerte de Termochufe", additional_info = "Objeto de misión\nÚnico"},
[9300] = {name = "Receta: elixir de matanza de demonios", additional_info = "Requiere Alquimia (250)\n[q2]Uso: Te enseña a hacer un elixir de matanza de demonios.\nElixir de matanza de demonios\nNecesitas ser de nivel 40\n[q2]Uso: Aumenta 265 p. el poder de ataque contra los demonios. Dura 5 min. (3 Seg Reutilización)\nRequiere Gromsanguina , Champiñón fantasma , Vial de cristal"},
[9301] = {name = "[q2]Receta: elixir de poder de las Sombras", additional_info = "Requiere Alquimia (250)\n[q2]Uso: Te enseña a hacer un elixir de Poder de las Sombras.\nElixir de poder de las Sombras\nNecesitas ser de nivel 40\n[q2]Uso: Aumenta 40 p. el daño de las Sombras con hechizos durante 30 min. (3 Seg Reutilización)\nRequiere Champiñón fantasma (3), Vial de cristal"},
[9302] = {name = "Receta: tinte fantasmal", additional_info = "Requiere Alquimia (245)\n[q2]Uso: Te enseña a hacer tinte fantasmal.\nTinte fantasmal\nRequiere Champiñón fantasma (2), Tinte morado , Vial de cristal"},
[9303] = {name = "Receta: piedra filosofal", additional_info = "Requiere Alquimia (225)\n[q2]Uso: Te enseña a crear una Piedra filosofal.\nPiedra filosofal\nSe liga al recogerlo\n[q]\"Necesaria para la transmutación alquímica.\"\nRequiere Barra de hierro (4), Vitriolo negro , Loto cárdeno (4), Flor de fuego (4)"},
