[9372] = {name = "[q4]Sul'thraze la Azotadora", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Espada}\n{108 - 163 p. de daño} {Velocidad 2.60}\n(52.12 p. de daño por segundo)\nDurabilidad 120 / 120\nNecesitas ser de nivel 50\n[q2]Probabilidad al acertar: Golpea al enemigo con la ira de Sul'thraze. Reduce la fuerza 15 p. e inflige 90 to 210 p. de daño de las Sombras con 125 p. de daño extra durante 15 s."},
[9375] = {name = "[q3]Casco para expertos buscadores de oro", additional_info = "Se liga al equiparlo\n{Cabeza} {Cuero}\n95 armadura\n+5 agilidad\n+6 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 33\n[q2]Equipar: Hachas aumentadas +7 p."},
[9378] = {name = "[q3]Hacha de minero de Palatiro", additional_info = "Se liga al equiparlo\nÚnico\n{Una mano} {Hacha}\n{50 - 94 p. de daño} {Velocidad 2.80}\n(25.71 p. de daño por segundo)\n+6 fuerza\nDurabilidad 90 / 90\nNecesitas ser de nivel 33\n[q2]Equipar: Aumenta 10 p. el poder de ataque."},
[9379] = {name = "[q3]Sang'thraze la Deflectora", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Espada}\n{34 - 65 p. de daño} {Velocidad 1.70}\n(29.12 p. de daño por segundo)\nDurabilidad 90 / 90\nNecesitas ser de nivel 44\n[q2]Equipar: Aumenta un 1% tu probabilidad de parar un ataque."},
[9380] = {name = "[q3]Jang'thraze la Protectora", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Espada}\n{44 - 83 p. de daño} {Velocidad 1.90}\n(33.42 p. de daño por segundo)\nDurabilidad 90 / 90\nNecesitas ser de nivel 45\n[q2]Uso: Combina Jang'thraze y Sang'thraze para formar la poderosa espada Sul'thraze.\n[q2]Probabilidad al acertar: Protege al portador del daño físico absorbiendo 55 to 85 p. de daño. Dura 20 s."},
