[10714] = {name = "Azsharita cristalizada", additional_info = "Objeto de misión\n[q]\"Recién salida del horno.\""},
[10715] = {name = "Mira de Kim'jael", additional_info = "Objeto de misión\nÚnico"},
[10716] = {name = "Rayo reductor gnómico", additional_info = "Se liga al equiparlo\nAbalorio\nRequiere Ingeniería (205)\n[q2]Uso: Encoge al objetivo y reduce 250 p. su poder de ataque. O al menos eso es lo que suele hacer... (5 Min Reutilización)"},
[10717] = {name = "Brújula de Kim'jael", additional_info = "Objeto de misión\nÚnico"},
[10718] = {name = "Cachivache de Kim'jael", additional_info = "Objeto de misión\nÚnico"},
[10719] = {name = "Alarma móvil", additional_info = "Requiere Ingeniería (205)\n[q2]Uso: Invoca una oveja explosiva que carga contra un enemigo cercano y estalla infligiendo 135 to 165 p. de daño. Dura 3 minutos o hasta que estalla. (1 Min Reutilización)"},
[10720] = {name = "Proyector redomático gnómico", additional_info = "Se liga al equiparlo\nAbalorio\nRequiere Ingeniería (210)\n[q2]Uso: Captura al objetivo con una red durante 10 s. La red tiene muchos ganchos y en ocasiones se queda prendida en la ropa del que la lanza. (10 Min Reutilización)"},
[10721] = {name = "[q2]Cinturón de prevención de daño gnómico", additional_info = "Se liga al equiparlo\n{Cintura} {Cuero}\n66 armadura\n+6 aguante\nDurabilidad 30 / 30\nRequiere Ingeniería (215)\n[q2]Uso: Un escudo de fuerza te protege de los siguientes 500 p. de daño durante los próximos 10 min. ADVERTENCIA: El campo de fuerza se puede sobrecargar al recibir un golpe y desaparecer temporalmente. (Probabilidad de que accione: 5%) (1 Hora Reutilización)"},
[10722] = {name = "Pollo relleno de Kim'jael", additional_info = "Objeto de misión\nÚnico"},
[10723] = {name = "Radio gnómica", additional_info = "Abalorio"},
[10724] = {name = "[q2]Botas cohete gnómicas", additional_info = "Se liga al equiparlo\n{Pies} {Tela}\n41 armadura\nDurabilidad 35 / 35\nRequiere Ingeniería (225)\n[q2]Uso: Estas botas aumentan mucho tu velocidad de carrera durante 20 s. ADVERTENCIA: ni la fuente de alimentación ni los giros funcionan siempre como deberían. (30 Min Reutilización)"},
[10725] = {name = "Gallo de batalla gnómico", additional_info = "Se liga al recogerlo\nAbalorio\nRequiere Ingeniería (230)\n[q2]Uso: Crea un gallo de batalla que luchará por ti durante 1.50 min o hasta que lo destruyan. (30 Min Reutilización)"},
[10726] = {name = "[q2]Gorro de control mental gnómico", additional_info = "Se liga al equiparlo\n{Cabeza} {Tela}\n50 armadura\n+14 espíritu\nDurabilidad 45 / 45\nRequiere Ingeniería (215)\n[q2]Uso: Participa en un combate mental contra un objetivo humanoide para controlar su mente. Si todo sale bien, controlarás la mente del objetivo durante 20 s. (30 Min Reutilización)"},
[10727] = {name = "Escopeta dragón goblin", additional_info = "Se liga al recogerlo\nAbalorio\n[q2]Uso: Inflige 61 to 69 p. de daño de Fuego durante 10 s a todos los objetivos situados en un cono frente al ingeniero al utilizar el arma. Eso siempre y cuando no explote... (5 Min Reutilización)"},
[10728] = {name = "Patrón: camisa de espadachín negra", additional_info = "Requiere Sastrería (200)\n[q2]Uso: Te enseña a confeccionar una camisa de espadachín negra.\nCamisa de espadachín negra\nCamisa\nRequiere Madeja de paño de seda (5), Tinte negro , Hilo de seda"},
