[13506] = {name = "Frasco de petrificación", additional_info = "Necesitas ser de nivel 50\n[q2]Uso: Te conviertes en piedra y obtienes protección contra todos los ataques físicos y hechizos durante 1 min, pero no puedes atacar, moverte ni lanzar hechizos durante ese período. Solo puedes disfrutar del efecto de un frasco a la vez. (3 Seg Reutilización)"},
[13507] = {name = "Informe de Vigiarrisco Cuernolargo", additional_info = "Objeto de misión\nÚnico\n[q2]<Click derecho para leer>"},
[13508] = {name = "[q2]Ojo de Arachnida", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 55\n[q2]Uso: Invoca un Ojo de Kilrogg y vincula tu visión a él. El ojo se mueve con rapidez pero es muy frágil. (1 Min Reutilización)\n3 cargas"},
[13509] = {name = "[q2]Agarre de previsión", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 55\n[q2]Uso: Contrarresta el lanzamiento de hechizos del enemigo e impide el lanzamiento de hechizos de esa escuela de magia durante 10 s. Genera una gran amenaza. (1 Min Reutilización)"},
[13510] = {name = "Frasco de los titanes", additional_info = "Necesitas ser de nivel 50\n[q2]Uso: Aumenta 1200 p. la salud máxima del jugador durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[13511] = {name = "Frasco de sabiduría destilada", additional_info = "Necesitas ser de nivel 50\n[q2]Uso: Aumenta el maná máximo del jugador 2000 p. durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[13512] = {name = "Frasco de poder supremo", additional_info = "Necesitas ser de nivel 50\n[q2]Uso: Aumenta el daño que infligen los hechizos y efectos mágicos hasta 150 p. durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte. (3 Seg Reutilización)"},
[13513] = {name = "Frasco de resistencia cromática", additional_info = "Necesitas ser de nivel 50\n[q2]Uso: Aumenta 25 p. tu resistencia a todas las escuelas de magia durante 2 h. Solo puedes disfrutar del efecto de un frasco a la vez. El efecto persiste aun después de la muerte y se acumula con todos los demás objetos y hechizos de resistencia. (3 Seg Reutilización)"},
