[18646] = {name = "[q4]El Ojo de divinidad", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q]\"Ves movimiento si observas bien el Ojo.\"\n[q2]<Click derecho para leer>"},
[18647] = {name = "Esquema: fuegos artificiales rojos", additional_info = "Requiere Ingeniería (150)\n[q2]Uso: Te enseña a hacer fuego de artificio rojo.\nFuegos artificiales rojos\n[q2]Uso: Dispara fuegos artificiales que estallan en un millar de estrellas rojas.\nRequiere Pólvora potente , Cuero pesado"},
[18648] = {name = "Esquema: fuegos artificiales verdes", additional_info = "Requiere Ingeniería (150)\n[q2]Uso: Te enseña a hacer fuego de artificio verde.\nFuegos artificiales verdes\n[q2]Uso: Dispara fuegos artificiales que estallan en un millar de estrellas verdes.\nRequiere Pólvora potente , Cuero pesado"},
[18649] = {name = "Esquema: fuegos artificiales azules", additional_info = "Requiere Ingeniería (150)\n[q2]Uso: Te enseña a hacer fuego de artificio azul.\nFuegos artificiales azules\n[q2]Uso: Dispara fuegos artificiales que estallan en un millar de estrellas azules.\nRequiere Pólvora potente , Cuero pesado"},
[18650] = {name = "Esquema: dinamita para tontos II", additional_info = "Requiere Ingeniería (200)\n[q2]Uso: Te enseña a hacer dinamita para tontos II.\nDinamita para tontos II\nNecesitas ser de nivel 30\n[q2]Uso: Inflige 213 to 287 p. de daño de Fuego en un radio de 5 m. (Siempre que llegue al objetivo, se pueden aplicar algunas restricciones.) (1 Min Reutilización)\n[q]\"La dinamita para los que no son ingenieros que en muy pocas ocasiones* estalla en la mano y con el doble de potencia que la estándar para tontos.\"\nRequiere Pólvora sólida , Paño de tejido mágico (2)"},
[18651] = {name = "Esquema: transformador de veraplata", additional_info = "Requiere Ingeniería (260)\n[q2]Uso: Te enseña a hacer un transformador de veraplata.\nTransformador de veraplata\nRequiere Barra de veraplata (2), Tierra elemental (2), Aire elemental"},
[18652] = {name = "Esquema: reflector de hielo girohielo", additional_info = "Requiere Ingeniería (260)\n[q2]Uso: Te enseña a hacer un reflector de hielo girohielo.\n[q3]Reflector de hielo girohielo\nSe liga al equiparlo\nAbalorio\n+15 resistencia a Escarcha\nNecesitas ser de nivel 47\nRequiere Ingeniería (260)\n[q2]Uso: Devuelve los hechizos de Escarcha al taumaturgo durante 5 s. (5 Min Reutilización)\nRequiere Trasto de torio (6), Transformador de veraplata (2), Zafiro azul (2), Esencia de Fuego (4), Aceite de Escarcha (2), Setelo (4)"},
[18653] = {name = "[q2]Esquema: desfibriladores goblin XL", additional_info = "Requiere Ingeniería (265)\nRequiereIngeniero goblin\n[q2]Uso: Te enseña a hacer un desfibrilador goblin XL.\nDesfibriladores goblin XL\nAbalorio\nRequiere Ingeniería (265)\n[q2]Uso: A veces los desfibriladores podrán devolver a un jugador muerto a la vida. No se pueden usar en combate. (30 Min Reutilización)\nRequiere Trasto de torio (2), Transformador de veraplata (2), Cableado de fusibles (2), Seda de araña Tejehierro (2), Rubí estrella (2)"},
[18654] = {name = "[q2]Esquema: roboalarma gnómico", additional_info = "Requiere Ingeniería (265)\nRequiereIngeniero gnómico\n[q2]Uso: Te enseña a hacer un Roboalarma.\nRoboalarma gnómico\nRequiere Ingeniería (265)\n[q2]Uso: Invoca una Roboalarma durante 10 minutos que emite un pulso regularmente para detectar a los enemigos sigilosos o invisibles cercanos. (10 Min Reutilización)\nRequiere Barra de torio (4), Trasto de torio (2), Cuero basto (4), Rubí estrella , Cableado de fusibles"},
[18655] = {name = "[q2]Esquema: recombobulador sublime", additional_info = "Requiere Ingeniería (275)\n[q2]Uso: Te enseña a hacer un recombobulador sublime.\n[q2]Recombobulador sublime\nAbalorio\nRequiere Ingeniería (275)\n[q2]Uso: Elimina los efectos de polimorfia de un objetivo aliado. También restaura 375 to 625 p. de salud y maná. (5 Min Reutilización)\n10 cargas\nRequiere Tubo de torio (2), Transformador de veraplata , Paño rúnico (2)"},
[18656] = {name = "Esquema: carga de seforio potente", additional_info = "Requiere Ingeniería (275)\n[q2]Uso: Te enseña a hacer una carga de seforio potente.\nRequiere Ingeniería (275)\n[q2]Uso: Hace explotar la cerradura de casi cualquier puerta cerrada.\nRequiere Trasto de torio (2), Pólvora densa (3), Cuero basto (2), Agua de manantial refrescante"},
[18657] = {name = "[q2]Esquema: reflector de llamas hiperradiante", additional_info = "Requiere Ingeniería (290)\n[q2]Uso: Te enseña a hacer un reflector de llamas hiperradiante.\n[q3]Reflector de llamas hiperradiante\nSe liga al equiparlo\nAbalorio\n+18 resistencia a Fuego\nNecesitas ser de nivel 53\nRequiere Ingeniería (290)\n[q2]Uso: Devuelve los hechizos de Fuego al taumaturgo durante 5 s. (5 Min Reutilización)\nRequiere Barra de hierro negro (4), Transformador de veraplata (3), Esencia de agua (6), Rubí estrella (4), Diamante de Azeroth (2)"},
[18658] = {name = "[q2]Esquema: reflector de las Sombras ultradeslumbrante", additional_info = "Requiere Ingeniería (300)\n[q2]Uso: Te enseña a hacer un Reflector de las Sombras ultradeslumbrante.\n[q3]Reflector de las Sombras ultradeslumbrante\nSe liga al equiparlo\nAbalorio\n+20 resistencia a Sombras\nNecesitas ser de nivel 55\nRequiere Ingeniería (300)\n[q2]Uso: Devuelve los hechizos de las Sombras al taumaturgo durante 5 s. (5 Min Reutilización)\nRequiere Barra de hierro negro (8), Transformador de veraplata (4), Esencia viva (6), Esencia de no-muerto (4), Diamante de Azeroth (2), Ópalo grande (2)"},
