[19212] = {name = "Diseño: Ocaso", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereMaestro forjador de hachas\n[q2]Uso: Te enseña a hacer Ocaso.\n[q4]Ocaso\nSe liga al equiparlo\n{Dos manos} {Hacha}\n{187 - 282 p. de daño} {Velocidad 3.50}\n(67.00 p. de daño por segundo)\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: El daño con hechizos que recibe el objetivo aumenta un 15% durante 5 s.\nRequiere Núcleo de lava (8), Núcleo ígneo (5), Barra de arcanita (10), Barra de hierro negro (12), Esmeralda enorme (4)"},
[19213] = {name = "[q2]Dije de mérito Ala de Plata", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q]\"Prueba de victoria en la Garganta Grito de Guerra.\""},
[19214] = {name = "[q0]Monster - Staff, Wooden Handle Spiral Head Dark", additional_info = "{Dos manos} {Bastón}\n{2 - 4 p. de daño} {Velocidad 3.40}\n(0.88 p. de daño por segundo)\nDurabilidad 20 / 20"},
[19215] = {name = "Patrón: sabiduría de los Fauces de Madera", additional_info = "Se liga al recogerlo\nRequiere Sastrería (290)\nRequiereBastión Fauces de Madera\n: Honorable\n[q2]Uso: Te enseña a confeccionar Sabiduría de los Fauces de Madera.\n[q3]Sabiduría de los Fauces de Madera\nSe liga al equiparlo\n{Cintura} {Tela}\n46 armadura\n+21 intelecto\nDurabilidad 30 / 30\nNecesitas ser de nivel 53\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\nRequiere Madeja de paño rúnico (8), Esencia de tierra (3), Esencia viva (3), Seda de araña Tejehierro (2)"},
[19216] = {name = "Patrón: botas Argenta", additional_info = "Se liga al recogerlo\nRequiere Sastrería (290)\nRequiereEl Alba Argenta\n: Honorable\n[q2]Uso: Te enseña a confeccionar botas Argenta.\n[q3]Botas Argenta\nSe liga al equiparlo\n{Pies} {Tela}\n57 armadura\n+21 aguante\n+7 espíritu\n+4 resistencia a Sombras\nDurabilidad 40 / 40\nNecesitas ser de nivel 53\nRequiere Madeja de paño rúnico (6), Cuero encantado (4), Perla de oro (2), Piedra guardián (2), Seda de araña Tejehierro (2)"},
[19217] = {name = "Patrón: sobrehombros Argenta", additional_info = "Se liga al recogerlo\nRequiere Sastrería (300)\nRequiereEl Alba Argenta\n: Reverenciado\n[q2]Uso: Te enseña a confeccionar sobrehombros Argenta.\n[q3]Sobrehombros Argenta\nSe liga al equiparlo\n{Hombro} {Tela}\n68 armadura\n+23 aguante\n+8 espíritu\n+5 resistencia a Sombras\nDurabilidad 50 / 50\nNecesitas ser de nivel 59\nRequiere Tela lunar (5), Piedra guardián (2), Seda de araña Tejehierro (2)"},
[19218] = {name = "Patrón: manto de los Fauces de Madera", additional_info = "Se liga al recogerlo\nRequiere Sastrería (300)\nRequiereBastión Fauces de Madera\n: Reverenciado\n[q2]Uso: Te enseña a confeccionar un manto de los Fauces de Madera.\n[q3]Manto de los Fauces de Madera\nSe liga al equiparlo\n{Hombro} {Tela}\n68 armadura\n+21 intelecto\nDurabilidad 50 / 50\nNecesitas ser de nivel 59\n[q2]Equipar: Restaura 6 p. de maná cada 5 s.\nRequiere Tela lunar (5), Esencia de tierra (5), Esencia viva (5), Seda de araña Tejehierro (2)"},
[19219] = {name = "Patrón: toga Bengala del Núcleo", additional_info = "Se liga al recogerlo\nRequiere Sastrería (300)\n[q2]Uso: Te enseña a confeccionar una toga Bengala del Núcleo.\n[q4]Toga Bengala del Núcleo\nSe liga al equiparlo\n{Pecho} {Tela}\n102 armadura\n+35 aguante\n+15 resistencia a Fuego\nDurabilidad 100 / 100\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 23 p. el daño y la sanación de los hechizos y efectos mágicos.\nRequiere Tela lunar (10), Núcleo ígneo (2), Núcleo de lava (3), Esencia de Fuego (6), Seda de araña Tejehierro (4)"},
[19220] = {name = "Patrón: leotardos Bengala del Núcleo", additional_info = "Se liga al recogerlo\nRequiere Sastrería (300)\n[q2]Uso: Te enseña a confeccionar leotardos Bengala del Núcleo.\n[q4]Leotardos Bengala del Núcleo\nSe liga al equiparlo\n{Piernas} {Tela}\n94 armadura\n+21 aguante\n+16 resistencia a Fuego\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 43 p. el daño y la sanación de los hechizos y efectos mágicos.\nRequiere Tela lunar (8), Núcleo ígneo (5), Núcleo de lava (3), Esencia de Fuego (10), Seda de araña Tejehierro (4)"},
