[19782] = {name = "[q3]Presencia de poderío", additional_info = "Se liga al recogerlo\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 10 p. de aguante, 7 p. de defensa y 15 p. de valor de bloqueo de escudo a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19783] = {name = "[q3]Sigilo de Sincretista", additional_info = "Se liga al recogerlo\nClases: Paladín\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 10 p. de aguante y 7 p. de defensa, y le aumenta hasta 24 p. la sanación a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19784] = {name = "[q3]Abrazo de la Muerte", additional_info = "Se liga al recogerlo\nClases: Pícaro\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 28 p. de poder de ataque y un 1% de posibilidad de esquivar a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19785] = {name = "[q3]Llamada del falcón", additional_info = "Se liga al recogerlo\nClases: Cazador\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 24 p. de poder de ataque a distancia, 10 p. de aguante y un 1% de probabilidad de golpear a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19786] = {name = "[q3]Abrazo del vigilante de Vodouisant", additional_info = "Se liga al recogerlo\nClases: Chamán\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 15 p. de intelecto y le aumenta hasta 13 p. la sanación y el daño con hechizos a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19787] = {name = "[q3]Presencia de Vista", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 18 p. a todos los hechizos de sanación y daño y un 1% de probabilidad de golpear con hechizos a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19788] = {name = "[q3]Maleficio hudú", additional_info = "Se liga al recogerlo\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 10 p. de aguante y le aumenta hasta 18 p. el daño y la sanación con hechizos a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19789] = {name = "[q3]Aura profética", additional_info = "Se liga al recogerlo\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 10 p. de aguante y 4 p. de maná cada 5 s, y le aumenta hasta 24 p. la sanación a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
[19790] = {name = "[q3]Caricia del animista", additional_info = "Se liga al recogerlo\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Uso: Añade de forma permanente 10 p. de aguante y 10 p. de intelecto, y le aumenta hasta 24 p. la sanación a un objeto de la casilla para pierna o cabeza. No se suma a otros encantamientos de la casilla de equipamiento seleccionada."},
