[19955] = {name = "[q4]Talismán de naturaleza de Wushoolay", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Uso: Reduce un 40% el tiempo de lanzamiento de tus hechizos de Toque de sanación y reduce un 5% el costo de maná de tus hechizos de sanación durante 15 s. (3 Min Reutilización)\n\n[q]Atuendo de Haruspex (0/5)\n[q0]Alga de los Mares del Sur encantada prístina\nTalismán de naturaleza de Wushoolay\nBrazales de haruspex Zandalar\nCinturón de haruspex Zandalar\nGuerrera de haruspex Zandalar\n[q0](2) Conjunto : Restaura 4 p. de maná cada 5 s.\n(3) Conjunto : Aumenta 5 s la duración de Fuego feérico.\n(5) Conjunto : Aumenta un 3% la probabilidad de golpe crítico de tu hechizo Fuego estelar."},
[19956] = {name = "[q4]Talismán de espíritus de Wushoolay", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Chamán\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 100% el daño que inflige tu hechizo Escudo de relámpagos durante 20 s. (3 Min Reutilización)\n\n[q]Atavío de Augur (0/5)\n[q0]Visión inmaculada de Voodress\nTalismán de espíritus de Wushoolay\nBrazales de augur Zandalar\nCinturón de augur Zandalar\nCamisote de augur Zandalar\n[q0](2) Conjunto : Restaura 4 p. de maná cada 5 s.\n(3) Conjunto : Mejora la duración de tu hechizo de choque de Escarcha 1 s.\n(5) Conjunto : Aumenta el alcance de tu hechizo de Descarga de relámpagos 5 m."},
[19957] = {name = "[q4]Talismán de destrucción de Hazza'rah", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 10% la probabilidad de golpe crítico de tus hechizos de Destrucción durante 20 s. (3 Min Reutilización)\n\n[q]Vestuario demoníaco (0/5)\n[q0]Mancha imparable de Kezan\nTalismán de destrucción de Hazza'rah\nBrazaletes de endemoniado Zandalar\nManto de endemoniado Zandalar\nToga de endemoniado Zandalar\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Aumenta un 2% el daño de corrupción.\n(5) Conjunto : Reduce el tiempo de reutilización de Espiral mortal un 15%."},
[19958] = {name = "[q4]Talismán de sanación de Hazza'rah", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q2]Uso: Reduce un 40% el tiempo de lanzamiento de tus hechizos de Sanación superior y reduce un 5% el costo de maná de tus hechizos de sanación durante 15 s. (3 Min Reutilización)\n\n[q]Vestiduras de confesor (0/5)\n[q0]El Ojo que todo lo ve de Zuldazar\nTalismán de sanación de Hazza'rah\nBrazaletes de confesor Zandalar\nAtaduras de confesor Zandalar\nManto de confesor Zandalar\n[q0](2) Conjunto : Aumenta hasta 22 p. la sanación de los hechizos y efectos.\n(3) Conjunto : Aumenta el alcance de tus hechizos Fuego Sagrado y Punición 5 m.\n(5) Conjunto : Reduce el tiempo de lanzamiento de tu hechizo Control mental 0.5 s."},
[19959] = {name = "[q4]Talismán de magia de Hazza'rah", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Mago\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 5% la probabilidad de golpe crítico de tus hechizos Arcanos, y un 50% el daño de golpe crítico de tus hechizos Arcanos durante 20 s. (3 Min Reutilización)\n\n[q]Ropajes del Ilusionista (0/5)\n[q0]Joya de Kajaro\nTalismán de magia de Hazza'rah\nBrazaletes de ilusionista Zandalar\nManto de ilusionista Zandalar\nToga de ilusionista Zandalar\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Reduce el coste de maná de Intelecto Arcano y Luminosidad Arcana un 5%.\n(5) Conjunto : Reduce el tiempo de lanzamiento de tu hechizo Fogonazo 0.5 s."},
