[20011] = {name = "Receta: Poción de sangre de mago", additional_info = "Se liga al recogerlo\nRequiere Alquimia (275)\nRequiereTribu Zandalar\n: Reverenciado\n[q2]Uso: Te enseña a hacer una poción de sangre de mago.\nPoción de sangre de mago\nNecesitas ser de nivel 40\n[q2]Uso: Regenera 12 p. de maná cada 5 s durante 1 h. (3 Seg Reutilización)\nRequiere Hojasueño , Flor de plaga (2), Vial de cristal"},
[20012] = {name = "Receta: Letargo sin sueños superior", additional_info = "Se liga al recogerlo\nRequiere Alquimia (275)\nRequiereTribu Zandalar\n: Amistoso\n[q2]Uso: Te enseña a hacer una poción de letargo sin sueños superior.\nPoción de letargo sin sueños superior\nNecesitas ser de nivel 55\n[q2]Uso: Quien lo bebe entra en un letargo sin sueños durante 12 s. Durante ese tiempo, se sana 2100 p. de salud y 2100 p. de maná. (2 Min Reutilización)\nRequiere Hojasueño (2), Sansam dorado , Vial de cristal"},
[20013] = {name = "Receta: poción de acción viva", additional_info = "Se liga al recogerlo\nRequiere Alquimia (285)\nRequiereTribu Zandalar\n: Exaltado\n[q2]Uso: Te enseña a hacer una poción de acción viva.\nPoción de acción viva\nNecesitas ser de nivel 47\n[q2]Uso: Te vuelve inmune a los efectos de aturdimiento y de reducción de movimiento durante los próximos 5 s. También elimina los efectos de aturdimiento y reducción del movimiento existentes. (2 Min Reutilización)\nRequiere Setelo (2), Salviargenta de montaña (2), Corazón de fiera (2), Vial de cristal"},
