[20033] = {name = "[q0]Toga de endemoniado Zandalar", additional_info = "Se liga al recogerlo\n{Pecho} {Tela}\n100 armadura\n+35 aguante\nDurabilidad 100 / 100\nClases: Brujo\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con hechizos.\n[q2]Equipar: Aumenta hasta 27 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Vestuario demoníaco (0/5)\n[q0]Mancha imparable de Kezan\nTalismán de destrucción de Hazza'rah\nBrazaletes de endemoniado Zandalar\nManto de endemoniado Zandalar\nToga de endemoniado Zandalar\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Aumenta un 2% el daño de corrupción.\n(5) Conjunto : Reduce el tiempo de reutilización de Espiral mortal un 15%."},
[20034] = {name = "[q0]Toga de ilusionista Zandalar", additional_info = "Se liga al recogerlo\n{Pecho} {Tela}\n100 armadura\n+23 aguante\n+24 intelecto\nDurabilidad 100 / 100\nClases: Mago\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con hechizos.\n[q2]Equipar: Aumenta hasta 27 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Ropajes del Ilusionista (0/5)\n[q0]Joya de Kajaro\nTalismán de magia de Hazza'rah\nBrazaletes de ilusionista Zandalar\nManto de ilusionista Zandalar\nToga de ilusionista Zandalar\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Reduce el coste de maná de Intelecto Arcano y Luminosidad Arcana un 5%.\n(5) Conjunto : Reduce el tiempo de lanzamiento de tu hechizo Fogonazo 0.5 s."},
[20035] = {name = "[q3]Punta glacial", additional_info = "Se liga al recogerlo\n{Una mano} {Daga}\n{31 - 59 p. de daño} {Velocidad 1.30}\n(34.62 p. de daño por segundo)\n+4 intelecto\nDurabilidad 65 / 65\n[q2]Equipar: Tus hechizos Descarga de Escarcha tienen un 6% de probabilidad de restaurar 50 p. de maná al lanzarlos.\n[q]\"Runas diabólicas adornan la espada.\""},
[20036] = {name = "[q3]Rubí de fuego", additional_info = "Se liga al recogerlo\nAbalorio\n[q2]Uso: Restaura 1 to 500 p. de maná y aumenta hasta 100 p. el daño de tu siguiente hechizo de Fuego. El efecto dura 1 min. (3 Min Reutilización)\n[q]\"Lo imprevisible lleva tanto a la victoria como a la muerte.\""},
[20037] = {name = "[q3]Colgante de cristal Arcano", additional_info = "Se liga al recogerlo\nCuello\n+6 intelecto\n[q2]Equipar: Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q]\"Los cristales Arcanos son muy útiles para los propósitos de los magos.\""},
