[20073] = {name = "[q4]Capa de guardia de honor", additional_info = "Se liga al recogerlo\nEspalda\n50 armadura\n+5 agilidad\n+11 aguante\nNecesitas ser de nivel 60\nRequiereLiga de Arathor\n: Exaltado\n[q2]Equipar: Aumenta 34 p. el poder de ataque."},
[20074] = {name = "Estofado de crocolisco pesado", additional_info = "Necesitas ser de nivel 20\n[q2]Uso: Restaura 874.8 p. de salud durante 27 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 8 p. de aguante y espíritu durante 15 min."},
[20075] = {name = "Receta: estofado de crocolisco pesado", additional_info = "Requiere Cocina (150)\n[q2]Uso: Te enseña a hacer estofado de crocolisco pesado.\nEstofado de crocolisco pesado\nNecesitas ser de nivel 20\n[q2]Uso: Restaura 874.8 p. de salud durante 27 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 8 p. de aguante y espíritu durante 15 min.\nRequiere Carne de crocolisco tierna (2), Especias calmantes"},
[20076] = {name = "[q3]Sello Zandalar de mojo", additional_info = "Se liga al recogerlo\n[q2]Uso: Añade de forma permanente daño y hasta 18 p. de daño y sanación de hechizos y efectos mágicos a un objeto de la casilla de hombros."},
[20077] = {name = "[q3]Sello Zandalar de poderío", additional_info = "Se liga al recogerlo\n[q2]Uso: Añade de forma permanente 30 p. de poder de ataque a un objeto de la casilla de hombros."},
[20078] = {name = "[q3]Sello Zandalar de serenidad", additional_info = "Se liga al recogerlo\n[q2]Uso: Añade de forma permanente hasta 33 p. de sanación de hechizos y efectos a un objeto de la casilla de hombros."},
[20079] = {name = "[q2]Espíritu de Zanza", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 55\n[q2]Uso: Aumenta 50 p. el espíritu del jugador y 50 p. su aguante durante 2 h. Solo puedes beneficiarte del efecto de una poción de Zanza a la vez. (3 Seg Reutilización)\n[q]\"¡Bendecido con el mojo de Zanza!\""},
[20080] = {name = "[q2]Brillo de Zanza", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 55\n[q2]Uso: Aumenta un 3% la probabilidad de que el jugador rechace hechizos hostiles durante 2 h. Rechazará automáticamente el primer hechizo ofensivo lanzado contra el usuario. Solo puede haber 1 poción de Zanza activa a la vez. (2 Min Reutilización)\n[q]\"¡Bendecido con el mojo de Zanza!\""},
[20081] = {name = "[q2]Presteza de Zanza", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 55\n[q2]Uso: Aumenta un 20% la velocidad de carrera del jugador durante 2 h. Solo puedes beneficiarte del efecto de una poción de Zanza a la vez. (3 Seg Reutilización)\n[q]\"¡Bendecido con el mojo de Zanza!\""},
