[22191] = {name = "[q4]Guerrera de malla de obsidiana", additional_info = "Se liga al equiparlo\n{Pecho} {Malla}\n458 armadura\nDurabilidad 140 / 140\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 76 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: Se reduce el daño con hechizos recibido 10 p."},
[22192] = {name = "Elixir de esquivez de alga de sangre", additional_info = "Se liga al recogerlo\n[q2]Uso: Aumenta la probabilidad de esquivar un 3% durante 30 min."},
[22193] = {name = "Elixir de resistencia de alga de sangre", additional_info = "Se liga al recogerlo\n[q2]Uso: Aumenta todas las resistencias mágicas 15 p. durante 30 min."},
[22194] = {name = "[q4]Garra negra del Destructor", additional_info = "Se liga al equiparlo\n{Manos} {Malla}\n279 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 28 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 8 p. de maná y, si es posible, absorbes 8 p. de maná del objetivo."},
[22195] = {name = "[q3]Cinturón de obsidiana ligero", additional_info = "Se liga al equiparlo\n{Cintura} {Malla}\n224 armadura\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 32 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: +5 p. todas las resistencias."},
[22196] = {name = "[q4]Coraza gruesa de obsidiana", additional_info = "Se liga al equiparlo\n{Pecho} {Placas}\n814 armadura\n+38 fuerza\n+16 aguante\nDurabilidad 165 / 165\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando te golpea un hechizo de daño tienes un 30% de probabilidad de obtener un escudo contra hechizos 6 s que absorbe 300 to 500 p. de daño de esa escuela. (Probabilidad de que accione: 30%, 10s de reutilización)"},
[22197] = {name = "[q3]Cinturón de obsidiana pesado", additional_info = "Se liga al equiparlo\n{Cintura} {Placas}\n397 armadura\n+25 fuerza\nDurabilidad 45 / 45\nNecesitas ser de nivel 60\n[q2]Equipar: +5 p. todas las resistencias."},
[22198] = {name = "[q4]Escudo dentado de obsidiana", additional_info = "Se liga al equiparlo\n{Mano izquierda} {Escudo}\n2645 armadura\n48 bloqueo\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: +5 p. todas las resistencias.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 5% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 5%, 20s de reutilización)"},
[22199] = {name = "[q0]Monster - Axe, 2H Arcanite Reaper", additional_info = "{Dos manos} {Hacha}\n{2 - 4 p. de daño} {Velocidad 3.30}\n(0.91 p. de daño por segundo)\nDurabilidad 20 / 20"},
