[22206] = {name = "[q2]Ramo de rosas rojas", additional_info = "Se liga al recogerlo\nÚnico\nSostener con la mano izquierda\n[q2]Uso: ¡Cubre a un objetivo cercano con una cascada de pétalos de rosa! (5 Min Reutilización)"},
[22207] = {name = "[q3]Fajín del Gran cazador", additional_info = "Se liga al recogerlo\n{Cintura} {Malla}\n199 armadura\n+15 agilidad\n+14 aguante\n+6 intelecto\nDurabilidad 40 / 40\nNecesitas ser de nivel 55\n[q2]Equipar: Arcos aumentados +2 p.\n[q2]Equipar: Armas de fuego aumentadas +2 p.\n[q2]Equipar: Ballestas aumentadas +2 p."},
[22208] = {name = "[q3]Martillo de piedra de lava", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{135 - 203 p. de daño} {Velocidad 3.40}\n(49.71 p. de daño por segundo)\n+10 fuerza\n+14 aguante\n+12 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 53\n[q2]Equipar: Aumenta hasta 20 p. el daño y la sanación de los hechizos y efectos mágicos."},
[22209] = {name = "Diseño: cinturón de obsidiana pesado", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereCírculo Cenarion\n: Amistoso\n[q2]Uso: Te enseña a hacer un cinturón de obsidiana pesado.\n[q3]Cinturón de obsidiana pesado\nSe liga al equiparlo\n{Cintura} {Placas}\n397 armadura\n+25 fuerza\nDurabilidad 45 / 45\nNecesitas ser de nivel 60\n[q2]Equipar: +5 p. todas las resistencias.\nRequiere Fragmento de obsidiana pequeño (14), Barra de torio encantado (4), Esencia de tierra (2)"},
[22210] = {name = "[q0]Monster - Knuckle, B01 Red", additional_info = "{Una mano} {Arma de puño}\n{1 p. de daño} {Velocidad 1.50}\n(0.67 p. de daño por segundo)\nDurabilidad 16 / 16"},
[22211] = {name = "[q0]Monster - Knuckle, B01 Red Offhand", additional_info = "{Mano izquierda} {Arma de puño}\n{1 p. de daño} {Velocidad 1.50}\n(0.67 p. de daño por segundo)\nDurabilidad 16 / 16"},
[22212] = {name = "[q3]Espaldares a medida gólem", additional_info = "Se liga al recogerlo\n{Hombro} {Malla}\n250 armadura\n+13 agilidad\n+17 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 51"},
[22213] = {name = "[q0]Monster - Mace, Hand of Edward the Odd", additional_info = "{Una mano} {Maza}\n{1 - 2 p. de daño} {Velocidad 2.00}\n(0.75 p. de daño por segundo)\nDurabilidad 20 / 20"},
[22214] = {name = "Diseño: cinturón de obsidiana ligero", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereCírculo Cenarion\n: Honorable\n[q2]Uso: Te enseña a hacer un cinturón de obsidiana ligero.\n[q3]Cinturón de obsidiana ligero\nSe liga al equiparlo\n{Cintura} {Malla}\n224 armadura\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 32 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: +5 p. todas las resistencias.\nRequiere Fragmento de obsidiana pequeño (14), Cuero encantado (4)"},
[22215] = {name = "[q0]Monster - Dagger, Bonescraper", additional_info = "{Una mano} {Daga}\n{1 p. de daño} {Velocidad 1.50}\n(0.67 p. de daño por segundo)\nDurabilidad 16 / 16"},
[22216] = {name = "Glándula de veneno de Venoxis", additional_info = "Objeto de misión"},
[22217] = {name = "Glándula de veneno de Kurinnaxx", additional_info = "Objeto de misión"},
[22218] = {name = "Puñado de pétalos de rosa", additional_info = "Duración: 10 días\n[q2]Uso: ¡Cubre a un objetivo cercano con una cascada de pétalos de rosa! (30 Seg Reutilización)"},
[22219] = {name = "Diseño: escudo dentado de obsidiana", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereCírculo Cenarion\n: Reverenciado\n[q2]Uso: Te enseña a hacer un escudo dentado de obsidiana.\n[q4]Escudo dentado de obsidiana\nSe liga al equiparlo\n{Mano izquierda} {Escudo}\n2645 armadura\n48 bloqueo\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: +5 p. todas las resistencias.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 5% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 5%, 20s de reutilización)\nRequiere Fragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Barra de torio encantado (8), Esencia de tierra (4)"},
[22220] = {name = "[q3]Diseño: Garra negra del Destructor", additional_info = "Requiere Herrería (300)\n[q2]Uso: Te enseña a hacer una Garra negra del Destructor.\n[q4]Garra negra del Destructor\nSe liga al equiparlo\n{Manos} {Malla}\n279 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 28 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 8 p. de maná y, si es posible, absorbes 8 p. de maná del objetivo.\nRequiere Fragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Cuero encantado (8), Frasco de poder supremo"},
[22221] = {name = "Diseño: guerrera de malla de obsidiana", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereCírculo Cenarion\n: Exaltado\n[q2]Uso: Te enseña a hacer una guerrera de malla de obsidiana.\n[q4]Guerrera de malla de obsidiana\nSe liga al equiparlo\n{Pecho} {Malla}\n458 armadura\nDurabilidad 140 / 140\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 76 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: Se reduce el daño con hechizos recibido 10 p.\nRequiere Fragmento de obsidiana grande (15), Fragmento de obsidiana pequeño (36), Cuero encantado (12), Piedra guardián (10), Diamante de Azeroth (4)"},
[22222] = {name = "[q3]Diseño: coraza gruesa de obsidiana", additional_info = "Requiere Herrería (300)\n[q2]Uso: Te enseña a hacer una coraza gruesa de obsidiana.\n[q4]Coraza gruesa de obsidiana\nSe liga al equiparlo\n{Pecho} {Placas}\n814 armadura\n+38 fuerza\n+16 aguante\nDurabilidad 165 / 165\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando te golpea un hechizo de daño tienes un 30% de probabilidad de obtener un escudo contra hechizos 6 s que absorbe 300 to 500 p. de daño de esa escuela. (Probabilidad de que accione: 30%, 10s de reutilización)\nRequiere Fragmento de obsidiana grande (18), Fragmento de obsidiana pequeño (40), Barra de torio encantado (12), Esencia de tierra (10), Esmeralda enorme (4)"},
[22223] = {name = "[q3]Protector de cabeza de supervisor", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n469 armadura\n+15 fuerza\n+14 aguante\n+11 intelecto\nDurabilidad 80 / 80\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 13 p. el daño y la sanación de los hechizos y efectos mágicos."},
[22224] = {name = "Esencia de espectro bufón", additional_info = "Objeto de misión"},
[22225] = {name = "[q3]Capucha de piel de dragón", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n69 armadura\n<Encantamiento aleatorio>\n+12 aguante\n+15 intelecto\nDurabilidad 50 / 50\nNecesitas ser de nivel 55\n[q2]Equipar: Aumenta hasta 18 p. el daño y la sanación de los hechizos y efectos mágicos."},
[22226] = {name = "Restos druidas", additional_info = "Objeto de misión\n[q]\"Los silítidos han dejado poco del cadáver de este campeón del Círculo Cenarion.\""},
[22227] = {name = "Reliquia de Aldea Brisaestelar", additional_info = "Objeto de misión\n[q]\"Los gigantes Machacahielo congelaron esta antigüedad de los elfos de la noche. Ten cuidado con ella.\""},
[22228] = {name = "Espada luminosa de zelote", additional_info = "Objeto de misión\n[q]\"El filo más cortante, creado para abrirse camino a través de cualquier enemigo, vivo o muerto.\""},
