[22630] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{130 - 243 p. de daño} {Velocidad 2.90}\n(64.31 p. de daño por segundo)\n+30 aguante\n+29 intelecto\nDurabilidad 145 / 145\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora tu probabilidad de asestar un golpe crítico con hechizos un 2%.\n[q2]Equipar: Aumenta hasta 150 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Aumenta hasta 33 p. el daño y la sanación realizados con hechizos y efectos mágicos sobre los miembros de grupo en un radio de 30 m.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
[22631] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{130 - 243 p. de daño} {Velocidad 2.90}\n(64.31 p. de daño por segundo)\n+28 aguante\n+28 intelecto\n+27 espíritu\nDurabilidad 145 / 145\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 62 p. la sanación realizada con hechizos y efectos mágicos sobre los miembros de grupo en un radio de 30 m.\n[q2]Equipar: Aumenta hasta 120 p. tu daño con hechizos y hasta 300 p. tu sanación.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
[22632] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{130 - 243 p. de daño} {Velocidad 2.90}\n(64.31 p. de daño por segundo)\n+28 aguante\n+28 intelecto\n+27 espíritu\nDurabilidad 145 / 145\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Equipar: Restaura 11 p. de maná cada 5 s a todos los miembros del grupo en un radio de 30 m.\n[q2]Equipar: Aumenta hasta 300 p. la sanación de los hechizos y efectos.\n[q2]Equipar: +420 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
