[172070] = {name = "Botiquín de atención al cliente", additional_info = "Se liga al recogerlo\n[q]\"Contiene objetos para tu clase y nivel. Requiere 15 ranuras de inventario vacías.\""},
[180089] = {name = "Collera de panda", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Haz clic derecho para invocar y retirar a tu osito panda."},
[184937] = {name = "Desplazador de cronobeneficios", additional_info = "[q2]Uso: Altera el tejido del tiempo y suspende tus efectos de mundo beneficiosos de cazadragones, La Masacre, Zul'Gurub y Frondavil. (1 Hora Reutilización)"},
[184938] = {name = "[q2]Desplazador de cronobeneficios supercargado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Restaura tus efectos de mundo suspendidos."},
[189419] = {name = "Fire Resist Plate Gear", additional_info = "[q2]<Click derecho para abrir>"},
[189420] = {name = "Fire Resist Plate Gear", additional_info = "[q2]<Click derecho para abrir>"},
[189421] = {name = "Fire Resist Leather Gear", additional_info = "[q2]<Click derecho para abrir>"},
[189426] = {name = "Raid Consumables", additional_info = "[q2]<Click derecho para abrir>"},
