[190179] = {name = "Corazón de Avelina", additional_info = "Objeto de misión\nÚnico"},
[190180] = {name = "Corazón de Isaac", additional_info = "Objeto de misión\nÚnico"},
[190181] = {name = "Corazón de los amantes", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Invoca a un íncubo utilizando el Círculo de Invocación. (3 Min Reutilización)"},
[190186] = {name = "Figurilla de madera", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Invoca a un íncubo utilizando el Círculo de Invocación. (3 Min Reutilización)\n[q]\"Una inscripción en la base dice: “Estoy en casa”.\""},
[190187] = {name = "Bufanda desgastada", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Invoca a un íncubo utilizando el Círculo de Invocación. (3 Min Reutilización)\n[q]\"Hay unos diseños delicados bordados en la tela, junto con la inscripción \"M+K\".\""},
[190232] = {name = "Bufanda desgastada", additional_info = "Objeto de misión\nÚnico\n[q]\"Hay unos diseños delicados bordados en la tela, junto con la inscripción \"M+K\".\""},
[190307] = {name = "Antorcha apagada", additional_info = "Objeto mágico\nObjeto de misión\nÚnico\n[q]\"¿Sabes lo que quedaría muy bien en esta antorcha? Fuego.\""},
[190308] = {name = "Antorcha ardiente", additional_info = "Objeto mágico\nObjeto de misión\nÚnico\nDuración: 5 min\n[q2]Uso: Lanza una antorcha a la ubicación objetivo y enciende un fuego.\n[q]\"¡Útil para distracciones ardientes!\""},
[190309] = {name = "Figurilla de madera", additional_info = "Objeto de misión\nÚnico\n[q]\"Una inscripción en la base dice: “Estoy en casa”.\""},
[190325] = {name = "[q0]Monster - Incubus Whip Mace1H", additional_info = "{Una mano} {Maza}"},
[191204] = {name = "[q2]Piedra de muerte inferior", additional_info = "Se liga al recogerlo\n[q2]Uso: Convierte 100 piedras de muerte inferiores en una superior."},
[191249] = {name = "[q2]Piedra de muerte superior", additional_info = "Se liga al recogerlo\n[q]\"Una piedra verde radiante que brilla con energías inenarrables.\""},
[191267] = {name = "[q2]Runa de teletransporte: Antecámara", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Te transporta a la Antecámara de Naxxramas."},
[191268] = {name = "[q2]Orbe de corrupción", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Aplasta el orbe, lo que aumenta un 50% la cantidad de piedras de muerte inferiores absorbidas de los esbirros de Kel'Thuzad durante 30 min."},
[191272] = {name = "[q3]Vara de Nigromancia", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Somete la voluntad de un objetivo no-muerto en Naxxramas y provoca que quede embelesado durante 5 min.\n3 cargas"},
[191280] = {name = "[q3]Cúmulo de esporas fúngicas", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Otorga a tus facultades ofensivas la oportunidad de invocar una espora que afecta a los jugadores cercanos con Flor de hongo cuando muere. Este efecto dura 1 h.\n\nFlor de hongo\nInflige 150 p. de daño de Naturaleza cada 1 s y también aumenta un 15% la probabilidad de golpe crítico con un ataque cuerpo a cuerpo, a distancia o con hechizos. (Probabilidad de que accione: 10%, 15s de reutilización)"},
[191288] = {name = "[q4]Runa de teletransporte: Guarida de vermis de escarcha", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Te transporta a la Guarida de vermis de escarcha en Naxxramas."},
[191292] = {name = "[q3]Daga ritual", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Absorbe la fuerza vital de todos a tu alrededor y aumenta 3 p. el aguante por cada objetivo golpeado. Este efecto se acumula hasta 40 veces y dura 1 h."},
[191312] = {name = "[q4]Filacteria infalible", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 7 díasAbalorio\nNecesitas ser de nivel 60\n[q2]Equipar: Te protege de un ataque que debería matarte. Activar este efecto también te otorga inmunidad a 3 s p. de daño y destruye la filacteria."},
[191313] = {name = "Máscara de muerte", additional_info = "Duración: 7 días\n[q2]Uso: Adopta el semblante de un habitante de Naxxramas."},
[191414] = {name = "[q3]Artefacto esquelético", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Atrapa el alma del objetivo muerto, lo que te otorga un efecto beneficioso. Este efecto dura 1 h."},
[191458] = {name = "[q0]Filacteria destrozada", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 7 díasAbalorio\nNecesitas ser de nivel 60\n[q]\"Opaca e inútil.\""},
[191459] = {name = "[q4]Runa de fortuna", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Potencia a Kel'Thuzad y sus tenientes con energía nigromántica, lo que les otorga más salud y daño. Los enemigos potenciados otorgarán más recompensas cuando sean derrotados..\n\n Este efecto se acumula y dura una semana completa."},
[191477] = {name = "[q4]Palenque esquelético", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 7 días\nNecesitas ser de nivel 60\n[q2]Uso: Invoca un palenque esquelético.\n\n Los miembros del grupo pueden usarlo para obtener un corcel esquelético."},
[191480] = {name = "[q4]Corcel esquelético", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 1 hora\nMontura\nNecesitas ser de nivel 40\n[q2]Uso: Invoca y retira a un corcel esquelético. Este corcel obedece al invocador y puede usarse como montura en Naxxramas. Toda acción hostil contra su jinete obliga al corcel a huir despavorido. (3 Seg Reutilización)"},
[191481] = {name = "[q4]Tabardo de maestría", additional_info = "Se liga al recogerlo\nTabardo\n[q]\"Un testimonio de la maestría.\""},
[191550] = {name = "Libro de piedras de muerte: Máscara de muerte", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una máscara de muerte.\""},
[191605] = {name = "[q2]Libro de piedras de muerte: Runa de teletransporte I", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una runa de teletransporte.\""},
[191606] = {name = "[q2]Libro de piedras de muerte: Orbe de corrupción", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en un orbe de corrupción.\""},
[191607] = {name = "[q3]Libro de piedras de muerte: Artefacto esquelético", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en un artefacto esquelético.\""},
[191608] = {name = "[q3]Libro de piedras de muerte: Vara de Nigromancia", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una vara de necromancia.\""},
[191609] = {name = "[q3]Libro de piedras de muerte: Cúmulo de esporas fúngicas", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en un cúmulo de esporas fúngicas.\""},
[191610] = {name = "[q3]Libro de piedras de muerte: Daga ritual", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una daga ritual.\""},
[191611] = {name = "[q4]Libro de piedras de muerte: Filacteria infalible", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una filacteria infalible.\""},
[191612] = {name = "[q4]Libro de piedras de muerte: Runa de teletransporte II", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una runa de teletransporte.\""},
[191613] = {name = "[q4]Libro de piedras de muerte: Runa de fortuna", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en una runa de fortuna.\""},
[191614] = {name = "[q4]Libro de piedras de muerte: Palenque esquelético", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en un palenque esquelético.\""},
[191656] = {name = "[q4]Esencia de la muerte", additional_info = "Se liga al recogerlo\n[q2]<Click derecho para abrir>"},
[191660] = {name = "[q3]Descargas de relámpagos de Thaddius", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Te coloca las tuercas en el cuello, lo que aplica una descarga positiva o negativa de forma aleatoria que aumenta un 1% el daño y la sanación.\n\n Este efecto se acumula al estar cerca de los aliados que tengan una carga similar e inflige daño de Naturaleza a los aliados que tengan una carga opuesta."},
[191661] = {name = "[q3]Colmillo de araña monstruoso", additional_info = "Se liga al recogerlo\nDuración: 7 días\n[q2]Uso: Te clavas el colmillo, lo que aumenta un 15% la velocidad de movimiento, ataque y lanzamiento durante 1 h. (Probabilidad de que accione: 5%, 30s de reutilización)"},
[191664] = {name = "[q3]Libro de piedras de muerte: Descargas de relámpagos de Thaddius", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en las Descargas de relámpagos de Thaddius.\""},
[191666] = {name = "[q3]Libro de piedras de muerte: Colmillo de araña monstruoso", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Un escrito que detalla el arte de convertir piedras de muerte en un colmillo de araña monstruoso.\""},
[202251] = {name = "Bolsa de golosinas para mascotas", additional_info = "Se liga al recogerlo\n[q2]Uso: Abres la bolsa de bocadillos y la colocas en el bolsillo de tu objetivo, lo que aumenta el daño de las bestias contra el objetivo en 20 p. (1 Min Reutilización)"},
[202254] = {name = "[q3]Brazales de reorientación", additional_info = "Se liga al equiparlo\nMuñeca Cuero\n44 armadura\n+11 aguante\n+13 intelecto\n+8 espíritu\nDurabilidad 35 / 35\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora tu probabilidad de asestar un golpe crítico con hechizos un 1%."},
[202256] = {name = "[q2]Pistola ornamentada de corsario", additional_info = "Se liga al recogerlo\n{A distancia} {Arma de fuego}\n{6 - 13 p. de daño} {Velocidad 1.90}\n(5.00 p. de daño por segundo)\nDurabilidad 35 / 35\nClases: Pícaro\n[q2]Equipar: Obtienes la habilidad Desenfunde rápido:\n\n\nSaca tu arma a distancia, haz un disparo rápido contra un enemigo e inflige daño de arma a distancia normal y reduce la velocidad de movimiento del objetivo un 50% durante 6 s. Otorga 1 p. de combo.\n\n Desenfunde rápido se beneficia de todos los talentos y efectos que se activan por Golpe siniestro o lo modifican."},
[202641] = {name = "Cuaderno cubierto de barro", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\nClases: Pícaro\n[q]\"Este libro está cubierto de barro, pero contiene algunas runas inscritas en sus páginas y una breve nota escrita en jerga.\""},
[203723] = {name = "Nota de Navajín", additional_info = "Se liga al recogerlo\nClases: Pícaro\n[q]\"Un mensaje escrito en jerga de ladrones\"\n[q2]<Click derecho para leer>"},
[203726] = {name = "[q2]Runa de Navajín", additional_info = "Clases: Pícaro"},
[203745] = {name = "[q2]Notas de hechizo: Lanza de hielo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\nRequiereGrabado\n(1)\n[q2]Graba tus guantes con la runa Lanza de hielo:\n\n\nInflige entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ] de daño de Escarcha a un objetivo enemigo. Inflige un 400% de daño contra objetivos congelados.\n\n Cuando tus otros hechizos de Escarcha infligen daño a un objetivo que no controla un jugador, aumentan un 20% el daño que recibe el objetivo de tu siguiente Lanza de hielo. Este efecto se acumula hasta 5 veces y requiere el talento Escalofrío invernal.\n[q]\"Te enseña una nueva habilidad de tallado rúnico.\""},
[203746] = {name = "[q2]Notas de hechizo: Llama viva", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\nRequiereGrabado\n(1)\n[q2]Graba tus pantalones con la runa Llama viva:\n\n\nInvoca una llama piroarcana que se mueve hacia el objetivo y deja un rastro de piroarcano. Este rastro inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100] p. de daño Piroarcano por s a los enemigos cercanos. Dura 10 s.\n[q]\"Te enseña una nueva habilidad de tallado rúnico.\""},
[203747] = {name = "[q2]Notas de hechizo: Dedos de escarcha", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\nRequiereGrabado\n(1)\n[q2]Graba tu pechera o toga con la runa Dedos de Escarcha:\n\n\nDa a tus efectos de enfriamiento una probabilidad de un 25% de otorgarte el efecto Dedos de Escarcha, que hace que tus siguientes 2 hechizos traten al objetivo como si estuviese congelado. Dura 15 s.\n[q]\"Te enseña una nueva habilidad de tallado rúnico.\""},
[203748] = {name = "[q2]Notas de hechizo: Incendio", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu pechera con la runa Incendio:\n\n\nAumenta tu probabilidad de golpe crítico con todos los hechizos un 15%, pero tus golpes críticos con hechizos que no son periódicos ahora tienen un costo de maná adicional de un 1% de tu maná base.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[203749] = {name = "[q2]Notas de hechizo: Esclarecimiento", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu pechera o toga con la runa Esclarecimiento:\n\n\nInfliges un 10% más de daño cuando tienes más del 70% de maná. Cuando tienes menos del 30% de maná, conservas un 10% de tu regeneración de maná durante el lanzamiento de hechizos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[203750] = {name = "Mapa del tesoro de Elwynn", additional_info = "Se liga al recogerlo\nClases: Pícaro\n[q2]Uso: Desentierra un tesoro en la ubicación marcada (1 Min Reutilización)\n[q]\"Al oeste de la Torre de la Peña. Cerca del tocón detrás del cubil de los merodeadores.\""},
[203751] = {name = "[q2]Notas de hechizo: ALZO EN HIELAD", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un manual de comprensión para aprender un nuevo hechizo de grabado."},
[203752] = {name = "[q2]Notas de hechizo: MALVA VALI", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado."},
[203753] = {name = "[q2]Notas de hechizo: DASCAC HEDED SEOR", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado."},
[203754] = {name = "Archimago Antonidas: La autobiografía completa", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"A pesar de ser algo autocomplaciente, es una gran incorporación para la colección de cualquier biblioteca.\""},
[203755] = {name = "Diario de investigación del archimago Theocritus", additional_info = "Único\n[q]\"Notas de investigación de la Torre de Azora. Una gran incorporación para la colección de cualquier biblioteca.\""},
[203756] = {name = "[q2]Nota de aprendiz de Azora: página 1", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina 6 notas de aprendiz de Azora para crear una nueva receta de grabado."},
[203784] = {name = "Trozo superior derecho de mapa", additional_info = "[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
[203785] = {name = "Trozo superior izquierdo de mapa", additional_info = "[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
[203786] = {name = "Trozo inferior derecho de mapa", additional_info = "[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
[203787] = {name = "Trozo inferior izquierdo de mapa", additional_info = "[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
[203960] = {name = "[q2]Nota de aprendiz de Azora: página 2", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina 6 notas de aprendiz de Azora para crear una nueva receta de grabado."},
[203961] = {name = "[q2]Nota de aprendiz de Azora: página 3", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina 6 notas de aprendiz de Azora para crear una nueva receta de grabado."},
[203962] = {name = "[q2]Nota de aprendiz de Azora: página 4", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina 6 notas de aprendiz de Azora para crear una nueva receta de grabado."},
[203990] = {name = "[q2]Runa de Mutilación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus guantes con la runa Mutilar:\n\n\nAtacas instantáneamente con ambas armas e infliges 95% de daño con arma más [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Otorga 2 p. de combo.\n\n Mutilar se beneficia de todos los talentos y efectos que se activan con Puñalada o que la modifican a menos que se explicite lo contrario.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[203991] = {name = "[q2]Runa de Desenfunde rápido", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu pechera o tu toga con la runa Desenfunde rápido:\n\n\nSaca tu arma a distancia, haz un disparo rápido contra un enemigo e inflige daño de arma a distancia normal y reduce la velocidad de movimiento del objetivo un 50% durante 6 s. Otorga 1 p. de combo.\n\n Desenfunde rápido se beneficia de todos los talentos y efectos que se activan por Golpe siniestro o lo modifican.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[203992] = {name = "[q2]Runa de Artimaña", additional_info = "Clases: Pícaro\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[203993] = {name = "[q2]Runa de Masacre", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu pechera o toga con la runa Matanza desde las Sombras:\n\n\nReduce 30 p. el costo de energía de tu Puñalada y Emboscada, y aumenta el daño que infligen a objetivos que no están controlados por jugadores un 70. [ Grabar guantes - Mutilar : No aplica a Mutilar / No aplica a otras habilidades aprendidas con otras runas.]\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[203994] = {name = "[q2]Runa de Brebaje letal", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu pechera o tu toga con la runa Brebaje letal:\n\n\nOtorga diversas mejoras a tus venenos:\n\n Cuando aplicas cualquier otro veneno a un objetivo, también aplicas Veneno mortal.\n\n Si tu arma no tiene un veneno aplicado, tiene una probabilidad de activar Veneno instantáneo como si estuviese aplicado.\n\n Veneno mortal y Veneno instantáneo ahora obtienen más daño de tu poder de ataque.\n\n Tu Veneno mortal ahora puede estar activo en los objetivos afectados por el Veneno mortal de otro Pícaro.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204174] = {name = "[q2]Runa de Precisión", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus pantalones con la runa Entre los ojos:\n\n\nRemate a distancia que inflige daño por p. de combo, que aumenta según el poder de ataque y aturde al objetivo:\n\n 1 punto: Â  De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))] p. de daño, 1 s de aturdimiento\n 2 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)] p. de daño, 2 s de aturdimiento\n 3 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)] p. de daño, 3 s de aturdimiento\n 4 puntos: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)] p. de daño, 4 s de aturdimiento\n 5 puntos: De [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] a [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)] p. de daño, 5 s de aturdimiento\n\n Comparte el tiempo de reutilización con Golpe en los riñones.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204270] = {name = "Núcleo de las profundidades", additional_info = "Único"},
[204441] = {name = "[q2]Runa de Frenesí sangriento", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu pechera con la runa Frenesí sangriento:\n\n\nAhora Desgarrar se puede usar en actitud rabiosa, su daño aumenta un 100% e inflige una mayor cantidad de daño, equivalente al 4% de tu poder de ataque, cada vez que inflige daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204476] = {name = "Cabeza de kóbold cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[204477] = {name = "Cabeza de múrloc cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[204478] = {name = "Cabeza de gnoll cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[204688] = {name = "Primer fragmento de runa de cazador de monstruos", additional_info = "[q2]Uso: Combina este objeto con 2 piezas más para formar una runa completa."},
[204689] = {name = "Segundo fragmento de runa de cazador de monstruos", additional_info = "[q2]Uso: Combina este objeto con 2 piezas más para formar una runa completa."},
[204690] = {name = "Tercer fragmento de runa de cazador de monstruos", additional_info = "[q2]Uso: Combina este objeto con 2 piezas más para formar una runa completa."},
[204703] = {name = "[q2]Runa de Devastar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus guantes con la runa Devastar:\n\n\nMientras estás en actitud defensiva y tienes un escudo equipado, Hender armadura también inflige daño equivalente al 150% del daño por segundo de tu arma equipada, y aumenta un 10% por aplicación de Hender armadura que ya haya en el objetivo. El daño de Devastar genera una gran cantidad de amenaza mientras estás en Actitud defensiva.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204716] = {name = "[q2]Runa de Asalto frenético", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus pantalones con la runa Asalto frenético:\n\n\nMientras blandes un arma de dos manos, tu velocidad de ataque aumenta un 40% y tus golpes cuerpo a cuerpo exitosos generan 2 p. más de ira, o 4 p. más de ira si son golpes críticos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204795] = {name = "[q2]Runa de Golpesombra", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus guantes con la runa Golpesombra:\n\n\nTe teletransportas detrás de tu objetivo y ejecutas un ataque que le inflige un 150% de daño con arma. Debes estar en sigilo. Otorga 1 p. de combo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204804] = {name = "[q3]Brazaletes de Hydraxis", additional_info = "Se liga al recogerlo\nMuñeca Malla\n95 armadura\n+4 fuerza\n+7 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 25"},
[204806] = {name = "[q2]Runa de Ataque de la victoria", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus guantes con la runa Ataque de la victoria:\n\n\nAtacas al instante al objetivo, le infliges (1 + Attack power * 45 / 100) p. de daño y recuperas una cantidad de salud equivalente al 30% de tu salud máxima. Â Solo puede usarse durante 20 s tras haber matado a un enemigo que otorga experiencia u honor.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204807] = {name = "[q3]Espada de las profundidades", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{71 - 107 p. de daño} {Velocidad 3.60}\n(24.72 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Probabilidad al acertar: Golpea a todos los enemigos que tienes enfrente con agua a presión.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q]\"El estrépito de las olas puede oírse con cada golpe.\""},
[204809] = {name = "[q2]Runa de Rayo furioso", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus pantalones con la runa Rayo furioso:\n\n\nAtronar ahora aumenta el tiempo entre ataques un 6% más. Puede usarse en cualquier actitud, inflige un 100% más de daño e inflige un 50% más de amenaza.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[204864] = {name = "[q2]Nota de aprendiz de Azora", additional_info = "Se liga al recogerlo\nÚnico (6)\n[q2]Uso: Combina 6 notas de aprendiz de Azora para crear una nueva receta de grabado."},
[204905] = {name = "Escrito ominoso", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invocar a Soboz\n[q]\"Coloca la mandíbula de un lobo y la sangre de un gnoll en el estómago de un cordero. Después, comienza con el encantamiento.\""},
[204906] = {name = "Sangre de gnoll", additional_info = "Único\n[q]\"Un componente para un ritual de invocación\""},
[204907] = {name = "Mandíbula de lobo", additional_info = "Único\n[q]\"Un componente para un ritual de invocación\""},
[204910] = {name = "[q0]Monster - Trident, Naga (Gold)", additional_info = "Se liga al recogerlo\n{Dos manos} {Arma de asta}\n{2 - 4 p. de daño} {Velocidad 3.00}\n(1.00 p. de daño por segundo)\nDurabilidad 20 / 20"},
[204912] = {name = "[q2]Runa de Gracia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus pantalones con la runa Gracia demoníaca:\n\n\nTe sobrecargas con energía vil, lo que aumenta un 20% tu probabilidad y la de tu mascota de esquivar y un 20% tu probabilidad de asestar golpes críticos con todos tus ataques. Dura 6 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205019] = {name = "Fragmento de alma contaminado", additional_info = "Se liga al recogerlo\nÚnico"},
[205020] = {name = "Fragmento de alma pura", additional_info = "Se liga al recogerlo\nÚnico"},
[205022] = {name = "[q2]Runa de Succión de alma", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu capa con la runa Succión de alma:\n\n\nHace que tu Drenar alma inflija daño 3 veces más rápido y aumenta la cantidad drenada por tus hechizos Drenar vida y Drenar alma un 6% más por cada efecto de las sombras de tu brujo aplicado sobre el objetivo, hasta un máximo de un 18% adicional. Cuando Drenar alma se lanza sobre un objetivo que tiene menos de un 20% de salud, en cambio obtiene un 50% por cada efecto, hasta un máximo de un 150%. Además, tu Drenar alma ahora puede activar tu talento Ocaso.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205181] = {name = "Artefacto sin identificar", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un objeto mágico esotérico. Un brujo más experimentado podría contarte más acerca de él.\""},
[205182] = {name = "Artefacto sin energía", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Ofrece tu sangre para potenciar el artefacto."},
[205183] = {name = "Artefacto alimentado con energía vil", additional_info = "Se liga al recogerlo\nÚnico"},
[205184] = {name = "Nota de acólito", additional_info = "Se liga al recogerlo\nÚnico\n[q2]<Click derecho para leer>"},
[205215] = {name = "[q2]Runa de Tácticas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu pechera o toga con la runa Tácticas demoníacas:\n\n\nAumenta un 10% la probabilidad de que tú y tu mascota asesten un golpe crítico cuerpo a cuerpo y con hechizos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205218] = {name = "[q2]Tratado sobre descubrimiento", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nClases: Paladín\nNecesitas ser de nivel 5\n[q2]Graba tu capa con la runa Succión de alma:\n\n\nHace que tu Drenar alma inflija daño 3 veces más rápido y aumenta la cantidad drenada por tus hechizos Drenar vida y Drenar alma un 6% más por cada efecto de las sombras de tu brujo aplicado sobre el objetivo, hasta un máximo de un 18% adicional. Cuando Drenar alma se lanza sobre un objetivo que tiene menos de un 20% de salud, en cambio obtiene un 50% por cada efecto, hasta un máximo de un 150%. Además, tu Drenar alma ahora puede activar tu talento Ocaso.\n[q]\"Mata a 5 enemigos para lograr un estado de Inspiración y úsalo para aprender una habilidad nueva.\""},
[205228] = {name = "[q2]Runa de Descarga de caos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus guantes con la runa Descarga de caos:\n\n\nLanza una descarga de fuego caótico al enemigo que inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100] p. de daño de Caos. Descarga de caos siempre golpea, no se puede resistir, y su conocimiento hace que todos tus hechizos de Fuego atraviesen los efectos de absorción. Los enemigos con 4 o más niveles por encima del tuyo tienen una alta probabilidad de resistir Descarga de caos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205230] = {name = "[q2]Runa de Posesión", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus guantes con la runa Poseer:\n\n\nLiberas un alma fantasmal contra un enemigo. Le inflige de [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100] a [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100] p. de daño y aumenta un 40% todo el daño de las Sombras con el tiempo que inflijas a ese objetivo durante 15 s. Cuando Poseer termina o se disipa, sanas por todo el daño que infligió al objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205364] = {name = "Morral de acólito", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]<Click derecho para abrir>"},
[205420] = {name = "[q2]Tratado sobre sentencia", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nClases: Paladín\n[q2]Graba tus guantes con la runa Golpe de cruzado:\n\n\nUn golpe instantáneo que inflige un 75% de daño con arma como daño Sagrado y regenera un 5% de tu maná máximo. La duración de todos los efectos de Sentencia en el objetivo se restablece a 30 s.\n[q]\"Aprendes una nueva habilidad después de aplicar 10 sellos sobre tus enemigos\""},
[205683] = {name = "[q2]Runa de Reprimenda", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus pantalones con la runa Reprimenda:\n\n\nInterrumpe el lanzamiento de hechizos y evita que se lancen hechizos de esa misma escuela durante 3 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205685] = {name = "[q2]Runa de Égida", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu pechera con la runa Égida:\n\n\nAumenta un 30% tu valor de bloqueo y modifica tu talento Baluarte. Baluarte ahora también tiene una probabilidad de 10% de activarse con cualquier ataque cuerpo a cuerpo o a distancia que recibas, y siempre se activa cuando asestas un golpe crítico cuerpo a cuerpo. Además, tu talento Expiación obtiene un 2% de probabilidad por punto de talento de activarse con cualquier ataque cuerpo a cuerpo o a distancia que recibas.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205863] = {name = "Tratado corrupto", additional_info = "Clases: Paladín"},
[205864] = {name = "Nota chamuscada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]<Click derecho para leer>"},
[205897] = {name = "[q2]Runa de Luz divina", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu capa con la runa Luz divina:\n\n\nRestaura de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100] p. de salud a un objetivo aliado. Un 50% de la sanación excedente del objetivo se convierte en un escudo de absorción que dura 15 s. Lanzar Luz divina múltiples veces no acumula este escudo.\n\n Luz divina se beneficia de todos los talentos y efectos que se activan por Luz Sagrada o que la modifican.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205905] = {name = "[q2]Recuerdo de un campeón devoto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu pechera o toga con la runa Fe distorsionada:\n\n\nTortura mental y Explosión mental infligen un 50% más de daño a los objetivos que están bajo los efectos de tu Palabra de las Sombras: dolor.\n[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[205932] = {name = "[q2]Profecía de la muerte de un rey", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus guantes con la runa Palabra de las Sombras: muerte:\n\n\nUna palabra de vínculo oscuro que inflige entre [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100] y [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100] p. de daño de las Sombras al objetivo. Si el objetivo no muere a causa de Palabra de las Sombras: muerte, el taumaturgo recibe daño equivalente a un 50% del daño que intentó infligirle.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[205940] = {name = "[q2]Recuerdo de un propósito oscuro", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus botas con la runa Plaga del Vacío:\n\n\nAflige al objetivo con una enfermedad que inflige [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 129 / 100 * 6] p. de daño de las Sombras durante 18 s.\n[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[205942] = {name = "Epifanía quimérica", additional_info = "[q2]Graba tus pantalones con la runa Rezo de alivio:\n\n\nLanza un hechizo sobre el objetivo que lo sanará [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] p. la próxima vez que reciba daño o sanación. Una vez sanado, Rezo de alivio pasará a otro miembro del grupo o banda en un radio de 20 m. Salta hasta 5 veces y dura 30 s después de cada salto. Este hechizo solo puede estar activo en un único objetivo a la vez."},
[205943] = {name = "Profecía de una ciudadela profanada", additional_info = "Único\n[q2]Graba tus pantalones con la runa Homúnculos:\n\n\nFragmenta trozos de tu alma para animar 3 copias miniatura de ti que intentan atacar a tu objetivo actual con una maza, espada o hacha para reducir la velocidad de ataque, el poder de ataque y la armadura de cualquier objetivo que golpee.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[205944] = {name = "[q2]Epifanía recíproca", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus pantalones con la runa Rezo de alivio:\n\n\nLanza un hechizo sobre el objetivo que lo sanará [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] p. la próxima vez que reciba daño o sanación. Una vez sanado, Rezo de alivio pasará a otro miembro del grupo o banda en un radio de 20 m. Salta hasta 5 veces y dura 30 s después de cada salto. Este hechizo solo puede estar activo en un único objetivo a la vez.\n[q]\"Aprendes una nueva habilidad de grabado.\""},
[205945] = {name = "[q2]Recuerdo de un salvador encerrado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus pantalones con la runa Dolor compartido:\n\n\nTu Palabra de las Sombras: dolor ahora también afecta a un máximo de 2 objetivos más en un radio de 15 m.\n[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[205946] = {name = "[q2]Recuerdo de la traición de un líder", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus botas con la runa Supresión de dolor:\n\n\nReduce un 40% al instante todo el daño recibido por un objetivo aliado y aumenta la resistencia a las mecánicas de Disipación un 65% durante 8 s.\n[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[205947] = {name = "[q2]Profecía de una ciudadela profanada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus pantalones con la runa Homúnculos:\n\n\nFragmenta trozos de tu alma para animar 3 copias miniatura de ti que intentan atacar a tu objetivo actual con una maza, espada o hacha para reducir la velocidad de ataque, el poder de ataque y la armadura de cualquier objetivo que golpee.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[205948] = {name = "Epifanía anodina", additional_info = "[q2]Graba tu capa con la runa Toque vampírico:\n\n\nAplica tu talento Abrazo vampírico a tu objetivo, lo que le inflige [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] p. de daño de las Sombras durante 15 s, y hace que todos los miembros del grupo obtengan una cantidad de maná equivalente al 2% de cualquier daño con hechizos de las Sombras que inflijas al objetivo."},
[205949] = {name = "Epifanía múltiple", additional_info = "Clases: Sacerdote\n[q2]Graba tus guantes con la runa Círculo de sanación:\n\n\nRestablece de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205950] = {name = "[q2]Epifanía tenebrosa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus guantes con la runa Abrasamiento mental:\n\n\nProvoca una explosión de magia de las Sombras que daña al objetivo enemigo y a otros enemigos cercanos. Inflige de [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] a [78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)] p. de daño de las Sombras cada 1 s durante 6 s a todos los enemigos en un radio de 10 m del objetivo.\n[q]\"Aprendes una nueva habilidad de grabado.\""},
[205951] = {name = "[q2]Recuerdo de un acólito atribulado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus guantes con la runa Penitencia:\n\n\nLanza una salva de Luz Sagrada al objetivo, inflige [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100] p. de daño Sagrado a un enemigo, o [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100] p. de sanación a un aliado de forma instantánea y cada 1 s durante 2 s.\n[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[205952] = {name = "Recuerdo de un mundo devastado", additional_info = "[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[205953] = {name = "[q2]Profecía de juramento roto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Púa mental:\n\n\nGolpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[205961] = {name = "Carne de ave de Mulgore", additional_info = "Único\n[q2]Uso: Coloca un cebo cerca de la morada de un gato montés."},
[205979] = {name = "[q2]Runa de Flanqueo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus pantalones con la runa Golpe lateral:\n\n\nTú y tu mascota infligen un 100% de daño cuerpo a cuerpo de forma instantánea y en simultáneo. Después, infliges un 8% más de daño durante 10 s. Este efecto se acumula un máximo de 3 veces. Los ataques básicos de tu mascota tienen un 50% de probabilidad de restablecer el tiempo de reutilización de Golpe lateral.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[205995] = {name = "Almizcle de perro de la pradera", additional_info = "Clases: Cazador\n[q2]Uso: Tu habilidad Domesticar bestia también funciona en perros de la pradera (como mascota de compañía) (10 Min Reutilización)"},
[206032] = {name = "[q2]Runa de Cuchillada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus guantes con la runa Cuchillada:\n\n\nUn ataque de barrido que golpea a todos los enemigos frente a ti con tus armas cuerpo a cuerpo por un 65% de daño con arma. Tu objetivo principal recibe un 50% más de daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206155] = {name = "[q2]Runa de Puntería", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tu pechera o tu toga con la runa Maestro tirador:\n\n\nAumenta un 5% tu probabilidad de golpe crítico y reduce un 25% el costo de todas tus habilidades de Disparo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206157] = {name = "Carga minera de seforio", additional_info = "Objeto de misión\nÚnico (5)"},
[206159] = {name = "Disfraz de Ventura y Cía.", additional_info = "Objeto de misión\n[q]\"No parece un gran disfraz...\""},
[206168] = {name = "[q2]Runa de Quimera", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus guantes con la runa Disparo de quimera:\n\n\nInfliges un 135% de daño con arma, lo que renueva la Picadura actual de tu objetivo y activa un efecto:\n\n Picadura de serpiente: Inflige instantáneamente un 48% del daño infligido por tu Picadura de serpiente.\n\n Picadura de víbora: Restaura instantáneamente una cantidad de maná igual al 60% del maná drenado por tu Picadura de víbora.\n\n Picadura de escórpido: Intenta Desarmar al objetivo durante 10 s. Este efecto solo puede ocurrir una vez por minuto.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206169] = {name = "[q2]Runa de Disparo explosivo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus guantes con la runa Disparo explosivo:\n\n\nDisparas una carga explosiva al objetivo enemigo que inflige [Ranged attack power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged attack power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño de Fuego a todos los enemigos en un radio de 8 m. La carga volverá a infligir daño por segundo durante 2 s más.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206170] = {name = "Cono de viento furioso", additional_info = "Objeto de misión"},
[206175] = {name = "Bálsamo de pino", additional_info = "Objeto de misión\nÚnico"},
[206176] = {name = "Mortero y majadero", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Muele y mezcla 8 piñas Viento Furioso para crear un ungüento venenoso para armas. Teóricamente."},
[206177] = {name = "Mantequilla de piñones", additional_info = "Se liga al recogerlo\n[q2]Uso: Restaura 61.2 p. de salud durante 18 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 2 p. de aguante y espíritu durante 15 min."},
[206264] = {name = "[q2]Runa de Inspiración", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus pantalones con la runa Inspiración ejemplar:\n\n\nTu presencia inspiradora periódicamente disipa efectos de miedo y sueño en miembros del grupo cercanos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206344] = {name = "Conjunto de cuchillos", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Intenta filetear un pececito luminoso crudo."},
[206345] = {name = "Trozos de pescado", additional_info = "Objeto de misión\nÚnico"},
[206376] = {name = "[q2]Ícono de baluarte", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tu pechera o tu toga con la runa Maestría con escudos:\n\n\nCada vez que bloqueas, regeneras una cantidad de maná equivalente al 8% de tu maná máximo y obtienes una cantidad de armadura equivalente al 30% del valor de armadura de tu escudo, que se acumula hasta 5 veces. También aumenta un 10% la probabilidad de bloqueo y un 15% el valor de bloqueo.\n\n Además, cada vez que usas una habilidad de Choque, obtienes 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s.\n[q]\"Aprendes una nueva habilidad después de golpear enemigos 25 veces con Arma Muerdepiedras.\""},
[206381] = {name = "[q2]Ícono diádico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\n[q2]Graba tu pechera o toga con la runa Sobrecarga:\n\n\nDa a tus hechizos Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava una probabilidad de un 60% de lanzar un segundo hechizo similar en el mismo objetivo sin costo adicional que inflige la mitad del daño o sanación y no genera amenaza.\n[q]\"Aprendes una nueva habilidad después de recibir daño de Naturaleza 10 veces.\""},
[206382] = {name = "[q2]Ícono de tempestad", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\n[q2]Graba tus guantes con la runa Escudo de agua:\n\n\nEl taumaturgo queda rodeado por 3 esferas de agua que le dan un 1% del maná máximo cada 5 s. Cada hechizo o ataque cuerpo a cuerpo o a distancia que golpee al taumaturgo restaura un 4% del maná máximo y consume una de las esferas. Solo se activará una esfera cada varios segundos. Dura 10 min. El chamán solo puede activar un escudo elemental a la vez.\n[q]\"Aprendes una nueva habilidad después de golpear a 10 enemigos que no sean jugadores con 3 elementos diferentes (Naturaleza, Escarcha, Fuego).\""},
[206383] = {name = "[q2]Ícono lítico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tus pantalones con la runa Escudo de tierra:\n\n\nProtege al objetivo con un escudo de tierra que reduce el tiempo perdido de lanzamiento o canalización cuando recibe un 30% de daño y provoca que los ataques sanen [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] p. al objetivo escudado. Este efecto solo puede ocurrir una vez cada pocos segundos. 9 cargas. Dura 10 min. Escudo de tierra solo puede utilizarse en un objetivo a la vez.\n[q]\"Aprendes una nueva habilidad después de bloquear 20 ataques con tu escudo.\""},
[206384] = {name = "[q2]Ícono astral", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q]\"Aprendes una nueva habilidad después de golpear enemigos 25 veces con Arma Muerdepiedras.\""},
[206385] = {name = "[q2]Ícono clástico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tus pantalones con la runa Tradición de tierra:\n\n\nCuando Arma Muerdepiedras está activa en tu arma de mano derecha y tienes un escudo equipado, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño, obtienes un 6% menos de probabilidad de recibir golpes críticos de ataques cuerpo a cuerpo y Choque de tierra provoca a los objetivos para que te ataquen. Además, tiene un tiempo de reutilización aparte de los demás hechizos de Choque, pero su alcance se reduce a cuerpo a cuerpo. Sin embargo, el alcance de tu Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava se reduce 20 m.\n[q]\"Aprendes una nueva habilidad después de derrotar a 20 enemigos con Choque de tierra.\""},
[206386] = {name = "[q2]Ícono galvánico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\n[q2]Graba tu pechera o tu toga con la runa Maestría con escudos:\n\n\nCada vez que bloqueas, regeneras una cantidad de maná equivalente al 8% de tu maná máximo y obtienes una cantidad de armadura equivalente al 30% del valor de armadura de tu escudo, que se acumula hasta 5 veces. También aumenta un 10% la probabilidad de bloqueo y un 15% el valor de bloqueo.\n\n Además, cada vez que usas una habilidad de Choque, obtienes 4 p. de daño con hechizos por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s.\n[q]\"Aprendes una nueva habilidad después de derrotar enemigos 10 veces con Descarga de relámpagos.\""},
[206387] = {name = "[q2]Ícono kajárico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\n[q2]Graba tus guantes con la runa Ráfaga de lava:\n\n\nLanzas al objetivo lava fundida que inflige de [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] a [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)] p. de daño de Fuego. Si el objetivo tiene tu Choque de llamas, Ráfaga de lava asestará un golpe crítico.\n[q]\"Aprendes una nueva habilidad después de recibir daño de la lava 5 veces (reduce el daño recibido de alguna fuente de lava).\""},
[206388] = {name = "[q2]Ícono sulfúrico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\n[q2]Graba tus guantes con la runa Explosión de arrabio:\n\n\nHasta 10 enemigos en un cono frente a ti reciben entre [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Attack power] y [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Attack power] p. de daño de Fuego. Esta habilidad genera una alta cantidad de amenaza. El daño periódico de Choque de llamas tiene un 10% de probabilidad de reiniciar el tiempo de reutilización de Explosión de arrabio.\n[q]\"Aprendes una nueva habilidad después de derrotar a 10 enemigos con Choque de tierra.\""},
[206389] = {name = "[q2]Ícono de azufre", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tu cinturón con la runa Nova de Fuego:\n\n\nTu hechizo Tótem Nova de Fuego es reemplazado con Nova de Fuego, que hace que tu tótem de Fuego actual irradie daño en su ubicación.\n[q]\"Aprendes una nueva habilidad después de golpear enemigos 25 veces con Arma Muerdepiedras.\""},
[206390] = {name = "[q2]Ícono ictíneo", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tus guantes con la runa Escudo de agua:\n\n\nEl taumaturgo queda rodeado por 3 esferas de agua que le dan un 1% del maná máximo cada 5 s. Cada hechizo o ataque cuerpo a cuerpo o a distancia que golpee al taumaturgo restaura un 4% del maná máximo y consume una de las esferas. Solo se activará una esfera cada varios segundos. Dura 10 min. El chamán solo puede activar un escudo elemental a la vez.\n[q]\"Aprendes una nueva habilidad después de golpear enemigos 25 veces con Arma Muerdepiedras.\""},
[206391] = {name = "[q2]Ícono de Syzygic", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tus brazales con la runa\n Mareas Vivas:\n\n\nRestablece de [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] a [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. de salud a un objetivo aliado y [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. más durante 15 s. Tus lanzamientos de Sanación en cadena sobre ese objetivo principal en menos de 15 s aumentarán el efecto de Sanación en cadena un 25%. Este hechizo también activa Despertar ancestral.\n[q]\"Aprendes una nueva habilidad después de golpear enemigos 25 veces con Arma Muerdepiedras.\""},
[206466] = {name = "Corona de la pradera", additional_info = "[q2]Uso: Despierta a un espíritu de las llanuras"},
[206469] = {name = "Flor de la pradera", additional_info = "Clases: Druida\n[q2]Uso: Combina 3 flores de la pradera para hacer una corona."},
[206954] = {name = "[q2]Ídolo de cólera osuna", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\n[q2]Graba tus guantes con la runa Destrozar:\n\n\nDestroza al objetivo, lo que le inflige un 160% del daño normal y provoca que reciba un 30% más de daño de los efectos de sangrado y Triturar durante 1 min. Esta habilidad se beneficia de todos los efectos vinculados con Zarpa y Magullar y los activa.\n\n Golpear a un objetivo con Destrozar (oso) también te otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5). Dura 15 s.\n[q]\"Aprendes una nueva habilidad después de mantener tu ira en Forma de oso en 50 p. o más durante 60 segundos.\""},
[206963] = {name = "[q2]Runa de Potencial natural", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu pechera o toga con la runa Semilla viviente:\n\n\nCuando haces una sanación crítica a tu objetivo con cualquier hechizo de sanación no periódico, plantas una Semilla viviente en el objetivo con un 50% de la cantidad sanada. La Semilla viviente florecerá la próxima vez que el objetivo reciba daño o una sanación no periódica. Dura 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206966] = {name = "Bulbo de herbasátiro", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Esqueje de una especie invasiva de planta.\""},
[206970] = {name = "[q2]Runa de Vida", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus pantalones con la runa Flor de vida:\n\nReduce 0.5 s el tiempo de reutilización global de tu Rejuvenecimiento y Flor de vida, y obtienes la habilidad Flor de vida:\n\n\nRestablece [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al objetivo durante 7 s. Cuando Flor de vida se completa o disipa, el objetivo sana [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud al instante y el druida recupera la mitad del costo del hechizo. El efecto se acumula hasta 3 veces en un mismo objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206975] = {name = "Llave del depósito de artefactos", additional_info = "Único\n[q]\"Abre un cofre del depósito de artefactos\""},
[206985] = {name = "[q2]Eco del alfa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\nNecesitas ser de nivel 3\n[q2]Graba tus botas con la runa Espíritu del alfa:\n\n\nInfunde al objetivo con el espíritu de un lobo alfa y aumenta toda la amenaza generada por el objetivo un 45% durante 30 min. El límite es de 1 objetivo. Si se lanza sobre un objetivo que no sea él mismo, el Chamán también obtiene Beta leal, lo que aumenta un 5% el daño físico infligido y reduce toda la amenaza generada un 30% durante 30 min. Un objetivo no puede tener Espíritu del alfa y Beta leal al mismo tiempo.\n[q]\"Aprendes una nueva habilidad.\""},
[206989] = {name = "[q2]Runa del Sol", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus guantes con la runa Fuego solar:\n\n\nQuema al enemigo e inflige de [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] a [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza, además de [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza extra durante 12 s.\n\n Además, mientras estás en Forma de oso, Forma felina o Forma de oso temible, tu Fuego lunar es reemplazado por Fuego solar (oso) o Fuego solar (felino). Este hechizo se beneficia de todos los efectos vinculados con Fuego lunar y los activa.\n\n Fuego solar (oso)\nQuema al enemigo e inflige de [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] a [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza, además de [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza extra durante 12 s.\n\n Fuego solar (felino)\nQuema al enemigo e inflige de [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] a [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza, además de [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100] p. de daño de Naturaleza extra durante 12 s. Otorga 1 p. de combo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206992] = {name = "[q2]Runa de Testarazo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[206994] = {name = "Cabeza de jabaespín cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[206995] = {name = "Cabeza de arpía cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[207062] = {name = "Cabeza de centauro cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[207098] = {name = "Nota de Ba'so", additional_info = "Se liga al recogerlo\nClases: Pícaro\n[q]\"Un mensaje escrito en jerga de ladrones\"\n[q2]<Click derecho para leer>"},
[207106] = {name = "Trozo inferior izquierdo de mapa", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
[207107] = {name = "Trozo inferior derecho de mapa", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
[207108] = {name = "Trozo superior izquierdo de mapa", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
