[208085] = {name = "Sello de teniente escarlata", additional_info = "Único\n[q2]Uso: Crea documentos falsificados que siembren discordia entre la Cruzada Escarlata y la Alianza. Requiere suministros de escritura que se encuentran en el concejo de Rémol."},
[208086] = {name = "Memorándum Escarlata falsificado", additional_info = "Único\n[q]\"Una colección escandalosa de teorías sobre la supremacía de los humanos que sin duda alertará al liderazgo de la Alianza.\""},
[208139] = {name = "Escrito ominoso", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invocar a Soboz\n\"Lleva la mandíbula de un lobo y la sangre de un wendigo a Monte Luz. Párate sobre la piedra de ritual e invoca al demonio\""},
