[208185] = {name = "El manual de la metafísica del boticario", additional_info = "Único\n[q]\"Notas elementales sobre la teoría arcana y la investigación de hechizos, compiladas por el archimago Psicoputre de la Sociedad Real de Boticarios. Una gran incorporación para la colección de cualquier biblioteca.\""},
[208192] = {name = "Carne de cerdo de Dun Morogh", additional_info = "Único\n[q2]Uso: Coloca un cebo dentro de la guarida de un gran oso"},
[208196] = {name = "[q3]Sortija moa'kin", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+7 aguante\n+7 espíritu\nNecesitas ser de nivel 60\n[q2]Uso: Reclama el alma prometida. (3 H Reutilización)"},
