[208220] = {name = "Mapa del tesoro de Dun Morogh", additional_info = "Se liga al recogerlo\nClases: Pícaro\n[q2]Uso: Desentierra un tesoro en la ubicación marcada (1 Min Reutilización)\n[q]\"Bajo el puente de Kharanos a Forjaz.\""},
[208222] = {name = "[q3]Vindicadora del viejo guardia", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Hacha}\n{163 - 245 p. de daño} {Velocidad 3.90}\n(52.31 p. de daño por segundo)\n+8 fuerza\n+10 agilidad\n+41 aguante\nDurabilidad 100 / 100\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Equipar: Al asestar un golpe de gracia que otorga experiencia u honor, tu siguiente ataque será un golpe crítico.\n[q]\"Su dueño anterior cuidó de esta arma con el máximo esmero.\""},
[208223] = {name = "Morral de acólito", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]<Click derecho para abrir>"},
[208224] = {name = "Nota de acólito", additional_info = "Se liga al recogerlo\nÚnico\n[q2]<Click derecho para leer>"},
[208414] = {name = "[q2]Ídolo lunar", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\n[q2]Graba tu pechera o toga con la runa Furia de Tempestira:\n\n\nReduce un 100% el costo de maná de Cólera y cada vez que infliges daño con Cólera tienes una probabilidad de un 12% de que tu siguiente lanzamiento de Toque de sanación en 15 s sea instantáneo y pueda lanzarse en cualquier cambio de forma. Permite lanzar Cólera en forma de Árbol de la vida.\n[q]\"Derrota a 6 criaturas afectadas por tu Fuego lunar y úsalo para aprender una habilidad nueva.\""},
[208425] = {name = "[q7]Vestigio arcaico brillante", additional_info = "Se liga a la cuenta\nÚnico\nCuello\n+6 espíritu\nDurabilidad 35 / 35\n[q2]Uso: Te devuelve a <Hearthstone Location>. Habla con un tabernero en otro sitio para convertirlo en tu nuevo hogar. (1 Hora Reutilización)"},
[208484] = {name = "[q3]Luz solar", additional_info = "Se liga al recogerlo\nÚnico\nUna mano\n{10 - 14 p. de daño} {Velocidad 1.70}\n(7.06 p. de daño por segundo)\n+11 aguante\n+34 espíritu\n+17 resistencia a Sombras"},
[208601] = {name = "Trozo superior derecho de mapa", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina este objeto con 3 trozos más para completar el mapa.\n[q]\"Un trozo arrancado de lo que parece ser un mapa...\""},
