[208605] = {name = "Mapa del tesoro de Teldrassil", additional_info = "Se liga al recogerlo\nClases: Pícaro\n[q2]Uso: Desentierra un tesoro en la ubicación marcada (1 Min Reutilización)\n[q]\"El tocón hueco de Rut'theran.\""},
[208607] = {name = "Almizcle de ciervo", additional_info = "Clases: Cazador\n[q2]Uso: Tu habilidad Domesticar bestia también funciona en ciervos (como mascota de compañía) (10 Min Reutilización)"},
[208608] = {name = "Carne de ave de Teldrassil", additional_info = "Único\n[q2]Uso: Coloca un cebo dentro de la guarida de un gran oso"},
[208609] = {name = "Flor del prado", additional_info = "Clases: Druida\n[q2]Uso: Combina 3 flores del prado para hacer una corona."},
[208610] = {name = "Cabeza de búho cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[208611] = {name = "Cabeza de tigre cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[208612] = {name = "Cabeza de araña cortada", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un trofeo lúgubre. Podría ser de interés si encuentras al coleccionista adecuado...\""},
[208682] = {name = "Huevo de quijaforte abandonado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"Necesita un nuevo hogar.\""},
[208687] = {name = "[q2]Runa de Lacerar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus pantalones con la runa\n Lacerar:\n\n\nLacera al objetivo enemigo y hace que sangre por [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5] p. de daño durante 15 s más un 20% de daño con arma por aplicación existente de Lacerar en el objetivo. Genera una gran cantidad de amenaza. Este efecto se acumula hasta 5 veces en el mismo objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208689] = {name = "[q2]Ídolo feroz", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\n[q2]Graba tus pantalones con la runa Rugido salvaje:\n\n\nRemate que aumenta el daño físico infligido un 30% en Forma felina. Â Dura más por cada punto de combo:\n 1 p. Â : 14 segundos\n 2 p.: 19 segundos\n 3 p.: 24 segundos\n 4 p.: 29 segundos\n 5 p.: 34 segundos\n[q]\"Aplica daño de sangrado a humanoides 20 veces y usa este ídolo para aprender una habilidad nueva.\""},
[208701] = {name = "[q2]Runa de Maestría de bestias", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tu pechera o tu toga con la runa Maestría de bestias:\n\n\nEl daño y la salud de tu mascota aumentan un 15%, y su regeneración de enfoque aumenta un 50%. Además, el Bramido de tu mascota también provoca al objetivo para que la ataque durante 3 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208739] = {name = "Estandarte de guerra de la Horda", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q]\"Coloca esto en territorio de tus enemigos\""},
[208741] = {name = "[q2]Runa de Ira infinita", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu yelmo con la runa Ira infinita:\n\n\nGeneras un 25% más de ira por todo el daño que infliges.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208743] = {name = "Alma de codicia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo"},
[208744] = {name = "[q2]Runa de Descargas de las Sombras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus guantes con la runa Salva de descarga de las Sombras:\n\n\nTu Descarga de las Sombras ahora golpea a un máximo de 5 objetivos a una distancia de 10 m, pero inflige un 5% menos de daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208749] = {name = "Llave de alijo tuercepinos", additional_info = "Único\n[q]\"Tiene una rama de árbol grabada rudimentariamente en el extremo.\""},
[208750] = {name = "[q2]Runa de Mediación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu pechera o toga con la runa Canalización maestra:\n\n\nTu Drenar vida ya no requiere canalización, dura 15 s, tiene 15 s de tiempo de reutilización, cuesta un 100% más de maná y te sana por un 50% más cada vez que inflige daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208753] = {name = "[q2]Notas de hechizo: Regeneración", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu pechera o toga con la runa Regeneración:\n\n\nRestablece [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] p. de salud al objetivo durante 3 s y aplica Faro temporal durante 30 s.\n\n Faro temporal\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos.\n[q]\"Teaches you a new Engraving ability.\""},
[208754] = {name = "[q2]Notas de hechizo: RANGE CERNEIO", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado."},
[208758] = {name = "[q2]Runa terránea", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus pantalones con la runa Tradición de tierra:\n\n\nCuando Arma Muerdepiedras está activa en tu arma de mano derecha y tienes un escudo equipado, generas un 65% más de amenaza, obtienes un 25% más de salud, recibes un 10% menos de daño, obtienes un 6% menos de probabilidad de recibir golpes críticos de ataques cuerpo a cuerpo y Choque de tierra provoca a los objetivos para que te ataquen. Además, tiene un tiempo de reutilización aparte de los demás hechizos de Choque, pero su alcance se reduce a cuerpo a cuerpo. Sin embargo, el alcance de tu Descarga de relámpagos, Cadena de relámpagos, Sanación en cadena, Ola de sanación y Ráfaga de lava se reduce 20 m.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208760] = {name = "Corona del prado", additional_info = "[q2]Uso: Despierta a un espíritu de las llanuras"},
[208764] = {name = "[q2]Runa de la Mente", additional_info = "Único\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Púa mental:\n\n\nGolpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces."},
[208765] = {name = "[q2]Mano servicial", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q]\"La mano se abrirá para un salvador.\""},
[208766] = {name = "[q2]Mano servicial", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q]\"La mano se ha abierto ante ti.\"\n[q2]<Click derecho para abrir>"},
[208767] = {name = "[q2]Runa de Alivio", additional_info = "Único\nClases: Sacerdote\n[q2]Graba tus pantalones con la runa Rezo de alivio:\n\n\nLanza un hechizo sobre el objetivo que lo sanará [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100] p. la próxima vez que reciba daño o sanación. Una vez sanado, Rezo de alivio pasará a otro miembro del grupo o banda en un radio de 20 m. Salta hasta 5 veces y dura 30 s después de cada salto. Este hechizo solo puede estar activo en un único objetivo a la vez.\n[q]\"Te enseña una nueva habilidad de tallado rúnico.\""},
[208768] = {name = "Caja de fósforos de bucanero", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q]\"Se utiliza para encender materiales inflamables.\""},
[208771] = {name = "[q2]Runa de Danza de hojas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus pantalones con la runa Danza de hojas:\n\n\nRemate que aumenta un 10% tu probabilidad de parar y otorga 4 p. de poder de ataque por cada punto de tu habilidad de defensa por encima de ( 60 * 5) p. Dura más por cada punto de combo:\n\n 1 punto: 14 s\n 2 puntos: 18 s\n 3 puntos: 22 s\n 4 puntos: 26 s\n 5 puntos: 30 s\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208772] = {name = "[q2]Runa de Sablazo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus guantes con la runa Sablazo:\n\n\nCortas a un enemigo con violencia, le infliges un 100% de daño con arma y haces que tu objetivo sangre (Attack power * 5 / 100) p. de daño cada 2 s durante 12 s. Este efecto se acumula hasta 3 veces. Cada acumulación aumenta un 50% el daño infligido por tu Sablazo y Golpe siniestro. Otorga 1 $lp. de combo.\n\n Sablazo se beneficia de todos los talentos y efectos que se activan con Golpe siniestro o que lo modifican.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208773] = {name = "Arpón de pesca", additional_info = "Se liga al recogerlo\nClases: Guerrero , Cazador\n[q2]Uso: Lanza un arpón al objetivo (alcance: 40 m)\n[q]\"¡Un artículo infaltable para todo aspirante a cazador de tiburones!\""},
[208777] = {name = "[q2]Runa del Francotirador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus pantalones con la runa Instrucción de francotirador:\n\n\nAumenta un 2% la probabilidad de golpe crítico de tus habilidades de Disparo mientras no te hayas movido durante los últimos 2 s, y se acumula por segundo hasta un máximo de 5 veces. Al alcanzar 2 acumulaciones o más, tu Disparo de puntería se vuelve instantáneo. Si te mueves, perderás 1 acumulación por segundo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208778] = {name = "[q2]Runa de Golpe rápido", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus guantes con la runa Golpe rápido:\n\n\nUn ataque imprudente instantáneo cuerpo a cuerpo con tu arma de dos manos inflige de (Attack power * 30 / 100) a (Attack power * 40 / 100) p. de daño físico. Esta habilidad se beneficia de todos los efectos vinculados con Golpe heroico y los activa.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208799] = {name = "[q2]Notas de hechizo: Bomba viva", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus guantes con la runa Bomba viva:\n\n\nEl objetivo se convierte en una Bomba viva que recibe [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4] p. de daño de Fuego durante 12 s. Después de 12 s o cuando se disipa el hechizo, el objetivo explota e inflige [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100] p. de daño de Fuego a todos los enemigos en un radio de 10 m.\n\n Bomba viva se beneficia de todos los talentos y efectos que activan o modifican Agostar.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[208800] = {name = "Baxtan: Tratado de magias destructivas", additional_info = "Único\n[q]\"Los escritos de un importante mago goblin. Una gran incorporación para la colección de cualquier biblioteca.\""},
[208823] = {name = "Moneda de ofrenda", additional_info = "Se liga al recogerlo\nClases: Sacerdote\n[q2]Uso: Arrójala al pozo para pedir un deseo"},
[208828] = {name = "Recuerdo de un juramento roto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Púa mental:\n\n\nGolpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces.\n[q2]Uso: Te enfocas en el Recuerdo para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de los misterios espirituales de Azeroth."},
[208833] = {name = "Pastel malévolo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q]\"Un postre con una energía siniestra.\""},
[208838] = {name = "[q2]Arcón de Hierro Negro", additional_info = "Se liga al recogerlo\nÚnico\n[q0]Cerrado\n Requiere Abrir cerraduras (1)"},
[208843] = {name = "Tótem de batalla", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Uso: Reta a un tauren a un duelo\n[q]\"Un símbolo de hostilidad entre los miembros de la Horda\""},
[208847] = {name = "Geoda con forma de cráneo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q]\"Probablemente se abra con un buen golpe.\""},
[208848] = {name = "Geoda con forma de cráneo partida", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q]\"La geoda está partida.\"\n[q2]<Click derecho para abrir>"},
[208849] = {name = "[q2]Tratado sobre bendiciones", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nClases: Paladín\n[q2]Graba tu pechera con la runa Suelo santo:\n\n\nTu Consagración ahora también sana un 200% del valor de daño de Consagración a los miembros del grupo dentro del área.\n[q]\"Aprendes una nueva habilidad después de bendecir a 5 jugadores diferentes.\""},
[208851] = {name = "[q2]Tratado sobre justicia", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nClases: Paladín\n[q2]Graba tus guantes con la runa Mano de expiación:\n\n\nProvocas al objetivo para que te ataque, pero no tiene efecto si el objetivo ya te está atacando.\n\n Cuando conoces esta habilidad, la bonificación de amenaza de Furia recta aumenta a 80% y cuando te sanan otros, Furia recta hace que obtengas una cantidad de maná equivalente a un 25% de la cantidad sanada. Además, mientras Furia recta está activa, el daño que deje tu salud por debajo del 35% se reduce un 20%. Furia recta permanecerá activa hasta que se cancele.\n[q]\"Aprendes una nueva habilidad después de matar a 10 enemigos aturdidos por Martillo de justicia\""},
[208853] = {name = "[q2]Notas de hechizo: Congelación cerebral", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\nRequiereGrabado\n(1)\n[q2]Graba tus botas con la runa Congelación cerebral:\n\n\nTus hechizos de daño de Escarcha con efectos de enfriamiento tienen un 20% de probabilidad de hacer que tu siguiente hechizo Bola de Fuego, Descarga de fríoarcano, Descarga de fuego fardo o Descarga de Pirofrío sea instantáneo y no cueste maná.\n[q]\"Te enseña una nueva habilidad de tallado rúnico.\""},
[208854] = {name = "[q2]Notas de hechizo masticadas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado.\n[q]\"Los chamanes trogg sin duda son unos lectores voraces.\""},
[208855] = {name = "Carnada de atún blanco arco iris", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Alimenta al objetivo con carnada.\n[q]\"Un bocado delicioso para monstruos del lago\""},
[208860] = {name = "Rumi de Gnomeregan: Obras completas", additional_info = "Único\n[q]\"Los escritos de una importante maga gnoma. Una gran incorporación para la colección de cualquier biblioteca.\""},
[209027] = {name = "Bocados de cangrejo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador , Druida\n[q2]Uso: Alimenta al objetivo con un bocadillo.\n[q]\"Los fúrbolgs los usan para atrapar reptadores de arrecife jóvenes.\""},
[209028] = {name = "[q2]Notas de hechizo: OVMA BIVAB", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado."},
[209029] = {name = "Mensaje de Emily", additional_info = "Se liga al recogerlo\nClases: Pícaro\n[q2]<Click derecho para leer>"},
[209030] = {name = "Llave de alijo con equipamiento", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro"},
[209031] = {name = "Sobre discreto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]<Click derecho para abrir>"},
[209041] = {name = "Semillas de calabaza mágica", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Plantar semillas de calabaza\n[q]\"Necesita un suelo especial y comida para crecer.\""},
[209042] = {name = "Harina de hueso de pescado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"¡Tan nutritivo como apestoso! Muy bueno como fertilizante.\""},
[209043] = {name = "Muestra de tierra fértil", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"Cosechada por alguien que realmente conoce la tierra.\""},
[209045] = {name = "Alma del mar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Brujo"},
[209047] = {name = "Arpón nudoso", additional_info = "Se liga al recogerlo\nClases: Guerrero , Cazador\n[q2]Uso: Lanza un arpón al objetivo (alcance: 40 m)\n[q]\"Solo la sangre del trillador más grande puede saciar su sed\""},
[209056] = {name = "Piezas de repuesto de segador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago , Brujo\n[q2]Uso: Combina piezas de repuesto de segador con un núcleo elemental para crear un prototipo de motor."},
[209057] = {name = "Prototipo de motor", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago , Brujo\n[q2]Uso: Se instala en prototipo de segador de la cosecha."},
[209058] = {name = "Núcleo elemental", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago , Brujo\n[q2]Uso: Combina piezas de repuesto de segador con un núcleo elemental para crear un prototipo de motor."},
[209059] = {name = "Anca de dentosangre", additional_info = "Único\nClases: Cazador\n[q2]Uso: Coloca un cebo cerca de la morada de un coyote"},
[209418] = {name = "[q3]Armadura tortuga adamantina", additional_info = "Se liga al recogerlo\n{Pecho} {Malla}\n[q2]338 armadura\n+11 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 25"},
[209420] = {name = "[q2]Azotebranquias", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{18 - 34 p. de daño} {Velocidad 2.60}\n(10.00 p. de daño por segundo)\nDurabilidad 60 / 60\nClases: Guerrero\nNecesitas ser de nivel 14\n[q]\"Un arma encantada que supuestamente cosecha las almas de los múrlocs asesinados\""},
[209421] = {name = "[q3]Cordón de Aquanis", additional_info = "Se liga al recogerlo\n{Cintura} {Cuero}\n58 armadura\n+7 agilidad\n+4 aguante\n+7 espíritu\nDurabilidad 35 / 35\nNecesitas ser de nivel 25"},
