[209424] = {name = "[q3]Barrera de placas de caparazón", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n661 armadura\n14 bloqueo\n+12 fuerza\nDurabilidad 100 / 100\nNecesitas ser de nivel 25"},
[209432] = {name = "[q3]Cincho de Ghamoo-ra", additional_info = "Se liga al recogerlo\n{Cintura} {Tela}\n27 armadura\n+8 aguante\n+8 intelecto\nDurabilidad 30 / 30\nNecesitas ser de nivel 25"},
[209436] = {name = "[q3]Diente roto de Serra'kis", additional_info = "Se liga al recogerlo\n{Una mano} {Daga}\n{29 - 55 p. de daño} {Velocidad 1.80}\n(23.33 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 25\n[q2]Probabilidad al acertar: Envenena al objetivo infligiendo 4 p. de daño de Naturaleza cada 2 s durante 20 s.\n[q]\"Esta daga parece gastada, pero su filo sigue intacto.\""},
[209523] = {name = "[q3]Manteo de trillador fulgurante", additional_info = "Se liga al recogerlo\nEspalda\n24 armadura\n+6 fuerza\n+6 espíritu\nNecesitas ser de nivel 25"},
[209524] = {name = "[q3]Ataduras de Serra'kis", additional_info = "Se liga al recogerlo\nMuñeca Cuero\n[q2]75 armadura\n+6 fuerza\n+4 aguante\nDurabilidad 35 / 35\nNecesitas ser de nivel 25"},
[209525] = {name = "[q3]Talwar aguaoscura afilado", additional_info = "Se liga al recogerlo\n{Mano derecha} {Espada}\n{43 - 82 p. de daño} {Velocidad 2.70}\n(23.15 p. de daño por segundo)\nDurabilidad 90 / 90\nNecesitas ser de nivel 25\n[q2]Probabilidad al acertar: Lanza una descarga de las Sombras al enemigo, lo que le inflige 30 p. de daño de las Sombras."},
[209527] = {name = "[q3]Guanteletes de batalla naga", additional_info = "Se liga al recogerlo\n{Manos} {Cuero}\n[q2]94 armadura\n+6 fuerza\n+4 aguante\n+8 espíritu\nDurabilidad 35 / 35\nNecesitas ser de nivel 25"},
[209534] = {name = "[q4]Arbalesta azshari", additional_info = "Se liga al recogerlo\n{A distancia} {Ballesta}\n{36 - 69 p. de daño} {Velocidad 2.80}\n(18.75 p. de daño por segundo)\nDurabilidad 95 / 95\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 17 p. el poder de ataque a distancia."},
[209559] = {name = "[q3]Cachava de sabio del crepúsculo", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{51 - 78 p. de daño} {Velocidad 2.60}\n(24.81 p. de daño por segundo)\n+5 aguante\n+10 espíritu\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 24 p. la sanación de los hechizos y efectos."},
[209560] = {name = "[q3]Martillo de sentencia recta", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{17 - 32 p. de daño} {Velocidad 1.30}\n(18.85 p. de daño por segundo)\n50 armadura\n+3 fuerza\n+2 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 25"},
[209561] = {name = "[q4]Vara del insomne ancestral", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{37 - 63 p. de daño} {Velocidad 2.00}\n(25.00 p. de daño por segundo)\n+15 intelecto\n+14 espíritu\n+5 resistencia a Sombras\nDurabilidad 120 / 120\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 26 p. el daño y la sanación de los hechizos y efectos mágicos."},
[209562] = {name = "[q4]Golpe mortal de la hidra", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{87 - 132 p. de daño} {Velocidad 3.50}\n(31.29 p. de daño por segundo)\nDurabilidad 120 / 120\nNecesitas ser de nivel 25\n[q2]Probabilidad al acertar: Lanza al objetivo veneno corrosivo ancestral que inflige 20 p. de daño de Naturaleza cada 3 s y reduce la armadura del objetivo 150 p. durante 15 s."},
[209563] = {name = "[q3]Desgarracorazones naga", additional_info = "Se liga al recogerlo\n{A distancia} {Arco}\n{30 - 56 p. de daño} {Velocidad 2.90}\n(14.83 p. de daño por segundo)\n+5 fuerza\nDurabilidad 80 / 80\nNecesitas ser de nivel 25"},
[209564] = {name = "[q3]Tridente de guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Arma de asta}\n{59 - 90 p. de daño} {Velocidad 3.00}\n(24.83 p. de daño por segundo)\n+12 agilidad\n+11 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 25"},
[209565] = {name = "[q3]Sortija de lugares profundos", additional_info = "Se liga al recogerlo\nDedo\n+6 fuerza\n+6 aguante\nNecesitas ser de nivel 25"},
[209566] = {name = "[q3]Leotardos de los fieles", additional_info = "Se liga al recogerlo\n{Piernas} {Malla}\n191 armadura\n+10 fuerza\n+7 agilidad\n+9 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 25"},
[209567] = {name = "[q3]Hacha de arrecife de corales", additional_info = "Se liga al recogerlo\n{Dos manos} {Hacha}\n{65 - 98 p. de daño} {Velocidad 3.30}\n(24.70 p. de daño por segundo)\n+9 aguante\n+13 espíritu\nDurabilidad 100 / 100\nNecesitas ser de nivel 25"},
[209568] = {name = "[q3]Guanteletes de algas", additional_info = "Se liga al recogerlo\n{Manos} {Malla}\n136 armadura\n+10 fuerza\n+3 agilidad\n+4 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 25"},
[209569] = {name = "[q3]Botas altas de pellejo de múrloc", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n71 armadura\n+8 aguante\n+7 intelecto\n+3 espíritu\nDurabilidad 55 / 55\nNecesitas ser de nivel 25"},
[209570] = {name = "[q3]Tomo de conocimiento de la caverna", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n+6 aguante\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q]\"El subtítulo, algo desconcertante, reza: \"Una guía estratégica para explorar a fondo las estrellas\".\""},
[209571] = {name = "[q3]Luz mortecina", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{39 - 75 p. de daño de Arcano} {Velocidad 1.90}\n(30.00 p. de daño por segundo)\n+5 resistencia a Sombras\nDurabilidad 65 / 65\nNecesitas ser de nivel 25"},
[209572] = {name = "[q3]Cueros hervidos negros", additional_info = "Se liga al recogerlo\n{Pecho} {Cuero}\n103 armadura\n+9 agilidad\n+11 aguante\n+7 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 25"},
[209573] = {name = "[q3]Aguja colérica", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{55 - 84 p. de daño} {Velocidad 2.80}\n(24.82 p. de daño por segundo)\n+11 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 17 p. el daño que infligen los hechizos y efectos de Naturaleza.\n[q2]Equipar: Aumenta hasta 26 p. la sanación de los hechizos y efectos."},
[209574] = {name = "[q3]Doctrina descartada de la Mano de Plata", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nNecesitas ser de nivel 25\n[q2]Equipar: +15 p. de poder de ataque al luchar contra no-muertos.\n[q]\"Se ven signos de quemaduras en los bordes de este tomo gastado.\""},
[209575] = {name = "[q3]Ícono de madera a la deriva tallada", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 25\n[q2]Equipar: Restaura 2 p. de maná cada 5 s."},
[209576] = {name = "[q3]Champiñón expandementes", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 25\n[q2]Equipar: +5 p. de espíritu."},
[209577] = {name = "[q3]Puño de lo salvaje", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{44 - 72 p. de daño} {Velocidad 2.80}\n(20.71 p. de daño por segundo)\n60 armadura\n+6 fuerza\n+6 agilidad\n+6 aguante\n+6 intelecto\n+6 espíritu\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Equipar: +59 p. de poder de ataque solo en las formas felina, de oso y de oso temible."},
[209578] = {name = "[q3]Bandas de cuero resplandecientes", additional_info = "Se liga al recogerlo\nMuñeca Cuero\n45 armadura\n+6 espíritu\nDurabilidad 35 / 35\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos."},
[209579] = {name = "[q3]Trueno aplastante", additional_info = "Se liga al recogerlo\n{Mano derecha} {Arma de puño}\n{18 - 35 p. de daño} {Velocidad 1.40}\n(18.93 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 25\n[q2]Probabilidad al acertar: Descarga una mota de trueno que inflige 15 p. de daño de Naturaleza."},
[209580] = {name = "[q3]Racha de viento", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Arma de puño}\n{21 - 38 p. de daño} {Velocidad 1.40}\n(21.07 p. de daño por segundo)\nDurabilidad 60 / 60\nNecesitas ser de nivel 25\n[q2]Probabilidad al acertar: Desata una racha de viento que inflige 15 p. de daño de Naturaleza."},
[209581] = {name = "[q3]Escarpes de la Mano de Plata", additional_info = "Se liga al recogerlo\n{Pies} {Malla}\n150 armadura\n+9 fuerza\n+5 agilidad\n+4 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 25"},
[209590] = {name = "[q3]Globo de agua rajado", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n+4 intelecto\n+5 espíritu\n+5 resistencia a Escarcha\nNecesitas ser de nivel 25"},
[209608] = {name = "Llave esqueleto del capitán", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Abre el cofre del capitán calado."},
[209611] = {name = "[q3]Insignia de la Alianza", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Cazador\n[q2]Uso: Elimina los efectos de inmovilización, ralentización y Aturdir. (5 Min Reutilización)"},
