[209613] = {name = "[q3]Insignia de la Alianza", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Sacerdote\n[q2]Uso: Elimina los efectos de miedo, Polimorfia y aturdimiento. (5 Min Reutilización)"},
[209614] = {name = "[q3]Insignia de la Alianza", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Paladín\n[q2]Uso: Elimina los efectos de miedo, Polimorfia y aturdimiento. (5 Min Reutilización)"},
[209615] = {name = "[q3]Insignia de la Alianza", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Brujo\n[q2]Uso: Elimina los efectos de Embelesar, Miedo y Polimorfia. (5 Min Reutilización)"},
