[209843] = {name = "Almanaque de Nar'thalas, vol. 74", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Investigación arcana sobre los antiguos quel'dorei. Una gran incorporación para la colección de cualquier biblioteca.\""},
