[209846] = {name = "Secretos de los soñadores", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Observaciones e indagaciones sobre el Sueño Esmeralda. Una gran incorporación para la colección de cualquier biblioteca.\""},
[209847] = {name = "Manual de sistemas arcánicos", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Consejos de resolución de problemas poco prácticos para tecnologías goblin. Una gran incorporación para la colección de cualquier biblioteca.\""},
[209848] = {name = "Pergaminos Goaz", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"A pesar de haber sido escrito en el idioma perdido de los titanes, es una gran incorporación para la colección de cualquier biblioteca.\""},
[209849] = {name = "Crímenes contra la anatomía", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Escrito por el doctor Krastinov. Una dudosa incorporación para la colección de cualquier biblioteca.\""},
[209850] = {name = "Runa de los Reyes hechiceros", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una reliquia de los poderosos imperios de ogros de Draenor. Una gran incorporación para la colección de cualquier biblioteca.\""},
[209851] = {name = "Furia de la tierra", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Secretos chamánicos celosamente guardados del clan Tótem Siniestro. Una gran incorporación para la colección de cualquier biblioteca.\""},
[209852] = {name = "[q2]Runa de Matar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus pantalones con la runa Disparo mortal:\n\n\nTratas de rematar a un objetivo herido con un disparo a larga distancia que inflige un 100% de daño con arma y luego [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] p. de daño. Disparo mortal no tiene alcance mínimo. El tiempo de reutilización de Disparo mortal se restablece si se usa contra un enemigo que tiene un 20% de salud o menos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[209872] = {name = "Yelmo de matadragones", additional_info = "Se liga al recogerlo\nÚnico"},
[209873] = {name = "Escudo de matadragones", additional_info = "Se liga al recogerlo\nÚnico"},
[209874] = {name = "Lanza de matadragones", additional_info = "Se liga al recogerlo\nÚnico"},
[210015] = {name = "[q2]Runa de Arremetida enfurecida", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu pechera con la runa Arremetida enfurecida:\n\n\nUn golpe feroz que inflige un 115% de daño con arma, pero que solo se puede usar cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas. Las demás habilidades cuerpo a cuerpo que se usan cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas reducen 1 s el tiempo de reutilización restante de Arremetida enfurecida.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210026] = {name = "Símbolo del tercer búho", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"Has perfeccionado el dominio del mar.\""},
[210043] = {name = "Símbolo del segundo búho", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"El alma de Agon finalmente está en paz.\""},
[210044] = {name = "Símbolo del primer búho", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q]\"La marca de un verdadero guardián.\""},
[210045] = {name = "Sombrahoja", additional_info = "Objeto de misión"},
[210053] = {name = "Pata de lobo temible", additional_info = "Objeto de misión"},
[210055] = {name = "Huesos de humano de Trabalomas", additional_info = "Objeto de misión"},
