[210137] = {name = "[q2]Runa de Crecimiento salvaje", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus guantes con la runa Crecimiento salvaje:\n\n\nRestablece [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo durante 7 s. La sanación se aplica rápidamente al principio y luego más lentamente, cuando el Crecimiento salvaje alcanza su duración máxima.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210138] = {name = "Artillería Hierro Negro", additional_info = nil},
[210146] = {name = "Turbocargador de trituradora", additional_info = nil},
[210147] = {name = "Unidad de autorreciclaje de trituradora", additional_info = "[q2]Uso: Rebusca en los restos de la trituradora en busca de partes para reciclar."},
[210177] = {name = "Ataeric: Tratado de curiosidades arcanas", additional_info = "Único\n[q]\"Los escritos de un importante archimago del Kirin Tor. Una gran incorporación para la colección de cualquier biblioteca.\""},
[210178] = {name = "[q2]Esquema: Unidad de autorreciclaje de trituradora", additional_info = "Requiere Ingeniería (135)"},
[210179] = {name = "[q2]Notas de hechizo: ILMEGAI SARRBES", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Traduce las notas del hechizo para obtener una nueva fórmula de tallado rúnico. Requiere una referencia para interpretar la clave del autor."},
[210183] = {name = "Cuerno de Xelthos", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Emite un tono suave y cautivador.\""},
[210186] = {name = "Carga destructora", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Abre una puerta pesada, ¡al estilo goblin!"},
[210187] = {name = "Pedido de Ventura y Cía.", additional_info = "Se liga al recogerlo\nÚnico"},
[210188] = {name = "[q0]Pedido desgarrado", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Parece que sufrió daños en combate.\""},
[210195] = {name = "[q2]Ídolo desequilibrado", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\nNecesitas ser de nivel 10\n[q2]Uso: Equilibra el poder lunar, el poder del Sueño Esmeralda y el poder salvaje para aprender una habilidad nueva."},
[210209] = {name = "Llave gemela", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro"},
[210210] = {name = "[q0]Certificado de fundador de Industrias Defensivas Grizzwerks", additional_info = "[q]\"La letra pequeña deja perfectamente en claro que este certificado no tiene ningún valor de mercado ni confiere ninguna habilitación legal. Tal vez un comerciante lo compre si tapas esa parte con el pulgar.\""},
[210212] = {name = "Media llave de hermano", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina las mitades de las llaves hermanas."},
[210213] = {name = "Media llave de hermana", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina las mitades de las llaves hermanas."},
[210229] = {name = "[q2]Runa de Mutilación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus guantes con la runa Mutilar:\n\n\nAtacas instantáneamente con ambas armas e infliges 95% de daño con arma más [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100] p. adicionales con cada arma. El daño aumenta un 20% frente a objetivos envenenados. Otorga 2 p. de combo.\n\n Mutilar se beneficia de todos los talentos y efectos que se activan con Puñalada o que la modifican a menos que se explicite lo contrario.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210250] = {name = "Anillo de oro con inscripción", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n[q]\"La inscripción dice: Cuando __ estén __ los __ arrodíllense __ la __ del __.\""},
[210251] = {name = "Anillo de plata con inscripción", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n[q]\"La inscripción dice: __ ambos __ usando __ anillos, __ ante __ estatua __ cementerio.\""},
[210252] = {name = "[q2]Runa de Puyazo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus guantes con la runa Degollador:\n\n\nTus habilidades Emboscada, Puñalada y Garrote ya no requieren que estés detrás de tu objetivo, y Puñalada tiene una probabilidad de 15% de hacer que tu siguiente Emboscada en 10 s no requiera que estés en sigilo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210253] = {name = "[q2]Tótem de podredumbre", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Llama los espíritus de los elementos.\n[q]\"Un tótem tradicional... nudoso y enroscado por la magia negra, se parece poco a los que tienen las propiedades de comulgar con los elementos.\""},
[210322] = {name = "[q2]Runa de Veneno", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus pantalones con la runa Envenenar:\n\n\nRemate que inflige daño de veneno de forma instantánea según las dosis de Veneno mortal sobre el objetivo. Tras el ataque de Envenenar, aumenta un 75% la frecuencia de aplicación de Veneno instantáneo durante 1 s, y se agrega 1 s adicional por cada punto de combo. Se activa una dosis por cada punto de combo:\n 1 dosis: Â [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 1 + Attack power * 0.072] p. de daño\n 2 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Attack power * 0.144] p. de daño\n 3 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Attack power * 0.216] p. de daño\n 4 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Attack power * 0.288] p. de daño\n 5 dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Attack power * 0.36] p. de daño\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210323] = {name = "Combinación de caja fuerte", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q]\"0-4-5-1\""},
[210329] = {name = "Mapa del tesoro de Trabalomas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q]\"Sigue el río hacia el norte, más allá de las Montañas de Alterac. Lo que buscas se encuentra debajo de los rápidos en caída.\""},
[210330] = {name = "Información valiosa", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Toda buena información tiene su precio.\"\n[q2]<Click derecho para abrir>"},
[210410] = {name = "Cebo de mordedor de agua fresca", additional_info = "Clases: Cazador\n[q2]Uso: Arroja un cebo. (5 Min Reutilización)\n[q]\"¡Arrójalo al agua para atraer algo enorme!\""},
[210499] = {name = "Champiñón de pantano", additional_info = "[q2]Uso: Come (si te atreves)."},
[210500] = {name = "[q2]Runa de las Estrellas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus pantalones con la runa Oleada de estrellas:\n\n\nLanza oleadas de energías estelares que infligen de [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1 * 1)] a [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1 * 1)] p. de daño Arcano y aumenta el daño infligido por tus próximos lanzamientos de 1 Fuego estelar en un 80 % por 15 s.\n\n Oleada de estrellas se beneficia de la mayor parte de los talentos y efectos que se activan o benefician de Cólera o Fuego estelar y también los activa.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210534] = {name = "[q2]Ídolo de las fieras", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\n[q2]Graba tu pechera o tu toga con la runa Golpes feroces:\n\n\nCuando estás en Forma felina, de oso o de oso temible, los miembros del grupo o banda en un radio de 100 m obtienen mayor ferocidad de combate. Cada golpe cuerpo a cuerpo tiene un 20% de probabilidad de otorgar un ataque extra al atacante con un 20% de poder de ataque extra. No tiene efecto si el objetivo ya se ha beneficiado de Tótem Viento Furioso.\n[q]\"Sana a 10 bestias diferentes y usa este ídolo para aprender una habilidad nueva.\""},
[210568] = {name = "Filacteria decrépita", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un aura hedionda emana del artefacto.\""},
[210569] = {name = "[q2]Runa de Flagelación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu pechera con la runa Flagelación:\n\n\nObtienes ira del daño físico recibido como si no tuvieras armadura.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210573] = {name = "[q2]Runa de Ira acuciante", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus pantalones con la runa Consumido por la ira:\n\n\nTe enfurece (lo que activa las habilidades que requieren ese estado) durante 12 s después de que superas los 60 p. de ira. Además, Torbellino también golpea con armas cuerpo a cuerpo de mano izquierda cuando estás enfurecido.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210589] = {name = "[q2]Eco de los ancestros", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus pantalones con la runa Guía ancestral:\n\n\nDurante los próximos 10 s, un 25% de tu daño se convierte en sanación para un máximo de 3 miembros de grupo cercanos, y un 100% de tu sanación se convierte en daño contra tu objetivo de Choque de llamas más reciente.\n[q]\"Aprendes una nueva habilidad de grabado.\""},
[210596] = {name = "[q2]Runa de Golpes de cobra", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tu pechera o tu toga con la runa Golpes de cobra:\n\n\nLos golpes críticos de tus habilidades de disparo, golpe y Mordedura de mangosta hacen que los 2 siguientes ataques especiales de tu mascota sean golpes críticos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210653] = {name = "[q2]Runa de Guardamano", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus guantes con la runa Daga de guardamano:\n\n\nAtacas instantáneamente con tu arma de la mano izquierda para infligir daño con arma normal, y tu probabilidad de parar un ataque aumenta un 100% durante 5 s o hasta que paras un ataque de manera exitosa. Durante 20 s, después de usar Daga de guardamano, Golpe siniestro cuesta 20 p. menos de energía, genera un 50% más de amenaza, otorga acumulaciones de Bravura ante los golpes y tanto Golpe siniestro como Eviscerar infligen un 50% más de daño. Otorga 1 p. de combo.\n\n Daga de guardamano se beneficia de la mayoría de los talentos y efectos que se activan con Golpe siniestro o lo modifican. El efecto de Daga de guardamano no debilitará ni potenciará Daga de guardamano.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210654] = {name = "[q2]Notas de hechizo: Retroceder el tiempo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus brazales con la runa Retroceder en el tiempo:\n\n\nTu objetivo actual con tu Faro temporal se sana inmediatamente de todo el daño recibido durante los últimos 5 segundos. Es ineficaz contra objetivos que no tenían un Faro temporal hace 5 segundos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210655] = {name = "[q2]Notas de hechizo: MERLONECTEOR PERDIETE", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado."},
[210665] = {name = "Mota de ira torrencial", additional_info = "Se liga al recogerlo\nÚnico"},
[210667] = {name = "Mota de ira infernal", additional_info = "Se liga al recogerlo\nÚnico"},
[210668] = {name = "Mota de ira sísmica", additional_info = "Se liga al recogerlo\nÚnico"},
[210696] = {name = "[q2]Azote de podredumbre", additional_info = "Se liga al recogerlo\n{Mano derecha} {Espada}\n{18 - 34 p. de daño} {Velocidad 2.60}\n(10.00 p. de daño por segundo)\nDurabilidad 60 / 60\nClases: Guerrero\nNecesitas ser de nivel 14\n[q]\"La hoja está cubierta de sangre y ya no brilla en la luz, sino que sirve como advertencia...\""},
[210708] = {name = "Elixir de remordimientos fusionados", additional_info = "Necesitas ser de nivel 20\n[q2]Uso: Permite a quien lo ingiere hablar con el cadáver de un individuo con asuntos pendientes en el mundo mortal. También puede curar la indigestión. (3 Seg Reutilización)"},
[210709] = {name = "[q2]Receta: Elixir de remordimientos fusionados", additional_info = "Requiere Alquimia (90)\n[q2]Uso: Te enseña a hacer un elixir de remordimientos fusionados.\nElixir de remordimientos fusionados\nNecesitas ser de nivel 20\n[q2]Uso: Permite a quien lo ingiere hablar con el cadáver de un individuo con asuntos pendientes en el mundo mortal. También puede curar la indigestión. (3 Seg Reutilización)\nRequiere Alga estranguladora (5), Vial emplomado , Musgo de tumba (5), Polvo de alma"},
[210712] = {name = "Elixir de conocimiento", additional_info = "Se liga al recogerlo\n[q2]Uso: Contempla una visión en la fogata de Je'neu."},
[210713] = {name = "Alma torturada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Realiza una Ofrenda de sangre para liberar a esta alma torturada."},
[210724] = {name = "Bastón de Hirzek", additional_info = "Se liga al recogerlo"},
[210741] = {name = "[q3]Moledora automática de muchedumbre", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{53 - 85 p. de daño} {Velocidad 2.00}\n(34.50 p. de daño por segundo)\n+22 fuerza\n+8 agilidad\nDurabilidad 100 / 100\nClases: Paladín , Chamán , Druida\nNecesitas ser de nivel 40\n[q2]Equipar: +69 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Uso: Aumenta tu velocidad de ataque un 50% durante 30 s. No afecta a personajes de nivel 55 o más. (3 Min Reutilización)\n[q]\"Se han realizado distintas mejoras para aumentar la facilidad de uso del modelo de este año.\""},
[210746] = {name = "[q2]Runa de Escudo de tierra", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus pantalones con la runa Escudo de tierra:\n\n\nProtege al objetivo con un escudo de tierra que reduce el tiempo perdido de lanzamiento o canalización cuando recibe un 30% de daño y provoca que los ataques sanen [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100] p. al objetivo escudado. Este efecto solo puede ocurrir una vez cada pocos segundos. 9 cargas. Dura 10 min. Escudo de tierra solo puede utilizarse en un objetivo a la vez.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210763] = {name = "Rama de Altek", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un fragmento de poder astillado. Parece que en otra época fue la mitad de un arma poderosa.\""},
[210765] = {name = "Orbe de Des", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"En el interior del orbe se puede ver cómo se arremolinan llamas y magia oscura. Una imagen hipnotizante e inquietante a la vez. Parece que en otra época fue la mitad de un arma poderosa.\""},
[210771] = {name = "[q2]Suministros faltantes: Barras de cobre", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 barras de cobre para completar este cargamento."},
[210772] = {name = "[q2]Cargamento de suministros: Barras de cobre", additional_info = "Se liga al recogerlo\nÚnico: [Supply Shipment] (1)\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[210773] = {name = "[q3]Manto de la Segunda Guerra", additional_info = "Se liga al equiparlo\n{Hombro} {Malla}\n163 armadura\n+8 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 11 p. el daño que infligen los hechizos y efectos Sagrados."},
[210779] = {name = "[q2]Diseño: Manto de la Segunda Guerra", additional_info = "Se liga al recogerlo\nRequiere Herrería (150)\n[q2]Uso: Te enseña a confeccionar un manto de la Segunda Guerra.\n[q3]Manto de la Segunda Guerra\nSe liga al equiparlo\n{Hombro} {Malla}\n163 armadura\n+8 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 11 p. el daño que infligen los hechizos y efectos Sagrados.\nRequiere Barra de bronce (20), Ágata musgosa (2), Piedra lunar inferior (2), Perla iridiscente (2), Barra de plata (4)"},
[210781] = {name = "[q3]Ataduras de fénix", additional_info = "Se liga al equiparlo\nMuñeca Tela\n21 armadura\nDurabilidad 30 / 30\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 13 p. el daño que infligen los hechizos y efectos de Fuego."},
[210794] = {name = "[q4]Coraza de plata cambiante", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Void-Touched] (1)\n{Pecho} {Malla}\n238 armadura\n+12 fuerza\n+5 aguante\nDurabilidad 145 / 145\nNecesitas ser de nivel 25\nRequiere Herrería (100)\n[q2]Equipar: Este objeto está imbuido de puro poder del Vacío. Cuando el portador recibe un ataque, este objeto tiene una alta probabilidad de infligir una maldición que hace que el atacante reciba daño adicional de todas las fuentes durante 15 s. (Probabilidad de que accione: 25%)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[210795] = {name = "[q4]Botas de seda de araña extrabidimensionales", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Void-Touched] (1)\n{Pies} {Tela}\n35 armadura\n+5 aguante\n+5 intelecto\n+6 espíritu\nDurabilidad 50 / 50\nNecesitas ser de nivel 25\nRequiere Sastrería (100)\n[q2]Uso: Entra temporalmente en otro plano de existencia, lo que reduce instantáneamente la amenaza y todo el daño recibido e infligido un 30% durante 6 s. (10 Min Reutilización)\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[210811] = {name = "[q2]Runa de Furia primordial", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus pantalones con la runa Lobo fantasmal superior:\n\n\nAhora puedes usar tu habilidad Lobo fantasmal en interiores, y reduce todo el daño que recibes un 10% mientras está activa.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210817] = {name = "[q2]Runa de Supervivencia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu pechera o toga con la runa Supervivencia del más fuerte:\n\n\nReduce un 6% la probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo y reduce un 10% todo el daño recibido. El daño recibido se reduce un 10% más cuando estás en Forma de oso o Forma de oso temible.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210818] = {name = "[q2]Runa de Lobo solitario", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tu pechera o toga con la runa Lobo solitario:\n\n\nInfliges un 25% más de daño con todos tus ataques cuando no tienes una mascota activa.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210820] = {name = "[q2]Runa de Sacrificio", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus pantalones con la runa Mano de sacrificio:\n\n\nHace que el miembro del grupo o banda transfiera un 30% del daño recibido al taumaturgo. Dura 12 s o hasta que el taumaturgo haya transferido un 100% de su salud máxima.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210822] = {name = "[q2]Epifanía armoniosa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu pechera o toga con la runa Serendipia:\n\n\nSanar con Sanación relámpago reduce un 20% el tiempo de lanzamiento de tu siguiente Sanación inferior, Sanar, Sanación superior o Rezo de sanación durante 20 s. Se acumula hasta 3 veces.\n[q]\"Aprendes una nueva habilidad de grabado.\""},
[210823] = {name = "[q2]Runa de Especialización en doble empuñadura", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu pechera o tu toga con la runa Especialización en doble empuñadura:\n\n\nCuando usas dos armas, aumenta un 5% tu probabilidad de golpear con ataques de hechizos y cuerpo a cuerpo, y tu habilidad Golpe de tormenta ahora golpea con ambas armas. También aumenta un 60% el daño que inflige tu arma de mano izquierda.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210824] = {name = "[q2]Runa del Pacto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus pantalones con la runa Pacto demoníaco:\n\n\nTus hechizos de Fuego y Sombras infligen un 10% más de daño, y los golpes críticos de tu mascota aplican el efecto de Pacto demoníaco a los miembros de tu grupo o banda durante 45 s. Pacto demoníaco aumenta el daño con hechizos y la sanación un 10% de tu daño con hechizos o ( 60 / 2) p., el valor que sea más alto. No funciona sobre demonios subyugados.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210825] = {name = "[q2]Runa del Belisario", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210953] = {name = "Ojo de Bhossca", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Aunque el ojo no tiene vida, te sientes observado...\""},
[210955] = {name = "Uniforme de iniciado Escarlata", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te disfrazas como un miembro de la Cruzada Escarlata. La actividad sospechosa te dejará al descubierto."},
[210963] = {name = "Llave del arúspice", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro"},
[210966] = {name = "Sangre de la Legión", additional_info = "Objeto de misión\nÚnico (10)\n[q]\"Oscura y espesa... Esta sangre es parte del linaje de grandes comandantes de la legión.\""},
[210967] = {name = "Mensaje confidencial", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]<Click derecho para leer>"},
[210968] = {name = "Llave de relicario", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro"},
[210979] = {name = "[q2]Runa de Paso de las sombras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu cinturón con la runa Paso de las Sombras:\n\n\nIntenta dar un paso en las sombras y reaparecer detrás de tu enemigo. Aumenta la velocidad de movimiento un 70% durante 3 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[210980] = {name = "[q2]Runa de Metamorfosis", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211205] = {name = "[q2]Runa de Matacobras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus guantes con la runa Matacobras:\n\n\nMordedura de mangosta ahora tiene un 10% de probabilidad de activarse en cada uno de tus ataques cuerpo a cuerpo, y un 100% de probabilidad cuando un enemigo esquiva. Esta probabilidad se acumula, y aumenta un 10% por cada ataque subsiguiente si no se restablece. Mordedura de mangosta también inflige daño adicional equivalente a un 45% de tu poder de ataque.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211247] = {name = "[q2]Patrón: ataduras de fénix", additional_info = "Se liga al recogerlo\nRequiere Sastrería (125)\n[q2]Uso: Te enseña a confeccionar ataduras de fénix.\n[q3]Ataduras de fénix\nSe liga al equiparlo\nMuñeca Tela\n21 armadura\nDurabilidad 30 / 30\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 13 p. el daño que infligen los hechizos y efectos de Fuego.\nRequiere Madeja de paño de lana (6), Frasco de aceite (2), Hilo refinado (2)"},
[211263] = {name = "[q0]Coselete de sentencia", additional_info = "Se liga al recogerlo\n{Pecho} {Placas}\n857 armadura\n+17 fuerza\n+25 aguante\n+20 intelecto\n+10 resistencia a Fuego\n+10 resistencia a Naturaleza\nDurabilidad 165 / 165\nClases: Paladín\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 6 p. el índice de defensa.\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 32 p.\n\n[q]Baluarte de sentencia (0/1)\n[q0]Coselete de sentencia\n[q0](3) Conjunto : Tu Aura de devoción también reduce el daño con hechizos recibido un 5%.\n(5) Conjunto : Sentencia genera un 50% más de amenaza contra su objetivo.\n(8) Conjunto : Aumenta hasta 47 p. el daño y la sanación de los hechizos y efectos mágicos."},
[211269] = {name = "Ilustración primitiva", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión"},
[211301] = {name = "[q2]Runa de Exponer debilidad", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tu cinturón con la runa Exponer debilidad:\n\n\nTus golpes críticos cuerpo a cuerpo y a distancia aumentan tu poder de ataque un monto equivalente al 40% de tu agilidad actual durante 7 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211315] = {name = "[q2]Suministros faltantes: Cuero ligero", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 14 cueros ligeros para completar este cargamento."},
[211316] = {name = "[q2]Suministros faltantes: Flor de paz", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 flores de paz para completar este cargamento."},
[211317] = {name = "[q2]Suministros faltantes: Hojaplata", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 unidades de hojaplata para completar este cargamento."},
[211318] = {name = "[q2]Suministros faltantes: Pociones de sanación menores", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 pociones de sanación menores para completar este cargamento."},
[211319] = {name = "[q2]Suministros faltantes: Espadas cortas de cobre", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 6 espadas cortas de cobre para completar este cargamento."},
[211320] = {name = "[q2]Suministros faltantes: Pantalones rúnicos de cobre", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 3 pantalones rúnicos de cobre para completar este cargamento."},
[211321] = {name = "[q2]Suministros faltantes: Varitas mágicas inferiores", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 2 varitas mágicas inferiores para completar este cargamento."},
[211322] = {name = "[q2]Suministros faltantes: Aceite de zahorí menor", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 2 aceites de zahorí menores para completar este cargamento."},
[211323] = {name = "[q2]Suministros faltantes: Bombas de cobre férreas", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 12 bombas de cobre férreas para completar este cargamento."},
[211324] = {name = "[q2]Suministros faltantes: Bocardas férreas", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 3 bocardas férreas para completar este cargamento."},
[211325] = {name = "[q2]Suministros faltantes: Cinturones de cuero cosidos a mano", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 5 cinturones de cuero cosidos a mano para completar este cargamento."},
[211326] = {name = "[q2]Suministros faltantes: Jubón de cuero estampado", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 3 jubones de cuero estampados para completar este cargamento."},
[211327] = {name = "[q2]Suministros faltantes: Pantalones de lino marrones", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 6 pantalones de lino marrones para completar este cargamento."},
[211328] = {name = "[q2]Suministros faltantes: Togas de lino marrones", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 4 togas de lino marrones para completar este cargamento."},
[211329] = {name = "[q2]Suministros faltantes: Huevos a las finas hierbas", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 huevos a las finas hierbas para completar este cargamento."},
[211330] = {name = "[q2]Suministros faltantes: Carne de lobo especiada", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 unidades de carne de lobo especiada para completar este cargamento."},
[211331] = {name = "[q2]Suministros faltantes: Pececito luminoso", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 20 pececitos luminosos para completar este cargamento."},
[211332] = {name = "[q2]Suministros faltantes: Vendas de lino gruesas", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 10 vendas de lino gruesas para completar este cargamento."},
[211365] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[211367] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[211368] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[211382] = {name = "Bolsa de cartero pequeña", additional_info = "Se liga al recogerlo\nÚnico\nBolsa de 10 casillas"},
[211384] = {name = "[q2]Bolsa de cartero resistente", additional_info = "Se liga al recogerlo\nÚnico\nBolsa de 12 casillas"},
[211385] = {name = "[q2]Runa de Propagación serpentina", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus pantalones con la runa Propagación serpentina:\n\n\nLos objetivos golpeados con tu Multidisparo también son afectados por tu Picadura de serpiente durante 12 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211386] = {name = "[q2]Notas de hechizos: Oleada Arcana", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus pantalones con la runa Oleada Arcana:\n\n\nDesata todo tu maná restante en forma de una oleada de energía concentrada contra el objetivo y le inflige entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100] p. de daño Arcano que aumenta hasta un 300% según tu maná restante. Después se activa tu regeneración de maná normal y aumenta un 300% durante 8 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211387] = {name = "[q2]Runa de Luz de conocimiento", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus guantes con la runa Señal de la Luz:\n\n\nEl objetivo se convierte en una Señal de la Luz para todos los miembros de tu grupo o banda que se encuentren en un radio de 40 m. Cualquier sanación que lances sobre miembros de tu grupo o banda sanará también a la señal un 75% de la cantidad sanada. Solo un objetivo puede ser la Señal de la Luz cada vez. Dura 1 h.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211390] = {name = "[q2]Runa de Heridas superficiales", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu pechera o tu toga con la runa Heridas superficiales:\n\n\nRecibes un 30% menos de daño físico cuando Danza de hojas está activa, y ese daño se reduce un 1% más por cada 12 p. de tu habilidad de defensa por encima de ( 60 * 5)p. Además, tu probabilidad de esquivar se multiplica un 50%, tienes un 6% menos de probabilidad de recibir golpes críticos con ataques cuerpo a cuerpo, infliges un 20% menos de daño, la amenaza que generan tus acciones aumenta notablemente y tu habilidad Amago se reemplaza por Burla, que provoca al objetivo para que te ataque.\n\n\nProvoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211391] = {name = "[q2]Runa de Lluvia de sanación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu pechera o toga con la runa Lluvia de sanación:\n\n\nSelecciona el área de 15 m alrededor del jugador objetivo y sana [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100] p. de salud por s a todos los miembros del grupo del jugador objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211392] = {name = "[q2]Runa de Aflicción eterna", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus pantalones con la runa Aflicción eterna:\n\n\nDrenar vida, Drenar alma, Descarga de las Sombras, Cuchilla de las Sombras, Dolor abrasador, Incinerar y Poseer restablecen la duración de tu Corrupción sobre el objetivo al máximo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211393] = {name = "[q2]Runa de Furia enfilada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus guantes con la runa Furia enfilada:\n\n\nCuando usas dos armas, tu velocidad de movimiento aumenta un 10% y obtienes un 4% de velocidad de ataque cada vez que tu ataque automático cuerpo a cuerpo golpea al mismo objetivo de tu ataque automático anterior. Se acumula un máximo de 5 veces. Dura 10 s o hasta que tu ataque automático golpee a otro objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211419] = {name = "[q2]Montón de escamas cambiantes", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Estas extrañas escamas despiden un brillo tenue, casi como si fueran incorpóreas. Está claro que esconden algún tipo de magia maravillosa... Si tan solo pudieras encontrar a alguien que sepa más de ellas.\""},
[211420] = {name = "[q3]Dije de escamas cambiantes", additional_info = "Se liga al recogerlo\nAbalorio\n+5 espíritu\nNecesitas ser de nivel 25\n[q2]Equipar: Protege al portador de los efectos de Oscuridad aplastante."},
[211421] = {name = "La caja", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Intentas usar una fuente poderosa de la Luz para destruir la caja.\n[q]\"Al tocar la caja con tus propias manos, te invade una repentina sensación de intranquilidad... pero también, una inspiración creativa distinta a cualquier otra cosa que hayas sentido antes.\""},
[211422] = {name = "[q4]Fragmento del Vacío", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Todo lo que queda de la caja es una pequeña esquirla de un cristal perfectamente negro. Parece que atrae y consume la luz.\""},
[211423] = {name = "[q4]Guantes de cuero tocados por el Vacío", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Void-Touched] (1)\n{Manos} {Cuero}\n[q2]110 armadura\n+6 agilidad\n+6 aguante\n+4 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\nRequiere Peletería (100)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Uso: Desciende hacia la locura, aumenta un 10% la velocidad de ataque y la amenaza que generas durante 10 s. (10 Min Reutilización)"},
[211427] = {name = "[q3]Recipiente de alma", additional_info = "[q]\"Atrapa almas de demonios y les roba su poder.\""},
[211443] = {name = "[q2]Hoja de ira", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{31 - 47 p. de daño} {Velocidad 3.50}\n(11.14 p. de daño por segundo)\n50 armadura\n+3 fuerza\nDurabilidad 60 / 60\nNecesitas ser de nivel 13"},
[211444] = {name = "[q2]Capa de invocador", additional_info = "Se liga al recogerlo\nEspalda\n16 armadura\n+3 intelecto\n+1 espíritu\nNecesitas ser de nivel 13"},
[211445] = {name = "[q2]Arco recurvo bárbaro", additional_info = "Se liga al recogerlo\n{A distancia} {Arco}\n{12 - 24 p. de daño} {Velocidad 2.40}\n(7.50 p. de daño por segundo)\nDurabilidad 50 / 50\nNecesitas ser de nivel 13"},
[211447] = {name = "Cargamento de armas", additional_info = "Objeto de misión\nÚnico"},
[211448] = {name = "Contrato de compra firmado", additional_info = "Objeto de misión\nÚnico"},
[211449] = {name = "[q3]Perla del Vacío de vengador", additional_info = "Se liga al recogerlo\nÚnico: [Void Pearl] (1)\nAbalorio\n+10 resistencia a Sombras\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 18 p. el poder de ataque."},
[211450] = {name = "[q3]Perla del Vacío de invocador", additional_info = "Se liga al recogerlo\nÚnico: [Void Pearl] (1)\nAbalorio\n+10 resistencia a Sombras\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos."},
[211451] = {name = "[q3]Perla del Vacío de acólito", additional_info = "Se liga al recogerlo\nÚnico: [Void Pearl] (1)\nAbalorio\n+10 resistencia a Sombras\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 20 p. la sanación de los hechizos y efectos."},
[211452] = {name = "[q3]Perla Brazanegra perfecta", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 25\n[q]\"La sirvienta de los dioses antiguos Aku'mai está muerta. A Bashana Tótem de Runa le interesará escuchar esto.\""},
[211454] = {name = "Globo de agua extraño", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 25"},
[211455] = {name = "[q3]Guantes sin dedos hábiles", additional_info = "Se liga al recogerlo\n{Manos} {Cuero}\n68 armadura\n+7 aguante\n+5 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 22 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Aumenta hasta 14 p. el daño que infligen los hechizos y efectos de Naturaleza."},
[211456] = {name = "[q3]Daga de sacrificio voluntario", additional_info = "Se liga al recogerlo\nÚnico\n{Mano derecha} {Daga}\n{12 - 27 p. de daño} {Velocidad 1.50}\n(13.00 p. de daño por segundo)\n60 armadura\n+4 aguante\n+3 intelecto\nDurabilidad 65 / 65\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos."},
[211457] = {name = "[q3]Faja de defensor del crepúsculo", additional_info = "Se liga al recogerlo\n{Cintura} {Malla}\n128 armadura\n+7 fuerza\n+9 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 4 p. el índice de defensa."},
[211458] = {name = "[q3]Escrito de amparo contra las Sombras", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n40 armadura\n+4 aguante\n+3 intelecto\n+5 resistencia a Sombras\nNecesitas ser de nivel 25"},
[211460] = {name = "[q3]Rodela ártica ancestral", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n725 armadura\n15 bloqueo\n+7 aguante\n+8 espíritu\n+5 resistencia a Escarcha\nDurabilidad 100 / 100"},
[211461] = {name = "[q3]Cetro de lápida grabada", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{35 - 61 p. de daño de Sombras} {Velocidad 1.50}\n(32.00 p. de daño por segundo)\n+1 espíritu\n+5 resistencia a Sombras\nDurabilidad 65 / 65"},
[211462] = {name = "[q3]Anillo de apoyo eterno", additional_info = "Se liga al recogerlo\nDedo\n+3 aguante\n+8 espíritu"},
[211463] = {name = "[q3]Broches de alfazaque estridente", additional_info = "Se liga al recogerlo\nMuñeca Malla\n95 armadura\n+4 agilidad\n+7 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 25"},
[211464] = {name = "[q3]Manteo de prelación usado", additional_info = "Se liga al recogerlo\nEspalda\n24 armadura\n+9 espíritu"},
[211465] = {name = "[q3]Botas Nimbus de perspicacia", additional_info = "Se liga al recogerlo\n{Pies} {Tela}\n34 armadura\n+2 agilidad\n+5 intelecto\n+4 espíritu\nDurabilidad 35 / 35"},
[211466] = {name = "[q3]Faja de duramen del amable", additional_info = "Se liga al recogerlo\n{Cintura} {Cuero}\n57 armadura\n+8 aguante\n+7 espíritu\nDurabilidad 30 / 30"},
[211467] = {name = "[q3]Sortija del puño de hierro", additional_info = "Se liga al recogerlo\nDedo\n+4 fuerza\n+7 agilidad"},
[211468] = {name = "[q3]Manto de castaño raído", additional_info = "Se liga al recogerlo\n{Hombro} {Tela}\n30 armadura\n+2 aguante\n+6 intelecto\nDurabilidad 40 / 40\n[q2]Equipar: Aumenta hasta 5 p. el daño y la sanación de los hechizos y efectos mágicos."},
[211471] = {name = "Llave Fonroca", additional_info = "Único"},
[211472] = {name = "[q2]Tratado sobre destierro", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nClases: Paladín\n[q2]Graba tus pantalones con la runa Maestría en auras:\n\n\nProvoca que tu Aura de concentración haga inmunes ante los efectos de silencio e interrupción a todos los objetivos afectados y mejore el efecto del resto de las auras un 100%. Dura 6 s.\n[q]\"Aprende una nueva habilidad después de lanzar Ahuyentar no-muertos sobre 5 enemigos y matarlos con Exorcismo.\""},
[211476] = {name = "[q2]Runa de Estela de fuego", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu pechera o toga con la runa Lago de fuego:\n\n\nTu Lluvia de fuego ya no se canaliza, pero obtiene un tiempo de reutilización de 8 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211477] = {name = "[q2]Runa de Incineración", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus brazales con la runa Incinerar:\n\n\nQuema a tu enemigo, inflige de [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] a [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)] p. de daño y aumenta todo el daño de Fuego que infliges un 40% durante los próximos 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211482] = {name = "Ofrenda Rompelanzas", additional_info = "Se liga al recogerlo\nÚnico"},
[211487] = {name = "[q2]Explosivos para demoliciones", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Coloca una bomba con una mecha corta en el suelo frente a ti.\n[q]\"Solo parece útil para despejar escombros.\""},
[211488] = {name = "[q2]Runa de Vengador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus pantalones con la runa Escudo de vengador:\n\n\nLanza un escudo Sagrado al enemigo que inflige de [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] a [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell power + 0.091 * Attack power] p. de daño Sagrado, lo deja atontado y salta a los enemigos cercanos. Afecta a un total de 3 objetivos. Dura 5 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211490] = {name = "[q2]Profecía de las mil luces", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus guantes con la runa Círculo de sanación:\n\n\nRestablece de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100] p. de salud a todos los miembros del grupo del jugador objetivo en un radio de 43.5 m del objetivo.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth.\n[q]\"Aprendes una nueva habilidad de grabado.\""},
[211491] = {name = "[q4]Bolsa de piel de múrloc sin fondo", additional_info = "Se liga al recogerlo\nÚnico\nBolsa de 14 casillas"},
[211492] = {name = "[q4]Cartera de Kelris", additional_info = "Se liga al recogerlo\nBolsa de almas de 16 casillas\nClases: Brujo"},
[211498] = {name = "[q3]Sable de la noche de las centinelas de aprendiz", additional_info = "Se liga al recogerlo\nMontura\nRequiere cualquier raza de la Alianza\nNecesitas ser de nivel 25\n[q2]Uso: Invoca un sable de la noche de las centinelas de aprendiz. Solo puede usarse en Vallefresno. (3 Seg Reutilización)"},
[211499] = {name = "[q3]Lobo escolta de aprendiz", additional_info = "Se liga al recogerlo\nMontura\nRequiere cualquier raza de la Horda\nNecesitas ser de nivel 25\n[q2]Uso: Invoca un lobo escolta de aprendiz. Solo puede usarse en Vallefresno. (3 Seg Reutilización)"},
[211500] = {name = "[q3]Cinta de tela resiliente", additional_info = "Se liga al recogerlo\nÚnico\n{Cabeza} {Tela}\n50 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 20\n[q2]Equipar: Reduce un 5% todo el daño recibido y la probabilidad de recibir golpes críticos en Garganta Grito de Guerra."},
[211501] = {name = "[q4]Coselete de poder", additional_info = "Se liga al recogerlo\n{Pecho} {Placas}\n749 armadura\n+27 fuerza\n+18 aguante\n+10 resistencia a Fuego\nDurabilidad 165 / 165\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: Mejora tu probabilidad de golpear un 1%."},
[211502] = {name = "[q4]Guanteletes de cuero tocados por el Vacío", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Void-Touched] (1)\n{Manos} {Cuero}\n70 armadura\n+5 aguante\n+7 intelecto\n+6 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\nRequiere Peletería (100)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Uso: Desciende hacia la locura, aumenta un 10% el daño con hechizos y la amenaza que generas durante 10 s. (10 Min Reutilización)"},
[211504] = {name = "[q3]Anillas de vengador crepuscular", additional_info = "Se liga al recogerlo\n{Pecho} {Malla}\n218 armadura\n+9 fuerza\n+6 agilidad\n+8 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 4 p. el índice de defensa.\n\n[q]Malla de vengador brazanegra (0/3)\n[q0]Botas de vengador crepuscular\nAnillas de vengador crepuscular\nYelmo de vengador crepuscular\n[q0](2) Conjunto : Aumenta 12 p. el poder de ataque.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211505] = {name = "[q0]Yelmo de vengador crepuscular", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n176 armadura\n+9 fuerza\n+11 agilidad\n+3 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 4 p. el índice de defensa.\n\n[q]Malla de vengador brazanegra (0/3)\n[q0]Botas de vengador crepuscular\nAnillas de vengador crepuscular\nYelmo de vengador crepuscular\n[q0](2) Conjunto : Aumenta 12 p. el poder de ataque.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211506] = {name = "[q3]Botas de vengador crepuscular", additional_info = "Se liga al recogerlo\n{Pies} {Malla}\n150 armadura\n+10 fuerza\n+5 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 25\n\n[q]Malla de vengador brazanegra (0/3)\n[q0]Botas de vengador crepuscular\nAnillas de vengador crepuscular\nYelmo de vengador crepuscular\n[q0](2) Conjunto : Aumenta 12 p. el poder de ataque.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211507] = {name = "[q3]Capucha de elementalista crepuscular", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n84 armadura\n+9 aguante\n+10 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 8 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Pellejo de elementalista brazanegra (0/3)\n[q0]Capucha de elementalista crepuscular\nEscarpines de elementalista crepuscular\nToga de elementalista crepuscular\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211508] = {name = "[q3]Escarpines de elementalista crepuscular", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n71 armadura\n+5 agilidad\n+7 intelecto\n+7 espíritu\nDurabilidad 55 / 55\nNecesitas ser de nivel 25\n\n[q]Pellejo de elementalista brazanegra (0/3)\n[q0]Capucha de elementalista crepuscular\nEscarpines de elementalista crepuscular\nToga de elementalista crepuscular\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211509] = {name = "[q0]Toga de elementalista crepuscular", additional_info = "Se liga al recogerlo\n{Pecho} {Cuero}\n103 armadura\n+10 aguante\n+10 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Pellejo de elementalista brazanegra (0/3)\n[q0]Capucha de elementalista crepuscular\nEscarpines de elementalista crepuscular\nToga de elementalista crepuscular\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211510] = {name = "[q3]Capucha de destripador crepuscular", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n84 armadura\n+10 agilidad\n+9 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 14 p. el poder de ataque.\n\n[q]Cuero de destripador brazanegra (0/3)\n[q0]Capucha de destripador crepuscular\nEscarpines de destripador crepuscular\nGuerrera de destripador crepuscular\n[q0](2) Conjunto : Aumenta 12 p. el poder de ataque.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211511] = {name = "[q3]Escarpines de destripador crepuscular", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n71 armadura\n+5 fuerza\n+7 agilidad\n+7 aguante\nDurabilidad 55 / 55\nNecesitas ser de nivel 25\n\n[q]Cuero de destripador brazanegra (0/3)\n[q0]Capucha de destripador crepuscular\nEscarpines de destripador crepuscular\nGuerrera de destripador crepuscular\n[q0](2) Conjunto : Aumenta 12 p. el poder de ataque.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211512] = {name = "[q0]Guerrera de destripador crepuscular", additional_info = "Se liga al recogerlo\n{Pecho} {Cuero}\n103 armadura\n+13 agilidad\n+9 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n\n[q]Cuero de destripador brazanegra (0/3)\n[q0]Capucha de destripador crepuscular\nEscarpines de destripador crepuscular\nGuerrera de destripador crepuscular\n[q0](2) Conjunto : Aumenta 12 p. el poder de ataque.\n(3) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[211514] = {name = "[q2]Notas de hechizo: Regeneración en masa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus pantalones con la runa Regeneración en masa:\n\n\nSana [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3] p. de salud a todos los miembros del grupo del jugador objetivo que estén en un radio de 43.5 m del jugador objetivo durante 3 s y aplica Faro temporal a cada objetivo durante 15 s.\n\n Faro temporal\n\nRegistra la posición en el espacio-tiempo del sujeto. Un 70% de todo el daño Arcano infligido por el taumaturgo se convertirá en sanación cronomántica en cada uno de los objetivos actuales de Faro temporal del taumaturgo. La sanación se reduce un 50% sobre uno mismo, y también se reduce un 80% al infligir daño a varios objetivos con hechizos arcanos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211527] = {name = "[q3]Bolsa de dormir acogedora", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Desenrolla una bolsa de dormir. Usarla para dormir durante al menos un minuto otorgará una bonificación a la experiencia obtenida, que se acumula un máximo de 3 veces. (1 Hora Reutilización)\n[q]\"Vieja, pero aún en buenas condiciones.\""},
[211528] = {name = "Perspicacia oscura", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Uso: Reflexiona en una tumba solitaria específica en Bosque del Ocaso para recibir una profecía."},
[211530] = {name = "[q2]Profecía de una ciudad cautivada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus brazales con la runa Palabra de poder: barrera:\n\n\nInvoca una barrera sagrada para proteger a todos los miembros del grupo en la ubicación del objetivo durante 10 s, lo que reduce un 25% todo el daño recibido y evita el daño del lanzamiento de hechizos retrasado.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[211531] = {name = "[q2]Profecía de los siete visitantes", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu pechera o toga con la runa Fuerza del alma:\n\n\nSanación inferior, Sanar, Sanación superior y Sanación relámpago reducen 2 s la duración restante de Alma debilitada en objetivos que sanan. Además, los objetivos de Palabra de poder: escudo obtendrán ira al recibir daño aunque el daño sea absorbido, y Furia recta se activará con el daño absorbido por tu Palabra de poder: escudo como si fuera una sanación.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[211534] = {name = "Perspicacia primigenia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Uso: Reflexiona en un atrapasueños piel de cardo en lo alto de las copas de los árboles para recibir una profecía."},
[211691] = {name = "[q2]Notas de hechizo: Explosión Arcana", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus guantes con la runa Explosión Arcana:\n\n\nGolpea al objetivo con energía, lo que inflige de [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 453 / 100] a [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 527 / 100] p. de daño Arcano. Cada vez que lanzas el hechizo Explosión Arcana, el daño de todos tus demás hechizos Arcanos aumentan un 15%, y el costo de maná de Explosión Arcana aumenta un 175%. El efecto se acumula hasta 4 veces y dura 6 s o hasta que se lance cualquier otro hechizo Arcano que inflija daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[211777] = {name = "Manuscrito naga", additional_info = "Se liga al recogerlo\nClases: Mago\n[q2]<Click derecho para leer>"},
[211779] = {name = "Talismán de comprensión", additional_info = "Se liga al recogerlo\nClases: Mago\n[q]\"Ayuda a traducir pergaminos y notas de hechizos.\""},
[211780] = {name = "Pergamino: KWYJIBO", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211784] = {name = "Pergamino: WUBBA WUBBA", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211785] = {name = "Pergamino: CWAL", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211786] = {name = "Scroll: CHAP BALK WELLES", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211787] = {name = "Pergamino: MENOS MARCA CUALQUIERA", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211789] = {name = "[q3]Capucha de Artemisa", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n84 armadura\n+7 agilidad\n+6 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 24 p. el poder de ataque."},
[211799] = {name = "Saco de bienes robados", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q]\"Probablemente sea lo que se llevaron de la catedral cuando Ada huyó.\"\n[q2]<Click derecho para abrir>"},
[211800] = {name = "Pergamino de reintegración", additional_info = "Clases: Mago\nNecesitas ser de nivel 12\n[q2]Uso: Devuelve a un jugador muerto a la vida con un 15% de salud y maná. No se puede utilizar estando en combate."},
[211809] = {name = "Manual de comprensión", additional_info = "Objeto de misión\nClases: Mago\n[q]\"Ayuda a traducir notas de hechizos elementales.\""},
[211813] = {name = "[q2]Talismán de centinela Ala de Plata", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Conseguiste este objeto de una centinela Ala de Plata caída en batalla. Tal vez al clarividente le interese.\""},
[211814] = {name = "[q2]Marca de escolta Grito de Guerra", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Conseguiste este objeto de una escolta Grito de Guerra caída en batalla. Tal vez a la sacerdotisa de la Luna le interese.\""},
[211815] = {name = "Himno de batalla Ala de Plata", additional_info = "Se liga al recogerlo\n[q2]Uso: Aumenta todo el daño infligido y la sanación realizada un 5% durante 2 h.\n[q]\"Una composición emocionante para subir la moral antes de la batalla.\""},
[211816] = {name = "Tambor de batalla Grito de Guerra", additional_info = "Se liga al recogerlo\n[q2]Uso: Aumenta todo el daño infligido y la sanación realizada un 5% durante 2 h.\n[q]\"Tambores de guerra para prepararse para la batalla.\""},
