[211841] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[211842] = {name = "[q3]Gorro de pensar raído de Rakkamar", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n38 armadura\n+8 intelecto\n+6 espíritu\nDurabilidad 55 / 55\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos."},
[211843] = {name = "[q3]Máscara de desdén", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n177 armadura\n+9 fuerza\n+7 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta 7 p. el índice de defensa."},
[211845] = {name = "[q2]Piedra de afilar Brazanegra", additional_info = "[q2]Uso: Cuando se aplica al arma objetivo, aumenta la probabilidad de golpe un 2% durante 30 minutos. No tiene efecto fuera de las Cavernas de Brazanegra.\n[q]\"Parece que estas misteriosas piedras encantadas brillan con más intensidad cuanto más desciendes en Brazanegra.\""},
[211846] = {name = "[q3]Diseño: Piedra de afilar Brazanegra", additional_info = "Se liga al recogerlo\nRequiere Herrería (100)\n[q2]Uso: Te enseña a hacer una piedra de afilar Brazanegra.\n\n\n[q2]Piedra de afilar Brazanegra\n[q2]Uso: Cuando se aplica al arma objetivo, aumenta la probabilidad de golpe un 2% durante 30 minutos. No tiene efecto fuera de las Cavernas de Brazanegra.\n[q]\"Parece que estas misteriosas piedras encantadas brillan con más intensidad cuanto más desciendes en Brazanegra.\"\nRequiere Piedra de afilar burda , Esencia mágica inferior"},
[211848] = {name = "[q2]Aceite de maná Brazanegra", additional_info = "Necesitas ser de nivel 25\n[q2]Uso: Cuando se aplica al arma objetivo, restaura 12 p. de maná cada 5 segundos y aumenta el golpe con hechizos un 2% durante 5 min. No tiene efecto fuera de las Cavernas de Brazanegra.\n5 cargas"},
[211849] = {name = "[q3]Fórmula: Aceite de maná Brazanegra", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (100)\n[q2]Uso: Te enseña a hacer aceite de maná Brazanegra.\n\n\n[q2]Aceite de maná Brazanegra\nNecesitas ser de nivel 25\n[q2]Uso: Cuando se aplica al arma objetivo, restaura 12 p. de maná cada 5 segundos y aumenta el golpe con hechizos un 2% durante 5 min. No tiene efecto fuera de las Cavernas de Brazanegra.\n5 cargas\nRequiere Vial emplomado , Esencia mágica superior , Polvo extraño (5)"},
[211852] = {name = "[q3]Manijas de agua contaminada", additional_info = "Se liga al recogerlo\n{Manos} {Tela}\n[q2]69 armadura\n+6 aguante\n+4 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 9 p. el daño que infligen los hechizos y efectos de las Sombras."},
[211853] = {name = "Pergamino: VOCE WELL", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211854] = {name = "Pergamino: OMIT KESA", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211855] = {name = "Pergamino: STHENIC LUNATE", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[211856] = {name = "[q3]Almófar de malla resiliente", additional_info = "Se liga al recogerlo\nÚnico\n{Cabeza} {Malla}\n175 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 20\n[q2]Equipar: Reduce un 5% todo el daño recibido y la probabilidad de recibir golpes críticos en Garganta Grito de Guerra."},
[211857] = {name = "[q3]Máscara de cuero resiliente", additional_info = "Se liga al recogerlo\nÚnico\n{Cabeza} {Cuero}\n80 armadura\nDurabilidad 50 / 50\nNecesitas ser de nivel 20\n[q2]Equipar: Reduce un 5% todo el daño recibido y la probabilidad de recibir golpes críticos en Garganta Grito de Guerra."},
[211933] = {name = "[q2]Suministros faltantes: Piedra férrea", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 10 piedra férrea para completar este cargamento."},
[211934] = {name = "[q2]Suministros faltantes: Pociones de sanación", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 10 pociones de sanación para completar este cargamento."},
[211935] = {name = "[q2]Suministros faltantes: Elixir de poder de Fuego", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 15 elixir de poder de Fuego para completar este cargamento."},
[211940] = {name = "[q3]Guardián tribal de Ecks'av", additional_info = "Se liga al recogerlo\n{Dos manos} {Arma de asta}\n{155 - 231 p. de daño} {Velocidad 3.70}\n(52.16 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 59\n[q2]Equipar: Otorga 40 p. de armadura extra a los miembros del grupo cercanos durante 4 min. Los jugadores solo pueden tener un aura a la vez por cada paladín."},
[211941] = {name = "[q3]Yari de viajero del viento", additional_info = "Se liga al recogerlo\n{Dos manos} {Arma de asta}\n{147 - 223 p. de daño} {Velocidad 3.60}\n(51.39 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 58\n[q2]Probabilidad al acertar: Golpea a los enemigos situados frente a ti con el poder del viento, fuego... ¡y todo eso!"},
[211944] = {name = "[q3]Karma de Tojara", additional_info = "Se liga al recogerlo\n{Dos manos} {Arma de asta}\n{158 - 234 p. de daño} {Velocidad 3.50}\n(56.00 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 58\n[q2]Probabilidad al acertar: El taumaturgo irradia una ola de llamas que inflige 208 to 249 p. de daño de fuego a todos los enemigos que quedan atrapados en la explosión y los atonta durante 6 s."},
[211953] = {name = "[q2]Pergamino de recuperación arcana I", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 20\n[q2]Uso: Restaura 8 p.de maná cada 5 s."},
[211954] = {name = "[q2]Pergamino de precisión arcana I", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 20\n[q2]Uso: Aumenta un 1% tu probabilidad de golpear con hechizos."},
[211955] = {name = "[q2]Pergamino de protección arcana: Fuego I", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 20\n[q2]Uso: Aumenta 20 p. tu resistencia al Fuego durante 30 min."},
[211956] = {name = "[q2]Pergamino de protección arcana: Escarcha I", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 20\n[q2]Uso: Aumenta 20 p. tu resistencia a la Escarcha durante 30 min."},
[211957] = {name = "[q2]Pergamino de poder arcano I", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 20\n[q2]Uso: Aumenta un 1% tu probabilidad de asestar golpes críticos con hechizos."},
[212160] = {name = "Desplazador de cronobeneficios", additional_info = "Temporada de descubrimiento\n[q2]Uso: Altera el tejido del tiempo y suspende los efectos de mundo beneficiosos de matar dragones, La Masacre, Zul'Gurub y Frondavil. (5 Min Reutilización)"},
[212225] = {name = "[q3]Recipiente de alma inagotable", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: El lanzamiento de tu próximo hechizo que cuesta fragmentos de alma no tiene costo. (5 Min Reutilización)"},
[212230] = {name = "[q3]Esquema: Recipiente de alma", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: Te enseña a hacer un recipiente de alma.\n[q3]Recipiente de alma\n[q]\"Atrapa almas de demonios y les roba su poder.\"\nRequiere Gema de las Sombras (4), Vitriolo negro , Figurilla demoníaca"},
[212548] = {name = "[q2]Runa de Eclipse", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu cinturón con la runa Eclipse:\n\n\nFuego estelar aumenta un 30% la probabilidad de golpe crítico de tus dos próximas Cóleras, y Cólera reduce 1.0 s el tiempo de lanzamiento de tu próximo Fuego estelar. Los dos efectos pueden acumular un máximo de 4 cargas. Además, los dos hechizos obtienen un 70% de probabilidad en todo momento de no perder tiempo de lanzamiento cuando recibes daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212549] = {name = "[q2]Runa de Trampero", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tus botas con la runa Lanzador de trampas:\n\n\nAhora puedes colocar tus Trampas congelante, de inmolación y explosiva en cualquier ubicación en un radio de 35 m. Además, tus trampas de Fuego y Escarcha ahora tienen tiempos de reutilización compartidos para cada escuela.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212551] = {name = "[q2]Runa de la Guerra", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus botas con la runa El arte de la guerra:\n\n\nTus golpes críticos cuerpo a cuerpo reducen el tiempo de reutilización restante de Exorcismo en 2 s y el costo de maná de Exorcismo un 80%.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212552] = {name = "[q2]Epifanía psicosófica", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Púa mental:\n\n\nGolpea al objetivo, le inflige de [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] a [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100] p. de daño de Friosombra y aumenta un 30% la probabilidad de golpe crítico de tu próxima Explosión mental contra el objetivo. Este efecto se acumula un máximo de 3 veces.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212559] = {name = "[q2]Runa de la Hoja envenenada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu cinturón con la runa Cuchillo envenenado:\n\n\nLanzas instantáneamente tu arma de la mano izquierda para infligir daño de arma normal con un 100% de probabilidad de aplicar el veneno de tu arma de la mano izquierda. Otorga 1 p. de combo. Restituye 5 p. de energía por aplicación de Veneno mortal sobre el objetivo.\n\n Cuchillo envenenado se beneficia de todos los talentos y efectos que se activan con Golpe siniestro o que lo modifican.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212560] = {name = "[q2]Runa de Despertar ancestral", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus botas con la runa Despertar ancestral:\n\n\nCuando realizas sanación crítica con tu Ola de sanación o tu Ola de sanación inferior, invocas a un espíritu ancestral para que te ayude y sane instantáneamente al miembro del grupo con el porcentaje de salud más bajo en un radio de 40 m un 30% de la cantidad de sanación realizada.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212561] = {name = "[q2]Runa de Oscuridad ardiente", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu cinturón con la runa Sombras y llamas:\n\n\nTus golpes críticos con hechizos de Fuego y de las Sombras aumentan un 10% el daño de Fuego y de las Sombras que infliges durante 10 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212562] = {name = "[q2]Runa de Ira curativa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus botas con la runa Regeneración iracunda:\n\n\nTe sana un 30% de tu salud máxima durante 10 s, pero solo se puede usar cuando Enfurecer, Ira rabiosa o Ira sangrienta están activas. Se puede usar mientras estás aturdido.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[212568] = {name = "[q3]Trofeo de cabeza de lobo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\nNecesitas ser de nivel 40\n[q2]Uso: Encanta un objeto de casilla de yelmo permanentemente para obtener 20 p. de energía o 5 p. de ira cuando asumes la Forma felina o de oso."},
[212580] = {name = "[q3]Bastón del Tradicionalista", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{57 - 87 p. de daño} {Velocidad 2.90}\n(24.83 p. de daño por segundo)\n+10 aguante\n+6 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Equipar: Restaura 4 p. de maná cada 5 s."},
[212581] = {name = "[q3]Arco de avanzado", additional_info = "Se liga al recogerlo\n{A distancia} {Arco}\n{25 - 47 p. de daño} {Velocidad 2.40}\n(15.00 p. de daño por segundo)\nDurabilidad 80 / 80\nNecesitas ser de nivel 25"},
[212582] = {name = "[q3]Espada de protector", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Espada}\n{35 - 67 p. de daño} {Velocidad 2.70}\n(18.89 p. de daño por segundo)\n+6 fuerza\n+3 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 25"},
[212583] = {name = "[q3]Hoja de centinela", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Daga}\n{22 - 43 p. de daño} {Velocidad 1.70}\n(19.12 p. de daño por segundo)\n+6 agilidad\n+3 aguante\nDurabilidad 65 / 65\nNecesitas ser de nivel 25"},
[212584] = {name = "[q3]Bastón nudoso de consejero", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{57 - 87 p. de daño} {Velocidad 2.90}\n(24.83 p. de daño por segundo)\n+10 aguante\n+6 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 25\n[q2]Equipar: Restaura 4 p. de maná cada 5 s."},
[212585] = {name = "[q3]Arco de escolta", additional_info = "Se liga al recogerlo\n{A distancia} {Arco}\n{25 - 47 p. de daño} {Velocidad 2.40}\n(15.00 p. de daño por segundo)\nDurabilidad 80 / 80\nNecesitas ser de nivel 25"},
[212586] = {name = "[q3]Espada de Legionario", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Espada}\n{35 - 67 p. de daño} {Velocidad 2.70}\n(18.89 p. de daño por segundo)\n+6 fuerza\n+3 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 25"},
[212587] = {name = "[q3]Hoja de explorador", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Daga}\n{22 - 43 p. de daño} {Velocidad 1.70}\n(19.12 p. de daño por segundo)\n+6 agilidad\n+3 aguante\nDurabilidad 65 / 65\nNecesitas ser de nivel 25"},
[212588] = {name = "[q2]Guantes de proveedor", additional_info = "Se liga al recogerlo\n{Manos} {Tela}\n20 armadura\n+3 aguante\n+3 espíritu\nDurabilidad 20 / 20\nNecesitas ser de nivel 12"},
[212589] = {name = "[q2]Botines de mensajero", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n50 armadura\n+4 agilidad\nDurabilidad 35 / 35\nNecesitas ser de nivel 12"},
[212590] = {name = "[q2]Correa de seguridad", additional_info = "Se liga al recogerlo\n{Cintura} {Malla}\n85 armadura\n+2 fuerza\n+2 aguante\nDurabilidad 25 / 25\nNecesitas ser de nivel 12"},
[212748] = {name = "[q2]Nota raída", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 30"},
[212994] = {name = "[q3]Ataduras de trotatormentas", additional_info = "Se liga al recogerlo\nMuñeca Cuero\n53 armadura\n+8 fuerza\n+7 agilidad\n+5 aguante\nDurabilidad 35 / 35\nClases: Chamán\nNecesitas ser de nivel 35"},
[212996] = {name = "[q3]Ataduras de clamarelámpagos", additional_info = "Se liga al recogerlo\nMuñeca Cuero\n53 armadura\n+5 aguante\n+7 intelecto\nDurabilidad 35 / 35\nClases: Chamán\nNecesitas ser de nivel 35\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con hechizos."},
[212997] = {name = "[q3]Ataduras de clamamareas", additional_info = "Se liga al recogerlo\nMuñeca Cuero\n53 armadura\n+5 aguante\n+7 intelecto\nDurabilidad 35 / 35\nClases: Chamán\nNecesitas ser de nivel 35\n[q2]Equipar: Restaura 3 p. de maná cada 5 s."},
[213036] = {name = "Agua de Elune'ara", additional_info = "Objeto de misión\nDuración: 1 hora (tiempo real)\n[q2]Uso: Da agua a un retoño anciano. (1 Min Reutilización)\n[q]\"Un delicado globo de agua bendecido por Orokai.\""},
[213074] = {name = "[q2]Runa de Revitalización", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu cinturón con la runa Nutrir:\n\n\nRestablece de [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] a [189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)] p. de salud a un objetivo aliado. Sana un 20% extra si tienes los efectos Rejuvenecimiento, Recrecimiento, Flor de vida o Crecimiento salvaje activos sobre el objetivo. Este hechizo se beneficia de todos los efectos vinculados con Toque de sanación o Recrecimiento y los activa.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213086] = {name = "[q2]Runa de la Tormenta", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu cinturón con la runa Arma vorágine:\n\n\nCuando infliges daño con un ataque cuerpo a cuerpo, tienes la posibilidad de reducir un 20%. El tiempo de lanzamiento y el costo de maná de tu siguiente hechizo Descarga de relámpagos, Cadena de relámpagos, Ola de sanación inferior o Ráfaga de lava. La probabilidad aumenta un 50% mientras tu arma de la mano derecha esté encantada con Arma Viento Furioso, y un 50% más si usas un arma de dos manos. Se acumula un máximo de 5 veces. Dura 30 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213087] = {name = "[q3]Capa de Sargento", additional_info = "Se liga al recogerlo\nÚnico\nEspalda\n24 armadura\n+4 fuerza\n+4 agilidad\n+4 aguante\n+4 intelecto\n+4 espíritu\nNecesitas ser de nivel 25"},
[213088] = {name = "[q3]Capa de Sargento", additional_info = "Se liga al recogerlo\nÚnico\nEspalda\n24 armadura\n+4 fuerza\n+4 agilidad\n+4 aguante\n+4 intelecto\n+4 espíritu\nNecesitas ser de nivel 25"},
[213090] = {name = "[q2]Runa de Sinergia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu cinturón con la runa Grimorio de sinergia:\n\n\nEl daño que infligen tú o tu demonio invocado tiene una probabilidad del 10% de aumentar el daño que inflige el otro un 10% durante 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213093] = {name = "[q2]Runa de Poder", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu cinturón con la runa Oleada de poder:\n\n\nCada vez que Choque de llamas inflige daño, tiene un 5% de probabilidad de restablecer el tiempo de reutilización de Ráfaga de lava y Cadena de relámpagos, y de hacer que el próximo lanzamiento de Ráfaga de lava o Cadena de relámpagos en 10 s sea instantáneo. Cada vez que Mareas Vivas sana, tiene un 5% de probabilidad de hacer que tu siguiente Sanación en cadena en 10 s sea instantáneo. Además, cada 5 s obtienes maná equivalente a un 15% de tu intelecto.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213094] = {name = "[q2]Runa de Nova de fuego", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu cinturón con la runa Nova de Fuego:\n\n\nTu hechizo Tótem Nova de Fuego es reemplazado con Nova de Fuego, que hace que tu tótem de Fuego actual irradie daño en su ubicación.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213096] = {name = "[q2]Runa de Señuelos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus botas con la runa Tótem señuelo:\n\n\nInvoca un Tótem señuelo durante 10 s con 5 p. de salud a los pies del objetivo que redirigirá el siguiente ataque cuerpo a cuerpo o a distancia realizado contra el objetivo hacia el tótem. El tótem también otorga inmunidad al objetivo contra efectos de reducción de movimiento durante 10 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213098] = {name = "[q2]Runa de Invocación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu cinturón con la runa Invocación:\n\n\nAplicar Corrupción, Inmolar, Maldición de agonía, Aflicción inestable, Llama de las Sombras o Succionar vida hará que inflijas un daño instantáneo al objetivo equivalente a un pulso del daño periódico del hechizo. Renovar cualquiera de esos hechizos cuando le quedan menos de 6 s hará que inflijas un daño instantáneo al objetivo equivalente al daño periódico restante del hechizo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213100] = {name = "[q2]Runa de Conocimiento prohibido", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus botas con la runa Conocimiento demoníaco:\n\n\nAumenta tu daño y sanación con hechizos por un valor equivalente a un 3% de la suma total del aguante más el intelecto de tu mascota demoníaca.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213101] = {name = "[q2]Runa de Llamas de las sombras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus botas con la runa Llama de las Sombras:\n\n\nQuema al enemigo e inflige [173 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100 * ( ( ( 1 ) ) ) ] p. de daño de Pirosombra y [64 * 5 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. más de daño de Pirosombra durante 15 s.\n\n Llama de las Sombras se activa y se beneficia de todos los efectos que modifican o interactúan con Inmolar o con tus hechizos de Aflicción, Destrucción, de Fuego o de las Sombras, pero solo puede haber un hechizo de Inmolar o Llama de las Sombras activo por brujo en cualquier objetivo. Además, Llama de las Sombras puede activar tu talento Descarga de las sombras mejorada y hacer que tenga 26 cargas más.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213102] = {name = "[q2]Runa de Perversidad", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus botas con la runa Danza de los malvados:\n\n\nTú y tu mascota demoníaca obtienen una probabilidad de esquivar equivalente a un 70% de tu probabilidad de golpe crítico con hechizos cada vez que asestas un golpe crítico a un enemigo, y los dos recuperan un 2% del maná máximo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213103] = {name = "[q2]Runa de Oleada de sangre", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu cinturón con la runa Oleada de sangre:\n\n\nGolpe heroico, Sed de sangre y Torbellino tienen una probabilidad de un 30% de hacer que tu siguiente Embate en 15 s sea instantáneo, golpee con ambas armas cuerpo a cuerpo y no cueste ira.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213104] = {name = "[q2]Runa de Precisión brutal", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu cinturón con la runa Sincronización de precisión:\n\n\nEmbate ahora es instantáneo, pero tiene un tiempo de reutilización de 6 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213105] = {name = "[q3]Shawarmagedón", additional_info = "Se liga al recogerlo\n{Una mano} {Maza}\n{50 - 93 p. de daño} {Velocidad 2.60}\n(27.50 p. de daño por segundo)\nDurabilidad 90 / 90\nClases: Guerrero\nNecesitas ser de nivel 40\n[q2]Uso: Aumenta un 4% la velocidad de ataque. Los ataques cuerpo a cuerpo tienen una probabilidad de infligir 7 p. más de daño de Fuego. (2 Min Reutilización)"},
[213109] = {name = "[q2]Runa de Ira concentrada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu cinturón con la runa Ira concentrada:\n\n\nReduce el costo de ira de tus habilidades ofensivas en 3.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213110] = {name = "[q2]Runa del Comandante", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus botas con la runa Berrido de convocación:\n\n\nEmite un berrido de convocación, que otorga un 15% más de salud máxima a los miembros del grupo y banda en un radio de 40 m durante 10 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213111] = {name = "[q2]Runa de Intervención", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus botas con la runa Intervenir:\n\n\nCorres a gran velocidad hacia un miembro del grupo, e interceptas el siguiente ataque cuerpo a cuerpo o a distancia que le hagan. Además, reduces su amenaza total un 10%.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213112] = {name = "[q2]Notas de hechizo: Tromba de misiles", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu cinturón con la runa Tromba de misiles:\n\n\nDa a tu Explosión Arcana una probabilidad de un 40% y a Bola de Fuego y Descarga de Escarcha una probabilidad de un 20% de reducir la duración canalizada de tus siguientes Misiles Arcanos un 50%; reduce el costo de maná un 100% y disparará misiles cada 0.5 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213117] = {name = "[q2]Runa de Rabia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu cinturón con la runa Rabia:\n\n\nCuando se activa, esta habilidad provoca que tu habilidad Destrozar (oso) y Lacerar golpeen a un máximo de 3 objetivos, que Lacerar no cueste ira y que Destrozar (oso) no tenga tiempo de reutilización, además de reducir un 50% el costo de energía de todas tus habilidades de Forma felina. Dura 15 s. Requiere Forma de oso, Forma felina o Forma de oso temible para activarse.\n\n Elimina el efecto de miedo y te hace inmune al miedo mientras dura.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213118] = {name = "[q2]Runa del Rey de la selva", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus botas con la runa Rey de la selva:\n\n\nFuria del tigre ahora aumenta todo el daño físico que infliges un 15% en lugar de un monto fijo, y te otorga 60 p. de energía de forma instantánea. Ya no tiene un tiempo de reutilización global, sino que ahora tiene su propio tiempo de reutilización de 30 s. Además, Furia del tigre persistirá al estar en Forma felina, pero se cancelará al cambiar a Forma de oso o Forma de oso temible.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213119] = {name = "[q2]Runa de Instinto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus botas con la runa Instintos de supervivencia:\n\n\nCuando se activa, te otorga un 30% de tu salud máxima y aumenta un 20% toda la sanación que no sea física que realizas durante 20 s. Después de que el efecto expira, los puntos de salud se pierden. Se puede usar en cualquier forma menos Forma de lechúcico lunar.\n\n Además, regeneras 5 p. de ira cada vez que esquivas mientras estás en Forma de oso o Forma de oso temible, 10 p. de energía mientras estás en Forma felina, o un 1% de tu maná máximo mientras estás en otra forma.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213120] = {name = "[q2]Runa del Soñador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus botas con la runa Estado onírico:\n\n\nLos golpes críticos con hechizos de daño no periódico o cualquier daño de Oleada de estrellas te otorgan un 50% de tu regeneración de maná mientras lanzas hechizos durante 8 s, y aumentan un 20% el daño Arcano y de Naturaleza infligido a objetivos no jugadores durante 12 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213121] = {name = "[q2]Acebo en conserva", additional_info = "Necesitas ser de nivel 25\n[q2]Uso: Transforma tu montura en algo más festivo. (1 Min Reutilización)"},
[213122] = {name = "[q2]Runa de Disparo firme", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tu cinturón con la runa Disparo firme:\n\n\nUn disparo firme que inflige un 100% de daño con arma a distancia.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213123] = {name = "[q2]Runa de Exposición", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tu cinturón con la runa Exponer debilidad:\n\n\nTus golpes críticos cuerpo a cuerpo y a distancia aumentan tu poder de ataque un monto equivalente al 40% de tu agilidad actual durante 7 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213124] = {name = "[q2]Runa de Combate cuerpo a cuerpo", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tu cinturón con la runa Especialista cuerpo a cuerpo:\n\n\nTu Golpe de raptor ahora es instantáneo, y Mordedura de mangosta y Golpe de raptor tienen un 40% de probabilidad de reiniciar los tiempos de reutilización de Mordedura de mangosta y Golpe de raptor con cada ataque.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213125] = {name = "[q2]Runa de Vigorización", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tus botas con la runa Golpe de dracoleón:\n\n\nReemplaza tu habilidad Picadura de dracoleón por Golpe de dracoleón, un golpe brutal que inflige un 140% de daño de arma y hace que el objetivo sangre y reciba daño con el tiempo.\n\n Golpe de dracoleón requiere que tengas el talento Picadura de dracoleón y reemplaza las habilidades de Picadura de dracoleón que se encuentran en el libro de hechizos de Supervivencia.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213126] = {name = "[q2]Runa del Desguazador", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tus botas con la runa Especialización en doble empuñadura:\n\n\nAumenta el daño infligido por tu arma de mano izquierda un 60%, y hace que tu Golpe de raptor golpee con ambas armas cuando portas dos armas.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213127] = {name = "[q2]Notas de hechizo: DEROEB OFNACRÍORA", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Descifra las notas de hechizo con un talismán de comprensión para aprender un nuevo hechizo de grabado."},
[213128] = {name = "[q2]Runa de Piedad", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu cinturón con la runa Protección maleable:\n\n\nAhora puedes actuar durante Protección divina, y su duración aumenta un 50%, pero en lugar de hacerte inmune, solo reduce el daño que recibes un 50%. Además, si activas Escudo sagrado, obtendrás 4 de poder de ataque por cada punto de habilidad de defensa por encima de ( 60 * 5) y durará 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213129] = {name = "[q2]Runa de Abrazo de la Luz", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu cinturón con la runa Vaina de Luz:\n\n\nInfligir daño con tu arma cuerpo a cuerpo aumenta tu daño con hechizos una cantidad equivalente al 30% de tu poder de ataque durante 1 min.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213130] = {name = "[q2]Runa de Infusiones", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu cinturón con la runa Infusión de Luz:\n\n\nAumenta un 50% el daño y la sanación realizados por tu Choque sagrado, reduce el tiempo de reutilización de Choque sagrado a 6 s, y tus golpes críticos con Choque sagrado restablecen su costo de maná y reducen 3 s su tiempo de reutilización restante.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213131] = {name = "[q2]Runa de Escudos sacros", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus botas con la runa Escudo sacro:\n\n\nCada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante un máximo de 6 s. Además, provoca que tu Destello de Luz sane a los objetivos con Escudo sacro un 100% más durante 12 s. No pueden obtener este efecto más de una vez cada 6 s. Dura 1 min. Solo un objetivo puede tener este efecto a la vez.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213132] = {name = "[q2]Runa de Custodio", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus botas con la runa Custodiado por la Luz:\n\n\nCada vez que golpeas a un objetivo con tu arma cuerpo a cuerpo, obtienes un 5% de tu maná máximo cada 3 s durante 15 s, pero tus hechizos de sanación sanan un 50% menos durante esta regeneración de maná.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213136] = {name = "[q2]Runa de Sutileza", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus botas con la runa Maestro de la sutileza:\n\n\nLos ataques realizados mientras estás en modo sigilo y durante los 6 s posteriores a abandonar el modo sigilo infligen un 10% extra de daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213137] = {name = "[q2]Runa de Atacante", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus botas con la runa Acecho:\n\n\nTus golpes con Emboscada y Puñalada desequilibran a tu objetivo, lo que aumenta el tiempo entre sus ataques cuerpo a cuerpo un 10% y reduce su velocidad de movimiento un 50% durante 8 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213138] = {name = "[q2]Runa de Pata izquierda", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus botas con la runa Bravura ante los golpes:\n\n\nCada vez que esquivas o paras un ataque, obtienes un 5% más de salud, que se acumula hasta 5 veces.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213139] = {name = "[q2]Runa de Asesino", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu cinturón con la runa Lanzamiento de shuriken:\n\n\nLanza un shuriken a tu enemigo y le inflige una cantidad de daño equivalente al 50% de tu poder de ataque, y también golpea a un máximo de 4 objetivos cercanos más. Otorga 1 p. de combo por cada objetivo golpeado.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213140] = {name = "[q2]Profecía de la senda acelerada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Renovar potenciado:\n\n\nAhora tu Renovar sana una vez más inmediatamente cuando se aplica, y obtiene un 15% más de beneficios cada vez que sana con tus efectos que potencian sanaciones.\n\n Además, tu Renovar ahora puede estar activo sobre objetivos afectados por el Renovar de otro sacerdote.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[213141] = {name = "[q2]Runa de Esperanza", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Esperanza renovada:\n\n\nEl efecto de tus sanaciones de Sanación relámpago, Sanación inferior, Sanar, Sanación superior y Penitencia aumenta un 20% cuando se lanzan sobre objetivos con Alma debilitada.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213142] = {name = "[q2]Profecía de maldad aprisionada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus botas con la runa\n Dispersión:\n\n\nTe conviertes en energía de las Sombras pura y reduces todo el daño recibido un 90%. No puedes atacar ni lanzar hechizos, pero regeneras un 6% de maná cada 1 s durante 6 s. Dispersión se puede lanzar mientras estás aturdido, asustado o silenciado, quita todos los efectos de frenado y de reducción del movimiento al lanzarlo y te hace inmune a ellos mientras dura.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[213143] = {name = "[q2]Epifanía apócrifa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus botas con la runa Supresión de dolor:\n\n\nReduce un 40% al instante todo el daño recibido por un objetivo aliado y aumenta la resistencia a las mecánicas de Disipación un 65% durante 8 s.\n[q]\"Aprendes una nueva habilidad de grabado.\""},
[213144] = {name = "[q2]Epifanía luminosa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus botas con la runa Espíritu del redentor:\n\n\nActívalo para convertirte en un Espíritu redentor durante 10 s. Mientras estés en esta forma, puedes lanzar cualquier hechizo de sanación sin costo, pero no puedes moverte, atacar, ser atacado o ser objetivo de ningún hechizo o efecto. Requiere el talento Espíritu redentor para activarse, y no serás Espíritu redentor al morir.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[213165] = {name = "Los basiliscos y el infundado miedo a la petrificación", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Intento de investigación sobre el uso de partes de basilisco como componentes. Una gran incorporación para la colección de cualquier biblioteca.\""},
[213168] = {name = "[q2]Moneda de sangre de cobre", additional_info = "Se liga al recogerlo\n[q2]Uso: Transmuta 100 monedas de sangre de cobre y las convierte en 1 moneda de sangre de plata.\n[q]\"Una muestra de tu pequeño servicio al loa de la sangre.\""},
[213169] = {name = "[q3]Moneda de sangre de plata", additional_info = "Se liga al recogerlo\n[q2]Uso: Transmuta 100 monedas de sangre de plata y las convierte en 1 moneda de sangre de oro.\n[q]\"Una muestra de tu modesto servicio al loa de la sangre.\""},
[213170] = {name = "[q4]Moneda de sangre de oro", additional_info = "Se liga al recogerlo\n[q]\"Un muestra de tu gran servicio al loa de la sangre.\""},
[213278] = {name = "[q3]Manoplas de maestro de golpes", additional_info = "Se liga al recogerlo\n{Manos} {Cuero}\n84 armadura\n+10 agilidad\n+11 aguante\nDurabilidad 35 / 35\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta las armas de puño en 3 p.\n[q2]Equipar: Mazas aumentadas +3 p."},
[213279] = {name = "[q3]Capacete reflectivo", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n222 armadura\n+11 aguante\n+13 intelecto\n+8 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 13 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213280] = {name = "[q3]Visor de Tirador", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n222 armadura\n+9 agilidad\n+13 aguante\n+8 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[213281] = {name = "[q3]Reactivador de hiperflujo electromagnético", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n55 armadura\n+15 intelecto\n+12 espíritu\nDurabilidad 50 / 50\nNecesitas ser de nivel 40\n[q2]Uso: Canaliza una descarga de relámpagos y la lanza hacia todos los enemigos que se encuentren enfrente del taumaturgo, causando 152 to 172 p. de daño de Naturaleza. El taumaturgo queda rodeado por una barrera de electricidad durante 10 minutos. (30 Min Reutilización)\n[q2]Equipar: Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213282] = {name = "[q4]Equipo de innovación hipercargado", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Hypercharged Gear] (1)\nDedo\n+5 intelecto\n+8 espíritu\n+5 resistencia a Arcano\n+5 resistencia a Naturaleza\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 13 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 3 p. de maná cada 5 s."},
[213283] = {name = "[q4]Equipo de conflagración hipercargado", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Hypercharged Gear] (1)\nDedo\n+4 intelecto\n+5 resistencia a Arcano\n+5 resistencia a Naturaleza\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s."},
[213284] = {name = "[q4]Equipo de devastación hipercargado", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Hypercharged Gear] (1)\nDedo\n+7 fuerza\n+8 agilidad\n+10 aguante\n+5 resistencia a Arcano\n+5 resistencia a Naturaleza\nNecesitas ser de nivel 40"},
[213285] = {name = "[q3]Ataduras manchadas con aceite de Lev", additional_info = "Se liga al recogerlo\nMuñeca Tela\n28 armadura\n+5 aguante\n+4 intelecto\nDurabilidad 30 / 30\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 9 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 3 p. de maná cada 5 s."},
[213286] = {name = "[q4]Aguja de Electrocutor", additional_info = "Se liga al recogerlo\n{Mano derecha} {Espada}\n{41 - 75 p. de daño} {Velocidad 1.70}\n(34.12 p. de daño por segundo)\nDurabilidad 105 / 105\nNecesitas ser de nivel 40\n[q2]Probabilidad al acertar: Descarga una mota de trueno que inflige 25 to 35 p. de daño de Naturaleza."},
[213287] = {name = "[q3]Hexatuerca de Electrocutor", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+6 aguante\n+9 espíritu\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 8 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213288] = {name = "[q3]Guanteletes grasosos de Grubbis", additional_info = "Se liga al recogerlo\n{Manos} {Placas}\n300 armadura\n+9 fuerza\n+5 aguante\nDurabilidad 45 / 45\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
