[213336] = {name = "[q3]Botos hiperconductivos", additional_info = "Se liga al recogerlo\n{Pies} {Tela}\n45 armadura\n+9 aguante\n+12 intelecto\nDurabilidad 40 / 40\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 9 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Atuendo de zahorí hiperconductivo (0/3)\n[q0]Toga hiperconductiva\nBotos hiperconductivos\nFalda hiperconductiva\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n(2) Conjunto : +100 p. de armadura.\n(3) Conjunto : El lanzamiento de hechizos tiene la probabilidad de aumentar hasta 40 p. el daño y la sanación que realizas durante 10 s. (Probabilidad de que accione: 10%)"},
[213337] = {name = "[q0]Sandalias hiperconductivas", additional_info = "Se liga al recogerlo\n{Pies} {Tela}\n45 armadura\n+5 aguante\n+8 intelecto\n+12 espíritu\nDurabilidad 40 / 40\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 15 p. la sanación de los hechizos y efectos.\n\n[q]Meditación de ensalmador hiperconductiva (0/3)\n[q0]Camisa resplandeciente hiperconductiva\nBombachos hiperconductivos\nSandalias hiperconductivas\n[q0](2) Conjunto : +14 p. de espíritu.\n(3) Conjunto : Restaura 7 p. de maná cada 5 s."},
[213338] = {name = "[q0]Botas de aislamiento electromántico", additional_info = "Se liga al recogerlo\n{Pies} {Malla}\n188 armadura\n+7 aguante\n+8 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 8 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\n\n[q]Cadena de extiendetormentas electromántica (0/3)\n[q0]Camisa de anillas electromántica\nChaquetón electromántico\nBotas de aislamiento electromántico\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : -0.1 s de tiempo de lanzamiento de tu hechizo Descarga de relámpagos."},
[213339] = {name = "[q3]Escarpes de aislamiento electromántico", additional_info = "Se liga al recogerlo\n{Pies} {Malla}\n188 armadura\n+11 agilidad\n+9 aguante\n+9 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 40\n\n[q]Malla de devastador electromántica (0/3)\n[q0]Malla de anillas electromántica\nEscarpes de aislamiento electromántico\nBotarga electromántica\n[q0](2) Conjunto : Aumenta 24 p. el poder de ataque.\n(3) Conjunto : Tus ataques tienen un 5% de probabilidad de restaurar 100 p. de maná. (Probabilidad de que accione: 5%)"},
[213340] = {name = "[q3]Botas de operadores de gnomobots", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n[q2]172 armadura\n+9 fuerza\n+7 agilidad\n+9 aguante\nDurabilidad 50 / 50\nNecesitas ser de nivel 40"},
[213341] = {name = "[q0]Botas de trabajo aisladas", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n92 armadura\n+8 fuerza\n+9 agilidad\n+8 aguante\nDurabilidad 50 / 50\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta tu nivel efectivo de sigilo en 1 p.\n\n[q]Cueros aislados (0/3)\n[q0]Coselete aislado\nMusleras aisladas\nBotas de trabajo aisladas\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : +20 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n(3) Conjunto : Dagas aumentadas +3 p."},
[213342] = {name = "[q0]Galochas aisladas", additional_info = "Se liga al recogerlo\n{Pies} {Cuero}\n92 armadura\n+6 aguante\n+9 intelecto\n+7 espíritu\nDurabilidad 50 / 50\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 16 p. el daño que infligen los hechizos y efectos de Naturaleza.\n\n[q]Cueros de hechicero aislados (0/3)\n[q0]Mandil aislado\nLeotardos aislados\nGalochas aisladas\n[q0](2) Conjunto : Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Aumenta un 2% la probabilidad de golpe crítico de Cólera y Fuego estelar."},
[213343] = {name = "[q4]Insignia de justicia", additional_info = "Se liga al recogerlo\nÚnico\nCuello\n+6 fuerza\n+7 aguante\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta un 1% tu probabilidad de esquivar un ataque.\n[q2]Equipar: Aumenta 4 p. el índice de defensa."},
[213344] = {name = "[q4]Torque de oficial de paz de Gnomeregan", additional_info = "Se liga al recogerlo\nÚnico\nCuello\n+6 aguante\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta 16 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[213345] = {name = "[q4]Colgante de pistón", additional_info = "Se liga al recogerlo\nÚnico\nCuello\n+4 aguante\n+8 intelecto\n+9 espíritu\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 9 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213346] = {name = "[q4]Colgante de regreso a casa", additional_info = "Se liga al recogerlo\nÚnico\nCuello\n+8 intelecto\n+10 espíritu\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 13 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 3 p. de maná cada 5 s."},
[213347] = {name = "[q3]Cámara de combustión miniaturizada", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+6 intelecto\n+10 resistencia a Fuego\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Convierte una cantidad aleatoria de salud, entre 1 y 150 p., en maná, entre 1 y 150 p., cada 1 s durante 10 s. (30 Min Reutilización)"},
[213348] = {name = "[q3]Experimento giromático 420b", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+10 resistencia a Escarcha\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta 18 p. el poder de ataque.\n[q2]Uso: Aumenta un 5% la velocidad de ataque. Tal vez puedas forzar este experimento un poco más... (30 Min Reutilización)"},
[213349] = {name = "[q3]Botella de píldoras de gniodino", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+7 espíritu\n+10 resistencia a Naturaleza\nNecesitas ser de nivel 40\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\n[q2]Uso: Hace que el objetivo aliado sea inmune a efectos de frenado e inmovilizadores durante los próximos 5 s. También elimina los efectos de frenado e inmovilizadores existentes. (30 Min Reutilización)\n[q]\"Los efectos secundarios pueden incluir: Dolor de estómago, acidez y encogimiento.\""},
[213350] = {name = "[q3]Núcleo endurecido de Perdal", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+7 aguante\n+5 resistencia a Arcano\n+5 resistencia a Naturaleza\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta un 1% tu probabilidad de esquivar un ataque.\n[q2]Uso: Aumenta 1000 p. la armadura, pero la velocidad de movimiento se reduce un 60%. El efecto no se puede eliminar y dura 10 s. (30 Min Reutilización)\n[q]\"El núcleo más duro.\""},
[213351] = {name = "[q3]Escudo pavés irradiado", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n1580 armadura\n24 bloqueo\n+5 aguante\n+7 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213352] = {name = "[q3]Gracia del reparador de equipo", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{53 - 99 p. de daño} {Velocidad 2.50}\n(30.40 p. de daño por segundo)\n+4 intelecto\n+3 espíritu\nDurabilidad 90 / 90\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 20 p. la sanación de los hechizos y efectos."},
[213353] = {name = "[q4]Bastón desfibrilador", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{102 - 160 p. de daño} {Velocidad 3.30}\n(39.70 p. de daño por segundo)\n+11 aguante\n+14 intelecto\n+15 espíritu\nDurabilidad 120 / 120\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 35 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Aumenta hasta 26 p. el daño que infligen los hechizos y efectos Arcanos.\n[q2]Uso: A veces el personal podrá devolver a un jugador muerto a la vida. No se puede usar en combate. (30 Min Reutilización)"},
[213354] = {name = "[q3]Bastón del genio malvado", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{80 - 121 p. de daño} {Velocidad 3.30}\n(30.45 p. de daño por segundo)\n+4 aguante\n+4 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 20 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q]\"El asta tiene grabado el nombre \"I. N. Sidioso\"\""},
[213355] = {name = "[q3]Aguijón de Falco", additional_info = "Se liga al recogerlo\n{A distancia} {Ballesta}\n{33 - 62 p. de daño} {Velocidad 2.00}\n(23.75 p. de daño por segundo)\n+8 agilidad\nDurabilidad 75 / 75\nNecesitas ser de nivel 40\n[q]\"Hay una mantícora pequeña grabada en la empuñadura.\""},
[213356] = {name = "[q4]Desintegrador personalizado de Termochufe", additional_info = "Se liga al recogerlo\n{A distancia} {Arma de fuego}\n{54 - 100 p. de daño} {Velocidad 2.90}\n(26.55 p. de daño por segundo)\nDurabilidad 95 / 95\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta 26 p. el poder de ataque a distancia."},
[213369] = {name = "[q3]Cuero con resplandor tenue", additional_info = nil},
[213370] = {name = "[q2]Restos de cuero irradiado", additional_info = "Se liga al recogerlo\n[q]\"Un peletero experimentado podría convertir este material en algo útil.\""},
[213371] = {name = "[q2]Cajón de solución de gniodino maculada", additional_info = "Se liga al recogerlo\n[q]\"Un alquimista experimentado podría convertir este material en algo útil.\""},
[213372] = {name = "[q3]Gniodino aislante", additional_info = nil},
[213373] = {name = "[q2]Chatarra reflectiva", additional_info = "Se liga al recogerlo\n[q]\"Un herrero experimentado podría convertir este material en algo útil.\""},
[213376] = {name = "[q3]Placas de veraplata de bajo fondo", additional_info = nil},
[213378] = {name = "[q2]Microfilamento inestable", additional_info = "Se liga al recogerlo\n[q]\"Un sastre experimentado podría convertir este material en algo útil.\""},
[213379] = {name = "[q3]Arcanofilamento hiperconductivo", additional_info = nil},
[213381] = {name = "[q2]Pila de engranajes deslustrados", additional_info = "Se liga al recogerlo\n[q]\"Un ingeniero experimentado podría convertir este material en algo útil.\""},
[213383] = {name = "[q3]Engranajes de veraplata pulidos", additional_info = nil},
[213390] = {name = "[q4]Murotuerca de veraplata giratorio", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n1760 armadura\n29 bloqueo\n+9 fuerza\n+10 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 40\nRequiere Ingeniería (225)\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 1%.\n[q2]Equipar: Cuando realizas un bloqueo exitoso, los engranajes afilados giratorios de este escudo infligen 5 to 10 p. de daño físico al atacante y 2 to 10 p. de daño físico al portador.\n[q]\"Los bordes giratorios de este escudo son realmente filosos. Parece tan peligroso para el portador como para el atacante.\""},
[213407] = {name = "Hierba gatera", additional_info = "Clases: Druida\nNecesitas ser de nivel 20\n[q2]Uso: Aumenta tu velocidad de ataque un 50% durante 30 s. (3 Min Reutilización)\n[q]\"Ristell Zarpa originalmente cultivó esta hierba para incentivar a los druidas de la Zarpa antes de la batalla.\""},
[213408] = {name = "[q3]Macroajustador giromático", additional_info = "Se liga al recogerlo\n{Dos manos} {Arma de asta}\n{101 - 152 p. de daño} {Velocidad 3.20}\n(39.53 p. de daño por segundo)\n+15 agilidad\n+9 aguante\n+15 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 40"},
[213409] = {name = "[q4]Arcanotrituradora de Mekkatorque", additional_info = "Se liga al recogerlo\n{Mano derecha} {Arma de puño}\n{62 - 115 p. de daño} {Velocidad 2.60}\n(34.04 p. de daño por segundo)\n+2 fuerza\n+3 agilidad\nDurabilidad 80 / 80\nNecesitas ser de nivel 40\n[q2]Probabilidad al acertar: Descarga una explosión de energía arcana que inflige 30 p. de daño Arcano, reduce las resistencias 45 p. y aumenta todo el daño con hechizos recibido un 6% durante 20 s. Solo afecta a los enemigos de niveles inferiores a 45"},
[213410] = {name = "[q4]Dagartilugio destellante", additional_info = "Se liga al recogerlo\n{Mano derecha} {Daga}\n{20 - 41 p. de daño} {Velocidad 1.20}\n(25.42 p. de daño por segundo)\n70 armadura\n+7 aguante\n+4 intelecto\nDurabilidad 80 / 80\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 19 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213411] = {name = "[q3]Chispero inextinguible de Fulguizzle", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{59 - 110 p. de daño de Fuego} {Velocidad 2.00}\n(42.25 p. de daño por segundo)\n+8 intelecto\nDurabilidad 65 / 65\nNecesitas ser de nivel 40\n[q]\"¡Ahora perfectamente capaz de almacenarse!\""},
[213412] = {name = "[q4]Escudo de seguridad dieléctrico", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n1760 armadura\n29 bloqueo\n+9 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 22 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s."},
[213413] = {name = "[q3]Hombreras muy acolchadas", additional_info = "Se liga al recogerlo\n{Hombro} {Cuero}\n100 armadura\n+8 intelecto\n+14 espíritu\nDurabilidad 50 / 50\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 11 p. la sanación de los hechizos y efectos."},
[213414] = {name = "[q3]Fajín de ensalmador de mecas", additional_info = "Se liga al recogerlo\n{Cintura} {Tela}\n37 armadura\n+6 intelecto\n+6 espíritu\nDurabilidad 30 / 30\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 24 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s."},
[213415] = {name = "[q3]Cubremuñecas de manitas", additional_info = "Se liga al recogerlo\nMuñeca Tela\n28 armadura\n+6 intelecto\n+7 espíritu\nDurabilidad 30 / 30\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 18 p. la sanación de los hechizos y efectos."},
[213416] = {name = "[q4]Cuchilla cohete de Termochufe", additional_info = "Se liga al recogerlo\n{Dos manos} {Hacha}\n{117 - 175 p. de daño} {Velocidad 3.30}\n(44.24 p. de daño por segundo)\n+29 fuerza\n+12 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 40"},
[213417] = {name = "[q3]Almófar de filamento de veraplata", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n390 armadura\n+8 aguante\n+12 intelecto\nDurabilidad 80 / 80\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Restaura 5 p. de maná cada 5 s."},
[213418] = {name = "[q3]Arandelas soldadas de veraplata", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Placas\n210 armadura\n+6 aguante\n+5 intelecto\nDurabilidad 45 / 45\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 14 p. el daño que infligen los hechizos y efectos Sagrados."},
[213419] = {name = "[q3]Manual de reparación 9-60", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n+6 aguante\n+6 intelecto\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 22 p. la sanación de los hechizos y efectos."},
[213421] = {name = "Nota incinerada", additional_info = "Se liga al recogerlo\nClases: Mago\n[q2]<Click derecho para leer>"},
[213426] = {name = "Pararrayos de ogro", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Plantar en tierra suave."},
[213427] = {name = "[q2]Reciclaje con mugre incrustada", additional_info = nil},
[213442] = {name = "[q3]Garra de maestro de engranajes", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Arma de puño}\n{60 - 111 p. de daño} {Velocidad 2.80}\n(30.54 p. de daño por segundo)\n+6 fuerza\n+6 agilidad\n+5 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 40"},
[213443] = {name = "Presente que hace \"tic, tac\"", additional_info = "Se liga al recogerlo\n[q2]<Click derecho para abrir>"},
[213452] = {name = "[q2]Runa sagrada inerte", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q]\"Primero, tienes que dar tu vida por el prójimo. Luego, antes de que tu espíritu parta, recibirás la salvación por tu entrega.\""},
[213513] = {name = "[q2]Tratado sobre salvación", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nClases: Paladín\nNecesitas ser de nivel 18\n[q2]Graba tus botas con la runa Escudo sacro:\n\n\nCada vez que el objetivo recibe daño, obtiene un Escudo sacro que absorbe [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100] p. de daño y aumenta un 50% la probabilidad del paladín de asestar un golpe crítico con Destello de Luz durante un máximo de 6 s. Además, provoca que tu Destello de Luz sane a los objetivos con Escudo sacro un 100% más durante 12 s. No pueden obtener este efecto más de una vez cada 6 s. Dura 1 min. Solo un objetivo puede tener este efecto a la vez.\n[q]\"Aprende una nueva habilidad después de usar Bendición de libertad para liberar a otros de los efectos de reducción de movimiento 5 veces.\""},
[213526] = {name = "Anca híbrida", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Sabe a bife *y* a pollo.\""},
[213527] = {name = "Mezcla de especias de contrabandista", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"La joya más preciada en la cocina de cualquier navío. Puede hacer que hasta una bota tenga buen sabor.\""},
[213528] = {name = "Brebaje fresco", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"La verdad es que no es tan refrescante como dice su nombre.\""},
[213529] = {name = "Toxina viscosa", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Elimina las alimañas de pantano como si no fueran nada. ¡Perfecta para usar de aderezo!\""},
[213542] = {name = "[q3]El Necro-Gnomicón", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n+2 intelecto\n+2 espíritu\n+3 resistencia a Sombras\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos."},
[213543] = {name = "Pergamino: QUÉONDA", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[213544] = {name = "Pergamino: EZFOO KATASI", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[213545] = {name = "Pergamino: TOPSE ALTOMIAGU", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[213546] = {name = "Pergamino: CUCAMONGA", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[213547] = {name = "Pergamino: QÉUSAPEDA", additional_info = "Clases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[213548] = {name = "Pergamino de Pasaje liminal", additional_info = "Clases: Mago\nNecesitas ser de nivel 6\n[q2]Uso: Teletransporta a un miembro del grupo. El objetivo y tú deben estar descansando en una posada o en una ciudad."},
[213549] = {name = "Pergamino de Pesca arcana", additional_info = "Clases: Mago\nNecesitas ser de nivel 12"},
[213550] = {name = "Pergamino de Polimorfia: Melón extraño", additional_info = "Se liga al recogerlo\nClases: Mago\nNecesitas ser de nivel 16\n[q2]Uso: Aplica Polimorfia al objetivo y lo convierte en un melón extraño. (5 Seg Reutilización)"},
[213551] = {name = "Pergamino de Desplazamiento controlado", additional_info = "Clases: Mago\nNecesitas ser de nivel 12"},
[213552] = {name = "Lágrima de Theradras", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Se dice que estas lágrimas, guardadas y protegidas con mucho cuidado por la tribu de centauros Gelkis, le otorgan la protección de los espíritus terráneos a quien las porte.\""},
[213553] = {name = "Lágrima de Theradras", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Se dice que estas lágrimas, guardadas y protegidas con mucho cuidado por la tribu de centauros Gelkis, le otorgan la protección de los espíritus terráneos a quien las porte.\""},
[213554] = {name = "Vial de agua cristalina", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Mezclar con lágrimas de Theradras para crear una salva elemental capaz de purificar la corrupción.\n[q]\"El agua es tan transparente que el vial parece vacío.\""},
[213558] = {name = "Bálsamo elemental", additional_info = "[q2]Uso: Verter sobre objetos corruptos para purificarlos.\n[q]\"Un bálsamo potente capaz de purgar la corrupción más profunda.\""},
[213559] = {name = "[q3]Palanca de cambios de mecazancudo", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{44 - 83 p. de daño de Arcano} {Velocidad 1.50}\n(42.33 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 9 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q]\"Este objeto implica la existencia de mecazancudos con transmisión manual.\""},
[213560] = {name = "[q3]Silenciador de mecazancudos", additional_info = "Se liga al recogerlo\n{Una mano} {Maza}\n{51 - 95 p. de daño} {Velocidad 2.40}\n(30.42 p. de daño por segundo)\n+7 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta 16 p. el poder de ataque."},
[213563] = {name = "Guía de campo", additional_info = "Se liga al recogerlo\n[q2]<Click derecho para leer>"},
[213564] = {name = "Pergamino de evocación menor", additional_info = "Clases: Mago\n[q2]Uso: Restaura maná. (8 Min Reutilización)"},
[213565] = {name = "Kit inicial para entomología", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador , Druida\n[q2]<Click derecho para abrir>"},
[213583] = {name = "[q2]Tallado de azufre", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Parece que el dueño anterior jugó con fuego demasiadas veces.\""},
[213594] = {name = "[q2]Ídolo del molesto", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\nNecesitas ser de nivel 28\n[q2]Graba tu cinturón con la runa Rabia:\n\n\nCuando se activa, esta habilidad provoca que tu habilidad Destrozar (oso) y Lacerar golpeen a un máximo de 3 objetivos, que Lacerar no cueste ira y que Destrozar (oso) no tenga tiempo de reutilización, además de reducir un 50% el costo de energía de todas tus habilidades de Forma felina. Dura 15 s. Requiere Forma de oso, Forma felina o Forma de oso temible para activarse.\n\n Elimina el efecto de miedo y te hace inmune al miedo mientras dura.\n[q]\"Provoca a 2 o más enemigos con Rugido desafiante y mata a por lo menos uno de ellos. Después de 3 asesinatos, usa este ídolo para aprender una nueva habilidad.\""},
[213599] = {name = "[q2]Visión angustiante", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu cinturón con la runa Esperanza renovada:\n\n\nEl efecto de tus sanaciones de Sanación relámpago, Sanación inferior, Sanar, Sanación superior y Penitencia aumenta un 20% cuando se lanzan sobre objetivos con Alma debilitada.\n[q2]Uso: Te concentras en la visión para aprender un hechizo nuevo. Requiere un vistazo de conocimiento corrupto."},
[213632] = {name = "[q2]Notas parciales de hechizo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas parciales de hechizo para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan dos de tres partes.\""},
[213633] = {name = "[q2]Notas parciales de hechizo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas parciales de hechizo para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan dos de tres partes.\""},
[213634] = {name = "[q2]Notas parciales de hechizo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas parciales de hechizo para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan dos de tres partes.\""},
[213641] = {name = "[q3]Caja de reciclaje de Gnomeregan", additional_info = "Se liga al recogerlo\n[q]\"Esta caja de reciclaje de Gnomeregan podría contener algo útil para tu profesión\"\n[q2]<Click derecho para abrir>"},
[213701] = {name = "Pluma de arpía fuerte", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q2]Uso: Combina 10 plumas de arpía fuertes y 3 colmillos de dragón nimbo con 1 hilo de seda para crear una ofrenda al espíritu de viento."},
[213709] = {name = "Colmillo de serpiente nubosa", additional_info = "Se liga al recogerlo\nÚnico (3)\n[q2]Uso: Combina 10 plumas de arpía fuertes y 3 colmillos de dragón nimbo con 1 hilo de seda para crear una ofrenda al espíritu de viento."},
[213735] = {name = "[q3]Procesador de N.Ú.C.L.E.O. G-7 prístino", additional_info = "Se liga al recogerlo\n[q]\"Esta cosa puede prerrenderizar más de 4 millones de gigaflops de explocódigos de baja divergencia. ¡Guau!\""},
[213736] = {name = "[q2]Procesador de N.Ú.C.L.E.O. G-7 corroído", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Este núcleo procesador está cubierto de corrosión y una sustancia negra pegajosa, pero con un poco de esfuerzo puedes ver entre la mugre el número de modelo y algunas palabras ilegibles. Puede que necesites a un especialista para restaurarlo.\""},
[213737] = {name = "Ofrenda al espíritu de viento", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Crea una ofrenda al espíritu de viento para demostrar tu fe."},
[214435] = {name = "Llave de jaula de pumas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Abre la jaula de pumas"},
[215111] = {name = "[q4]Monóculo de arcanfilamento gneurovinculado", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n58 armadura\n+10 aguante\n+11 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 40\nRequiere Sastrería (225)\n[q2]Equipar: Aumenta hasta 22 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\n[q2]Uso: Controlas la energía arcana latente del aire a tu alrededor para obtener inspiración cargada, que reduce un 50% el costo de maná de todos los hechizos, y aumenta hasta 50 p. el daño y la sanación realizados durante 12 s. (10 Min Reutilización)"},
[215114] = {name = "[q4]Almófar de escamas brillantes hiperconductivo", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n242 armadura\n+14 aguante\n+15 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 40\nRequiere Peletería (225)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Causa un choque hiperconductivo que te inflige 312 to 688 p. de daño al instante, pero también aumenta tu velocidad de lanzamiento de hechizos un 20% durante 10 s. (10 Min Reutilización)"},
[215115] = {name = "[q4]Envoltura dorada hiperconductiva", additional_info = "Se liga al recogerlo\n{Cintura} {Tela}\n40 armadura\n+9 aguante\nDurabilidad 35 / 35\nNecesitas ser de nivel 40\nRequiere Ingeniería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Uso: Sacas una moneda hiperconductiva de tu cinturón y la tiras al aire. Si sale cara, obtienes un 3% más de probabilidad de infligir golpes críticos con todos los hechizos y ataques durante 30 s. Si sale cruz, obtienes un 10% de velocidad de movimiento durante 30 s. (15 Min Reutilización)\n[q]\"Este cinturón tintinea levemente cuando te mueves.\""},
[215127] = {name = "[q2]Bomba de radiación de alto rendimiento", additional_info = "Necesitas ser de nivel 35\nRequiere Ingeniería (200)\n{[q2]Uso: Inflige 150 to 250 p. de daño de Fuego} en el radio de la explosión, además de 25 p. de {daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante hasta cancelación. (1 Min Reutilización)}"},
[215129] = {name = "[q4]Fórmula: Encantar arma: Desguarnecer", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (225)\n[q2]Uso: Encanta un arma de forma permanente para que todos los hechizos y los ataques puedan infligir ocasionalmente 60 to 90 p. más de daño a las criaturas mecánicas."},
[215138] = {name = "[q4]Fórmula: encantar pechera: Reprentizador", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (225)\n[q2]Uso: Te enseña a encantar de forma permanente una armadura de torso para que refleje 9 p. de daño hacia el atacante cuando el portador recibe un golpe cuerpo a cuerpo."},
[215141] = {name = "[q2]Sigilo encantado: Innovación", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (225)\n[q2]Uso: Te enseña a conjurar un sigilo de innovación.\n[q2]Sigilo encantado: Innovación\nSe liga al recogerlo\nÚnico (5)\nNecesitas ser de nivel 40\nRequiere Encantamiento (225)\n[q2]Uso: Otorga un sigilo encantado de innovación que te potencia para aumentar hasta 20 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 20 p. durante 30 min. Esto solo aplica fuera de combate. (30 Min Reutilización)\nRequiere Polvo de visión (5)"},
[215149] = {name = "[q4]Patrón: Monóculo de arcanofilamento gneurovinculado", additional_info = "Se liga al recogerlo\nRequiere Sastrería (225)\n[q2]Uso: Te enseña a fabricar un monóculo de arcanofilamento gneurovinculado.\n[q4]Monóculo de arcanfilamento gneurovinculado\nSe liga al recogerlo\n{Cabeza} {Tela}\n58 armadura\n+10 aguante\n+11 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 40\nRequiere Sastrería (225)\n[q2]Equipar: Aumenta hasta 22 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\n[q2]Uso: Controlas la energía arcana latente del aire a tu alrededor para obtener inspiración cargada, que reduce un 50% el costo de maná de todos los hechizos, y aumenta hasta 50 p. el daño y la sanación realizados durante 12 s. (10 Min Reutilización)\nRequiere Arcanofilamento hiperconductivo (5), Cuero con resplandor tenue , Gniodino aislante , Polvo de visión (10), Madeja de tejido mágico (10)"},
[215152] = {name = "[q4]Patrón: Capucha gneurovinculada con resplandor", additional_info = "Se liga al recogerlo\nRequiere Peletería (225)\n[q2]Uso: Te enseña a fabricar una capucha gneurovinculada con resplandor.\n[q4]Capucha gneurovinculada con resplandor\nSe liga al recogerlo\n{Cabeza} {Cuero}\n118 armadura\n+14 agilidad\n+14 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 40\nRequiere Peletería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Daño con arma +3.\n[q2]Uso: Causa un choque neurológico que te inflige 343 to 757 p. de daño al instante, pero también aumenta tu velocidad de ataque cuerpo a cuerpo y a distancia un 20% durante 10 s. (10 Min Reutilización)\nRequiere Arcanofilamento hiperconductivo , Pellejo grueso curtido (5), Hilo de seda (2), Cuero con resplandor tenue (5)"},
[215153] = {name = "[q4]Esquema: Murotuerca de veraplata giratorio", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (225)\n[q2]Uso: Te enseña a confeccionar un murotuerca de veraplata giratorio.\n[q4]Murotuerca de veraplata giratorio\nSe liga al recogerlo\n{Mano izquierda} {Escudo}\n1760 armadura\n29 bloqueo\n+9 fuerza\n+10 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 40\nRequiere Ingeniería (225)\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 1%.\n[q2]Equipar: Cuando realizas un bloqueo exitoso, los engranajes afilados giratorios de este escudo infligen 5 to 10 p. de daño físico al atacante y 2 to 10 p. de daño físico al portador.\n[q]\"Los bordes giratorios de este escudo son realmente filosos. Parece tan peligroso para el portador como para el atacante.\"\nRequiere Placas de veraplata de bajo fondo (3), Engranajes de veraplata pulidos (5), Cuero con resplandor tenue (2), Envoltura de mitril (2), Girocronátomo (2), Barra de mitril (15)"},
[215155] = {name = "[q4]Diseño: Yelmo anulainterferencias templado", additional_info = "Se liga al recogerlo\nRequiere Herrería (225)\n[q2]Uso: Te enseña a fabricar un yelmo anulainterferencias templado\n[q4]Yelmo anulainterferencias templado\nSe liga al recogerlo\n{Cabeza} {Placas}\n426 armadura\n+20 fuerza\n+14 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 40\nRequiere Herrería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Uso: Obtienes concentración intensa, que reduce la velocidad de movimiento un 20%, pero también aumenta 50 p. tu resistencia contra hechizos de todas las escuelas y aumenta la velocidad de ataque cuerpo a cuerpo un 20% durante 10 s. (10 Min Reutilización)\n[q]\"¡Protección garantizada de tu cerebro contra todo tipo de amenazas, daño físico y otros eventos!\"\nRequiere Barra de mitril (25), Placas de veraplata de bajo fondo (4), Arcanofilamento hiperconductivo , Cuero con resplandor tenue (2)"},
[215156] = {name = "[q4]Esquema: Envoltura dorada hiperconductiva", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (225)\n[q2]Uso: Te enseña a confeccionar una envoltura dorada hiperconductiva\n[q4]Envoltura dorada hiperconductiva\nSe liga al recogerlo\n{Cintura} {Tela}\n40 armadura\n+9 aguante\nDurabilidad 35 / 35\nNecesitas ser de nivel 40\nRequiere Ingeniería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Uso: Sacas una moneda hiperconductiva de tu cinturón y la tiras al aire. Si sale cara, obtienes un 3% más de probabilidad de infligir golpes críticos con todos los hechizos y ataques durante 30 s. Si sale cruz, obtienes un 10% de velocidad de movimiento durante 30 s. (15 Min Reutilización)\n[q]\"Este cinturón tintinea levemente cuando te mueves.\"\nRequiere Engranajes de veraplata pulidos (3), Arcanofilamento hiperconductivo (3), Cuero con resplandor tenue , Barra de oro (10)"},
[215161] = {name = "[q4]Yelmo anulainterferencias templado", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n426 armadura\n+20 fuerza\n+14 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 40\nRequiere Herrería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Uso: Obtienes concentración intensa, que reduce la velocidad de movimiento un 20%, pero también aumenta 50 p. tu resistencia contra hechizos de todas las escuelas y aumenta la velocidad de ataque cuerpo a cuerpo un 20% durante 10 s. (10 Min Reutilización)\n[q]\"¡Protección garantizada de tu cerebro contra todo tipo de amenazas, daño físico y otros eventos!\""},
[215162] = {name = "Poción de rejuvenecimiento levemente irradiada", additional_info = "Necesitas ser de nivel 35\n[q2]Uso: Restaura 262 to 438 p. de maná y 340 to 460 p. de salud. También aumenta 40 p. el poder de ataque y 35 p. el daño que infligen todos los hechizos durante 20 s. (2 Min Reutilización)\n[q]\"Los efectos secundarios pueden incluir mareos, sequedad en la boca, fatiga, pérdida de apetito, envenenamiento radiactivo agudo, mutación y muerte. Úsala solo como se indica.\""},
[215163] = {name = "[q4]Receta: Poción de rejuvenecimiento levemente irradiada", additional_info = "Se liga al recogerlo\nRequiere Alquimia (225)\n[q2]Uso: Te enseña a preparar una poción de rejuvenecimiento levemente irradiada.\nPoción de rejuvenecimiento levemente irradiada\nNecesitas ser de nivel 35\n[q2]Uso: Restaura 262 to 438 p. de maná y 340 to 460 p. de salud. También aumenta 40 p. el poder de ataque y 35 p. el daño que infligen todos los hechizos durante 20 s. (2 Min Reutilización)\n[q]\"Los efectos secundarios pueden incluir mareos, sequedad en la boca, fatiga, pérdida de apetito, envenenamiento radiactivo agudo, mutación y muerte. Úsala solo como se indica.\"\nRequiere Cajón de solución de gniodino maculada , Poción de Rejuvenecimiento menor , Residuos radioactivos de Gnomeregan (3), Vial de cristal (5)"},
[215166] = {name = "[q4]Capucha gneurovinculada con resplandor", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n118 armadura\n+14 agilidad\n+14 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 40\nRequiere Peletería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Daño con arma +3.\n[q2]Uso: Causa un choque neurológico que te inflige 343 to 757 p. de daño al instante, pero también aumenta tu velocidad de ataque cuerpo a cuerpo y a distancia un 20% durante 10 s. (10 Min Reutilización)"},
[215168] = {name = "[q2]Bomba de radiación para tontos", additional_info = "Necesitas ser de nivel 40\n{[q2]Uso: Inflige 112 to 188 p. de daño de Fuego} en el radio de la explosión, además de 10 p. de {daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante 10 s. (1 Min Reutilización)}\n[q]\"Una versión menor pero no menos letal de su contraparte más compleja para aquellos que carezcan de la aptitud pero rebosen de confianza.\""},
[215257] = {name = "Pergamino de comprensión", additional_info = "Clases: Mago\n[q2]Uso: Crea 2 talismanes de comprensión, o 4 si estás descansando en una taberna o ciudad."},
[215365] = {name = "[q2]Manto de invocador", additional_info = "Se liga al equiparlo\n{Hombro} {Tela}\n32 armadura\n+5 intelecto\nDurabilidad 45 / 45\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos."},
[215366] = {name = "[q2]Cordón de invocador", additional_info = "Se liga al equiparlo\n{Cintura} {Tela}\n24 armadura\n+5 intelecto\nDurabilidad 25 / 25\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos."},
[215367] = {name = "[q3]Patrón: Cuero con resplandor tenue", additional_info = "Se liga al recogerlo\nRequiere Peletería (200)\n[q2]Uso: Te enseña a fabricar cuero con resplandor tenue.\n[q3]Cuero con resplandor tenue\nRequiere Pellejo grueso curtido , Restos de cuero irradiado (5)"},
[215368] = {name = "[q3]Patrón: Arcanofilamento hiperconductivo", additional_info = "Se liga al recogerlo\nRequiere Sastrería (200)\n[q2]Uso: Te enseña a fabricar un carrete de arcanofilamento hiperconductivo.\n[q3]Arcanofilamento hiperconductivo\nRequiere Madeja de tejido mágico (2), Microfilamento inestable (5), Hilo de seda grueso (5)"},
[215369] = {name = "[q2]Patrón: cordón de invocador", additional_info = "Requiere Sastrería (150)\n[q2]Uso: Te enseña a confeccionar cordón de invocador.\n[q2]Cordón de invocador\nSe liga al equiparlo\n{Cintura} {Tela}\n24 armadura\n+5 intelecto\nDurabilidad 25 / 25\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos.\nRequiere Madeja de paño de seda (3), Gema de las Sombras , Hilo refinado , Tinte gris"},
[215370] = {name = "[q2]Patrón: manto de invocador", additional_info = "Requiere Sastrería (150)\n[q2]Uso: Te enseña a confeccionar un manto de invocador.\n[q2]Manto de invocador\nSe liga al equiparlo\n{Hombro} {Tela}\n32 armadura\n+5 intelecto\nDurabilidad 45 / 45\nNecesitas ser de nivel 25\n[q2]Equipar: Aumenta hasta 7 p. el daño y la sanación de los hechizos y efectos mágicos.\nRequiere Madeja de paño de seda (4), Tinte gris (4), Hilo refinado , Tinte azul (4)"},
[215371] = {name = "[q2]Talismán de Jani", additional_info = "Se liga al equiparlo\nÚnico\nAbalorio\nClases: Pícaro"},
[215373] = {name = "Martillo de entrenamiento de la Mano de Plata", additional_info = "{Dos manos} {Maza}\n{17 - 54 p. de daño} {Velocidad 3.40}\n(10.44 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 26\n[q]\"Recuperado de la Isla Theramore, donde su antiguo dueño murió en batalla contra hordas de orcos sanguinarios.\""},
[215374] = {name = "Espada ancestral", additional_info = "{Dos manos} {Espada}\n{17 - 46 p. de daño} {Velocidad 3.10}\n(10.16 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 26\n[q]\"Ha pasado de generación en generación dentro de una familia noble de Lordaeron. Hace tiempo se la daba por perdida en los pantanos de Kyross, junto con el último guerrero que la blandió.\""},
[215375] = {name = "Bastón de la estratega", additional_info = "{Dos manos} {Bastón}\n{16 - 49 p. de daño} {Velocidad 3.50}\n(9.29 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 26\n[q]\"La gran comprensión de las tácticas de guerra de su dueña solo se compara con su temible control de la escarcha y las llamas.\""},
[215376] = {name = "Maza de cruzado", additional_info = "{Mano derecha} {Maza}\n{21 - 36 p. de daño} {Velocidad 2.90}\n(9.83 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 26\n[q]\"Decorada con trozos secos de caparazones de insectos.\""},
[215377] = {name = "[q3]Toga irradiada", additional_info = "Se liga al recogerlo\n{Pecho} {Tela}\n65 armadura\n-5 fuerza\n-10 aguante\n+7 intelecto\n+8 espíritu\n+7 resistencia a Naturaleza\nDurabilidad 80 / 80\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 23 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Prendas irradiadas (0/3)\n[q0]Toga irradiada\nCalzas irradiadas\nBotas irradiadas\n[q0](2) Conjunto : -5 p. de aguante.\n(2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos."},
[215378] = {name = "[q0]Botas irradiadas", additional_info = "Se liga al recogerlo\n{Pies} {Tela}\n45 armadura\n-5 agilidad\n-10 aguante\n+12 intelecto\n+11 espíritu\nDurabilidad 40 / 40\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Prendas irradiadas (0/3)\n[q0]Toga irradiada\nCalzas irradiadas\nBotas irradiadas\n[q0](2) Conjunto : -5 p. de aguante.\n(2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos."},
[215379] = {name = "[q3]Calzas irradiadas", additional_info = "Se liga al recogerlo\n{Piernas} {Tela}\n57 armadura\n-5 agilidad\n-10 aguante\n+10 intelecto\n+13 espíritu\n+10 resistencia a Naturaleza\nDurabilidad 75 / 75\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s.\n\n[q]Prendas irradiadas (0/3)\n[q0]Toga irradiada\nCalzas irradiadas\nBotas irradiadas\n[q0](2) Conjunto : -5 p. de aguante.\n(2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos."},
[215380] = {name = "[q4]Faja para levantar peso asistida eléctricamente", additional_info = "Se liga al recogerlo\n{Cintura} {Malla}\n168 armadura\n+14 fuerza\n+15 aguante\nDurabilidad 50 / 50\nNecesitas ser de nivel 40\n[q2]Equipar: Hachas de dos manos aumentadas +3 p.\n[q2]Equipar: Espadas de dos manos aumentadas +3 p.\n[q2]Equipar: Mazas de dos manos aumentadas +3 p."},
[215381] = {name = "[q4]Caperuza de canalizador gneuroconductiva", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n118 armadura\n+11 aguante\n+12 intelecto\n+11 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 40\nRequiere Peletería (225)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Obtienes meditación neuromántica, que te permite conservar un 100% de tu regeneración de maná en el lanzamiento de hechizos, y aumenta el daño y la sanación realizados con hechizos hasta 50 p. durante 20 s. (10 Min Reutilización)"},
[215382] = {name = "[q4]Caperuza de escamas resistente a la radiación", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n[q2]342 armadura\n+10 aguante\n+10 intelecto\nDurabilidad 85 / 85\nNecesitas ser de nivel 40\nRequiere Peletería (225)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 32 p. el poder de ataque.\n[q2]Uso: Activa los protocolos de mitigación de radiación de este casco, lo que hace que elimines inmediatamente todos los efectos de veneno activos y obtengas inmunidad a todo el daño de Naturaleza durante 3 s. (10 Min Reutilización)"},
[215383] = {name = "[q4]Diseño: Cajasesos de veraplata reflectiva", additional_info = "Se liga al recogerlo\nRequiere Herrería (225)\n[q2]Uso: Te enseña a fabricar una cajasesos de veraplata reflectiva.\n[q4][Reflective Truesilver Braincage]\nSe liga al recogerlo\n{Cabeza} {Placas}\n426 armadura\n+14 aguante\n+15 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 40\nRequiere Herrería (225)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Obtienes fuerza de voluntad reforzada, que impide los efectos de silenciamiento e interrupción y el retraso de hechizos durante 10 s. (10 Min Reutilización)\nRequiere Barra de mitril (25), Placas de veraplata de bajo fondo (4), Arcanofilamento hiperconductivo (2), Engranajes de veraplata pulidos"},
[215384] = {name = "[q3]Diseño: Placas de veraplata de bajo fondo", additional_info = "Se liga al recogerlo\nRequiere Herrería (200)\n[q2]Uso: Te enseña a fabricar placas de veraplata de bajo fondo.\n[q3]Placas de veraplata de bajo fondo\nRequiere Barra de veraplata , Chatarra reflectiva (5)"},
