[215429] = {name = "[q3]Esquema: engranajes de veraplata pulidos", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (200)\n[q2]Uso: Te enseña a confeccionar un conjunto de engranajes de veraplata pulidos.\n[q3]Engranajes de veraplata pulidos\nRequiere Barra de veraplata , Pila de engranajes deslustrados (5)"},
[215430] = {name = "Residuos radioactivos de Gnomeregan", additional_info = nil},
[215431] = {name = "[q4]Esquema: bomba de radiación de alto rendimiento", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (225)\n[q2]Uso: Te enseña a confeccionar un paquete de bombas de radiación de alto rendimiento.\n[q2]Bomba de radiación de alto rendimiento\nNecesitas ser de nivel 35\nRequiere Ingeniería (200)\n{[q2]Uso: Inflige 150 to 250 p. de daño de Fuego} en el radio de la explosión, además de 25 p. de {daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante hasta cancelación. (1 Min Reutilización)}\nRequiere Pólvora sólida , Residuos radioactivos de Gnomeregan , Barra de mitril (2)"},
[215432] = {name = "[q4]Esquema: bomba de radiación para tontos", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (225)\n[q2]Uso: Te enseña a confeccionar bombas de radiación para tontos.\n[q2]Bomba de radiación para tontos\nNecesitas ser de nivel 40\n{[q2]Uso: Inflige 112 to 188 p. de daño de Fuego} en el radio de la explosión, además de 10 p. de {daño de Naturaleza cada 2 s durante 10 s. También reduce la velocidad de movimiento de los objetivos afectados un 25% durante 10 s. (1 Min Reutilización)}\n[q]\"Una versión menor pero no menos letal de su contraparte más compleja para aquellos que carezcan de la aptitud pero rebosen de confianza.\"\nRequiere Pólvora sólida (2), Residuos radioactivos de Gnomeregan , Barra de mitril (2)"},
[215433] = {name = "[q3]Receta: gniodino aislante", additional_info = "Se liga al recogerlo\nRequiere Alquimia (200)\n[q2]Uso: Te enseña a destilar un vial de gniodino aislante.\n[q3]Gniodino aislante\nRequiere Vial emplomado , Cajón de solución de gniodino maculada (5)"},
[215435] = {name = "[q3]Tratado sobre oración", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nNecesitas ser de nivel 40\n[q2]Equipar: Reduce 10 p. el costo de maná de tus hechizos de Sello."},
[215436] = {name = "[q3]Tótem de llama vigorizante", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 40\n[q2]Equipar: Reduce el costo de maná de tu hechizo Choque de llamas un 10%."},
[215437] = {name = "[q3]Transfigurador trogg 3000", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 40\n[q2]Uso: Transfigura al taumaturgo para que sea vea como un trogg. (30 Min Reutilización)\n[q]\"Suele usarse para tareas de reconocimiento.\""},
[215441] = {name = "[q2]Martillo roto", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"En este martillo de guerra ornamentado se ve la insignia de la Mano de Plata.\""},
[215443] = {name = "Fragmento de orbe destrozado", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Los restos de un orbe destrozado que brillan tenuemente y se sienten cálidos al tacto.\""},
[215444] = {name = "[q0]Monstruo - Maza - Tuberías rotas", additional_info = "Único\n{Mano derecha} {Maza}\n{1 - 2 p. de daño de Fuego} {Velocidad 2.80}\n(0.54 p. de daño por segundo)\nDurabilidad 18 / 18"},
[215449] = {name = "[q2]Encogemundos", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 40\n[q2]Uso: Encoge el mundo entero durante 5 min o hasta que ataques. (1 Hora Reutilización)\n[q]\"Parece ser un amplificador de mundo hecho con ingeniería inversa.\""},
[215450] = {name = "Proyecto de tabardo (Aidan)", additional_info = "Se liga al recogerlo\nÚnico\nTabardo\nRequiereLiga de Arathor\n: Exaltado"},
[215456] = {name = "Mensaje calcinado", additional_info = "[q]\"Te lo dije.\""},
[215458] = {name = "Mensaje cerrado", additional_info = "Clases: Pícaro\n[q]\"En serio, NO abras la última caja. Ya conseguiste lo que querías.\""},
[215459] = {name = "Mensaje cerrado", additional_info = "Clases: Pícaro\n[q]\"Detente. Esta es la última advertencia.\""},
[215460] = {name = "Mensaje cerrado", additional_info = "Clases: Pícaro\n[q]\"¡CUIDADO! Nadie debe abrir la caja que está junto a esta nota.\""},
[215461] = {name = "[q3]Pollo de ataque domesticado", additional_info = "Se liga al recogerlo\nAbalorio\nNecesitas ser de nivel 40\n[q2]Uso: Libera a tu pollo de ataque domesticado que luchará por ti durante 1.50 min o hasta que lo derroten. (30 Min Reutilización)"},
[215468] = {name = "Órdenes del Gran Cruzado", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"La carta está toda arrugada y tiene manchas de sangre seca.\""},
[215683] = {name = "Geomancia: De rocas y verdades", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Teorías sobre el origen y el uso de la magia elemental. Una gran incorporación para la colección de cualquier biblioteca.\""},
[215815] = {name = "Magia defensiva I", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una guía introductoria de la magia defensiva y las barreras. Una gran incorporación para la colección de cualquier biblioteca.\""},
[215816] = {name = "Una red de mentiras: Toda la verdad sobre los mitos y las leyendas", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una tesis incompleta que afirma que las arañas son inofensivas, pero de todos modos es una gran incorporación para la colección de cualquier biblioteca.\""},
[215817] = {name = "Los demonios y tú", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un texto extraño en el que se defiende a los demonios, pero no deja de ser una gran incorporación para la colección de cualquier biblioteca.\""},
[215820] = {name = "Momias: Una guía de los no-muertos más espantosos", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Cuentos tan aterradores que podrían asustar hasta al guerrero más duro. Una gran incorporación para la colección de cualquier biblioteca.\""},
[215822] = {name = "¡RwlRwlRwlRwl!", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Los pasajes extraños están borroneados, pero son más o menos legibles a pesar del daño del agua. Una gran incorporación para la colección de cualquier biblioteca.\""},
[215824] = {name = "Guía de cuidado de mascotas demoníacas para el ludita común", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Contiene consejos útiles para mantener a tus diablillos mascota lejos de tus componentes. Una gran incorporación para la colección de cualquier biblioteca.\""},
[216483] = {name = "Mazo Secacorteza", additional_info = "Único\n[q2]Uso: Golpea el gong en la guarida de los Secacorteza."},
[216484] = {name = "[q0]Botas de batalla impactojorfadas", additional_info = "Se liga al recogerlo\n{Pies} {Placas}\n330 armadura\n+7 aguante\n+11 intelecto\nDurabilidad 65 / 65\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 13 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Placa de guerra impactoforjada (0/3)\n[q0]Quijotes impactoforjados\nCoraza impactoforjada\nBotas de batalla impactojorfadas\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Aumenta un 2% la probabilidad de golpe crítico de Choque sagrado."},
[216485] = {name = "[q3]Coraza impactoforjada", additional_info = "Se liga al recogerlo\n{Pecho} {Placas}\n480 armadura\n+3 aguante\n+8 intelecto\nDurabilidad 125 / 125\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 19 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Placa de guerra impactoforjada (0/3)\n[q0]Quijotes impactoforjados\nCoraza impactoforjada\nBotas de batalla impactojorfadas\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Aumenta un 2% la probabilidad de golpe crítico de Choque sagrado."},
[216486] = {name = "[q3]Quijotes impactoforjados", additional_info = "Se liga al recogerlo\n{Piernas} {Placas}\n420 armadura\n+8 aguante\n+12 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 22 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Placa de guerra impactoforjada (0/3)\n[q0]Quijotes impactoforjados\nCoraza impactoforjada\nBotas de batalla impactojorfadas\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n(3) Conjunto : Aumenta un 2% la probabilidad de golpe crítico de Choque sagrado."},
[216490] = {name = "[q3]ídolo de la cólera", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta un 2% el daño de tu hechizo Cólera."},
[216491] = {name = "Cargamento de leña de Tuercespina", additional_info = "Se liga al recogerlo\n[q]\"Un cargamento de leña de la Vega de Tuercespina que puede servirle a tu facción en las Tierras Altas de Arathi.\""},
[216492] = {name = "[q3]Silbato del raptor sanguino jaspeado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 40\n[q2]Uso: Invoca y retira a un raptor que se puede montar. (3 Seg Reutilización)"},
[216494] = {name = "[q3]Tuercemundos extravagante de Aragriar", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 40\n[q2]Uso: ¿A dónde llevará este dispositivo...? En fin. ¡¿A quién le importa?! (4 H Reutilización)"},
[216495] = {name = "[q4]Trituradora sanguina", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Dos manos} {Maza}\n{110 - 165 p. de daño} {Velocidad 3.40}\n(40.44 p. de daño por segundo)\n+18 fuerza\n+12 aguante\nDurabilidad 120 / 120\nClases: Guerrero\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico."},
[216496] = {name = "[q4]Trituracráneos sanguina", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Una mano} {Maza}\n{50 - 93 p. de daño} {Velocidad 2.30}\n(31.09 p. de daño por segundo)\n+10 fuerza\n+6 agilidad\nDurabilidad 105 / 105\nClases: Guerrero\nNecesitas ser de nivel 40"},
[216497] = {name = "[q4]Desangrado", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Mano derecha} {Espada}\n{44 - 81 p. de daño} {Velocidad 2.00}\n(31.25 p. de daño por segundo)\n+6 aguante\nDurabilidad 105 / 105\nClases: Guerrero\nNecesitas ser de nivel 40\n[q2]Uso: Desata un aluvión de acero y sangre que hiere a todos los objetivos enemigos en un radio de 8 m, inflige 65 p. de daño de Golpesombra y los hace sangrar 5 p. más de daño cada 2 s durante 30 s. (3 Min Reutilización)"},
[216498] = {name = "[q4]Grimorio sanguino encantado", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nSostener con la mano izquierda\nClases: Druida\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 16 p. el daño que infligen los hechizos y efectos Arcanos.\n[q2]Equipar: Aumenta hasta 16 p. el daño que infligen los hechizos y efectos de Naturaleza."},
[216499] = {name = "[q4]Trituradora sangrecorteza", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Dos manos} {Maza}\n{54 - 86 p. de daño} {Velocidad 2.00}\n(35.00 p. de daño por segundo)\n30 armadura\n+17 fuerza\n+11 agilidad\n+6 aguante\nDurabilidad 120 / 120\nClases: Druida\nNecesitas ser de nivel 40\n[q2]Equipar: +80 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Uso: Agrega 5 p. de daño Geofísico a tus ataques cuerpo a cuerpo, que dañan a tu objetivo y sus aliados más cercanos, hasta un máximo de 3 objetivos. Provoca más amenaza. Dura 20 s. (3 Min Reutilización)"},
[216500] = {name = "[q4]Talismán arbóreo con juramento de sangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nAbalorio\nClases: Druida\nNecesitas ser de nivel 40\n[q2]Uso: Sana de forma instantánea a un objetivo aliado 300 p. de salud, pero sacrificas 300 p. de tu salud después de 2 s. (5 Min Reutilización)"},
