[216503] = {name = "[q4]Joya tormenta de sangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nAbalorio\nClases: Chamán\nNecesitas ser de nivel 40\n[q2]Uso: Sana de forma instantánea a un objetivo aliado 300 p., pero sacrificas 300 p. de tu salud después de 2 s. (5 Min Reutilización)"},
[216504] = {name = "[q4]Sable luz de sangre eclipsado", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Mano derecha} {Espada}\n{48 - 89 p. de daño} {Velocidad 2.20}\n(31.14 p. de daño por segundo)\n+4 aguante\n+4 intelecto\nDurabilidad 105 / 105\nClases: Paladín\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 14 p. el daño que infligen los hechizos y efectos Sagrados."},
