[216518] = {name = "[q4]Sello de alianza de sangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nDedo\n+8 aguante\n+7 intelecto\n+7 espíritu\nClases: Sacerdote\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 13 p. la sanación de los hechizos y efectos."},
[216519] = {name = "[q4]Sortija sombra sanguina", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nDedo\n+5 aguante\n+6 intelecto\nClases: Sacerdote\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 14 p. el daño que infligen los hechizos y efectos de las Sombras.\n[q2]Equipar: Restaura 3 p. de maná cada 5 s."},
[216520] = {name = "[q4]Cuchilla cosechasangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Una mano} {Daga}\n{41 - 77 p. de daño} {Velocidad 1.90}\n(31.05 p. de daño por segundo)\n+9 agilidad\n+8 aguante\nDurabilidad 65 / 65\nClases: Pícaro\nNecesitas ser de nivel 40"},
