[216549] = {name = "[q3]Riendas del tigre de bengala", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 40\n[q2]Uso: Invoca y retira a un tigre de bengala que se puede montar. (3 Seg Reutilización)"},
[216570] = {name = "[q3]Riendas del dientes de sable dorado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 40\n[q2]Uso: Invoca y retira a un dientes de sable dorado que se puede montar. (3 Seg Reutilización)"},
[216606] = {name = "[q2]Runa de Maestría en dos manos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu pechera o tu toga con la runa Maestría en dos manos:\n\n\nCada vez que golpeas a un enemigo con un arma de dos manos, obtienes un 45% de velocidad de ataque con armas de dos manos, un 10% más de poder de ataque y tu probabilidad de golpear con hechizos aumenta un 10% durante 10 s. Este efecto se disipará si golpeas a un enemigo con un arma de una mano.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[216607] = {name = "[q4]Ofrenda de luz sanguínea", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nAbalorio\nClases: Paladín\nNecesitas ser de nivel 40\n[q2]Uso: Sana de forma instantánea a un objetivo aliado 300 p., pero sacrificas 300 p. de tu salud después de 2 s. (5 Min Reutilización)"},
[216608] = {name = "[q4]Reflectores de rayos radiantes", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n1 armadura\nDurabilidad 50 / 50\n[q]\"Lleva grabada a un costado la palabra \"Arréglatelas\".\""},
[216610] = {name = "Órdenes del Gran Cruzado", additional_info = "Objeto de misión\nÚnico\n[q2]<Click derecho para leer>"},
