[216617] = {name = "Uniforme de luchador de Kurzen", additional_info = "Se liga al recogerlo\nÚnico"},
[216618] = {name = "Recompensa de la capitana Aransas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]<Click derecho para abrir>"},
[216619] = {name = "[q2]Vianda de estudiante", additional_info = "Se liga al recogerlo\n[q2]Uso: ¡Come un puñado y recupera el tiempo perdido siguiendo el rastro! (30 Min Reutilización)\n[q]\"Unos viejos y sabrosos cacahuetes y pasas... ¡y más!\""},
[216620] = {name = "[q3]Capa de podrisangre", additional_info = "Se liga al recogerlo\nEspalda\n32 armadura\n+7 aguante\n+6 intelecto\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 11 p. el daño y la sanación de los hechizos y efectos mágicos."},
[216621] = {name = "[q3]Mantón empapado de sangre", additional_info = "Se liga al recogerlo\nEspalda\n32 armadura\nNecesitas ser de nivel 40\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[216622] = {name = "[q3]Capa coagulada", additional_info = "Se liga al recogerlo\nEspalda\n[q2]82 armadura\n+12 aguante\nNecesitas ser de nivel 40"},
[216623] = {name = "[q3]Manteo de hemostasis", additional_info = "Se liga al recogerlo\nEspalda\n32 armadura\n+7 aguante\n+6 intelecto\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 18 p. la sanación de los hechizos y efectos."},
[216633] = {name = "Tornapunta de veraplata hidráulica", additional_info = "Se liga al recogerlo\nÚnico"},
[216634] = {name = "Fusible GG12-082", additional_info = "Objeto de misión"},
[216635] = {name = "[q2]Núcleo del vacío gastado", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combínalo con una fuente de energía adecuada para crear un núcleo del vacío cargado. (3 Seg Reutilización)\n[q]\"Este objeto parece coincidir con la descripción del núcleo del vacío que necesita Perdal, pero se lo ve completamente inerte. Debe haber una forma de recargarlo...\""},
[216636] = {name = "Núcleo del vacío cargado", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Este objeto parece absorber toda la luz y la calidez de su entorno. Se siente muy frío al tacto.\""},
[216637] = {name = "Una pila de piezas aleatorias", additional_info = "[q]\"En algún lado debe haber alguien que le encuentre utilidad a todo esto, pero parece ser pura chatarra para ti.\""},
[216645] = {name = "[q2]Mota de oscuridad", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una energía oscura permea en esta pequeña mota flotante de energía. ¿Quién sabe qué tipo de magias asombrosas podría alimentar?\""},
[216646] = {name = "[q2]Cajón misterioso de Ziri", additional_info = "Se liga al recogerlo\n[q]\"Contiene algo que tal vez alguien encuentre útil.\"\n[q2]<Click derecho para abrir>"},
[216661] = {name = "Anillo con mugre incrustada", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 40"},
[216662] = {name = "[q2]Anillo de oro luminoso", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+6 aguante\n+6 espíritu"},
[216673] = {name = "[q3]Anillo de oro luminoso de Talvash", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n70 armadura\n+16 aguante"},
[216674] = {name = "[q3]Anillo de oro luminoso de Nogg", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n70 armadura\n+16 aguante"},
[216675] = {name = "[q3]Togas civinad prístinas", additional_info = "Se liga al recogerlo\n{Pecho} {Tela}\n65 armadura\n+9 aguante\n+22 espíritu\nDurabilidad 80 / 80"},
[216676] = {name = "[q3]Peto de corredor veloz", additional_info = "Se liga al recogerlo\n{Piernas} {Cuero}\n117 armadura\n+5 fuerza\n+21 agilidad\n+8 aguante\nDurabilidad 75 / 75"},
[216678] = {name = "[q3]Leotardos triples reforzados", additional_info = "Se liga al recogerlo\n{Piernas} {Malla}\n[q2]460 armadura\nDurabilidad 90 / 90\n[q2]Equipar: Aumenta 6 p. el índice de defensa."},
[216679] = {name = "[q3]Herramienta de desmantelamiento de Shoni", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Hacha}\n{37 - 68 p. de daño} {Velocidad 1.90}\n(27.63 p. de daño por segundo)\nDurabilidad 90 / 90\n[q2]Probabilidad al acertar: Desarma el arma de un objetivo durante 5 s."},
[216680] = {name = "[q3]Manoplas llamativas", additional_info = "Se liga al recogerlo\n{Manos} {Tela}\n41 armadura\n+12 intelecto\n+11 espíritu\nDurabilidad 30 / 30"},
[216698] = {name = "[q3]Braquiales de pellejo de dragón de Alférez", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Cuero\n64 armadura\n+8 aguante\n+4 intelecto\nDurabilidad 35 / 35\nClases: Druida\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 6 p. el daño y la sanación de los hechizos y efectos mágicos."},
[216699] = {name = "[q3]Guardabrazos de anillas de Alférez", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Malla\n131 armadura\n+5 agilidad\n+12 aguante\nDurabilidad 40 / 40\nClases: Cazador\nNecesitas ser de nivel 40"},
[216700] = {name = "[q3]Braquiales de cuero de Alférez", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Cuero\n64 armadura\n+5 agilidad\n+12 aguante\nDurabilidad 35 / 35\nClases: Pícaro\nNecesitas ser de nivel 40"},
[216701] = {name = "[q3]Guardamuñecas de placas de Alférez", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Placas\n231 armadura\n+5 fuerza\n+12 aguante\nDurabilidad 45 / 45\nClases: Guerrero , Paladín\nNecesitas ser de nivel 40"},
[216702] = {name = "[q3]Puños de seda de Alférez", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Tela\n31 armadura\n+6 aguante\n+3 intelecto\nDurabilidad 30 / 30\nClases: Sacerdote , Mago , Brujo\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 8 p. el daño y la sanación de los hechizos y efectos mágicos."},
[216703] = {name = "[q3]Guardamuñecas de malla de Gran capataz", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Malla\n131 armadura\n+5 agilidad\n+10 aguante\n+7 intelecto\nDurabilidad 40 / 40\nClases: Cazador , Chamán\nNecesitas ser de nivel 40"},
[216704] = {name = "[q3]Guardabrazos de pellejo de dragón de Gran capataz", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Cuero\n64 armadura\n+8 aguante\n+4 intelecto\nDurabilidad 35 / 35\nClases: Druida\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 6 p. el daño y la sanación de los hechizos y efectos mágicos."},
[216705] = {name = "[q3]Brazales de placas de Gran capataz", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Placas\n231 armadura\n+5 fuerza\n+12 aguante\nDurabilidad 45 / 45\nClases: Guerrero\nNecesitas ser de nivel 40"},
[216706] = {name = "[q3]Guardabrazos de cuero de Gran capataz", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Cuero\n64 armadura\n+5 agilidad\n+12 aguante\nDurabilidad 35 / 35\nClases: Pícaro\nNecesitas ser de nivel 40"},
[216707] = {name = "[q3]Puños de seda de Gran capataz", additional_info = "Se liga al recogerlo\nÚnico\nMuñeca Tela\n31 armadura\n+6 aguante\n+3 intelecto\nDurabilidad 30 / 30\nClases: Sacerdote , Mago , Brujo\nNecesitas ser de nivel 40\n[q2]Equipar: Aumenta hasta 8 p. el daño y la sanación de los hechizos y efectos mágicos."},
[216738] = {name = "[q2]Manual de Redirigir", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Elimina todos tus puntos de combo existentes sobre tu objetivo y los almacena durante un máximo de 15 s. Estos puntos de combo almacenados se transferirán al próximo enemigo que no sea un jugador y que golpees con una habilidad cuerpo a cuerpo o a distancia.\n[q]\"Te enseña Redirigir.\""},
[216740] = {name = "[q2]Tomo de Intelecto expandido", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Reduce un 50% el costo de maná de Intelecto Arcano y aumenta un 50% su duración.\n[q]\"Te enseña Intelecto expandido.\""},
[216744] = {name = "[q2]Pergamino de Entereza aumentada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Reduce un 50% el costo de maná de Palabra de poder: entereza y aumenta un 50% su duración.\n[q]\"Te enseña Entereza aumentada.\""},
[216745] = {name = "[q2]Pergamino de Maligno de las Sombras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Crea un maligno de las Sombras que ataca al objetivo. El taumaturgo recibe un 5% de maná cuando el maligno de las Sombras ataca. Dura 15 s.\n[q]\"Te enseña Maligno de las Sombras.\""},
[216746] = {name = "[q2]Vademécum de Grito de orden", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]El guerrero grita y aumenta el aguante de todos los miembros del grupo en un radio de 30 m en 2 p. Dura 5 min.\n[q]\"Te enseña Grito de orden.\""},
[216747] = {name = "[q2]Grimorio de Cosecha de almas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Cada vez que Drenar alma inflige daño, tienes una probabilidad de obtener un fragmento de alma adicional. Esta probabilidad aumenta cada vez que no obtienes un fragmento de alma.\n[q]\"Te enseña Cosecha de almas.\""},
[216748] = {name = "[q2]Grimorio de Portal de invocación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Da comienzo a un ritual que crea un portal de invocación. Dos miembros del grupo o banda pueden usar el portal de invocación para invocar a un miembro del grupo o banda seleccionado. El portal para el ritual requiere al taumaturgo y 2 miembros del grupo o banda más para que se complete. Para poder participar, los jugadores deben estar fuera de combate y tienen que hacer clic con el botón derecho del ratón en el portal y no moverse hasta que se haya completado el ritual.\n[q]\"Te enseña Portal de invocación.\""},
[216764] = {name = "[q2]Panfleto de Salvajismo dominante", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Reduce un 50% el costo de maná de Marca de lo Salvaje y aumenta un 50% su duración.\n[q]\"Te enseña Salvajismo dominante.\""},
[216767] = {name = "[q2]Panfleto de Revivir", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Devuelve a un jugador muerto a la vida con un 15% de salud y maná. No se puede utilizar estando en combate.\n[q]\"Te enseña Revivir.\""},
[216768] = {name = "[q2]Testamento de Bendiciones potenciadas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Aumenta un 100% la duración de tu Bendición de poderío, de sabiduría, de salvación, de salvaguardia, de Luz y de reyes, y reduce un 50% su costo de maná.\n[q]\"Te enseña Bendiciones potenciadas.\""},
[216769] = {name = "[q2]Revelación de Proyección totémica", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Traslada tus tótems activos a la ubicación especificada.\n[q]\"Te enseña Proyección totémica.\""},
[216770] = {name = "[q2]Tratado sobre Aspecto de la víbora", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]El cazador asume el aspecto de la víbora, lo que hace que tus ataques automáticos cuerpo a cuerpo y a distancia regeneren maná, pero reduce el daño total un 10%. Además, obtienes un 10% del maná máximo cada 3 s. El maná obtenido se basa en la velocidad de tu arma. Solo puede haber un aspecto activo cada vez.\n[q]\"Te enseña Aspecto de la víbora.\""},
[216771] = {name = "[q2]Panfleto de Restauración mejorada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Ahora tus hechizos Rejuvenecimiento y Recrecimiento pueden estar activos sobre objetivos afectados por el Rejuvenecimiento o Recrecimiento de otro Druida.\n[q]\"Te enseña Restauración mejorada.\""},
[216879] = {name = "Pergamino trol misterioso", additional_info = "Único\nClases: Mago\n[q2]Uso: Descifra el pergamino con un talismán de comprensión. ¡Quién sabe qué magia contenga!"},
[216880] = {name = "Pergamino trol descifrado", additional_info = "Único\nEste objeto inicia una misión\nClases: Sacerdote"},
[216884] = {name = "[q4]Hoja sedienta de sangre", additional_info = "Se liga al recogerlo\nÚnico: (Desconocido #636) (0)\n{Dos manos} {Espada}\n{649 - 764 p. de daño} {Velocidad 4.20}\n(168.21 p. de daño por segundo)\n+333 fuerza\nDurabilidad 120 / 120\nNecesitas ser de nivel 125\n[q2]Probabilidad al acertar: Reclama el alma prometida."},
[216914] = {name = "[q0]Mención deslustrada", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 30\n[q]\"Ha perdido su brillo...\""},
[216918] = {name = "[q4]Botas corazón vil", additional_info = "Se liga al recogerlo\n{Pies} {Tela}\n[q2]150 armadura\n+25 aguante\n+5 intelecto\n+5 resistencia a Fuego\nDurabilidad 50 / 50\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Aumenta 10 p. el índice de defensa.\n\n[q]Corazón vil maligno (0/8)\n[q0]Ataduras corazón vil\nBotas corazón vil\nCorona corazón vil\nAbrazo corazón vil\nMandiletes corazón vil\nLeotardos corazón vil\nManto corazón vil\nFajín corazón vil\n[q0](2) Conjunto : Desterrar ahora se lanza al instante y se puede lanzar sobre ti mismo mientras seas un demonio. No puedes Desterrarte a ti mismo mientras tienes Abstinencia, y si lo haces recibirás Abstinencia durante 1 min.\n(4) Conjunto : Cada vez que recibes daño, tú y tu mascota obtienen una cantidad de maná equivalente al daño recibido, hasta un máximo de 420 p. de maná por evento. Solo puede ocurrir una vez cada pocos segundos. (3.5s de reutilización)\n(6) Conjunto : Tus golpes de Cuchilla de las Sombras tienen un 20% de probabilidad de otorgarte un fragmento de alma, restablecer el tiempo de reutilización de Fuego de alma y hacer que tu siguiente Fuego de alma en los próximos 10 s sea instantáneo. (Probabilidad de que accione: 20%, 100ms de reutilización)"},
[216919] = {name = "[q0]Fajín corazón vil", additional_info = "Se liga al recogerlo\n{Cintura} {Tela}\n[q2]137 armadura\n+25 aguante\n+5 intelecto\n+7 resistencia a Fuego\nDurabilidad 35 / 35\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 6 p. el índice de defensa.\n[q2]Equipar: Aumenta hasta 9 p. el daño y la sanación de los hechizos y efectos mágicos.\n\n[q]Corazón vil maligno (0/8)\n[q0]Ataduras corazón vil\nBotas corazón vil\nCorona corazón vil\nAbrazo corazón vil\nMandiletes corazón vil\nLeotardos corazón vil\nManto corazón vil\nFajín corazón vil\n[q0](2) Conjunto : Desterrar ahora se lanza al instante y se puede lanzar sobre ti mismo mientras seas un demonio. No puedes Desterrarte a ti mismo mientras tienes Abstinencia, y si lo haces recibirás Abstinencia durante 1 min.\n(4) Conjunto : Cada vez que recibes daño, tú y tu mascota obtienen una cantidad de maná equivalente al daño recibido, hasta un máximo de 420 p. de maná por evento. Solo puede ocurrir una vez cada pocos segundos. (3.5s de reutilización)\n(6) Conjunto : Tus golpes de Cuchilla de las Sombras tienen un 20% de probabilidad de otorgarte un fragmento de alma, restablecer el tiempo de reutilización de Fuego de alma y hacer que tu siguiente Fuego de alma en los próximos 10 s sea instantáneo. (Probabilidad de que accione: 20%, 100ms de reutilización)"},
