[217350] = {name = "[q4]Notas de ingeniería de Termochufe", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 40\n[q]\"Este cuaderno maltrecho contiene planos para diversos armamentos destructivos y aterradores. Deberías entregarle estas notas al Alto rey Mekkatorque lo antes posible.\""},
[217351] = {name = "[q4]Notas de ingeniería de Termochufe", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 40\n[q]\"Este cuaderno maltrecho contiene planos para diversos armamentos destructivos y aterradores. Seguramente a Nogg le interese mucho.\""},
