[219147] = {name = "[q2]Runa de Gracia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus brazales con la runa Gracia de Luz:\n\n\nTu hechizo Luz Sagrada reduce 0.5 s el tiempo de lanzamiento de tu próxima Luz Sagrada. Dura 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[219223] = {name = "[q3]Furia del maestro del acero", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{104 - 157 p. de daño} {Velocidad 3.00}\n(43.50 p. de daño por segundo)\n+17 fuerza\n+10 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\n[q2]Uso: Ataca a un máximo de 4 enemigos en un radio de 8 m, lo que inflige daño con arma a cada enemigo y restablece el tiempo de reutilización de tu habilidad Torbellino. (2 Min Reutilización)"},
[219326] = {name = "[q3]Semilla de renovación", additional_info = "Se liga al recogerlo\nAbalorio\nNecesitas ser de nivel 50\n[q2]Equipar: Hay una probabilidad de incrustar una semilla en los humanoides, las bestias y los dragonantes golpeados por tus habilidades o hechizos. Si la criatura muere en los primeros 30 segundos desde la plantación de la semilla, crecerá una Flor sanadora de su cadáver. (Probabilidad de que accione: 40%, 2m de reutilización)"},
[219343] = {name = "[q3]Capucha de ratero", additional_info = "Se liga al recogerlo\nEspalda\n36 armadura\n+11 agilidad\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta en 3 tu nivel de sigilo efectivo. Aumenta 2 m el radio de Desactivar trampa y Robar, y 5 m el radio de Distraer."},
[219345] = {name = "[q3]Lazo infernal", additional_info = "Se liga al recogerlo\nAbalorio\nNecesitas ser de nivel 50\n[q2]Uso: Enraíza al demonio o bestia objetivo en el sitio e inflige 200 p. de daño de Fuego durante 24 s. El daño infligido puede interrumpir el efecto. Se puede domar a los canes del Núcleo enlazados. (1 Min Reutilización)"},
