[220105] = {name = "[q2]Autorización de designación: Misión XVII de Feralas", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 1 hora\n[q2]Uso: Designa a un miembro del grupo para compartirle esta misión y que pueda completarla contigo.\n4 cargas\n[q]\"Te permite compartir esta misión con los miembros del grupo.\""},
[220106] = {name = "[q2]Autorización de designación: Misión XVIII de Feralas", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 1 hora\n[q2]Uso: Designa a un miembro del grupo para compartirle esta misión y que pueda completarla contigo.\n4 cargas\n[q]\"Te permite compartir esta misión con los miembros del grupo.\""},
[220164] = {name = "[q2]Runa del Gladiador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus botas con la runa Actitud de gladiador:\n\n\nUna actitud agresiva que aumenta el daño un 10% cuando llevas un escudo y aumenta un 10% la probabilidad de bloqueo, pero que reduce un 30% la armadura y un 30% la amenaza generada. Además, obtienes un 50% más de ira cuando tu ataque automático daña a un enemigo que no te tiene como objetivo.\n\n Cuando llevas un escudo en la Actitud de gladiador, puedes usar todas las habilidades que están restringidas a otras actitudes.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[220165] = {name = "[q2]Runa de Cólera", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu yelmo con la runa Cólera:\n\n\nAhora tu daño de Consagración puede ser un golpe crítico, y el daño de tus hechizos Exorcismo, Choque sagrado, Cólera sagrada y Consagración obtiene una probabilidad de golpe crítico equivalente a tu probabilidad de golpe crítico cuerpo a cuerpo.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[220166] = {name = "Núcleo infernal ardiente", additional_info = "Objeto de misión"},
[220167] = {name = "Polvo de sepultura resplandeciente", additional_info = "Objeto de misión\n[q]\"Polvo de sepultura del sitio de descanso de alguien que fue asesinado por sus seres queridos...\""},
[220168] = {name = "Cerveza fundida de triple filtrado", additional_info = "Objeto de misión\nÚnico\n[q]\"Un elixir de fuego creado con manos firmes y una mente inestable...\""},
[220169] = {name = "Símbolo de fe", additional_info = "Objeto de misión\n[q]\"Un símbolo de fe, obsequio de alguien cuyo propósito fue descubierto recientemente...\""},
[220173] = {name = "[q4]Parasomnia", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Dos manos} {Espada}\n{142 - 213 p. de daño} {Velocidad 3.40}\n(52.21 p. de daño por segundo)\n+15 fuerza\n+11 agilidad\n+28 aguante\nDurabilidad 120 / 120\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\n[q2]Probabilidad al acertar: Aplica Parasomnia al objetivo, lo que hace que deambule sin rumbo hasta durante 2 s.\n[q]\"Nacido de la pesadilla\""},
[220213] = {name = "Sangrevida vil", additional_info = "Se liga al recogerlo\nÚnico"},
[220214] = {name = "Eslabón infernal", additional_info = "Se liga al recogerlo\nÚnico (5)"},
[220216] = {name = "Lazo infernal", additional_info = "Se liga al recogerlo\n[q2]Uso: Debilita a Calefactus, el Desatado. (30 Seg Reutilización)"},
[220217] = {name = "[q2]Runa del Voraz", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tu yelmo con la runa Matanza rápida:\n\n\nReduce el tiempo de reutilización de Fuego rápido un 80%. Fuego rápido ahora también otorga un 40% más de velocidad de ataque cuerpo a cuerpo, y tu siguiente habilidad de Disparo en un período de 20 s después de matar a un objetivo que otorga experiencia u honor inflige un 20% de daño extra.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220345] = {name = "Hechicería sanguina", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una presentación de distintos rituales de sangre poderosos. Una incorporación polémica para la colección de cualquier biblioteca.\""},
[220346] = {name = "Leyendas de los maresabios", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Un tomo repleto de notas y diagramas ilegibles escritos rápidamente con una mano temblorosa. Aun así, podría ser una incorporación decente para la colección de cualquier biblioteca.\""},
[220347] = {name = "Lo liminal y lo arcano", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Las palabras de las páginas se entremezclan y aparecen borrosas, lo que imposibilita la lectura. Una incorporación enigmática para la colección de cualquier biblioteca.\""},
[220348] = {name = "Etiqueta para el día a día", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una guía sobre el rol de la magia elemental en la sociedad altonato educada. Una gran incorporación para la colección de cualquier biblioteca.\""},
[220349] = {name = "Diseño trabajado en piedra", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Técnicas de arquitectura capaces de soportar hasta los desastres más cataclísmicos. Una gran incorporación para la colección de cualquier biblioteca.\""},
[220350] = {name = "Travesías venenosas", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Notas sobre las propiedades alteramentes de varias toxinas y venenos. Una gran incorporación para la colección de cualquier biblioteca.\""},
[220351] = {name = "Sapta de aire de Murky", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Permite al chamán ver a los espíritus elementales."},
[220352] = {name = "Mente metálica", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Técnicas enanas para aplicar la magia a la metalurgia, la excavación a cielo abierto y la industria pesada. Una incorporación informativa, aunque un poco desoladora, para la colección de cualquier biblioteca.\""},
[220353] = {name = "Códice del conjurador", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una colección de hechizos y teorías arcanas anteriores a la guerra que se han dejado de usar con el tiempo. Una gran incorporación para la colección de cualquier biblioteca.\""},
[220360] = {name = "[q2]Runa de Floración", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus brazales con la runa Floración:\n\n\nTu Alivio presto ahora también provoca Floración, que sana [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100] p. de salud cada 1 s a todos los miembros del grupo en un radio de 15 m de la ubicación del objetivo de Alivio presto durante 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220375] = {name = "Fragmento de aire", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina el fragmento de aire con esencias elementales. Puede ayudar a encontrar el santuario corrupto."},
[220379] = {name = "Notas de chamán rasgadas", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nClases: Chamán\n[q]\"Notas escritas con prisa que son casi ilegibles. Las páginas parecen estar envueltas alrededor de algo.\""},
[220446] = {name = "[q2]Tesoro sobrenatural", additional_info = "Se liga al recogerlo\n[q2]<Click derecho para abrir>"},
[220510] = {name = "Esencia elemental", additional_info = "Objeto de misión\nClases: Chamán"},
[220511] = {name = "[q3]Gran yelmo de la pesadilla", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n469 armadura\n+25 fuerza\n+6 aguante\nDurabilidad 80 / 80\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[220512] = {name = "[q3]Casco de acero aúreo inmaculado", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n469 armadura\n+8 aguante\n+14 intelecto\nDurabilidad 80 / 80\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 44 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 4 p. de maná cada 5 s."},
[220514] = {name = "[q3]Visor de plumas verdeante", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n266 armadura\n+14 intelecto\n+13 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 31 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 8 p. de maná cada 5 s."},
[220515] = {name = "[q3]Casco esmeralda encantado", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n266 armadura\n+9 aguante\n+8 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 29 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220516] = {name = "[q3]Visor olvidado de Gasher", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n266 armadura\n+12 aguante\n+12 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 30 p. el poder de ataque."},
[220518] = {name = "[q3]Sombrero polvoriento de Ba'ham", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n128 armadura\n+15 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\n[q2]Equipar: Aumenta 38 p. el poder de ataque."},
[220519] = {name = "[q3]Ornato emplumado vudú", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n128 armadura\n+11 aguante\n+14 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 29 p. la sanación de los hechizos y efectos."},
[220521] = {name = "[q3]Ornato de ritualista hakkari", additional_info = "Se liga al recogerlo\n{Cabeza} {Cuero}\n128 armadura\n+14 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 22 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220522] = {name = "[q3]Corona atrapadora de almas", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n64 armadura\n+15 intelecto\n+12 espíritu\nDurabilidad 50 / 50\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 44 p. la sanación de los hechizos y efectos."},
[220523] = {name = "[q4]Rostro de los exiliados", additional_info = "Se liga al recogerlo\n{Cabeza} {Tela}\n67 armadura\n+14 aguante\n+15 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220525] = {name = "Fragmento de aire resplandeciente", additional_info = "Se liga al recogerlo\nÚnico"},
[220526] = {name = "[q2]Procesador de N.Ú.C.L.E.O. G-7 cubierto de fango", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Este núcleo de procesador de alguna forma está en peor estado que la última vez que lo encontraste. Está cubierto de un pegote negro que parece... ¿retorcerse? Qué asco.\""},
[220527] = {name = "[q3]Manto de rabioso Atal'ai", additional_info = "Se liga al recogerlo\n{Hombro} {Malla}\n246 armadura\n+18 fuerza\n+4 agilidad\n+6 aguante\n+7 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 50"},
[220528] = {name = "[q3]Sobrehombros de cazador Atal'ai", additional_info = "Se liga al recogerlo\n{Hombro} {Malla}\n246 armadura\n+18 agilidad\n+12 aguante\nDurabilidad 70 / 70\nNecesitas ser de nivel 50"},
[220529] = {name = "[q3]Bufas de fanatismo", additional_info = "Se liga al recogerlo\n{Hombro} {Placas}\n433 armadura\n+15 fuerza\n+10 agilidad\nDurabilidad 80 / 80\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[220530] = {name = "[q4]Voluntad del guerrero Atal'ai", additional_info = "Se liga al recogerlo\n{Pecho} {Placas}\n608 armadura\n+11 fuerza\n+5 agilidad\n+18 aguante\nDurabilidad 165 / 165\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 30 p."},
[220531] = {name = "Flor púrpura ondulante", additional_info = "Objeto de misión\nÚnico\n[q]\"Una pequeña flor que parece ondularse en tus manos. Te da una mala sensación de tan solo sujetarla.\""},
[220532] = {name = "[q3]Bufas Atal'ai reforzadas", additional_info = "Se liga al recogerlo\n{Hombro} {Cuero}\n118 armadura\n+9 fuerza\n+7 agilidad\n+12 aguante\nDurabilidad 60 / 60\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta un 1% tu probabilidad de esquivar un ataque."},
[220533] = {name = "[q3]Coraza Atal'ai reforjada", additional_info = "Se liga al recogerlo\n{Pecho} {Malla}\n327 armadura\n+21 agilidad\n+20 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 50"},
[220534] = {name = "[q4]Abrazo eterno de la serpiente alada", additional_info = "Se liga al recogerlo\n{Pecho} {Tela}\n86 armadura\n+8 aguante\n+17 intelecto\n+15 espíritu\n+12 resistencia a Naturaleza\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 44 p. la sanación de los hechizos y efectos."},
[220535] = {name = "[q4]Prendas de profeta Atal'ai", additional_info = "Se liga al recogerlo\n{Pecho} {Tela}\n83 armadura\n+10 aguante\n+14 intelecto\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 35 p. el daño y la sanación de los hechizos y efectos mágicos."},
