[220597] = {name = "[q4]Piedra draco de emisario del sueño", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 23 p. el daño que infligen los hechizos y efectos de Escarcha.\n[q2]Equipar: Aumenta hasta 23 p. el daño que infligen los hechizos y efectos de Naturaleza.\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220598] = {name = "[q4]Piedra draco emisario de pesadilla", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 23 p. el daño que infligen los hechizos y efectos de las Sombras.\n[q2]Equipar: Aumenta hasta 23 p. el daño que infligen los hechizos y efectos Arcanos.\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220599] = {name = "[q4]Piedra draco de profeta de sangre", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 35 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Aumenta hasta 23 p. el daño que infligen los hechizos y efectos de Fuego.\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220600] = {name = "[q4]Emblema de preeminencia", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2043 armadura\n36 bloqueo\n+8 fuerza\n+11 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 21 p."},
[220601] = {name = "[q4]Protector de médica bruja Hakkari", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2043 armadura\n36 bloqueo\n+8 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220602] = {name = "[q4]Medio caparazón de tortuga de alcantarilla", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2043 armadura\n36 bloqueo\n+8 aguante\n+9 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 35 p. la sanación de los hechizos y efectos."},
[220603] = {name = "[q4]Vara de corrosión irreversible", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{52 - 96 p. de daño de Naturaleza} {Velocidad 1.30}\n(56.92 p. de daño por segundo)\n+6 intelecto\n+8 espíritu\n+5 resistencia a Naturaleza\nDurabilidad 75 / 75\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 13 p. la sanación de los hechizos y efectos."},
[220604] = {name = "[q4]Trofeo de pesadilla", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{72 - 136 p. de daño de Sombras} {Velocidad 1.80}\n(57.78 p. de daño por segundo)\n+5 intelecto\nDurabilidad 75 / 75\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 12 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220605] = {name = "[q3]Tratado sobre sacrilegio", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta un 2% la probabilidad de bloqueo de tu próximo hechizo Escudo Sagrado."},
[220606] = {name = "[q3]Ídolo del sueño", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta un 2% el daño de Flagelo y Triturar."},
[220607] = {name = "[q3]Tótem de linaje atormentado", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 50\n[q2]Equipar: Choque de llamas otorga 10 p. de poder de ataque, daño con hechizos y sanación durante 12 s."},
[220608] = {name = "[q4]Mantón de piel emplumada", additional_info = "Se liga al recogerlo\nEspalda\n41 armadura\n+10 intelecto\n+7 espíritu\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 35 p. la sanación de los hechizos y efectos."},
[220609] = {name = "[q3]Mantón del ocaso", additional_info = "Se liga al recogerlo\nEspalda\n39 armadura\n+8 agilidad\n+14 aguante\nNecesitas ser de nivel 50"},
[220610] = {name = "[q2]Runa de Maña mental", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu yelmo con la runa Maña mental:\n\n\nInfligir daño con Golpe de tormenta aumenta tu poder de ataque una cantidad equivalente al 150% de tu intelecto, y aumenta el daño de tus hechizos una cantidad equivalente al 35% de tu poder de ataque total durante 30 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220611] = {name = "[q3]Manteo de maleficio de Hukku", additional_info = "Se liga al recogerlo\nEspalda\n39 armadura\n+10 intelecto\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 15 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220612] = {name = "[q2]Runa de Maremotos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu yelmo con la runa Maremotos:\n\n\nCuando lanzas Sanación en cadena o Mareas Vivas, obtienes 2 cargas de Maremotos, que reducen un 30% el tiempo de lanzamiento de tu Ola de sanación, reducen un 15% el tiempo de lanzamiento de tu Sanación en cadena y aumentan un 25% la probabilidad de efecto crítico de tu Ola de sanación inferior.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220613] = {name = "[q2]Runa de Trueno ensordecedor", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus brazales con la runa Trueno ensordecedor:\n\n\nDescarga de relámpagos y Cadena de relámpagos tienen un 50% de probabilidad de agregar una carga más a tu Escudo de relámpagos activo, hasta un máximo de 9 cargas.\n\n Cuando tienes más de 3 cargas, Choque de tierra ahora libera las cargas excedentes para que inflijan su daño al objetivo y te energicen con un 2% de tu maná máximo por carga.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220614] = {name = "[q2]Runa de Choque estático", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus brazales con la runa Choque estático:\n\n\nTu Escudo de relámpagos ahora tiene 9 cargas, y tus ataques cuerpo a cuerpo tienen un 12% de probabilidad (6% de probabilidad cuando usas dos armas) de activar una de esas cargas, que infligen daño a tu objetivo inmediatamente.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220615] = {name = "[q3]Capa de piel de pantera", additional_info = "Se liga al recogerlo\nEspalda\n39 armadura\n+6 fuerza\n+15 agilidad\nNecesitas ser de nivel 50"},
[220616] = {name = "[q2]Runa de Sobrecarga", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus brazales con la runa Sobrecarga:\n\n\nTu Escudo de relámpagos nunca pierde cargas, ahora tiene un tiempo de reutilización de 3 s e inflige daño a todos los enemigos que están en un radio de 8 m.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220617] = {name = "[q2]Runa de Pandemia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu yelmo con la runa Pandemia:\n\n\nEl daño periódico de tus habilidades Corrupción, Aflicción inestable, Maldición de agonía, Inmolar, Maldición del Apocalipsis y Succionar vida ahora pueden ser golpes críticos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220618] = {name = "[q2]Runa de Aura de inmolación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus brazales con la runa Aura de inmolación:\n\n\nQuema a los enemigos cercanos por [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100] p. de daño cada vez que un enemigo te ataca cuerpo a cuerpo (no más de una vez por segundo), reduce todo el daño mágico recibido un 10%, y aumenta el daño de Fuego infligido un 10%. Dura hasta cancelación.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220619] = {name = "[q4]Ceremonia de sangre atal'ai", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Una daga de sacrificios. Tiene grabado un cántico que pertenecía a una antigua ceremonia de sangre atal'ai. (35 Seg Reutilización)\n[q]\"El loa de la sangre solo elige a los dignos.\""},
[220620] = {name = "[q4]Calavera de serpiente alada", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Haz clic con el botón derecho del ratón para invocar y retirar a tu serpiente alada."},
[220621] = {name = "[q4]Cristal de resonancia de pesadilla", additional_info = "Se liga al recogerlo\nAbalorio\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Exaltado\n[q2]Uso: El cristal resuena en respuesta a la pesadilla.\n[q]\"Esencia de la pesadilla cristalizada. Vibra en respuesta al Sueño. Parece que anhela la... ¿corrupción?\""},
[220622] = {name = "[q4]Ojo de dragón perfectamente preservado", additional_info = "Se liga al recogerlo\nCuello\n+8 aguante\n+10 intelecto\n+8 espíritu\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 24 p. la sanación de los hechizos y efectos."},
[220623] = {name = "[q4]Guardapelo perdido de Jin'do", additional_info = "Se liga al recogerlo\nCuello\n+9 aguante\n+8 intelecto\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 19 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220624] = {name = "[q3]Talismán de valor manchado de sangre", additional_info = "Se liga al recogerlo\nCuello\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 18 p. el poder de ataque."},
[220625] = {name = "[q3]Resiliencia de los exiliados", additional_info = "Se liga al recogerlo\nCuello\n90 armadura\n+8 aguante\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[220626] = {name = "[q4]Sortija de garra de draco de rabioso", additional_info = "Se liga al recogerlo\nDedo\n+13 aguante\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 20 p. el poder de ataque."},
[220627] = {name = "[q4]Sortija de garra de draco de acechador", additional_info = "Se liga al recogerlo\nDedo\n+10 aguante\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 31 p. el poder de ataque a distancia."},
[220628] = {name = "[q4]Sortija de garra de draco de emisario", additional_info = "Se liga al recogerlo\nDedo\n+11 intelecto\n+12 espíritu\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 15 p. el daño y la sanación de los hechizos y efectos mágicos."},
[220629] = {name = "[q4]Sortija de garra de draco de profeta de sangre", additional_info = "Se liga al recogerlo\nDedo\n+12 intelecto\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 20 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 5 p. de maná cada 5 s."},
[220630] = {name = "[q4]Sortija de garra de draco de gigante", additional_info = "Se liga al recogerlo\nDedo\n[q2]60 armadura\n+16 aguante\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[220632] = {name = "[q4]Medallón de ritual de sangre atal'ai", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta el daño cuerpo a cuerpo y a distancia en 20 p. durante 20 s. Cada vez que alcances a un objetivo, esta bonificación se reducirá en 1 p. (2 Min Reutilización)"},
[220633] = {name = "[q4]Insignia de ritual de sangre atal'ai", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta 1000 p. tu armadura y 20 p. tu habilidad de defensa durante 20 s. Cada vez que recibes daño cuerpo a cuerpo o a distancia, esta bonificación pierde 100 p. de armadura y 2 p. de defensa. (2 Min Reutilización)"},
[220634] = {name = "[q4]Talismán de ritual de sangre atal'ai", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta hasta 96 p. tu daño con hechizos y hasta 192 p. tu sanación durante 20 s. Cada vez que lanzas un hechizo, la bonificación pierde 8 p. de daño con hechizos y 16 p. de sanación. (2 Min Reutilización)"},
[220635] = {name = "[q4]Roca encantada de Atal'alarion", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Concentra tu espíritu en la roca favorita de Atal'alarion. Encantada con los últimos ecos de su alma. (15 Min Reutilización)"},
[220636] = {name = "[q3]Ícono de sangre atal'ai", additional_info = "Se liga al recogerlo\nClases: Guerrero , Paladín , Cazador , Pícaro , Chamán"},
[220637] = {name = "[q3]Ficha de ritual atal'ai", additional_info = "Se liga al recogerlo\nClases: Sacerdote , Mago , Brujo , Druida"},
[220638] = {name = "[q4]Palo de maleficios poco ortodoxo", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Te lanza un antiguo maleficio atal'ai. (15 Min Reutilización)\n[q]\"A test for only the strongest of bonds.\""},
[220639] = {name = "[q4]Inanimator de Lledra", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: ¡Te vuelve inanimado! (3 Seg Reutilización)"},
[220642] = {name = "[q3]Armadura de placas de mártir expulsado", additional_info = "Se liga al recogerlo\n{Pecho} {Placas}\n577 armadura\n+5 fuerza\n+9 agilidad\n+18 aguante\nDurabilidad 135 / 135\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 24 p.\n\n[q]Placa total de mártir expulsado (0/3)\n[q0]Armadura de placas de mártir expulsado\nMusleras de placas de mártir expulsado\nBotas de placas de mártir expulsado\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n(3) Conjunto : Obtienes 50 de valor de bloqueo 6 s después de bloquear."},
[220643] = {name = "[q3]Musleras de placas de mártir expulsado", additional_info = "Se liga al recogerlo\n{Piernas} {Placas}\n505 armadura\n+11 fuerza\n+18 aguante\nDurabilidad 100 / 100\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 23 p.\n\n[q]Placa total de mártir expulsado (0/3)\n[q0]Armadura de placas de mártir expulsado\nMusleras de placas de mártir expulsado\nBotas de placas de mártir expulsado\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n(3) Conjunto : Obtienes 50 de valor de bloqueo 6 s después de bloquear."},
[220648] = {name = "[q0]Botas de placas de mártir expulsado", additional_info = "Se liga al recogerlo\n{Pies} {Placas}\n397 armadura\n+7 fuerza\n+19 aguante\nDurabilidad 65 / 65\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 1%.\n\n[q]Placa total de mártir expulsado (0/3)\n[q0]Armadura de placas de mártir expulsado\nMusleras de placas de mártir expulsado\nBotas de placas de mártir expulsado\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n(3) Conjunto : Obtienes 50 de valor de bloqueo 6 s después de bloquear."},
[220649] = {name = "[q3]Herencia de Merithra", additional_info = "Se liga al recogerlo\nÚnico\n{Pecho} {Tela}\n72 armadura\n+20 aguante\n+5 resistencia a Arcano\n+5 resistencia a Naturaleza\nDurabilidad 80 / 80\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Reverenciado\n[q2]Uso: Duerme al enemigo objetivo durante un máximo de 30 s. Cualquier daño que se inflija lo despertará. Solo se puede dormir a un objetivo a la vez. (15 Min Reutilización)"},
[220650] = {name = "[q3]Peto de profeta obsesionado", additional_info = "Se liga al recogerlo\n{Pecho} {Placas}\n577 armadura\n+11 aguante\n+10 intelecto\nDurabilidad 135 / 135\nClases: Paladín\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 37 p. la sanación de los hechizos y efectos.\n\n[q]Placas de profeta obsesionado (0/3)\n[q0]Peto de profeta obsesionado\nMusleras de profeta obsesionado\nBotas ornamentadas de profeta obsesionado\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : Aumenta la probabilidad de conseguir un golpe crítico con hechizos Sagrados un 3%."},
[220651] = {name = "[q3]Musleras de profeta obsesionado", additional_info = "Se liga al recogerlo\n{Piernas} {Placas}\n505 armadura\n+6 aguante\n+14 intelecto\nDurabilidad 85 / 85\nClases: Paladín\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 33 p. la sanación de los hechizos y efectos.\n\n[q]Placas de profeta obsesionado (0/3)\n[q0]Peto de profeta obsesionado\nMusleras de profeta obsesionado\nBotas ornamentadas de profeta obsesionado\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : Aumenta la probabilidad de conseguir un golpe crítico con hechizos Sagrados un 3%."},
[220652] = {name = "[q0]Botas ornamentadas de profeta obsesionado", additional_info = "Se liga al recogerlo\n{Pies} {Placas}\n397 armadura\n+8 aguante\n+10 intelecto\nDurabilidad 65 / 65\nClases: Paladín\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 13 p. la sanación de los hechizos y efectos.\n\n[q]Placas de profeta obsesionado (0/3)\n[q0]Peto de profeta obsesionado\nMusleras de profeta obsesionado\nBotas ornamentadas de profeta obsesionado\n[q0](2) Conjunto : Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n(3) Conjunto : Aumenta la probabilidad de conseguir un golpe crítico con hechizos Sagrados un 3%."},
