[220686] = {name = "[q4]Azote del cabecilla", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{146 - 219 p. de daño} {Velocidad 3.50}\n(52.14 p. de daño por segundo)\n+35 fuerza\nDurabilidad 120 / 120\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[220687] = {name = "[q2]Runa del Raptor", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tus brazales con la runa Furia de raptor:\n\n\nGolpe de raptor aumenta un 15% el daño infligido por Golpe de raptor y Mordedura de mangosta durante 30 s. Se acumula hasta 5 veces. Las aplicaciones posteriores no extienden la duración de este efecto.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220688] = {name = "[q4]Manto de pesadillas inerte", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Si sujetas este objeto y aguzas el oído, puedes escuchar gritos a lo lejos.\""},
[220689] = {name = "[q3]Avambrazos potenciados por el Vacío", additional_info = "Se liga al recogerlo\nMuñeca Tela\n31 armadura\n+6 fuerza\n+6 agilidad\n+6 aguante\n+6 intelecto\n+6 espíritu\nDurabilidad 30 / 30\nNecesitas ser de nivel 50\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q]\"Cuando vistes estos avambrazos, un escalofrío te recorre la espalda, como si alguien se parara justo detrás de ti.\""},
[220738] = {name = "[q4]Hombreras de pavor", additional_info = "Se liga al recogerlo\n{Hombro} {Placas}\n472 armadura\n+12 fuerza\n+12 agilidad\n+12 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\nRequiere Herrería (250)\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Tus ataques cuerpo a cuerpo tienen una probabilidad de aumentar tu velocidad de ataque un 5% y tu poder de ataque 50 p. durante 10 s. No tiene efecto fuera de las áreas bajo la influencia de la Pesadilla. (Probabilidad de que accione: 30%, 40s de reutilización)"},
