[220912] = {name = "Martillo de geodas", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{34 - 64 p. de daño} {Velocidad 1.90}\n(25.79 p. de daño por segundo)\nDurabilidad 75 / 75\nNecesitas ser de nivel 41\n[q]\"La cabeza tiene algunas grietas.\""},
[220913] = {name = "[q2]Runa de Demolición", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus brazales con la runa Equipo de demolición:\n\n\nTus golpes críticos cuerpo a cuerpo te enfurecen (lo que activa las habilidades que requieren ese estado) y aumentan el daño de Golpe mortal, Sed de sangre y Embate con escudo un 10% durante 12 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[220914] = {name = "[q0]Martillo de geodas roto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q]\"La cabeza está partida.\"\n[q2]<Click derecho para abrir>"},
[220915] = {name = "[q2]Ídolo del arrastrapiés colérico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nClases: Druida\n[q2]Graba tu yelmo con la runa Piel de corteza mejorada:\n\n\nAhora Piel de corteza puede lanzarse sobre aliados, ya no penaliza la velocidad de combate cuerpo a cuerpo ni el tiempo de lanzamiento de hechizos, y puede usarse durante un cambio de forma.\n[q]\"Mata a 5 enemigos con daño de Naturaleza mientras estás bajo los efectos de Piel de corteza. Luego, usa el ídolo para aprender una nueva habilidad.\""},
