[220933] = {name = "[q2]Suministros faltantes: Rifles de torio", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 2 rifles de torio para completar este cargamento."},
