[220936] = {name = "[q2]Suministros faltantes: Guanteletes de veraplata", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 2 guanteletes de veraplata para completar este cargamento."},
[220937] = {name = "[q2]Suministros faltantes: Refuerzos para armadura bastos", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 12 refuerzos para armadura bastos para completar este cargamento."},
[220938] = {name = "[q2]Suministros faltantes: Brazales de cuero maligno", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 6 brazales de cuero maligno para completar este cargamento."},
[220939] = {name = "[q2]Suministros faltantes: Brazales de cuero rúnico", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 5 brazales de cuero rúnico para completar este cargamento."},
[220940] = {name = "[q2]Suministros faltantes: Cintas de tejido mágico negra", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 5 cintas de tejido mágico negras para completar este cargamento."},
[220941] = {name = "[q2]Suministros faltantes: Cinturones de paño rúnico", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 6 cinturones de paño rúnico para completar este cargamento."},
[220942] = {name = "[q2]Suministros faltantes: Camisas de esmoquin", additional_info = "Se liga al recogerlo\nÚnico: [Waylaid Shipment] (12)\n[q2]Uso: Agrega 4 camisas de esmoquin para completar este cargamento."},
[220964] = {name = "[q3]Avambrazos potenciados por el Vacío descargados", additional_info = "Objeto de misiónMuñeca Tela\n31 armadura\nDurabilidad 30 / 30\nNecesitas ser de nivel 50"},
[220965] = {name = "[q4]Gran hacha de Horrocrusto", additional_info = "Se liga al recogerlo\n{Dos manos} {Hacha}\n{138 - 207 p. de daño} {Velocidad 3.40}\n(50.74 p. de daño por segundo)\nDurabilidad 120 / 120\nNecesitas ser de nivel 50\n[q2]Equipar: +117 p. de poder de ataque en la lucha contra dragonantes.\n[q]\"Un remedio digno de un dragón.\""},
[221008] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[221009] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[221010] = {name = "[q2]Cargamento de suministros", additional_info = "Se liga al recogerlo\n[q]\"Entrégalos a un oficial de suministros para obtener una recompensa generosa.\""},
[221017] = {name = "Registro de Keldara", additional_info = "Se liga al recogerlo\nÚnico\n[q2]<Click derecho para leer>"},
[221018] = {name = "Botiquín de campo", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina 3 muestras de herbasátiro para elaborar una tintura."},
[221019] = {name = "Muestra de herbasátiro", additional_info = "Se liga al recogerlo"},
[221020] = {name = "[q2]Runa de la Diosa lunar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus brazales con la runa Fuegos de Elune:\n\n\nAlgunos de tus hechizos y habilidades extienden la duración de tus efectos de daño y sanación con el tiempo en el objetivo:\n\n Fuego estelar extiende 6 s la duración de Fuego lunar.\n Cólera extiende 3 s la duración de Fuego solar.\n Recrecimiento extiende 6 s la duración de Rejuvenecimiento.\n Triturar extiende 2 s la duración de Destripar.\n\n Cada efecto solo se puede extender hasta completar su duración inicial.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[221021] = {name = "[q2]Semilla de pesadilla", additional_info = nil},
[221024] = {name = "[q4]Frasco de pesadillas perpetuas", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\nRequiere Alquimia (250)\n[q2]Uso: Aumenta el poder de ataque a distancia y cuerpo a cuerpo 45 p. Los beneficios de este frasco solo se aplican en áreas que están bajo la influencia de la pesadilla. (30 Seg Reutilización)\n[q]\"Por mucho que intentes beber su contenido, este frasco nunca se vaciará.\""},
[221025] = {name = "[q4]Avambrazos de invocador potenciados por el Vacío", additional_info = "Se liga al recogerlo\nMuñeca Tela\n37 armadura\n+7 aguante\n+8 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 50\nRequiere Ingeniería (250)\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q2]Uso: Canaliza el poder del Vacío, lo que otorga inmunidad al miedo durante 15 s. (10 Min Reutilización)\n[q]\"Incluye las mejores partes del diseño original de Ziri, con algunas modificaciones extra.\""},
[221026] = {name = "[q4]Avambrazos de destripador potenciados por el Vacío", additional_info = "Se liga al recogerlo\nMuñeca Cuero\n75 armadura\n+9 fuerza\n+18 agilidad\n+5 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 50\nRequiere Ingeniería (250)\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q2]Uso: Canaliza el poder del Vacío, lo que otorga inmunidad al miedo durante 15 s. (10 Min Reutilización)\n[q]\"Incluye las mejores partes del diseño original de Ziri, con algunas modificaciones extra.\""},
[221027] = {name = "[q4]Avambrazos de protector potenciados por el Vacío", additional_info = "Se liga al recogerlo\nMuñeca Placas\n275 armadura\n+10 fuerza\n+12 aguante\nDurabilidad 55 / 55\nNecesitas ser de nivel 50\nRequiere Ingeniería (250)\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 19 p.\n[q2]Equipar: Ofrece protección contra ciertos tipos de ataques psíquicos.\n[q2]Uso: Canaliza el poder del Vacío, lo que otorga inmunidad al miedo durante 15 s. (10 Min Reutilización)\n[q]\"Incluye las mejores partes del diseño original de Ziri, con algunas modificaciones extra.\""},
[221028] = {name = "[q2]Sigilo encantado: sueños vivos", additional_info = "Se liga al recogerlo\nÚnico (5)\nNecesitas ser de nivel 50\nRequiere Encantamiento (250)\n[q2]Uso: Otorga un sigilo encantado de sueños vivos que te potencia para aumentar hasta 30 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 30 p. durante 30 min. Esto solo aplica fuera de combate. (30 Min Reutilización)"},
[221030] = {name = "[q2]Mojo atal'ai de magia prohibida", additional_info = "Se liga al recogerlo\nÚnico (2)\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta 40 p. el poder con hechizos. Los golpes con hechizos exitosos tienen una probabilidad de liberar una Descarga de las Sombras contra el objetivo. Solo puede haber un tipo de poción atal'ai activa a la vez. Esto no tiene efecto fuera del Templo Sumergido. (Probabilidad de que accione: 25%, 40s de reutilización) (3 Seg Reutilización)\n[q]\"Agua encantada que se transformó a partir de la esencia del mojo atal'ai. Unas sombras se agitan detrás del contenido en su interior...\""},
[221191] = {name = "[q3]Piedra onírica", additional_info = "Se liga al recogerlo\nÚnico"},
[221192] = {name = "Diario de sueños", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te devuelve a <Hearthstone Location>. Habla con un tabernero en otro sitio para convertirlo en tu nuevo hogar."},
[221193] = {name = "[q3]Anillo de esmeralda", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+12 aguante\n+5 resistencia a Arcano\nNecesitas ser de nivel 45\nRequiereCeladores Esmeralda\n: Honorable\n[q2]Equipar: Aumenta 14 p. el poder de ataque.\n[q2]Uso: Entra en el sueño de un amigo seleccionado. (1 Hora Reutilización)\n[q]\"Una luz se mueve en el interior de la fascinante esmeralda.\""},
[221196] = {name = "[q2]Mojo atal'ai de guerra", additional_info = "Se liga al recogerlo\nÚnico (2)\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta el poder de ataque cuerpo a cuerpo y a distancia 48 p. Con cada ataque cuerpo a cuerpo o a distancia, hay una probabilidad de aumentar de tamaño, lo que aumenta la fuerza o la agilidad (el mayor de los dos) 35 p. durante 10 s. Solo puede haber un tipo de poción atal'ai activa a la vez en cualquier momento. Esto no tiene efecto fuera del Templo Sumergido. (Probabilidad de que accione: 15%, 40s de reutilización) (3 Seg Reutilización)\n[q]\"Sientes una atracción por la batalla mientras contemplas el encanto rojizo de la poción...\""},
[221199] = {name = "Tintura de herbasátiro", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Cura a una criatura de la corrupción de sátiro."},
[221256] = {name = "Brazo derecho del Desintegrador", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina este objeto con 4 trozos más para reconstruir a Iodax."},
[221257] = {name = "Brazo izquierdo del Desintegrador", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina este objeto con 4 trozos más para reconstruir a Iodax."},
[221258] = {name = "Pie derecho del Desintegrador", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina este objeto con 4 trozos más para reconstruir a Iodax."},
[221259] = {name = "Pie izquierdo del Desintegrador", additional_info = "Se liga al recogerlo\n[q2]Uso: Combina este objeto con 4 trozos más para reconstruir a Iodax."},
[221260] = {name = "Cabeza del Desintegrador", additional_info = "Se liga al recogerlo"},
[221261] = {name = "[q2]Jarabe de susurro salvaje", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Invoca el espíritu de Agamaggan. Solo se puede usar en la cima de la Espiral de las Zarzas en Zahúrda Rajacieno, después de derrotar a todos los enemigos cercanos. (5 Seg Reutilización)"},
[221262] = {name = "[q2]Ofrenda salvaje", additional_info = "Se liga al recogerlo"},
[221267] = {name = "[q2]Runa de los Sanguinarios", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu yelmo con la runa Gusto por la sangre:\n\n\nCada vez que tu habilidad Desgarrar inflige daño, tu habilidad Abrumar se activará durante 9 s o un ataque. Este efecto no puede ocurrir más de una vez cada 6 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[221271] = {name = "[q3]As de Naturaleza", additional_info = "[q2]Uso: Combina desde el as hasta el ocho de Naturaleza para completar el palo."},
[221272] = {name = "[q4]Baraja de Naturaleza", additional_info = "Este objeto inicia una misión\n[q]\"Propiedad de la Feria de la Luna Negra.\""},
