[221307] = {name = "[q4]Naipe de la Luna Negra: Descomposición", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Equipar: Los hechizos y ataques a veces absorben 40 p. de salud del objetivo y aplican una acumulación de Descomposición. Cuando Descomposición alcanza las 5 acumulaciones, el objetivo recibe 225 to 375 p. de daño. (3s de reutilización)"},
[221308] = {name = "[q4]Naipe de la Luna Negra: Sobrecrecimiento", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Equipar: Probabilidad de restaurar 8 p. de energía, 1% de maná o 4 p. de furia al objetivo con un hechizo de sanación directa o con cada pulso de sanación efectiva con el tiempo. (Probabilidad de que accione: 10%)"},
[221309] = {name = "[q4]Naipe de la Luna Negra: Tormenta de arena", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Equipar: Los hechizos y ataques tienen una probabilidad de invocar una tormenta de arena que te rodea e inflige 50 to 100 p. de daño de Naturaleza a los objetivos que atraviesa. (Probabilidad de que accione: 30%, 8s de reutilización)"},
[221310] = {name = "[q4]Naipe de la Luna Negra: Tormento", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 50\n[q2]Equipar: Otorga una probabilidad de que los ataques y hechizos del portador causen Tormento en su objetivo, lo que hace que deambule con sufrimiento durante 3 s. (Probabilidad de que accione: 5%, 15s de reutilización)"},
[221311] = {name = "[q2]Mojo atal'ai de vida", additional_info = "Se liga al recogerlo\nÚnico (2)\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta 45 p. toda la sanación realizada y 11 p. la regeneración de maná durante 5 s. Tus sanaciones tienen una probabilidad de restaurar 8 p. de energía, un 1% de maná o 4 p. de ira. Solo puede haber una poción atal'ai activa a la vez. Esto no tiene efecto fuera del Templo Sumergido. (Probabilidad de que accione: 25%, 20s de reutilización) (3 Seg Reutilización)\n[q]\"El contenido del vial emana una tonalidad azul profunda. Casi parece como si te estuviera exigiendo que lo tomaras...\""},
[221312] = {name = "[q2]Frasco de mojo atal'ai", additional_info = "[q]\"El mejor mojo de los trols atal'ai.\""},
[221313] = {name = "[q3]Frasco de mojo de pesadilla", additional_info = "[q]\"Un poderoso vudú atal'ai imbuido de pesadillas se arremolina en el vial.\""},
[221314] = {name = "Cartel de SE BUSCA", additional_info = "Objeto de misión\nÚnico\n[q]\"Un dibujo muy pobre de un enano Hierro Negro.\"\n[q2]<Click derecho para leer>"},
[221315] = {name = "[q3]Generador de arcoíris", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: ¡Poder arcoíris! (30 Min Reutilización)"},
[221316] = {name = "Uniforme exclusivo de Premo", additional_info = "Se liga al recogerlo\nÚnico\nCamisa\n[q2]Uso: Concéntrate."},
[221317] = {name = "Leycrist de Feralas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Usa 4 cristales ley para armonizarte con Azeroth y aprender una habilidad nueva."},
[221318] = {name = "Leycrist de Azshara", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Usa 4 cristales ley para armonizarte con Azeroth y aprender una habilidad nueva."},
[221319] = {name = "Leycrist de Roca Negra", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Usa 4 cristales ley para armonizarte con Azeroth y aprender una habilidad nueva."},
[221320] = {name = "Leycrist de las Tierras del Interior", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Usa 4 cristales ley para armonizarte con Azeroth y aprender una habilidad nueva."},
[221321] = {name = "[q3]Sello atal'ai de poderío", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Añade de forma permanente 15 p. de poder de ataque a un objeto de la casilla de hombros."},
[221322] = {name = "[q3]Sello atal'ai de mojo", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Añade de forma permanente 9 p. de daño y sanación de hechizos y efectos mágicos a un objeto de la casilla de hombros."},
[221323] = {name = "[q3]Sello atal'ai de serenidad", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Añade de forma permanente hasta 18 p. de sanación de hechizos y efectos a un objeto de la casilla de hombros."},
[221324] = {name = "Llave Forjatiniebla frágil", additional_info = "Objeto de misión\nÚnico\nDuración: 15 min\n[q]\"Colocar esta llave quebradiza en tu llavero sería imposible.\""},
[221325] = {name = "Carga explosiva para tontos", additional_info = "Se liga al recogerlo\nDuración: 15 min\n[q2]Uso: Hace explotar las cerraduras de cofres bien cerrados.\n[q]\"¡La mecha ya está encendida, y se quema lentamente!\""},
[221326] = {name = "Corazón de venado sagrado", additional_info = "Se liga al recogerlo\n[q2]Uso: Presenta una ofrenda en el Santuario de la bestia."},
[221327] = {name = "[q2]Esquema: Rayo reductor gnómico", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un rayo reductor gnómico]\n\n\nRayo reductor gnómico\nSe liga al equiparlo\nAbalorio\nRequiere Ingeniería (205)\n[q2]Uso: Encoge al objetivo y reduce 250 p. su poder de ataque. O al menos eso es lo que suele hacer... (5 Min Reutilización)\nRequiere Tubo de mitril , Activador inestable , Barra de mitril (4), Frasco de mojo (4), Jade (2)"},
[221328] = {name = "[q2]Esquema: Gafas gnómicas", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear unas gafas gnómicas]\n\n\n[q2]Gafas gnómicas\nSe liga al recogerlo\n{Cabeza} {Tela}\n45 armadura\n+9 agilidad\n+9 aguante\n+9 espíritu\nDurabilidad 45 / 45\nRequiere Ingeniería (210)\nRequiere Gafas de Fuego , Tubo de mitril , Núcleo de poder de oro (2), Frasco de mojo (2), Cuero pesado (2)"},
[221329] = {name = "[q2]Esquema: Proyector redomático gnómico", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un proyector redomático gnómico]\n\n\nProyector redomático gnómico\nSe liga al equiparlo\nAbalorio\nRequiere Ingeniería (210)\n[q2]Uso: Captura al objetivo con una red durante 10 s. La red tiene muchos ganchos y en ocasiones se queda prendida en la ropa del que la lanza. (10 Min Reutilización)\nRequiere Tubo de mitril , Seda de las Sombras (2), Seda de araña espesa (4), Pólvora sólida (2), Barra de mitril (4)"},
[221330] = {name = "[q2]Esquema: Cinturón de prevención de daño gnómico", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un cinturón de prevención de daño gnómico]\n\n\n[q2]Cinturón de prevención de daño gnómico\nSe liga al equiparlo\n{Cintura} {Cuero}\n66 armadura\n+6 aguante\nDurabilidad 30 / 30\nRequiere Ingeniería (215)\n[q2]Uso: Un escudo de fuerza te protege de los siguientes 500 p. de daño durante los próximos 10 min. ADVERTENCIA: El campo de fuerza se puede sobrecargar al recibir un golpe y desaparecer temporalmente. (Probabilidad de que accione: 5%) (1 Hora Reutilización)\nRequiere Cinturón oscurecido , Barra de mitril (4), Barra de veraplata (2), Activador inestable , Aguamarina (2)"},
[221331] = {name = "[q2]Esquema: Botas cohete gnómicas", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear unas botas cohete gnómicas]\n\n\n[q2]Botas cohete gnómicas\nSe liga al equiparlo\n{Pies} {Tela}\n41 armadura\nDurabilidad 35 / 35\nRequiere Ingeniería (225)\n[q2]Uso: Estas botas aumentan mucho tu velocidad de carrera durante 20 s. ADVERTENCIA: ni la fuente de alimentación ni los giros funcionan siempre como deberían. (30 Min Reutilización)\nRequiere Botas de tejido mágico negras , Tubo de mitril (2), Cuero pesado (4), Pólvora sólida (8), Girocronátomo (4)"},
[221332] = {name = "[q2]Esquema: Gallo de batalla gnómico", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un gallo de batalla gnómico]\n\n\nGallo de batalla gnómico\nSe liga al recogerlo\nAbalorio\nRequiere Ingeniería (230)\n[q2]Uso: Crea un gallo de batalla que luchará por ti durante 1.50 min o hasta que lo destruyan. (30 Min Reutilización)\nRequiere Envoltura de mitril , Barra de veraplata (6), Barra de mitril (6), Cilindro de mitril taraceado (2), Núcleo de poder de oro , Jade (2)"},
[221333] = {name = "[q2]Esquema: Gorro de control mental gnómico", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un gorro de control mental gnómico]\n\n\n[q2]Gorro de control mental gnómico\nSe liga al equiparlo\n{Cabeza} {Tela}\n50 armadura\n+14 espíritu\nDurabilidad 45 / 45\nRequiere Ingeniería (215)\n[q2]Uso: Participa en un combate mental contra un objetivo humanoide para controlar su mente. Si todo sale bien, controlarás la mente del objetivo durante 20 s. (30 Min Reutilización)\nRequiere Barra de mitril (10), Barra de veraplata (4), Núcleo de poder de oro , Rubí estrella (2), Paño de tejido mágico (4)"},
[221334] = {name = "[q2]Esquema: Rayo mortal gnómico", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un rayo mortal gnómico]\n\n\nRayo mortal gnómico\nSe liga al recogerlo\nAbalorio\n[q2]Uso: El dispositivo se carga con el correr del tiempo utilizando tu fuerza vital, y luego dirige una ráfaga de energía contra tu oponente. (5 Min Reutilización)\n[q]\"El uso de este dispositivo puede causar la muerte o daños graves.\"\nRequiere Tubo de mitril (2), Activador inestable , Esencia de no-muerto , Icor de no-muerto (4), Cilindro de mitril taraceado"},
[221335] = {name = "[q2]Esquema: Casco de albañil goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un casco de albañil goblin]\n\n\n[q2]Casco de albañil goblin\nSe liga al recogerlo\n{Cabeza} {Tela}\n44 armadura\n+15 resistencia a Fuego\nDurabilidad 45 / 45\nRequiere Ingeniería (205)\n[q2]Uso: Amortigua 300 to 500 p. de daño de Fuego. Dura 1 min. (1 Hora Reutilización)\nRequiere Barra de mitril (8), Citrino , Fuego elemental (4)"},
[221336] = {name = "[q2]Esquema: Casco de minero goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un casco de minero goblin]\n\n\n[q2]Casco de minero goblin\nSe liga al recogerlo\n{Cabeza} {Malla}\n190 armadura\n+15 aguante\nDurabilidad 60 / 60\nRequiere Ingeniería (205)\nEquipar: Minería +5 p.\nRequiere Barra de mitril (8), Citrino , Tierra elemental (4)"},
[221337] = {name = "[q2]Esquema: Mortero goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un mortero goblin]\n\n\nMortero goblin\nSe liga al equiparlo\nAbalorio\nRequiere Ingeniería (205)\n[q2]Uso: Inflige 383 to 517 p. de daño de Fuego y aturde a los objetivos de un radio de 5 m durante 3 s. (10 Min Reutilización)\n6 cargas\nRequiere Tubo de mitril (2), Barra de mitril (4), Pólvora sólida (5), Núcleo de poder de oro , Fuego elemental"},
[221338] = {name = "[q2]Esquema: Carga de zapador goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear una carga de zapador goblin]\n\n\nRequiere Ingeniería (205)\n[q2]Uso: Estalla al ser activada infligiendo 450 to 750 p. de daño de Fuego a todos los enemigos cercanos y 375 to 625 p. de daño a ti. (5 Min Reutilización)\nRequiere Paño de tejido mágico , Pólvora sólida (3), Activador inestable"},
[221339] = {name = "[q2]Esquema: Botas cohete goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear unas botas cohete goblin]\n\n\n[q2]Botas cohete goblin\nSe liga al equiparlo\n{Pies} {Tela}\n41 armadura\nDurabilidad 35 / 35\n[q2]Uso: Estas botas de aspecto peligroso aumentan mucho tu velocidad de carrera durante 20 s. Tienen tendencia a explotar, así que úsalas con cuidado. (5 Min Reutilización)\nRequiere Botas de tejido mágico negras , Tubo de mitril (2), Cuero pesado (4), Combustible de cohete goblin (2), Activador inestable"},
[221340] = {name = "[q2]Esquema: Dispensador de bombas goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un dispensador de bombas goblin]\n\n\nDispensador de bombas goblin\nSe liga al recogerlo\nAbalorio\nRequiere Ingeniería (230)\n[q2]Uso: Crea una bomba móvil que embiste al enemigo más cercano y explota infligiendo 315 to 385 de daño de Fuego. (30 Min Reutilización)\nRequiere Envoltura de mitril (2), Pólvora sólida (4), Barra de veraplata (6), Activador inestable , Mira de precisión (2)"},
[221341] = {name = "[q2]Esquema: El Grande", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear La grande]\n\n\nLa grande\nRequiere Ingeniería (225)\n[q2]Uso: Inflige 340 to 460 p. de daño de Fuego y aturde a los objetivos durante 5 s en un radio de 10 m. Cualquier daño anulará el efecto. (1 Min Reutilización)\nRequiere Envoltura de mitril , Combustible de cohete goblin , Dinamita sólida (6), Activador inestable"},
[221342] = {name = "[q2]Esquema: Escopeta dragón goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear una escopeta dragón goblin]\n\n\nEscopeta dragón goblin\nSe liga al recogerlo\nAbalorio\n[q2]Uso: Inflige 61 to 69 p. de daño de Fuego durante 10 s a todos los objetivos situados en un cono frente al ingeniero al utilizar el arma. Eso siempre y cuando no explote... (5 Min Reutilización)\nRequiere Tubo de mitril (2), Combustible de cohete goblin (4), Barra de mitril (6), Barra de veraplata (6), Activador inestable"},
[221343] = {name = "[q2]Esquema: Casco cohete goblin", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (205)\n[q2]Uso: [Te enseña a crear un casco cohete goblin]\n\n\n[q2]Casco de cohete goblin\nSe liga al equiparlo\n{Cabeza} {Tela}\n50 armadura\n+15 aguante\nDurabilidad 45 / 45\nRequiere Ingeniería (235)\nRequiere Casco de albañil goblin , Combustible de cohete goblin (4), Barra de mitril (4), Activador inestable"},
[221344] = {name = "[q3]Libro de hechizos personal", additional_info = "Se liga al recogerlo\nÚnico\nSostener con la mano izquierda\nClases: Mago\n[q2]Equipar: Aumenta hasta 21 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Crea 5 talismanes de comprensión. (4 H Reutilización)"},
[221345] = {name = "[q3]Sangre corrupta de Eranikus", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 50"},
[221346] = {name = "[q4]Omóplato del avatar caído", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 50\n[q]\"Un omóplato prístino. Tiene una forma maravillosa y parece estar en perfecto estado.\""},
[221347] = {name = "Sapta de fuego turbia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Permite al chamán ver a los espíritus elementales."},
[221348] = {name = "Sapta de agua turbia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Permite al chamán ver a los espíritus elementales."},
[221349] = {name = "Sapta de tierra turbia", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Permite al chamán ver a los espíritus elementales."},
[221350] = {name = "Notas de chamán chamuscadas", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nClases: Chamán\n[q]\"Las páginas están casi carbonizadas, lo que imposibilita la lectura. Las páginas parecen estar envueltas alrededor de algo.\""},
[221351] = {name = "Notas de chamán empapadas", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nClases: Chamán\n[q]\"El agua ha borrado la tinta al punto de la ilegibilidad. Las páginas parecen estar envueltas alrededor de algo.\""},
[221352] = {name = "Notas de chamán borroneadas", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nClases: Chamán\n[q]\"El polvo y el desgaste han hecho que las notas sean ilegibles. Las páginas parecen estar envueltas alrededor de algo.\""},
[221353] = {name = "Fragmento de fuego", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina el fragmento de fuego con esencias elementales. Puede ayudar a encontrar el santuario corrupto."},
[221354] = {name = "Fragmento de agua", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina el fragmento de agua con esencias elementales. Puede ayudar a encontrar el santuario corrupto."},
[221355] = {name = "Fragmento de tierra", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Combina el fragmento de tierra con esencias elementales. Puede ayudar a encontrar el santuario corrupto."},
[221356] = {name = "Fragmento de fuego resplandeciente", additional_info = "Se liga al recogerlo\nÚnico"},
[221357] = {name = "Fragmento de agua resplandeciente", additional_info = "Se liga al recogerlo\nÚnico"},
[221358] = {name = "Fragmento de tierra resplandeciente", additional_info = "Se liga al recogerlo\nÚnico"},
[221359] = {name = "Pluma de lechubestia prístina", additional_info = "Se liga al recogerlo"},
[221360] = {name = "Papiro farraki", additional_info = "Se liga al recogerlo"},
[221361] = {name = "Resina de Zukk'ash", additional_info = "Se liga al recogerlo"},
[221362] = {name = "Paño para limpiar armas", additional_info = "RequiereCeladores Esmeralda\n: Amistoso\n[q2]Uso: Limpia tu arma y elimina todos los encantamientos temporales. ¡Como nueva!"},
[221363] = {name = "[q4]Omóplato del avatar caído", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 50\n[q]\"Un omóplato prístino. Tiene una forma maravillosa y parece estar en perfecto estado.\""},
[221364] = {name = "[q2]Moneda de masacre de cobre", additional_info = "Se liga al recogerlo\n[q2]Uso: Transmuta 100 monedas de masacre de cobre y las convierte en 1 moneda de masacre de plata.\n[q]\"Una muestra de tu pequeño servicio al loa de la sangre.\""},
[221365] = {name = "[q3]Moneda de masacre de plata", additional_info = "Se liga al recogerlo\n[q2]Uso: Transmuta 100 monedas de masacre de plata y las convierte en 1 moneda de masacre de oro.\n[q]\"Una muestra de tu servicio al loa de la sangre.\""},
[221366] = {name = "[q4]Moneda de masacre de oro", additional_info = "Se liga al recogerlo\n[q]\"Una muestra de tu gran servicio al loa de la sangre.\""},
[221367] = {name = "Cartera de monedas de masacre de cobre", additional_info = "Se liga al recogerlo\n[q]\"Contiene 100 monedas de masacre de cobre.\"\n[q2]<Click derecho para abrir>"},
[221368] = {name = "Cartera de monedas de masacre de plata", additional_info = "Se liga al recogerlo\n[q]\"Contiene 100 monedas de masacre de plata.\"\n[q2]<Click derecho para abrir>"},
[221369] = {name = "[q3]Succión de pesadilla", additional_info = "Se liga al recogerlo\nAbalorio\nNecesitas ser de nivel 20\nRequiereCeladores Esmeralda\n: Amistoso\n[q2]Equipar: Restaura 150 p. de salud y maná cuando matas a un objetivo que otorga experiencia u honor. Este efecto no puede ocurrir más de una vez cada 10 s. (10s de reutilización)"},
[221370] = {name = "Medallón precioso", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"El dorso dice \"Jabbey + Enie\".\""},
[221371] = {name = "Monedero de secuestrador", additional_info = "Se liga al recogerlo\nÚnico\n[q2]<Click derecho para abrir>"},
[221372] = {name = "[q0]Monedero destrozado", additional_info = "[q]\"El contenido quedó dañado en combate.\""},
[221374] = {name = "[q3]Angustia del Sueño", additional_info = "Se liga al recogerlo\nAbalorio\nNecesitas ser de nivel 30\nRequiereCeladores Esmeralda\n: Amistoso\n[q2]Equipar: Cuando matas a un objetivo que otorga experiencia u honor, aumenta 40 p. el daño o sanación de tu próximo ataque, hechizo o habilidad. Este efecto no puede ocurrir más de una vez cada 10 s. (10s de reutilización)"},
[221376] = {name = "[q0]Yelmo del Sueño Esmeralda", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n429 armadura\n+10 fuerza\n+11 aguante\nDurabilidad 80 / 80\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Honorable\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n\n[q]Placa del Sueño Esmeralda (0/6)\n[q0]Espaldares del Sueño Esmeralda\nCoraza del Sueño Esmeralda\nEscarpes del Sueño Esmeralda\nGuanteletes del Sueño Esmeralda\nQuijotes del Sueño Esmeralda\nYelmo del Sueño Esmeralda\n[q0](3) Conjunto : +10 p. de aguante.\n(6) Conjunto : Aumenta 20 p. el poder de ataque."},
[221377] = {name = "[q3]Quijotes del Sueño Esmeralda", additional_info = "Se liga al recogerlo\n{Piernas} {Placas}\n462 armadura\n+11 fuerza\n+8 agilidad\n+12 aguante\nDurabilidad 100 / 100\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Honorable\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n\n[q]Placa del Sueño Esmeralda (0/6)\n[q0]Espaldares del Sueño Esmeralda\nCoraza del Sueño Esmeralda\nEscarpes del Sueño Esmeralda\nGuanteletes del Sueño Esmeralda\nQuijotes del Sueño Esmeralda\nYelmo del Sueño Esmeralda\n[q0](3) Conjunto : +10 p. de aguante.\n(6) Conjunto : Aumenta 20 p. el poder de ataque."},
[221378] = {name = "[q3]Guanteletes del Sueño Esmeralda", additional_info = "Se liga al recogerlo\n{Manos} {Placas}\n330 armadura\n+13 fuerza\n+14 aguante\nDurabilidad 45 / 45\nClases: Guerrero , Paladín\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Amistoso\n\n[q]Placa del Sueño Esmeralda (0/6)\n[q0]Espaldares del Sueño Esmeralda\nCoraza del Sueño Esmeralda\nEscarpes del Sueño Esmeralda\nGuanteletes del Sueño Esmeralda\nQuijotes del Sueño Esmeralda\nYelmo del Sueño Esmeralda\n[q0](3) Conjunto : +10 p. de aguante.\n(6) Conjunto : Aumenta 20 p. el poder de ataque."},
