[221439] = {name = "[q3]Armadura del letargo esmeralda", additional_info = "Se liga al recogerlo\nÚnico\n{Pecho} {Cuero}\n146 armadura\n+22 aguante\n+5 resistencia a Arcano\n+5 resistencia a Naturaleza\nDurabilidad 100 / 100\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Reverenciado\n[q2]Equipar: Al recibir un golpe cuerpo a cuerpo, el atacante tiene un 5% de probabilidad de caer dormido durante 10 s. Solo afecta a los enemigos de niveles inferiores a 50. (Probabilidad de que accione: 5%)"},
[221440] = {name = "[q4]Rugido del Sueño", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+14 aguante\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Exaltado\n[q2]Equipar: Tus hechizos dañinos tienen una probabilidad de aumentar 66 p. tu daño con hechizos durante 10 s. (Probabilidad de que accione: 5%)"},
[221441] = {name = "[q3]Celador del Sueño", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{60 - 94 p. de daño} {Velocidad 2.00}\n(38.50 p. de daño por segundo)\n+18 fuerza\n+14 agilidad\n+10 aguante\nDurabilidad 100 / 100\nNecesitas ser de nivel 43\nRequiereCeladores Esmeralda\n: Reverenciado\n[q2]Equipar: +73 p. de poder de ataque solo en las formas de oso, oso temible y felina."},
[221442] = {name = "[q4]Rugido del guardián", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+10 aguante\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Exaltado\n[q2]Uso: Aumenta 70 p. tu poder de ataque cuerpo a cuerpo y a distancia. El efecto dura 20 s. (2 Min Reutilización)"},
[221443] = {name = "[q4]Rugido de la arboleda", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+10 aguante\nNecesitas ser de nivel 50\nRequiereCeladores Esmeralda\n: Exaltado\n[q2]Uso: Invoca el poder del Sueño durante 15 s. Mientras está en este círculo, el taumaturgo obtiene 120 p. de poder de sanación. (2 Min Reutilización)"},
[221444] = {name = "Durian de jungla", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Restaura 3222 p. de salud y 6618 p. de maná durante 30 s. Debes permanecer sentado mientras comes.\n[q]\"Si puedes superar el aroma hediondo, ¡es una fruta realmente deliciosa!\""},
[221445] = {name = "[q2]Runa de Fuego enfocado", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tus brazales con la runa Enfocar fuego:\n\n\nConsume todas las aplicaciones de Frenesí de tu mascota, lo que aumenta un 3% tu velocidad de ataque a distancia y otorga 4 p. de enfoque a tu mascota por cada aplicación de Frenesí consumida. Dura 20 s.\n\n Tu mascota obtiene Frenesí cada vez que usa un ataque básico, lo que aumenta un 6% su velocidad de ataque cuerpo a cuerpo durante 10 s. Se acumula un máximo de 5 veces.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221446] = {name = "[q4]Martillo de ritualista", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Dos manos} {Maza}\n{108 - 173 p. de daño} {Velocidad 3.00}\n(46.83 p. de daño por segundo)\n+11 fuerza\n+15 agilidad\n+30 aguante\nDurabilidad 120 / 120\nClases: Druida\nNecesitas ser de nivel 50\n[q2]Equipar: +114 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Uso: Agrega 5 p. de daño Geofísico a tus ataques cuerpo a cuerpo, que dañan a tu objetivo y sus aliados más cercanos, hasta un máximo de 3 objetivos. Provoca más amenaza. Dura 20 s. (3 Min Reutilización)"},
[221447] = {name = "[q4]Grimorio de ritualista de la luna de sangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nSostener con la mano izquierda\n+14 aguante\n+5 intelecto\nClases: Druida\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos."},
[221448] = {name = "[q4]Talismán de la Arboleda Corrupta", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nAbalorio\n+8 aguante\nClases: Druida\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 29 p. la sanación de los hechizos y efectos.\n[q2]Equipar: Restaura 7 p. de maná cada 5 s."},
[221450] = {name = "[q4]Arco de luchador de fosa gurubashi", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{A distancia} {Arco}\n{39 - 72 p. de daño} {Velocidad 1.80}\n(30.83 p. de daño por segundo)\nDurabilidad 95 / 95\nClases: Cazador\nNecesitas ser de nivel 50\n[q2]Equipar: Probabilidad de aumentar la fuerza 75 p. durante 15 s al impactar. (Probabilidad de que accione: 5%)"},
