[221465] = {name = "[q4]Aplastatoria corrupta", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Dos manos} {Maza}\n{150 - 226 p. de daño} {Velocidad 3.60}\n(52.22 p. de daño por segundo)\n+15 fuerza\n+28 aguante\n+6 intelecto\nDurabilidad 120 / 120\nClases: Chamán\nNecesitas ser de nivel 50\n[q2]Probabilidad al acertar: Atonta al objetivo durante 2 s."},
[221466] = {name = "[q4]Aro de sangre ardiente", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nDedo\n+14 aguante\n+4 intelecto\nClases: Brujo\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 17 p. el daño que infligen los hechizos y efectos de Fuego."},
[221467] = {name = "[q4]Ojo de la luna de sangre", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nDedo\n+14 aguante\n+4 intelecto\nClases: Brujo\nNecesitas ser de nivel 50\n[q2]Equipar: Aumenta hasta 17 p. el daño que infligen los hechizos y efectos de las Sombras."},
[221468] = {name = "[q4]Muro de susurros", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\n{Mano izquierda} {Escudo}\n1902 armadura\n34 bloqueo\n+6 aguante\nDurabilidad 120 / 120\nClases: Guerrero\nNecesitas ser de nivel 50\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 5% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 5%, 20s de reutilización)"},
[221469] = {name = "[q4]Lanza con púas de rebanacabezas", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Blood Moon] (1)\nArrojadiza Arrojadizas\n{70 - 130 p. de daño} {Velocidad 3.00}\n(33.33 p. de daño por segundo)\nClases: Guerrero\nNecesitas ser de nivel 50\n[q2]Uso: Arroja la lanza al objetivo y lo inmoviliza durante 5 s. (5 Min Reutilización)"},
[221470] = {name = "[q3]Esmeralda onírica", additional_info = nil},
[221471] = {name = "[q2]Cofre de los Celadores Esmeralda", additional_info = "Se liga al recogerlo\n[q2]<Click derecho para abrir>"},
[221473] = {name = "[q2]Runa de Velador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu yelmo con la runa Vigilancia:\n\n\nEnfoca tu mirada protectora en un miembro de grupo o banda, lo que reduce un 3% el daño recibido y te transfiere un 10% de la amenaza que genera. Además, cada vez que recibe un ataque, el tiempo de reutilización de tu Provocar se restablece. Dura 30 min. Este efecto solo puede estar activo sobre un objetivo cada vez.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221474] = {name = "[q3]Esencia encadenada de Eranikus", additional_info = "Se liga al recogerlo\nAbalorio\n+10 aguante\n+10 resistencia a Naturaleza\nNecesitas ser de nivel 50\n[q2]Uso: Envenena a todos los enemigos en un radio de 8 m alrededor del taumaturgo. Las víctimas del envenenamiento sufren 50 p. de daño de Naturaleza cada 5 s durante 45 s. (10 Min Reutilización)"},
[221475] = {name = "[q2]Esencia de Eranikus", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 50\n[q]\"Hay un velo verde que gira dentro de la gema.\""},
[221480] = {name = "[q2]Notas de hechizo: Armadura de arrabio", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus brazales con la runa Armadura de arrabio:\n\n\nInflige [10 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)] p. de daño de Fuego al recibir un golpe, aumenta un 5% tu probabilidad de golpe crítico con hechizos y reduce un 5% la probabilidad de recibir un golpe crítico. Solo puede haber un hechizo de armadura activo sobre el mago a la vez. Dura 30 min.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221481] = {name = "[q2]Epifanía nihilista", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus brazales con la runa Zona de vacío:\n\n\nInvoca una zona de vacío en el área objetivo que inflige [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 51 / 100] p. de daño de las Sombras por segundo a los enemigos que se paran ahí durante 10 s.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221482] = {name = "[q2]Runa de Aflicción", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus brazales con la runa Aflicción inestable:\n\n\nLa energía de las Sombras destruye poco a poco al objetivo e inflige [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. de daño durante 18 s. Además, quien disipe tu hechizo Aflicción inestable recibirá [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100] p. de daño y quedará silenciado durante 5 s. Solo puede haber un hechizo Aflicción inestable o Inmolar activo sobre un objetivo por brujo.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221483] = {name = "[q2]Runa de Quemar", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu yelmo con la runa Quemar:\n\n\nTu Choque de llamas ahora golpea a un máximo de 5 objetivos, dura 6 s más e inflige un 100% más de daño. Además, mientras tu arma equipada en la mano derecha esté imbuida con Arma Lengua de Fuego, tu daño con hechizos aumenta una cantidad equivalente al 150% de tu intelecto.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221484] = {name = "[q4]Palo de maleficios de médico brujo", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Te aplica un maleficio para que sea más difícil detectarte en el Templo Sumergido. (3 Seg Reutilización)"},
[221487] = {name = "[q2]Notas de hechizo: Resguardo avanzado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu yelmo con la runa Resguardo avanzado:\n\n\nAhora puedes lanzar tus hechizos Escudo de maná, Resguardo contra la Escarcha y Resguardo contra el Fuego sobre cualquier objetivo aliado y absorben un 100% más de daño, y Escudo de maná consume un 50% menos de maná por el daño absorbido. Además, tu Eliminar maldición inferior es reemplazada con Eliminar maldición superior.\n\n\nElimina 1 maldición y 1 efecto de magia dañino de un objetivo aliado.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221488] = {name = "[q2]Runa de Epifanía", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu yelmo con la runa Égida divina:\n\n\nLas sanaciones críticas crean un escudo protector sobre el objetivo, que absorbe el 30% de la cantidad sanada. Dura 12 s.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221489] = {name = "[q2]Runa de Venganza", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu yelmo con la runa Venganza:\n\n\nCuando se activa, esta habilidad aumenta temporalmente un 30% tu salud máxima durante 20 s. Después de que el efecto expira, se pierde la salud. Además, mientras estás en Metamorfosis, Venganza hace que tus alas reduzcan tu velocidad de caída.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221490] = {name = "[q2]Runa de Mareas Vivas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tus brazales con la runa\n Mareas Vivas:\n\n\nRestablece de [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] a [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. de salud a un objetivo aliado y [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)] p. más durante 15 s. Tus lanzamientos de Sanación en cadena sobre ese objetivo principal en menos de 15 s aumentarán el efecto de Sanación en cadena un 25%. Este hechizo también activa Despertar ancestral.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221491] = {name = "[q2]Bolsa Diente Oscuro", additional_info = "Se liga al recogerlo\n[q]\"Contiene una carta aleatoria de la Luna Negra.\"\n[q2]<Click derecho para abrir>"},
[221497] = {name = "Llave vieja", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Uso: Abre el cofre antiguo"},
[221498] = {name = "Caja de comida robusta", additional_info = "Se liga al recogerlo\nBolsa de 12 casillas"},
[221499] = {name = "[q2]Runa del Guardia vil", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus brazales con la runa Invocar guardia vil:\n\n\nInvoca a un guardia vil bajo las órdenes del brujo.\n\n El guardia vil se beneficia de todos los talentos y efectos que se activan de cualquiera de tus otros esbirros demonios o los benefician.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221510] = {name = "[q2]Runa del Caballero", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tus brazales con la runa Escudo y espada:\n\n\nCuando tus habilidades Devastar o Revancha infligen daño, tienen un 30% de probabilidad de restablecer el tiempo de reutilización de tu habilidad Embate con escudo y de reducir un 100% su costo de ira durante 5 s.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221511] = {name = "[q2]Runa del Protector", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Graba tu yelmo con la runa Maestría con escudos:\n\n\nAumenta un 10% todo el daño físico que infliges cuando tienes un escudo equipado, y reduce un 50% la duración de todos los efectos de Desarmar que se usan en tu contra. Â No se acumula con otros efectos de reducción de duración de Desarmar.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221512] = {name = "[q2]Runa de Prontitud", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tus brazales con la runa Acortar:\n\n\nTus habilidades Eviscerar y Envenenar restablecen la duración de Hacer picadillo o Danza de hojas a su máximo de 5 puntos de combo. Si las dos están activas, solo se restablecerá la duración que esté más próxima a terminar.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221513] = {name = "[q2]Runa de Potencia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu yelmo con la runa Potencia de combate:\n\n\nTienes un 20% de probabilidad de obtener 15 p. de energía cada vez que infliges daño con tu arma de mano izquierda.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221514] = {name = "[q2]Runa de Poder de fuego", additional_info = "Se liga al recogerlo\nClases: Cazador\n[q2]Graba tu yelmo con la runa Bloquear y cargar:\n\n\nCada vez que colocas una trampa, tu próxima habilidad de Disparo (salvo Disparo de dispersión) en 20 s no cuesta maná ni incurre en tiempo de reutilización.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221515] = {name = "[q2]Runa de Detonación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tus brazales con la runa TNT:\n\n\nAumenta un 10% el daño infligido por Disparo explosivo y todas tus trampas de daño. Además, el daño inicial de Trampa explosiva y el daño periódico total de tu Trampa de inmolación aumentan un 25% de tu poder de ataque cuerpo a cuerpo o a distancia.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221516] = {name = "[q2]Runa de Energía primigenia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tus brazales con la runa Regeneración frenética mejorada:\n\n\nAhora puedes usar Regeneración frenética en todas las formas, excepto Forma de lechúcico lunar, o cuando no estás usando ninguna forma. Ahora convierte tu recurso activo en salud por segundo durante 10 s. Un máximo de 10 p. de ira, 10 p. de energía o un 20% del maná base se convierte en un máximo de 10% de salud por segundo.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221517] = {name = "[q2]Runa de Masacre", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu yelmo con la runa Cornada:\n\n\nGolpear a un objetivo con Lacerar, Flagelo o Magullar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Destrozar (oso) y de otorgar 10 p. de ira. Golpear a un objetivo con Destrozar (felina) o Triturar tiene un 15% de probabilidad de restablecer el tiempo de reutilización de Furia del tigre.\n[q]\"Te enseña una nueva facultad de grabado.\""},
[221518] = {name = "[q3]Susurro", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{109 - 163 p. de daño} {Velocidad 2.60}\n(52.31 p. de daño por segundo)\n+20 fuerza\n+12 aguante\nDurabilidad 100 / 100\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[221519] = {name = "[q3]Orbe Mannoroc", additional_info = "Objeto de misión\nÚnico"},
[221544] = {name = "Huevo de cuervo tormentoso", additional_info = "Se liga al recogerlo\nÚnico"},
[221545] = {name = "Notas de brujo descifradas", additional_info = "Único\nClases: Sacerdote , Chamán"},
[221547] = {name = "Notas de brujo en clave", additional_info = "Único\n[q2]Uso: Hace falta una clave para comprender las notas del brujo. ¿Quién sabe la clase de magia que contienen?"},
[221549] = {name = "Códice de vagayermos", additional_info = "[q]\"Ayuda a traducir documentos escritos por bandidos vagayermos.\""},
[221780] = {name = "[q3]Cetro de la princesa Theradras", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{111 - 174 p. de daño} {Velocidad 3.40}\n(41.91 p. de daño por segundo)\n90 armadura\n+13 fuerza\n+10 agilidad\n+15 aguante\n+9 espíritu\nDurabilidad 100 / 100\nNecesitas ser de nivel 46\n[q2]Equipar: +67 p. de poder de ataque solo en las formas de oso, oso temible y felina."},
[221781] = {name = "[q3]Yelmo de guardia vengador", additional_info = "Se liga al recogerlo\n{Cabeza} {Placas}\n469 armadura\n+10 fuerza\n+5 agilidad\n+25 aguante\nDurabilidad 80 / 80"},
[221782] = {name = "[q3]Yelmo de Exilio", additional_info = "Se liga al recogerlo\n{Cabeza} {Malla}\n266 armadura\n+11 agilidad\n+18 intelecto\nDurabilidad 70 / 70\n[q2]Equipar: Aumenta 36 p. el poder de ataque."},
[221783] = {name = "[q4]Bufas de Justiciero", additional_info = "Se liga al recogerlo\n{Hombro} {Placas}\n562 armadura\n+17 fuerza\n+15 aguante\n+7 resistencia a Fuego\nDurabilidad 100 / 100\nClases: Paladín\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 21 p. el daño que infligen los hechizos y efectos Sagrados.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n\n[q]Resplandor de Justiciero (0/8)\n[q0]Botas de batalla de Justiciero\nCoraza de Justiciero\nCorona de Justiciero\nFaja de Justiciero\nMandiletes de Justiciero\nLeotardos de Justiciero\nBufas de Justiciero\nBrazales de guerra de Justiciero\n[q0](2) Conjunto : Tu Sentencia de Luz y Sentencia de sabiduría también otorgan los efectos de Sentencia del cruzado.\n(4) Conjunto : Aumenta un 2% tu probabilidad de conseguir un golpe crítico con hechizos y ataques.\n(6) Conjunto : Tu Sello de orden, Sello de rectitud y Sello de martirio infligen un 35% menos de daño, pero ahora persisten durante 6 s después de que lanzas otro Sello, o hasta que lances un tercer Sello. Tus Sentencias ahora pueden activar varios Sellos si están activas."},
[221785] = {name = "[q0]Vestimentas Cenarion", additional_info = "Se liga al recogerlo\n{Pecho} {Cuero}\n200 armadura\n+11 aguante\n+17 intelecto\n+15 espíritu\n+10 resistencia a Fuego\nDurabilidad 120 / 120\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 62 p. la sanación de los hechizos y efectos.\n\n[q]Botín Cenarion (0/8)\n[q0]Cinturón Cenarion\nBotas Cenarion\nBrazales Cenarion\nGuantes Cenarion\nYelmo Cenarion\nLeotardos Cenarion\nBufas Cenarion\nVestimentas Cenarion\n[q0](2) Conjunto : Cuando lanzas Estimular sobre otro jugador, también se lanzará sobre ti.\n(4) Conjunto : Cuando lanzas tus hechizos de Toque de sanación o Nutrir, tienes un 25% de probabilidad de obtener una cantidad de maná equivalente al 35% del costo base del hechizo. (Probabilidad de que accione: 25%, 1s de reutilización)\n(6) Conjunto : Reduce un 100% el tiempo de reutilización de Tranquilidad y aumenta un 100% su sanación. (Probabilidad de que accione: 25%, 1s de reutilización)"},
[221971] = {name = "[q2]Cuerno de jurasueños", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Combina los componentes recogidos para crear una runa que te enseñará un nuevo hechizo de grabado.\n[q]\"Un componente único que contiene una esencia ígnea. Podrías fabricar una runa nueva si encuentras otros componentes como este.\""},
[221972] = {name = "[q2]Fuego de diablillo oniripira", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Combina los componentes recogidos para crear una runa que te enseñará un nuevo hechizo de grabado.\n[q]\"Un componente único que contiene una esencia ígnea. Podrías fabricar una runa nueva si encuentras otros componentes como este.\""},
[221973] = {name = "[q2]Colmillo de cazasueños", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Combina los componentes recogidos para crear una runa que te enseñará un nuevo hechizo de grabado.\n[q]\"Un componente único que contiene una esencia ígnea. Podrías fabricar una runa nueva si encuentras otros componentes como este.\""},
[221974] = {name = "[q2]Collar Tótem Siniestro", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Combina los componentes recogidos para formar un bastón frágil que puede ponerle fin al Letargo inmortal.\n[q]\"Un collar obtenido de un chamán Tótem Siniestro enfermo.\""},
[221975] = {name = "[q2]Bastón de Zarpaleña roto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Combina los componentes recogidos para formar un bastón frágil que puede ponerle fin al Letargo inmortal.\n[q]\"Parte de un bastón obtenido de un místico Zarpaleña enfermo.\""},
[221976] = {name = "[q2]Bastón de naturaleza enfermiza", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Despierta al objetivo actual de Letargo inmortal.\n[q]\"El bastón parece estar a punto de partirse, pero la magia ancestral que contiene aún podría ser de utilidad.\""},
[221978] = {name = "Alma de expedicionario", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Invoca tu Diablillo explorador. Aunque no pueda pelear, puede viajar por portales para explorar otros mundos y traerte tesoros.\n[q]\"Aprende a invocar al Diablillo explorador.\""},
[221979] = {name = "[q2]Profecía del invierno glauco", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu yelmo con la runa Dolor y sufrimiento:\n\n\nExplosión mental, Púa mental y Tortura mental restablecen al máximo la duración de una de tus habilidades Palabra de las Sombras: dolor, Plaga del Vacío o Toque vampírico sobre el objetivo. Siempre se restablecerá la habilidad a la que le quede menos tiempo restante.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[221980] = {name = "[q2]Profecía del caos desatado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu yelmo con la runa Ojo del Vacío:\n\n\nInvoca un ojo del Vacío para que luche por ti durante 30 s. El ojo puede lanzar una serie de maldiciones sobre tu objetivo.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[221981] = {name = "[q2]Profecía de la tribu perdida", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus brazales con la runa Oleada de Luz:\n\n\nLos lanzamientos de hechizos críticos hacen que tu próximo lanzamiento de Punición o Sanación relámpago en un período de 15 s sea instantáneo.\n[q2]Uso: Te enfocas en la Profecía para aprender un nuevo hechizo. Requiere una mente despejada mediante la meditación de dos misterios espirituales de Azeroth."},
[222952] = {name = "[q4]Frasco de sueños inquietos", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\nRequiere Alquimia (250)\n[q2]Uso: Aumenta hasta un máximo de 30 p. el daño infligido con hechizos, hasta un máximo de 45 p. la sanación realizada y 12 p. la regeneración de maná cada 5 s durante 1 h. Los beneficios de este frasco solo se aplican en áreas bajo la influencia de la pesadilla. (30 Seg Reutilización)\n[q]\"No importa cuánto bebas. El contenido del frasco parece no agotarse nunca.\""},
[222962] = {name = "Sabiduría de Hyjal", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Aprendes una nueva habilidad de grabado."},
[223073] = {name = "[q0]Cubrehombros de malla de Teniente caballero", additional_info = "Se liga al recogerlo\n{Hombro} {Malla}\n246 armadura\n+9 fuerza\n+11 aguante\n+5 intelecto\nDurabilidad 70 / 70\nClases: Cazador , Chamán\nNecesitas ser de nivel 50\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n\n[q]Malla de Teniente caballero (0/6)\n[q0]Armadura de malla de Caballero\nEscarpes de malla de Alférez\nGuanteletes de malla de Alférez\nYelmo de malla de Teniente caballero\nQuijotes de malla de Caballero\nCubrehombros de malla de Teniente caballero\n[q0](3) Conjunto : +15 p. de aguante.\n(6) Conjunto : Aumenta 30 p. el poder de ataque."},
