[224004] = {name = "[q2]Anillo de esmeralda", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+4 aguante\nNecesitas ser de nivel 20\nRequiereCeladores Esmeralda\n: Amistoso\n[q2]Equipar: Aumenta 6 p. el poder de ataque.\n[q2]Uso: Entra en el sueño de un amigo seleccionado. (1 Hora Reutilización)\n[q]\"Una luz se mueve en el interior de la fascinante esmeralda\""},
[224005] = {name = "[q2]Anillo de esmeralda", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+4 aguante\nNecesitas ser de nivel 20\nRequiereCeladores Esmeralda\n: Amistoso\n[q2]Equipar: Aumenta hasta 4 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Entra en el sueño de un amigo seleccionado. (1 Hora Reutilización)\n[q]\"Una luz se mueve en el interior de la fascinante esmeralda\""},
[224006] = {name = "[q3]Anillo de esmeralda", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n+12 aguante\n+5 resistencia a Arcano\nNecesitas ser de nivel 45\nRequiereCeladores Esmeralda\n: Honorable\n[q2]Equipar: Aumenta hasta 8 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Entra en el sueño de un amigo seleccionado. (1 Hora Reutilización)\n[q]\"Una luz se mueve en el interior de la fascinante esmeralda\""},
[224122] = {name = "[q4]Comesueños", additional_info = "Se liga al recogerlo\nÚnico\n{Una mano} {Daga}\n{69 - 126 p. de daño} {Velocidad 1.60}\n(60.94 p. de daño por segundo)\n+17 agilidad\nDurabilidad 75 / 75\nClases: Pícaro\nNecesitas ser de nivel 60\n[q2]Equipar: Tus remates que infligen daño tienen un 20% de probabilidad de restaurar 10 p. de energía por cada p. de combo."},
[224279] = {name = "[q4]Terrestris", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2964 armadura\n55 bloqueo\n+17 aguante\nDurabilidad 120 / 120\nClases: Chamán\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 7 p. el índice de defensa.\n[q2]Equipar: Los tótems invocados otorgan un favor de su elemento.\n[q2]Uso: Enciende las llamas de Terrestris para que entre en calor y en modo ofensivo. (1 Min Reutilización)"},
[224280] = {name = "[q4]Soberanía, Defensor de los Vuelos", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2964 armadura\n55 bloqueo\n+15 fuerza\nDurabilidad 120 / 120\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Equipar: Protege al portador de ser engullido por Llama de las Sombras.\n[q2]Equipar: Aumenta 10 p. el índice de defensa.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 18 p.\n[q2]Uso: Levanta a Soberanía durante 5 s, lo que reduce un 50% el daño con hechizos recibido. Si recibe un golpe de Aliento de dragón, obtiene Furia de la Soberanía, lo que otorga un 30% más de daño contra dragones durante 10 s. (1 Min Reutilización)"},
[224281] = {name = "[q4]Gla'sir", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Bastón}\n{140 - 241 p. de daño} {Velocidad 3.20}\n(59.53 p. de daño por segundo)\n+12 aguante\n+26 intelecto\n+14 espíritu\n+10 resistencia a Naturaleza\nDurabilidad 120 / 120\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 2% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 144 p. la sanación realizada y hasta 77 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Los efectos críticos de las sanaciones tienen una probabilidad de sanar 200 to 350 p. a 3 aliados cercanos , y los golpes de hechizo críticos tienen una probabilidad de infligir 100 to 175 p. de daño de Naturaleza a 3 enemigos cercanos. (Probabilidad de que accione: 15%, 15s de reutilización)\n[q2]Uso: Transforma a Gla'sir en Rae'lar. (1 Min Reutilización)"},
[224282] = {name = "[q4]Rae'lar", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Bastón}\n{125 - 226 p. de daño} {Velocidad 3.20}\n(54.84 p. de daño por segundo)\n+26 fuerza\n+23 agilidad\n+12 aguante\n+10 resistencia a Naturaleza\nDurabilidad 120 / 120\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Equipar: +338 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Equipar: Los ataques automáticos cuerpo a cuerpo tienen una probabilidad de robar 140 to 220 p. de vida al enemigo.\n[q2]Uso: Transforma a Rae'lar en Gla'sir. (1 Min Reutilización)"},
[224409] = {name = "[q0]Golpeador de serpiente", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Arma de puño}\n{73 - 136 p. de daño} {Velocidad 2.60}\n(40.19 p. de daño por segundo)\n+9 agilidad\n+7 aguante\nDurabilidad 75 / 75\nNecesitas ser de nivel 50\n[q2]Probabilidad al acertar: Envenena al enemigo e inflige 50 p. de daño de Naturaleza, lo que reduce la resistencia a la Naturaleza en 60 p. y aumenta el daño de Naturaleza y el daño Sagrado recibido un 8% durante 20 s. Solo afecta a los enemigos de niveles inferiores a 55.\n\n[q]Ascenso de la serpiente (0/2)\n[q0]Garra de colmillo de cobra\nGolpeador de serpiente\n[q0](2) Conjunto : Otorga una pequeña probabilidad de infundir al portador con una bendición de la serpiente cuando inflige daño cuerpo a cuerpo o a distancia. El poder de ataque cuerpo a cuerpo y a distancia aumenta 150 p. durante 12 s. (Probabilidad de que accione: 3%, 2m de reutilización)"},
[224806] = {name = "[q2]Ajustador del portal de la Legión", additional_info = "[q2]Uso: Conecta una cicatriz o falla vil con un mundo en la profundidad del espacio de la Legión. Puede provocar efectos impredecibles y peligrosos.\n5 cargas"},
