[225676] = {name = "Núcleo obsidiano fundido", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 10 min (tiempo real)\n[q]\"¡Enfríalo antes de que se haga líquido!\""},
[225686] = {name = "[q2]Runa de Exterminación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tus botas con la runa Exterminación:\n\n\nTu hechizo Fuego de alma ya no tiene tiempo de reutilización. Además, cuando tu Descarga de las sombras, Cuchilla de las Sombras, Incinerar o Fuego de alma golpea a un objetivo con menos de un 35% de salud, el tiempo de lanzamiento de tu hechizo Fuego de alma se reduce un 40% durante 10 s. Los Fuegos de alma lanzados bajo el efecto de Exterminación no cuestan fragmentos.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225687] = {name = "[q2]Runa de Armadura infernal", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu capa con la runa Armadura infernal:\n\n\nTu espíritu es imbuido con energía demoníaca que reduce todo el daño mágico recibido por un porcentaje equivalente a un 60% de la reducción de daño físico de tu armadura. Dura 10 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225688] = {name = "[q2]Runa de Marca del caos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu capa con la runa Marca del caos:\n\n\nTodas tus maldiciones, excepto Maldición de las Sombras y Maldición de los Elementos, ahora aplican la Marca del caos, lo que reduce [max(min( 56 + 19, 75), 27)] p. las resistencias del objetivo a lo Arcano, el Fuego, la Escarcha, las Sombras y la Naturaleza y aumenta un [max(min(( 56 - 8) * 0.125 + 4, 10), 4)]% todo el daño con hechizos que recibe de esas escuelas mientras permanece maldito.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225689] = {name = "[q2]Notas de hechizo: Tromba Arcana", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu capa con la runa Tromba Arcana:\n\n\nLanza varios misiles contra el objetivo enemigo que infligen entre [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100] y [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100] p. de daño Arcano. Este hechizo también tiene un 25% de probabilidad de activar Tromba de misiles.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225690] = {name = "[q2]Notas de hechizo: Orbe congelado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu capa con la runa\n Orbe congelado:\n\n\nArroja un orbe de hielo en espiral que se mueve rápidamente hacia adelante durante 16 s. Mientras se mueve, cada 1 s el orbe inflige [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño de Escarcha y aplica un enfriamiento que reduce un 30% la velocidad de movimiento de todos los enemigos que atraviesa. La primera vez que le inflige daño a un enemigo, su movimiento se ralentiza y tiene un 100% de probabilidad de activar la runa Dedos de Escarcha.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225691] = {name = "[q2]Notas de hechizo: Recalentamiento", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu capa con la runa Recalentamiento:\n\n\nExplosión de Fuego siempre asestará un golpe crítico, se puede lanzar durante el lanzamiento de otro hechizo y no se ve afectada por el tiempo de reutilización global, pero su tiempo de reutilización aumenta a 15 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225740] = {name = "[q2]Runa de Compostura", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu capa con la runa Coherencia:\n\n\nHace que la efectividad de tu Sanación en cadena solo se reduzca un 35% por salto y que la efectividad de Cadena de relámpagos solo se reduzca un 20% por salto. Además, hace que ambas salten a 1 objetivo más.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225838] = {name = "[q2]Ícono voltaico", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nClases: Chamán\n[q2]Graba tu capa con la runa Tormenta, Tierra y Fuego:\n\n\nReduce un 25% el tiempo de reutilización de tu Cadena de relámpagos, hace que tu Tótem Nexo Terrestre enraíce a los objetivos durante 5 s cuando se lanza y aumenta un 60% el daño periódico que inflige tu Choque de llamas.\n[q]\"Aprendes una nueva habilidad después de derrotar a 3 enemigos con una sola Cadena de relámpagos.\""},
[225893] = {name = "[q4]Fin de época", additional_info = "Se liga al recogerlo\nÚnico: (Desconocido #636) (0)\n{Dos manos} {Espada}\n{300 - 415 p. de daño} {Velocidad 4.20}\n(85.12 p. de daño por segundo)\n-322 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 77"},
[225914] = {name = "[q2]Runa del Espíritu vinculado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Graba tu capa con la runa Espíritu feral:\n\n\nInvoca dos espíritus de lobo a las órdenes del chamán. Duran 45 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[225929] = {name = "Fragmento de alma apestado", additional_info = "Se liga al recogerlo\nÚnico (3)"},
[225938] = {name = "[q2]Notas de hechizo rotas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas de hechizo rotas para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan tres de cuatro partes.\""},
[225939] = {name = "[q2]Notas de hechizo rotas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas de hechizo rotas para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan tres de cuatro partes.\""},
[225940] = {name = "[q2]Notas de hechizo rotas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas de hechizo rotas para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan tres de cuatro partes.\""},
[225941] = {name = "[q2]Notas de hechizo rotas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Uso: Combina las notas de hechizo rotas para crear un pergamino que te enseñará un nuevo hechizo de grabado.\n[q]\"Una página incompleta que parece similar a los pergaminos que enseñan habilidades de grabado. Faltan tres de cuatro partes.\""},
[225942] = {name = "Carne de jabalí contaminada", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Reviste con icor.\n[q]\"Probablemente solo necesita un poco de salsa.\""},
[225943] = {name = "Pedazo de carne rancio", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: ???\n[q]\"Le provocaría náuseas hasta al carroñero más miserable.\""},
[225954] = {name = "[q2]Notas de hechizo chamuscadas", additional_info = "Se liga al recogerlo\nClases: Mago\n[q]\"Una página rota y chamuscada que supo contener secretos arcanos para habilidades de grabado y ya no puede utilizarse por el daño del fuego.\""},
[225955] = {name = "[q2]Runa de Ingenio", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tu capa con la runa Inventiva:\n\n\nReduce un 100% el costo de maná de tus trampas y un 40% su tiempo de reutilización.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226122] = {name = "[q3]Cuerno de Dalton", additional_info = "Se liga al recogerlo\nÚnico\nReliquia\nNecesitas ser de nivel 50\n[q2]Uso: Haces sonar el cuerno de Dalton para invocar a tu escudero. Tu escudero te asistirá en batalla y aprenderá de ti en cada aventura que emprendan juntos. (Probabilidad de que accione: 3%) (15 Seg Reutilización)\n[q]\"Cocos no incluidos.\""},
[226201] = {name = "Espada del escudero Cuthbert", additional_info = "Objeto de misión\nÚnico\n[q]\"La espada está gastada y astillada, pero se siente cómoda en tus manos.\""},
[226207] = {name = "Eco de Anastari", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226208] = {name = "Eco de Barthilas", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226209] = {name = "Eco de Dathrohan", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226210] = {name = "Eco de Maleki", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226211] = {name = "Eco de Nerub'enkan", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226212] = {name = "Eco de Ramstein", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226213] = {name = "Eco de Osahendido", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226214] = {name = "Eco de Willey", additional_info = "Se liga al recogerlo\nÚnico\nDuración: 2 h (tiempo real)\n[q2]Uso: Ofrece el eco."},
[226252] = {name = "[q2]Runa de la Guerrilla", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]Graba tu capa con la runa\n Doble tenebroso:\n\n\nObtienes un 30% de velocidad de movimiento durante 15 s después de usar Golpe de raptor.\n\n Las habilidades de tu mascota que infligen daño le provocan un Frenesí rabioso al objetivo, lo que aumenta 91 p. su poder de ataque cuerpo a cuerpo pero reduce 640 p. su armadura durante 2 min. Los enemigos rabiosos no huirán e ignorarán los efectos de Miedo y Horror.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226374] = {name = "Veneno oculto I", additional_info = "Clases: Pícaro\nNecesitas ser de nivel 54\n[q2]Uso: Cubre de veneno un arma durante 30 minutos. Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligirle 108 p. de daño de Naturaleza durante 12 s, y de hacer que reciba un 4% más de daño Arcano, de Fuego, de Escarcha, de Naturaleza y de las Sombras. Se acumula hasta 5 veces en un solo objetivo.\n\n Veneno oculto cuenta como Veneno mortal y se beneficia de todos los talentos y efectos que se activan con Veneno mortal o lo modifican. (Probabilidad de que accione: 30%)"},
[226394] = {name = "[q2]Manual de Veneno atrófico", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Cubre un arma con veneno que dura 30 minutos.\n Cada golpe tiene un 30% de probabilidad de envenenar al enemigo y reducir 205 p. su poder de ataque cuerpo a cuerpo durante 15 s. 105 cargas.\n[q]\"Te enseña Veneno atrófico\""},
[226395] = {name = "[q2]Manual de Veneno entumecedor", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Cubre un arma con veneno que dura 30 minutos.\n Cada golpe tiene un 30% de probabilidad de envenenar al enemigo y aumentar un 20% el tiempo entre sus ataques cuerpo a cuerpo durante 15 s. 105 cargas.\n[q]\"Te enseña Veneno entumecedor\""},
[226396] = {name = "[q2]Manual de Veneno oculto", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Cubre de veneno un arma durante 30 minutos.\n Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligirle 108 p. de daño de Naturaleza durante 12 s, y de hacer que reciba un 4% más de daño Arcano, de Fuego, de Escarcha, de Naturaleza y de las Sombras. Se acumula hasta 5 veces en un solo objetivo.\n\n Veneno oculto cuenta como Veneno mortal y se beneficia de todos los talentos y efectos que se activan con Veneno mortal o lo modifican.\n[q]\"Te enseña Veneno oculto\""},
[226397] = {name = "[q2]Manual de Veneno sebáceo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Cubre un arma con veneno que dura 30 minutos.\n Cada golpe tiene un 30% de probabilidad de envenenar al enemigo y reducir 1700 p. su armadura durante 15 s. 105 cargas.\n\n Veneno sebáceo recibe los beneficios del talento Exponer armadura mejorado.\n[q]\"Te enseña Veneno sebáceo\""},
[226398] = {name = "[q2]Testamento de Martirio", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Te colmas de espíritu sagrado durante 30 s, lo que hace que cada uno de tus ataques cuerpo a cuerpo inflija un 50% de daño con arma a tu objetivo, pero pierdes una cantidad de salud equivalente al 10% del daño infligido. Cuando el sello está activo, los miembros de tu grupo y banda en un radio de 40 m obtienen una cantidad de maná equivalente al 65% del daño que recibas de este sello.\n\n Al desatar la energía de este sello, se juzgará a un enemigo y le infligirá instantáneamente un 85% de daño con arma a cambio de un 10% de salud del daño infligido.\n\n El sello y sentencia de esta habilidad se benefician de los talentos y efectos que modifican el sello y sentencia de Sello de rectitud.\n[q]\"Te enseña Sello de martirio.\""},
[226399] = {name = "[q2]Testamento de Cólera vengativa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\nNecesitas ser de nivel 25\n[q2]Aumenta todo el daño y la sanación infligidos un 20% durante 20 s. Â Causa Abstinencia y no se puede usar mientras Abstinencia está activa.\n[q]\"Te enseña Cólera vengativa.\""},
[226400] = {name = "[q2]Testamento del Exorcista", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Exorcismo ahora puede lanzarse sobre cualquier objetivo y tiene un 100% más de probabilidad de golpe crítico contra los no-muertos y demonios.\n[q]\"Te enseña Exorcista.\""},
[226401] = {name = "[q2]Tratado sobre Corazón del león", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\n[q2]El cazador invoca el corazón de un león, lo que aumenta un 10% las estadísticas totales y 200 p. el poder de ataque de todos los aliados cercanos y aumenta las estadísticas totales del Cazador un 10% más.\n[q]\"Te enseña Corazón del león.\""},
[226402] = {name = "[q2]Revelación de Ira del chamán", additional_info = "Se liga al recogerlo\nÚnico\nClases: Chamán\n[q2]Reduce un 20% todo el daño que recibes y regeneras una cantidad de maná equivalente al 5% de tu maná máximo por segundo durante 15 s. Los miembros de tu grupo y banda en un radio de 40 m también recibirán un 18% del maná que recibas con este efecto.\n[q]\"Te enseña Ira del chamán.\""},
[226403] = {name = "[q2]Vademécum de Gancho", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero\n[q2]Lanzas una cadena con gancho para refrenar a un objetivo y atraerlo hacia ti. No puede utilizarse contra enemigos de nivel superior a ( 60 + 1) o que estén marcados como jefes.\n[q]\"Te enseña Gancho.\""},
[226404] = {name = "[q2]Real de Minahonda deslustrado", additional_info = "Se liga al recogerlo\nÚnico (250)\n[q]\"Esta moneda de las Islas Perdidas está quedando de a poco fuera de circulación, pero sigue gozando de un tipo de cambio muy favorable en los Reinos del Este y Kalimdor.\""},
[226405] = {name = "[q2]Cajón de suministros de Minahonda dañado", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q]\"Este cajón raído y dañado parece haberse caído literalmente de un zepelín.\"\n[q2]<Click derecho para abrir>"},
[226406] = {name = "[q2]Runa de Especialización en espadas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Paladín , Cazador , Pícaro , Mago , Brujo\n[q2]Graba tu anillo con la runa de Especialización en espadas:\n\n\nAumenta 5 p. la habilidad con espadas y espadas de dos manos. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226407] = {name = "[q2]Runa de Especialización en hachas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Paladín , Cazador , Chamán\n[q2]Graba tu anillo con la runa de Especialización en hachas:\n\n\nAumenta 5 p. la habilidad con hachas y hachas de dos manos. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226408] = {name = "[q2]Runa de Especialización en mazas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Paladín , Pícaro , Sacerdote , Chamán , Druida\n[q2]Graba tu anillo con la runa de Especialización en mazas:\n\n\nAumenta 5 p. la habilidad con mazas y mazas de dos manos. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226409] = {name = "[q2]Runa de Especialización en dagas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Cazador , Pícaro , Sacerdote , Chamán , Mago , Brujo , Druida\n[q2]Graba tu anillo con la runa de Especialización en dagas:\n\n\nAumenta 5 p. la habilidad con dagas. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226410] = {name = "[q2]Runa de Especialización en armas a distancia", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Cazador , Pícaro\n[q2]Graba tu anillo con la runa de Especialización en armas a distancia:\n\n\nAumenta 5 p. la habilidad con arcos, armas de fuego, ballestas y armas arrojadizas. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226411] = {name = "[q2]Runa de Especialización en armas de puño", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Cazador , Pícaro , Chamán , Druida\n[q2]Graba tu anillo con la runa de Especialización en armas de puño:\n\n\nAumenta 5 p. la habilidad con armas de puño (sin armas). Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226412] = {name = "[q2]Runa de Especialización en armas de asta", additional_info = "Se liga al recogerlo\nÚnico\nClases: Guerrero , Paladín , Cazador , Sacerdote , Chamán , Mago , Brujo , Druida\n[q2]Graba tu anillo con la runa de Especialización en armas de asta:\n\n\nAumenta 5 p. la habilidad con bastones y armas de asta. Este efecto no se acumula con las bonificaciones raciales ni con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226413] = {name = "[q2]Runa de Especialización en lo Arcano", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador , Mago , Druida\n[q2]Graba tu anillo con la runa de Especialización en lo Arcano:\n\n\nAumenta la probabilidad de golpear con hechizos Arcanos un 6%. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226414] = {name = "[q2]Runa de Especialización en Fuego", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador , Chamán , Mago , Brujo\n[q2]Graba tu anillo con la runa de Especialización en Fuego:\n\n\nAumenta la probabilidad de golpear con hechizos de Fuego un 6%. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226415] = {name = "[q2]Runa de Especialización en Escarcha", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador , Chamán , Mago\n[q2]Graba tu anillo con la runa de Especialización en Escarcha:\n\n\nAumenta la probabilidad de golpear con hechizos de Escarcha un 6%. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226416] = {name = "[q2]Runa de Especialización en Naturaleza", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador , Pícaro , Chamán , Druida\n[q2]Graba tu anillo con la runa de Especialización en Naturaleza:\n\n\nAumenta la probabilidad de golpear con hechizos de Naturaleza un 6%. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226417] = {name = "[q2]Runa de Especialización en las Sombras", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote , Brujo\n[q2]Graba tu anillo con la runa de Especialización en las Sombras:\n\n\nAumenta la probabilidad de golpear con hechizos de las Sombras un 6%. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226418] = {name = "[q2]Runa de Especialización Sagrada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín , Sacerdote\n[q2]Graba tu anillo con la runa de Especialización Sagrada:\n\n\nAumenta la probabilidad de golpear con hechizos Sagrados un 6%. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226419] = {name = "[q2]Runa de Especialización en combate Feral", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Graba tu anillo con la runa de Especialización en combate Feral:\n\n\nLa habilidad en combate Feral aumenta 5 p. No se acumula con otras runas de anillo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[226420] = {name = "[q0]Busto esculpido con delicadeza", additional_info = "Se liga al recogerlo\n[q]\"Una obra de arte realizada con mucha delicadeza. Esta pieza es perfecta para una colección privada o un museo.\""},
[226440] = {name = "[q4]Cinturón de Destripador Nocturno", additional_info = "Se liga al recogerlo\n{Cintura} {Cuero}\n113 armadura\n+15 fuerza\n+17 agilidad\n+15 aguante\n+7 resistencia a Fuego\nDurabilidad 40 / 40\nClases: Pícaro\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n\n[q]Emoción de Destripador Nocturno (0/8)\n[q0]Cinturón de Destripador Nocturno\nPulseras de Destripador Nocturno\nPechera de Destripador Nocturno\nBotas de Destripador Nocturno\nCasquete de Destripador Nocturno\nGuantes de Destripador Nocturno\nPantalones de Destripador Nocturno\nHombreras de Destripador Nocturno\n[q0](2) Conjunto : Amago también otorga Eludir durante 6 s, lo que reduce un 50% todo el daño recibido de ataques con área de efecto de enemigos que no sean jugadores.\n(4) Conjunto : Aumenta un 100% la bonificación de daño por golpe crítico con tus venenos.\n(6) Conjunto : Tus remates tienen una probabilidad del 5% por punto de combo de hacer que tu próxima habilidad no cueste energía."},
