[227683] = {name = "[q5]Sulfuras, Mano de Ragnaros", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Maza}\n{229 - 382 p. de daño} {Velocidad 3.80}\n(80.39 p. de daño por segundo)\n+12 fuerza\n+12 aguante\n+32 resistencia a Fuego\nDurabilidad 145 / 145\nNecesitas ser de nivel 60\n[q2]Equipar: +358 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Probabilidad al acertar: Lanza una bola de fuego que inflige 273 to 333 p. de daño de Fuego y purga el alma del objetivo, lo que aumenta el daño de Fuego y daño Sagrado recibidos hasta un máximo de 30 p. e inflige 75 p. más de daño durante 10 s.\n[q2]Equipar: 20% de probabilidad de infligir 25 p. de daño de Fuego a todos los enemigos cercanos cuando te golpea un ataque cuerpo a cuerpo. (Probabilidad de que accione: 20%)"},
[227684] = {name = "[q4]Martillo de Sulfuron", additional_info = "Se liga al equiparlo\n{Dos manos} {Maza}\n{181 - 303 p. de daño} {Velocidad 3.80}\n(63.68 p. de daño por segundo)\n+10 fuerza\n+10 aguante\n+30 resistencia a Fuego\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: Lanza una bola ígnea que inflige 83 to 101 p. de daño de Fuego y 16 p. de daño extra durante 8 s.\n[q2]Equipar: Inflige 5 p. de daño de Fuego a quien te golpee en un ataque cuerpo a cuerpo.\n[q2]Equipar: +124 p. de poder de ataque solo en las formas felina, de oso y de oso temible."},
[227685] = {name = "Escalpelo sombrío modificado", additional_info = "Objeto de misión\n[q2]Uso: Enfoca el Escalpelo sombrío modificado en Arkonos, el Maldito, para disipar su barrera de protección.\n[q]\"Cuthbert ha aplicado la última bendición de Dalton en este instrumento. Con suerte, debería servir para anular la barrera que protege a Arkonos.\""},
[227686] = {name = "Martillo de guerra ornamentado", additional_info = "Objeto de misión\nÚnico"},
[227687] = {name = "[q2]Diente de oro favorito de Lorthas", additional_info = "Se liga al recogerlo\n[q2]Uso: Frota... el diente de Lorthas. Qué asco. (2 Min Reutilización)\n[q]\"Huele horrible.\""},
