[227915] = {name = "[q4]Dominio del duque", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+22 aguante\n+20 resistencia a Fuego\nRequiereSrs. del Agua de Hydraxis\n: Exaltado\n[q2]Uso: Expande el Dominio del duque, lo que aumenta 50 p. la resistencia al fuego de los que habitan en él. Dura 15 s. (1 Min, 30 Seg Reutilización)"},
[227921] = {name = "[q2]Runa de Cuchillos", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu capa con la runa Abanico de cuchillos:\n\n\nLanza instantáneamente las dos armas a todos los objetivos que se encuentren en un radio de 8 m, lo que inflige un 75% de daño con arma con dagas y un 50% de daño con arma con cualquier otra arma.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[227922] = {name = "[q2]Runa del Espadachín", additional_info = "Se liga al recogerlo\nÚnico\nClases: Pícaro\n[q2]Graba tu capa con la runa Trabuco:\n\n\nDispara una descarga de mosquete a un máximo de 4 enemigos en un cono frente a ti que inflige de [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Attack power] a [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Attack power] p. de daño físico.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
