[228117] = {name = "[q3]Diseño: campeona de arcanita refinada", additional_info = "Requiere Herrería (300)\nRequiereMaestro forjador de espadas\n[q2]Uso: Te enseña a hacer una campeona de arcanita.\n[q4]Campeona de arcanita refinada\nSe liga al equiparlo\n{Dos manos} {Espada}\n{107 - 161 p. de daño} {Velocidad 2.00}\n(67.00 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: Te sana 270 to 450 p. y aumenta tu fuerza 120 p. durante 30 s.\n[q2]Probabilidad al acertar: Aumenta 20 p. el daño infligido y un 5% la velocidad de ataque durante 15 s.\nRequiere Campeona de arcanita , Piedra de afilar elemental (10)"},
[228118] = {name = "[q4]Diseño: guanteletes de mayor aferramiento", additional_info = "Requiere Herrería (300)\nRequiereForjador de armaduras\n[q2]Uso: Te enseña a hacer guanteletes bastión.\n[q4]Guanteletes bastión\nSe liga al equiparlo\n{Manos} {Placas}\n441 armadura\n+12 aguante\nDurabilidad 55 / 55\nNecesitas ser de nivel 57\n[q2]Equipar: Inmune a Desarmar.\n[q2]Equipar: Aumenta un 1% tu probabilidad de parar un ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de conseguir un golpe crítico.\nRequiere Barra de arcanita (15), Barra de torio encantado (20), Esencia de tierra (10), Zafiro azul (4), Ópalo grande (4)"},
[228119] = {name = "[q3]Patrón: guanteletes de núcleo demoníaco", additional_info = "Requiere Peletería (290)\nRequiere Peletería tribal\n[q2]Uso: Te enseña a hacer unos guanteletes de núcleo demoníaco.\n[q4]Guanteletes de núcleo demoníaco\nSe liga al equiparlo\n{Manos} {Cuero}\n123 armadura\n+12 aguante\n+15 resistencia a Fuego\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 38 p. el poder de ataque.\n\n[q]Armadura de demosaurio (0/2)\n[q0]Guanteletes de núcleo demoníaco\nLeotardos de núcleo demoníaco\nRequiere Cuero basto (30), Cuero de demosaurio (8), Hilo rúnico , Esencia de Fuego (8)"},
[228120] = {name = "[q3]Patrón: leotardos de núcleo demoníaco", additional_info = "Requiere Peletería (300)\nRequiere Peletería tribal\n[q2]Uso: Te enseña a hacer unos leotardos de núcleo demoníaco.\n[q4]Leotardos de núcleo demoníaco\nSe liga al equiparlo\n{Piernas} {Cuero}\n173 armadura\n+14 aguante\n+20 resistencia a Fuego\nDurabilidad 90 / 90\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 58 p. el poder de ataque.\n\n[q]Armadura de demosaurio (0/2)\n[q0]Guanteletes de núcleo demoníaco\nLeotardos de núcleo demoníaco\nRequiere Cuero basto (30), Cuero de demosaurio (20), Pellejo basto curtido , Hilo rúnico , Esencia de Fuego (10)"},
[228121] = {name = "[q2]Patrón: bolsa de paño rúnico reforzada con cuero", additional_info = "Requiere Sastrería (300)\n[q2]Uso: Te enseña a hacer una bolsa de paño rúnico reforzada con cuero.\n\n\n[q3]Bolsa de paño rúnico reforzada con cuero\nBolsa de 18 casillas\nRequiere Madeja de paño rúnico (5), Cuero basto (2), Hilo rúnico , Pellejo basto curtido"},
[228122] = {name = "[q4]El Núcleo de Magma", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+20 resistencia a Fuego\nNecesitas ser de nivel 60\n[q2]Equipar: Tu muerte desestabiliza el Núcleo de Magma, hace que explote e inflige 1 to 2000 p. de daño de Fuego a los enemigos cercanos."},
[228123] = {name = "[q2]Epifanía jubilosa", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu capa con la runa Sanación conjunta:\n\n\nRestablece de [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 161 / 100] a [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 197 / 100] p. de salud a un objetivo aliado y al taumaturgo. Poca amenaza. Este hechizo se beneficia de todos los efectos asociados con Sanación relámpago y los activa.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[228124] = {name = "[q2]Epifanía onírica", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu capa con la runa Amparo de alma:\n\n\nTu Palabra de poder: escudo ya no tiene tiempo de reutilización, cuesta un 15% menos de maná, obtiene un 10% más de valor básico y obtiene un 10% más de tu poder de sanación.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[228125] = {name = "[q4]Campeona de arcanita refinada", additional_info = "Se liga al equiparlo\n{Dos manos} {Espada}\n{107 - 161 p. de daño} {Velocidad 2.00}\n(67.00 p. de daño por segundo)\nDurabilidad 100 / 100\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: Te sana 270 to 450 p. y aumenta tu fuerza 120 p. durante 30 s.\n[q2]Probabilidad al acertar: Aumenta 20 p. el daño infligido y un 5% la velocidad de ataque durante 15 s."},
[228126] = {name = "[q2]Epifanía aperitiva", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tu capa con la runa Toque vampírico:\n\n\nAplica tu talento Abrazo vampírico a tu objetivo, lo que le inflige [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5] p. de daño de las Sombras durante 15 s, y hace que todos los miembros del grupo obtengan una cantidad de maná equivalente al 2% de cualquier daño con hechizos de las Sombras que inflijas al objetivo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[228127] = {name = "[q4]Guardamuñecas de inestabilidad", additional_info = "Se liga al recogerlo\nMuñeca Placas\n328 armadura\n+27 fuerza\nDurabilidad 40 / 40\nNecesitas ser de nivel 60"},
