[228955] = {name = "[q4]Grimorio Piedra angular antigua", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 29 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Uso: Invoca a un esqueleto que te protege durante 1 min. (5 Min Reutilización)"},
[228978] = {name = "[q3]Sigilo encantado: aguas fluidas", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 60\nRequiere Encantamiento (290)\n[q2]Uso: Otorga un sigilo encantado de aguas fluidas que te potencia para aumentar hasta 30 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 30 p. durante 1 h. (1 Min Reutilización)"},
[228979] = {name = "[q3]Sigilo encantado: aguas fluidas", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (290)\nRequiereSrs. del Agua de Hydraxis\n: Reverenciado\n[q2]Uso: Te enseña a conjurar un Sigilo de aguas fluidas.\n[q3]Sigilo encantado: aguas fluidas\nSe liga al recogerlo\nNecesitas ser de nivel 60\nRequiere Encantamiento (290)\n[q2]Uso: Otorga un sigilo encantado de aguas fluidas que te potencia para aumentar hasta 30 p. el daño y la sanación realizados con hechizos, y aumenta el poder de ataque 30 p. durante 1 h. (1 Min Reutilización)\nRequiere Polvo de ilusión"},
[228980] = {name = "Recubrimiento de escudo conductor", additional_info = "Necesitas ser de nivel 40\n[q2]Uso: Cuando se aplica al escudo objetivo, aumenta hasta 24 p. el daño y la sanación con hechizos. Dura 30 minutos.\n5 cargas"},
[228981] = {name = "Fórmula: Recubrimiento de escudo conductor", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (275)\n[q2]Uso: Te enseña a crear un Recubrimiento de escudo conductor.\nRecubrimiento de escudo conductor\nNecesitas ser de nivel 40\n[q2]Uso: Cuando se aplica al escudo objetivo, aumenta hasta 24 p. el daño y la sanación con hechizos. Dura 30 minutos.\n5 cargas\nRequiere Polvo de ilusión (2), Flor de fuego , Vial de cristal"},
[228982] = {name = "[q3]Fórmula: encantar escudo - Ley de la naturaleza", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (300)\nRequiereBastión Fauces de Madera\n: Reverenciado\n[q2]Uso: Te enseña a encantar de forma permanente un escudo para que agregue hasta 30 p. de daño a los hechizos y hasta 55 p. de sanación a los hechizos de sanación."},
[228992] = {name = "[q2]Mochila de pellejo de Onyxia", additional_info = "Se liga al recogerlo\nBolsa de 20 casillas"},
[228993] = {name = "[q3]Patrón: bolsa sin fondo", additional_info = "Requiere Sastrería (300)\n[q2]Uso: Te enseña a confeccionar una bolsa sin fondo.\n[q3]Bolsa sin fondo\nSe liga al equiparlo\nBolsa de 20 casillas\nRequiere Madeja de paño rúnico (8), Tela lunar (12), Fragmento luminoso grande (2), Cuero del Núcleo (2), Hilo rúnico (2)"},
[228994] = {name = "[q3]Bolsa sin fondo", additional_info = "Se liga al equiparlo\nBolsa de 20 casillas"},
[229008] = {name = "Fórmula: encantar capa: Resistencia al Fuego superior", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (300)\nRequiereHermandad del Torio\n: Honorable\n[q2]Uso: Te enseña a encantar de forma permanente una capa para aumentar 15 p. de resistencia al Fuego."},
[229009] = {name = "Fórmula: encantar capa: resistencia a la Naturaleza superior", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (300)\nRequiereHermandad del Torio\n: Honorable\n[q2]Uso: Te enseña a encantar de forma permanente una capa para aumentar 15 p. de resistencia a la Naturaleza."},
