[231280] = {name = "[q0]Talismán de naturaleza de Wushoolay", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Uso: Alinea al druida con la naturaleza, lo que aumenta un 10% el daño que infligen los hechizos, mejora un 10% los efectos de sanación y aumenta un 10% la probabilidad de golpe crítico de los hechizos durante 20 s. (2 Min Reutilización)\n\n[q]Atuendo de haruspex (0/5)\n[q0]Brazales de haruspex Zandalar\nCinturón de haruspex Zandalar\nGuerrera de haruspex Zandalar\nAlgas de los Mares del Sur encantadas prístinas\nTalismán de naturaleza de Wushoolay\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los efectos y hechizos mágicos.\n(3) Conjunto : Reduce 0.5 s el tiempo de lanzamiento y el tiempo de reutilización global de Fuego estelar.\n(5) Conjunto : Aumenta un 10% la probabilidad de golpe crítico de Cólera."},
[231281] = {name = "[q0]Talismán de espíritus de Wushoolay", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Chamán\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 100% el daño que inflige tu hechizo Escudo de relámpagos durante 20 s. (2 Min Reutilización)\n\n[q]Atavío de Augur (0/5)\n[q0]Brazales de augur Zandalar\nCinturón de augur Zandalar\nCamisote de augur Zandalar\nVisión inmaculada de Voodress\nTalismán de espíritus de Wushoolay\n[q0](2) Conjunto : La defensa aumenta +7 p.\n(3) Conjunto : Aumenta un 10% tu probabilidad de bloquear ataques con un escudo.\n(5) Conjunto : Aumenta un 5% más la probabilidad de activar tu runa Oleada de poder."},
[231282] = {name = "[q0]Talismán de magia gélida de Hazza'rah", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Mago\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 5% la probabilidad de golpe crítico de tus hechizos Descarga de Escarcha, Descarga de fríoarcano y Orbe congelado, y aumenta un 50% el daño de golpe crítico de tus hechizos Descarga de Escarcha, Descarga de fríoarcano y Orbe congelado durante 20 s. (2 Min Reutilización)\n\n[q]Ropajes de ilusionista (0/5)\n[q0]Toga de ilusionista Zandalar\nManto de ilusionista Zandalar\nBrazaletes de ilusionista Zandalar\nJoya de Kajaro\nTalismán de magia gélida de Hazza'rah\n[q0](2) Conjunto : Aumenta hasta 14 p. el daño que infligen los efectos y hechizos de Escarcha.\n(3) Conjunto : Aumenta un 15% más la probabilidad de activar tu runa Dedos de Escarcha.\n(5) Conjunto : Aumenta un 75% el daño que infligen tus hechizos Descarga de Escarcha y Descarga de fríoarcano."},
[231283] = {name = "[q0]Talismán de protección de Hazza'rah", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q2]Uso: Reduce el tiempo de lanzamiento de tus hechizos de Sanación superior un 40%, reduce el costo de maná de tus hechizos de sanación un 5%, y los lanzamientos de Penitencia sobre aliados tendrán como objetivo hasta a 2 objetivos adicionales durante 15 s. (1 Min, 30 Seg Reutilización)\n\n[q]Vestiduras de confesor (0/5)\n[q0]Brazaletes de confesor Zandalar\nAtaduras de confesor Zandalar\nManto de confesor Zandalar\nEl Ojo que todo lo ve de Zuldazar\nTalismán de protección de Hazza'rah\n[q0](2) Conjunto : Aumenta hasta 22 p. la sanación realizada y hasta 7 p. el daño que infligen todos los efectos y hechizos mágicos.\n(3) Conjunto : Reduce 6 s el tiempo de reutilización de tu hechizo Penitencia.\n(5) Conjunto : Aumenta un 10% la absorción de daño de tu Palabra de poder: escudo."},
[231284] = {name = "[q0]Talismán de destrucción de Hazza'rah", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta tu probabilidad de golpe crítico un 10% y la velocidad de ataque de tu mascota un 50% durante 20 s. Este hechizo no afecta a las mascotas temporales ni a los demonios subyugados. (2 Min Reutilización)\n\n[q]Ropas demoníacas (0/5)\n[q0]Manto de endemoniado Zandalar\nToga de endemoniado Zandalar\nBrazaletes de endemoniado Zandalar\nMancha imparable de Kezan\nTalismán de destrucción de Hazza'rah\n[q0](2) Conjunto : Aumenta hasta 12 p. el daño y la sanación de los efectos y hechizos mágicos.\n(3) Conjunto : Aumenta un 20% el poder de ataque y el daño con hechizos que tu mascota demoníaca obtiene de tus atributos.\n(5) Conjunto : Aumenta un 50% los beneficios de tu talento Maestro demonólogo."},
[231285] = {name = "[q4]Talismán de valor de Gri'lek", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Paladín\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta un 10% la probabilidad de golpe crítico de los hechizos Sagrados durante 15 s. Si Choque y terror está grabado, obtienes un 5% más. (1 Min, 30 Seg Reutilización)\n\n[q]Armadura de librepensador (0/5)\n[q0]Coraza de librepensador Zandalar\nCinturón de librepensador Zandalar\nGuardabrazos de librepensador Zandalar\nTalismán de valor de Gri'lek\nEnseña de héroe\n[q0](2) Conjunto : Aumenta hasta 14 p. el daño que infligen los efectos y hechizos Sagrados.\n(3) Conjunto : Aumenta un 50% el daño infligido por tu hechizo Choque sagrado.\n(5) Conjunto : Reduce 3 s el tiempo de reutilización de tu hechizo Exorcismo y aumenta un 75% el daño que inflige."},
[231286] = {name = "[q0]Talismán de poderío de Gri'lek", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Uso: Aumenta 200 p. el valor de bloqueo de tu escudo durante 20 s, y aumenta 30 p. tu ira instantáneamente. (2 Min Reutilización)\n\n[q]Equipo de batalla de vindicador (0/5)\n[q0]Coraza de vindicador Zandalar\nCinturón de vindicador Zandalar\nGuardabrazos de vindicador Zandalar\nIra de Mugamba\nTalismán de poderío de Gri'lek\n[q0](2) Conjunto : La defensa aumenta +7 p.\n(3) Conjunto : Reduce 2 s el tiempo de reutilización de tu habilidad Embate con escudo.\n(5) Conjunto : Reduce 30 s el tiempo de reutilización de tu habilidad Ira sangrienta mientras estás en Actitud de gladiador."},
