[231385] = {name = "[q4]Simulacro del Alma de Dragón", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Equipar: Lleva la marca de un mensajero dracónico, aliado del vuelo.\n[q]\"Este simulacro se ha encantado para marcar al portador como amigo del Vuelo Rojo.\""},
[231386] = {name = "[q3]Dragontina negra impecable", additional_info = "Objeto de misión\nÚnico\nClases: Guerrero\nNecesitas ser de nivel 60\n[q]\"Esta escama es inmensa e impecable. Solo los dragones más venerables poseen escamas de esta calidad.\""},
[231387] = {name = "[q4]Tormentira, Hoja corta santificada del buscaráfagas", additional_info = "Se liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Daga}\n{45 - 113 p. de daño} {Velocidad 1.90}\n(41.58 p. de daño por segundo)\n+10 aguante\n+9 intelecto\n+7 espíritu\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 68 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Los hechizos de daño no periódico tienen una probabilidad de azotar hasta 3 objetivos por 181 to 229 p. de daño. (Probabilidad de que accione: 10%, 100ms de reutilización)"},
[231452] = {name = "[q4]Sangre del Iluminado", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nClases: Paladín\nNecesitas ser de nivel 60\n[q]\"Este diminuto relicario contiene una pequeña muestra de sangre. En la parte inferior puede verse una etiqueta de pergamino parcialmente rasgada que exhibe una sola palabra: \"Uther\".\""},
[231460] = {name = "[q4]Rompeplanos de Azgaloth", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{146 - 270 p. de daño} {Velocidad 3.60}\n(57.78 p. de daño por segundo)\n+31 aguante\n+32 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 90 p. la sanación realizada y hasta 30 p. el daño que infligen todos los efectos y hechizos mágicos."},
[231466] = {name = "[q4]Códice de brujo Alanegra", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\nNecesitas ser de nivel 60"},
[231509] = {name = "[q4]Tomo de Cassandra", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 47 p. el daño que infligen los hechizos y efectos de las Sombras.\n[q2]Equipar: Aumenta hasta 70 p. la sanación de los hechizos y efectos.\n[q2]Uso: Lee una profecía del tomo que aumenta un 100% la probabilidad de golpe crítico de tu siguiente ataque o hechizo no periódico. (2 Min Reutilización)"},
[231512] = {name = "[q3]Ídolo Hakkari primigenio", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 58\n[q]\"Un antiguo mal se agita dentro...\""},
