[231752] = {name = "[q0]S03 - Monster - Sword, 2H Alliance", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{1 - 2 p. de daño} {Velocidad 2.00}\n(0.75 p. de daño por segundo)\nDurabilidad 20 / 20"},
[231753] = {name = "[q4]Consuelo de Muro Celeste", additional_info = "Se liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Maza}\n{50 - 124 p. de daño} {Velocidad 2.10}\n(41.43 p. de daño por segundo)\n+8 aguante\n+16 intelecto\n+10 espíritu\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 128 p. la sanación realizada y hasta 43 p. el daño que infligen todos los efectos y hechizos mágicos."},
[231754] = {name = "[q4]Cernícalo", additional_info = "Se liga al recogerlo\nÚnico\n{Mano derecha} {Espada}\n{123 - 229 p. de daño} {Velocidad 2.90}\n(60.69 p. de daño por segundo)\n+14 agilidad\nDurabilidad 105 / 105\nClases: Cazador\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Probabilidad al acertar: Aumenta un 40% la velocidad de carrera durante 10 s.\n[q]\"Esta espada curva y pesada contiene el poder de un halcón de caza. Al igual que un cernícalo, se abalanza sobre su presa con una rapidez increíble.\""},
[231755] = {name = "[q4]Peregrino", additional_info = "Se liga al recogerlo\nÚnico\n{Mano izquierda} {Espada}\n{123 - 229 p. de daño} {Velocidad 2.90}\n(60.69 p. de daño por segundo)\n+9 agilidad\nDurabilidad 105 / 105\nClases: Cazador\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Probabilidad al acertar: Otorga 1 p. adicionales de ataque con ambas armas al instante.\n[q]\"Esta espada curva y pesada contiene el poder de un halcón de caza. Al igual que un peregrino, ataca con suma rapidez.\""},
[231777] = {name = "[q4]Extremidad de qiraji cristalizada", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nSostener con la mano izquierda\n+8 aguante\n+9 espíritu\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 55 p. la sanación realizada y hasta 19 p. el daño que infligen todos los efectos y hechizos mágicos."},
[231778] = {name = "Agua de manantial de montaña", additional_info = "Objeto mágico\nNecesitas ser de nivel 55\n[q2]Uso: Restaura 5100 p. de maná durante 30 s. Debes permanecer sentado mientras bebes."},
[231779] = {name = "[q4]Cólera de Wray", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\n+10 resistencia a Naturaleza\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Uso: Aumenta 92 p. tu fuerza. El efecto dura 20 s. (2 Min Reutilización)"},
[231780] = {name = "[q2]Escrito sobre Crear agua VIII", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\nNecesitas ser de nivel 60\n[q2]Crea 20 botellas de agua cristalina para que el mago y sus aliados tengan algo para beber.\n\n Los objetos creados por arte de magia desaparecen si el jugador permanece desconectado durante más de 15 min.\n[q]\"Te enseña Crear agua (Rango 8).\""},
