[231873] = {name = "[q4]Hacha de piedra Zulian", additional_info = "Ensangrentado\nSe liga al recogerlo\n{Dos manos} {Hacha}\n{187 - 281 p. de daño} {Velocidad 3.80}\n(61.58 p. de daño por segundo)\n+23 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 66 p. el poder de ataque.\n[q]\"Lleva la marca de Jin.\""},
[231874] = {name = "[q4]Colmillo de Venoxis", additional_info = "Ensangrentado\nSe liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Daga}\n{33 - 72 p. de daño} {Velocidad 1.30}\n(40.38 p. de daño por segundo)\n+8 intelecto\n+8 espíritu\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 36 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Restaura 6 p. de maná cada 5 s."},
[231875] = {name = "[q0]Agarre de Thekal", additional_info = "Ensangrentado\nSe liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Arma de puño}\n{94 - 175 p. de daño} {Velocidad 2.70}\n(49.81 p. de daño por segundo)\n+14 aguante\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n\n[q]Bendición primigenia (0/2)\n[q0]Agarre de Arlokk\nAgarre de Thekal\n[q0](2) Conjunto : Da una pequeña probabilidad de imbuir al que lo ejerce con una bendición de los dioses primigenios cuando se inflige daño cuerpo a cuerpo o a distancia. El poder de ataque a distancia y cuerpo a cuerpo aumenta 300 p. durante 12 s. (Probabilidad de que accione: 5%, 1.2m de reutilización)"},
[231876] = {name = "[q4]Cercenadora Zulian", additional_info = "Ensangrentado\nSe liga al recogerlo\nÚnico-Equipado: (Desconocido #663) (1)\n{Una mano} {Espada}\n{66 - 123 p. de daño} {Velocidad 2.00}\n(47.25 p. de daño por segundo)\n+7 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Probabilidad al acertar: Rebana al enemigo e inflige 72 to 96 p. de daño de Naturaleza.\n[q2]Equipar: Aumenta 12 p. el poder de ataque.\nEquipar: Desuello +10 p."},
[231882] = {name = "[q4]Recibo de aparato de supresión", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\nClases: Cazador\nNecesitas ser de nivel 60\n[q]\"Recibo de trampas de aparato de supresión para el señor de linaje Capazote de parte de Van Amburgh.\"\n[q2]<Click derecho para leer>"},
[231885] = {name = "[q4]Agonía de Escarcha", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{171 - 257 p. de daño} {Velocidad 3.60}\n(59.44 p. de daño por segundo)\nDurabilidad 120 / 120\nNecesitas ser de nivel 58\n[q2]Equipar: Aumenta tu velocidad de regeneración de vida y la velocidad de movimiento."},
[231890] = {name = "[q4]Terrestris", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2964 armadura\n55 bloqueo\n+7 aguante\n+8 intelecto\nDurabilidad 120 / 120\nClases: Chamán\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 20 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Los tótems invocados otorgan un favor de su elemento.\n[q2]Uso: Enfría las llamas de Terrestris para endurecerlo y que entre en modo defensivo. (1 Min Reutilización)"},
[231891] = {name = "[q2]Tratado del falcón", additional_info = "Se liga al recogerlo\nÚnico\nClases: Cazador\nNecesitas ser de nivel 60\n[q2]El cazador asume el aspecto de un halcón, lo que aumenta el poder de ataque cuerpo a cuerpo y a distancia la misma cantidad que el rango más alto de Aspecto del halcón que tenga.\n\n Mientras Aspecto del halcón está activo, los ataques cuerpo a cuerpo pueden activar Aspecto del halcón mejorado, lo que los potencia. Solo puede haber un aspecto activo a la vez. (Probabilidad de que accione: 5%)\n[q]\"Te enseña Aspecto del falcón\""},
[231901] = {name = "[q4]Faro de Verdad", additional_info = "Objeto de misión\nÚnico\nClases: Paladín\nNecesitas ser de nivel 60"},
