[231903] = {name = "Retazo de tela rasgada", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\nNecesitas ser de nivel 60\n[q]\"Un pequeño retazo de tela de la túnica de Uther el Iluminado que tiene algunas manchas de sangre.\""},
