[232261] = {name = "[q4]Escarpes de Cólera", additional_info = "Forjado del Núcleo\nSe liga al recogerlo\n{Pies} {Placas}\n589 armadura\n+10 fuerza\n+10 agilidad\n+27 aguante\n+10 resistencia a Naturaleza\nDurabilidad 75 / 75\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 11 p. el índice de defensa.\n\n[q]Poderío inamovible (0/8)\n[q0]Cinturón de poderío\nBrazales de poderío\nCoraza de poderío\nGuanteletes de poderío\nYelmo de poderío\nQuijotes de poderío\nHombreras de poderío\nEscarpes de poderío\n[q0](2) Conjunto : Aumenta 30 p. el valor de bloqueo de tu escudo.\n(4) Conjunto : Obtienes 1 p. más de ira cada vez que recibes o infliges daño con ataques automáticos.\n(6) Conjunto : Aumenta toda la amenaza que generas en actitud defensiva un 10% más y aumenta todo el daño que infliges en actitud de gladiador un 4%."},
[232262] = {name = "[q4]Coselete de Cólera", additional_info = "Forjado del Núcleo\nSe liga al recogerlo\n{Pecho} {Placas}\n857 armadura\n+18 fuerza\n+11 agilidad\n+32 aguante\n+10 resistencia a Naturaleza\n+10 resistencia a Escarcha\nDurabilidad 165 / 165\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 10 p. el índice de defensa.\n\n[q]Poderío inamovible (0/8)\n[q0]Cinturón de poderío\nBrazales de poderío\nCoraza de poderío\nGuanteletes de poderío\nYelmo de poderío\nQuijotes de poderío\nHombreras de poderío\nEscarpes de poderío\n[q0](2) Conjunto : Aumenta 30 p. el valor de bloqueo de tu escudo.\n(4) Conjunto : Obtienes 1 p. más de ira cada vez que recibes o infliges daño con ataques automáticos.\n(6) Conjunto : Aumenta toda la amenaza que generas en actitud defensiva un 10% más y aumenta todo el daño que infliges en actitud de gladiador un 4%."},
[232299] = {name = "[q4]Defensor Zulian", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2468 armadura\n44 bloqueo\n+8 aguante\n+10 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 23 p. el daño y la sanación de los hechizos y efectos mágicos."},
[232309] = {name = "[q4]Conducto de alma de Renataki", additional_info = "Se liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Espada}\n{57 - 117 p. de daño} {Velocidad 2.10}\n(41.43 p. de daño por segundo)\n+20 espíritu\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 23 p. el daño y la sanación de los hechizos y efectos mágicos."},
[232310] = {name = "[q4]Conducto de alma de Renataki", additional_info = "Ensangrentado\nSe liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Espada}\n{57 - 117 p. de daño} {Velocidad 2.10}\n(41.43 p. de daño por segundo)\n+20 espíritu\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 23 p. el daño y la sanación de los hechizos y efectos mágicos."},
[232311] = {name = "[q4]Capa de pellejo de tigre Zulian", additional_info = "Se liga al recogerlo\nEspalda\n50 armadura\n+17 agilidad\n+14 aguante\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[232312] = {name = "[q4]Sangre del Iluminado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\nNecesitas ser de nivel 60\n[q2]Uso: Aplica la sangre del Iluminado para consagrar tu arma."},
[232324] = {name = "[q3]Silbato de aves", additional_info = "Se liga al recogerlo\n[q2]Uso: Invoca a Pepe para que viaje sobre tu cabeza y te acompañe en tus aventuras."},
[232343] = {name = "QAEnchant Shield - Law of Nature", additional_info = "[q2]Uso: Permanently enchant a shield to give +2% chance to block."},
[232344] = {name = "[q4]Vick's VIP Pass", additional_info = "Único\n[q2]Uso: Attune yourself to Blackwing Lair! (30 Seg Reutilización)\n[q]\"For close personal friends of Lord Victor Nefarius only!\""},
[232357] = {name = "[q4]Vengador dracónico", additional_info = "Se liga al recogerlo\n{Dos manos} {Hacha}\n{201 - 303 p. de daño} {Velocidad 3.50}\n(72.00 p. de daño por segundo)\n+23 fuerza\n+28 agilidad\n+18 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 2% tu probabilidad de golpear con todos los hechizos y ataques."},
[232358] = {name = "[q4]Relicario vacío", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\nNecesitas ser de nivel 60"},
[232373] = {name = "[q4]Ojo de Sulfuras refinado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Druida\n[q2]Uso: Te sintoniza con tu llama interior, lo que reemplaza tu forma felina con un aspecto más ardiente."},
[232389] = {name = "[q4]Tratado sobre abundancia", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nNecesitas ser de nivel 60\n[q2]Equipar: Tu hechizo Golpe de cruzado restaura un 10 más de tu maná máximo."},
[232390] = {name = "[q4]Ídolo de enfoque celestial", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 10% el daño infligido con Lluvia de estrellas, pero reduce su radio un 50%."},
[232391] = {name = "[q4]Ídolo de enfoque felino", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 60\n[q2]Equipar: Tu habilidad Mordedura feroz ya no convierte la energía adicional en daño y devuelve 30 p. de energía al esquivar, fallar o parar."},
[232392] = {name = "[q4]Tótem de trueno implacable", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 60\n[q2]Equipar: Mientras tienes un escudo equipado, tus ataques cuerpo a cuerpo con Arma Muerdepiedras activan tu runa Arma vorágine con un 100 + (5 * ComboPoints)% más de frecuencia."},
[232409] = {name = "[q4]Tótem de los elementos", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 60\n[q2]Equipar: Tu talento Enfoque elemental ahora tiene un máximo de 2 cargas, y se establece en 2 cargas cuando se activa."},
[232414] = {name = "[q4]Sable dracodente", additional_info = "Objeto de misión\nÚnico\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Uso: Extrae una escama del cuero de Nefarian. Solo se puede usar cuando Nefarian ha sido debilitado significativamente en combate. (10 Seg Reutilización)"},
[232416] = {name = "[q4]Tótem de flujo astral", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta el poder de ataque de los ataques con arma Viento furioso 68 p."},
[232419] = {name = "[q4]Tótem de corrientes conductoras", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tótem}\nNecesitas ser de nivel 60\n[q2]Equipar: Mientras Arma Estigma de Escarcha está activa en tu arma de mano derecha, las activaciones de tu Escudo de agua reducen un 20% el tiempo de lanzamiento de tu siguiente Cadena de relámpagos en 15 s, y aumenta un 20% su daño. Se acumula hasta 5 veces."},
[232420] = {name = "[q4]Tratado sobre cólera", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nNecesitas ser de nivel 60\n[q2]Equipar: Infligir daño con tu Choque sagrado reduce el tiempo de lanzamiento y el costo de maná de tu siguiente Cólera sagrada lanzada en menos de 15 s un 20% y aumenta su daño un 20%. Este efecto se acumula hasta 5 veces."},
[232421] = {name = "[q4]Tratado sobre revancha", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Tratado}\nNecesitas ser de nivel 60\n[q2]Equipar: Tu Escudo de vengador golpea a 2 objetivos menos, pero golpeará a su objetivo 2 veces."},
[232423] = {name = "[q4]Ídolo de nutrición", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 77 p. la sanación de Nutrir."},
[232424] = {name = "[q4]Ídolo de crueldad", additional_info = "Se liga al recogerlo\nÚnico\n{Reliquia} {Ídolo}\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta el daño inicial y el periódico causado por Lacerar 7 p. con cada aplicación."},
[232433] = {name = "Venda de paño rúnico denso", additional_info = "Necesitas ser de nivel 50\nRequiere Primeros auxilios (300)\n[q2]Uso: Sana 3400 p. de daño durante 8 s."},
[232434] = {name = "Manual: Venda de paño rúnico denso", additional_info = "Requiere Primeros auxilios (300)\n[q2]Uso: Te enseña a hacer una Venda de paño rúnico denso.\nVenda de paño rúnico denso\nNecesitas ser de nivel 50\nRequiere Primeros auxilios (300)\n[q2]Uso: Sana 3400 p. de daño durante 8 s.\nRequiere Venda de paño rúnico gruesa (2)"},
[232436] = {name = "Sopa de pinza oscura", additional_info = "Necesitas ser de nivel 45\n[q2]Uso: Restaura 2148 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante 10 segundos, también aumentará tu daño con hechizos 12 p. durante 10 min."},
[232437] = {name = "Receta: Sopa de pinza oscura", additional_info = "Requiere Cocina (300)\n[q2]Uso: Te enseña a cocinar sopa de pinza oscura.\nSopa de pinza oscura\nNecesitas ser de nivel 45\n[q2]Uso: Restaura 2148 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante 10 segundos, también aumentará tu daño con hechizos 12 p. durante 10 min.\nRequiere Langosta pinza oscura , Agua bendita potable de Stratholme"},
[232438] = {name = "Branquirrojo ahumado", additional_info = "Necesitas ser de nivel 35\n[q2]Uso: Restaura 1392 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante 10 segundos, también aumentará 22 p. tu sanación infligida durante 10 min."},
[232443] = {name = "Receta: Branquirrojo ahumado", additional_info = "Requiere Cocina (300)\n[q2]Uso: Te enseña a cocinar Branquirrojo ahumado.\nBranquirrojo ahumado\nNecesitas ser de nivel 35\n[q2]Uso: Restaura 1392 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante 10 segundos, también aumentará 22 p. tu sanación infligida durante 10 min.\nRequiere Branquirrojo crudo"},
[232454] = {name = "[q7]Emblema de los dioses salvajes", additional_info = "Se liga a la cuenta\n[q]\"Prueba de haber asistido a la emisaria Diente Oscuro. Puedes canjearlo con el negociante de runas de las ciudades capitales.\""},
[232455] = {name = "[q7]Emblema de deshonor", additional_info = "Se liga a la cuenta\n[q]\"Prueba de haber enfrentado a Illari Plumaumbría. Puedes canjearlo con el negociante de runas de las ciudades capitales.\""},
[232456] = {name = "[q7]Emblema de El Ojo Violeta", additional_info = "Se liga a la cuenta\n[q]\"Prueba de victoria frente a los jinetes oscuros. Puedes canjearlo con el negociante de runas de las ciudades capitales.\""},
[232457] = {name = "[q7]Emblema de núcleo de mundo", additional_info = "Se liga a la cuenta\n[q]\"Prueba de armonización con conflujos de líneas ley. Puedes canjearlo con el negociante de runas de las ciudades capitales.\""},
[232458] = {name = "[q2]Runa de Santuario mejorado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu yelmo con la runa Santuario mejorado:\n\n\nAumenta un 100% el daño que previene tu Bendición de salvaguardia, y aumenta el daño que inflige tu Bendición de salvaguardia un monto equivalente al 20% de tu valor de bloqueo con escudo.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[232459] = {name = "[q2]Runa de Explosión de humo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Graba tu yelmo con la runa Explosión de humo:\n\n\nTu habilidad Conflagrar también otorga un 30% de celeridad de lanzamiento de hechizos durante 15 s y ya no consume Inmolar.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[232460] = {name = "[q2]Runa de Desplazamiento", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus brazales con la runa Desplazamiento:\n\n\nTe teletransporta de regreso al último lugar desde donde usaste la Traslación y restablece su tiempo de reutilización. Solo puede usarse durante 10 s después de usar Traslación.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[232461] = {name = "[q2]Runa de Desesperación", additional_info = "Se liga al recogerlo\nÚnico\nClases: Sacerdote\n[q2]Graba tus brazales con la runa Desesperación:\n\n\nEl daño periódico de tus hechizos ahora puede ser golpe crítico, y todos tus golpes críticos de hechizos dañinos infligen un 200% de daño.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[232462] = {name = "[q2]Runa de Poder purificador", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus brazales con la runa Poder purificador:\n\n\nReduce un 50% el tiempo de reutilización de Exorcismo y Cólera sagrada. Cólera sagrada ahora se puede lanzar a cualquier objetivo y aturdirá a objetivos no-muertos y demoníacos durante 2 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[232549] = {name = "[q2]Informe de tareas logísticas VI", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60"},
[232550] = {name = "[q4]Ashkandi, Espada magna de la Hermandad", additional_info = "Llama de las sombras\nSe liga al recogerlo\n{Dos manos} {Espada}\n{235 - 354 p. de daño} {Velocidad 3.60}\n(81.81 p. de daño por segundo)\n+20 fuerza\n+23 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 86 p. el poder de ataque.\n[q]\"Las iniciales A.L. están grabadas en la empuñadura.\""},
[232551] = {name = "[q4]Gran maza dracónica", additional_info = "Llama de las sombras\nSe liga al recogerlo\n{Dos manos} {Maza}\n{117 - 176 p. de daño} {Velocidad 2.00}\n(73.25 p. de daño por segundo)\n+33 fuerza\n+21 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 2% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: +260 p. de poder de ataque solo en las formas felina, de oso y de oso temible."},
[232552] = {name = "[q4]Lok'amir il Romathis", additional_info = "Llama de las sombras\nSe liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Maza}\n{47 - 127 p. de daño} {Velocidad 2.10}\n(41.43 p. de daño por segundo)\n+10 aguante\n+18 intelecto\n+8 espíritu\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 86 p. el daño y la sanación de los efectos y hechizos mágicos.\n[q]\"La mano de Nefarius\""},
[232555] = {name = "[q4]Crul'shorukh, Filo del Caos", additional_info = "Llama de las sombras\nSe liga al recogerlo\nÚnico-Equipado: (Desconocido #668) (1)\n{Una mano} {Hacha}\n{105 - 197 p. de daño} {Velocidad 2.40}\n(62.92 p. de daño por segundo)\n+13 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 38 p. el poder de ataque."},
