[232557] = {name = "[q4]Garra de Chromaggus", additional_info = "Llama de las sombras\nSe liga al recogerlo\nÚnico-Equipado\n{Mano derecha} {Daga}\n{36 - 89 p. de daño} {Velocidad 1.50}\n(41.67 p. de daño por segundo)\n+7 aguante\n+17 intelecto\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 68 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Tus lanzamientos de hechizos ofensivos aumentan 50 p. el daño con hechizos de una escuela de magia aleatoria durante 10 s. (9.5s de reutilización)"},
[232558] = {name = "[q4]Espada templada cromáticamente", additional_info = "Llama de las sombras\nSe liga al recogerlo\nÚnico-Equipado: (Desconocido #665) (1)\n{Una mano} {Espada}\n{110 - 205 p. de daño} {Velocidad 2.70}\n(58.33 p. de daño por segundo)\n+14 fuerza\n+15 agilidad\n+7 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60"},
