[232577] = {name = "[q4]Filo de la Fatalidad", additional_info = "Llama de las sombras\nSe liga al recogerlo\nÚnico-Equipado: (Desconocido #667) (1)\n{Una mano} {Hacha}\n{100 - 187 p. de daño} {Velocidad 2.60}\n(55.19 p. de daño por segundo)\n+10 fuerza\n+17 agilidad\n+7 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60"},
[232606] = {name = "[q4]Ashjre'thul, Ballesta de paliza", additional_info = "Llama de las sombras\nSe liga al recogerlo\n{A distancia} {Ballesta}\n{124 - 186 p. de daño} {Velocidad 3.40}\n(45.59 p. de daño por segundo)\n+7 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 36 p. el poder de ataque a distancia."},
[232607] = {name = "[q4]Apuntacorazones", additional_info = "Llama de las sombras\nSe liga al recogerlo\n{A distancia} {Arco}\n{98 - 183 p. de daño} {Velocidad 3.20}\n(43.91 p. de daño por segundo)\n+6 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 60\n[q2]Equipar: 2% de probabilidad de obtener 1 ataque adicional al golpear a distancia. (Probabilidad de que accione: 2%, 1s de reutilización)\n[q2]Equipar: Aumenta 18 p. el poder de ataque."},
[232608] = {name = "[q4]Culebrina aliento de dragón", additional_info = "Llama de las sombras\nSe liga al recogerlo\n{A distancia} {Arma de fuego}\n{92 - 172 p. de daño} {Velocidad 3.00}\n(44.00 p. de daño por segundo)\n+14 agilidad\n+7 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 60"},
[232610] = {name = "Fórmula: lustre trol magnífico", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (300)\nRequiereTribu Zandalar\n: Honorable\n[q2]Uso: Te enseña a crear lustre trol magnífico.\nLustre trol magnífico\nNecesitas ser de nivel 45\n[q2]Uso: Cuando se aplica al escudo objetivo, aumenta hasta 36 p. el daño y la sanación, y aumenta un 1% la probabilidad de golpe crítico con hechizos. Dura 30 minutos.\n5 cargas\nRequiere Frasco de mojo (3), Frasco de gran mojo (3), Fragmento luminoso grande (2), Vial imbuido"},
[232611] = {name = "Lustre trol magnífico", additional_info = "Necesitas ser de nivel 45\n[q2]Uso: Cuando se aplica al escudo objetivo, aumenta hasta 36 p. el daño y la sanación, y aumenta un 1% la probabilidad de golpe crítico con hechizos. Dura 30 minutos.\n5 cargas"},
[232652] = {name = "[q4]Zila Amanemodas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Brujo\n[q2]Uso: Te armoniza con la oscuridad que habita en ti, lo que te otorga un mayor control sobre tu demonio interior."},
[233197] = {name = "[q3]Manual de entrenamiento Argenta", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Usa el manual para llamar a tu escudero Argenta y darle una lección de entrenamiento en combate contra silítidos. Los silítidos derrotados en presencia del escudero aumentan tu reputación con el Alba Argenta. (5 Min Reutilización)\n3 cargas"},
[233198] = {name = "[q3]Cuerno del Alba", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Reúne a los miembros de tu grupo o banda cercanos, aumenta un 10% su probabilidad de golpe crítico con hechizos, un 5% su probabilidad de golpe crítico con ataques cuerpo a cuerpo o a distancia, y 140 p. su poder de ataque. Dura 2 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios. (30 Seg Reutilización)"},
[233200] = {name = "[q3]Semilla cantaflor", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Invoca una melodía que aumenta un 5% la probabilidad de golpe crítico cuerpo a cuerpo, a distancia o con hechizos, y 15 p. los atributos de todos los miembros de tu grupo o banda durante 1 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios. (30 Seg Reutilización)"},
[233201] = {name = "[q3]Globo fulgurante", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta 200 p. el poder de ataque, un 15% el aguante y un 3% la probabilidad de golpe crítico con hechizos de todos los miembros de tu grupo o banda durante 2 h. Solo se puede activar con efectos de mundo similares. No lo afectan los cronobeneficios. (30 Seg Reutilización)"},
[233206] = {name = "[q3]Yunque de sobrestante", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta 300 p. los puntos de salud. 15% de celeridad a los ataques cuerpo a cuerpo. 10 p. de regeneración de maná cada 5 s. Dura 1 h. (30 Seg Reutilización)"},
[233208] = {name = "[q3]Bola 8 mágica \"defectuosa\"", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta un 10% el daño infligido de todos los miembros de tu grupo o banda durante 2 h. (30 Seg Reutilización)\n[q]\"Por mucho que lo agites, este juguete siempre predice la misma fortuna oscura: Muerte dolorosa.\""},
[233209] = {name = "[q3]Caldero de aguardiente", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Invoca un caldero de aguardiente durante 10 min que todos los miembros de tu grupo o banda pueden usar para aumentar 35 p. el poder de ataque cuerpo a cuerpo y el tamaño durante 1 h. (30 Seg Reutilización)"},
[233211] = {name = "[q3]Caracola espiritual", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Aumenta un 10% la velocidad de movimiento y un 15% las estadísticas de todos los miembros de tu grupo o banda durante 2 h. (30 Seg Reutilización)"},
[233213] = {name = "[q3]Magnetita antigua", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Debilita a los miembros elementales del Consejo Abisal de Silithus, lo que reduce todo el daño que infligen un 20%. Dura 2 min. (1 Min Reutilización)\n10 cargas"},
[233215] = {name = "[q3]Trampa de arena explosiva", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Colocas una trampa en un lugar cercano que explota cuando se acerca un silítido de Colmen'Ashi, Colmen'Regal o Colmen'Zora, lo que hace que el silítido reciba un 6% de su salud como daño cada 3 s durante 15 s. (1 Min Reutilización)\n10 cargas"},
[233216] = {name = "[q3]Rayo congelamático", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Congela a un silítido en las colmenas Colmen'Ashi, Colmen'Regal o Colmen'Zora durante 1 min. Cualquier daño cancela el efecto. (1 Min Reutilización)\n10 cargas"},
[233217] = {name = "[q3]Incienso de tunelador", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Inhalar este incienso hace que te desvanezcas entre las sombras, lo que te permite escabullirte mientras estés en Colmen'Ashi, Colmen'Regal o Colmen'Zora, pero reduce un 50% tu velocidad. Dura 1 min. (1 Min Reutilización)\n10 cargas"},
[233226] = {name = "[q3]Antigua cuerda zandalariana", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Lanzas la cuerda antigua para sujetar a un silítido de Colmen'Ashi, Colmen'Regal o Colmen'Zora y atraerlo hacia ti. No puede utilizarse contra enemigos de nivel superior a ( 60 + 1) o que estén marcados como jefes. (1 Min Reutilización)\n10 cargas\n[q]\"La utilizaban en edades perdidas los trols del Imperio de Zul para luchar contra los aqir.\""},
[233250] = {name = "[q3]Rama antigua", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 50\n[q2]Uso: Usa la rama para invocar a un Anciano de la Guerra para que te ayude a combatir a los silítidos. (15 Min Reutilización)\n3 cargas"},
[233351] = {name = "[q4]Cristal resonador qiraji verde claro", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[233352] = {name = "[q4]Cristal resonador qiraji azul oscuro", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[233353] = {name = "[q4]Cristal resonador qiraji celeste", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[233356] = {name = "[q4]Cristal resonador qiraji naranja", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[233357] = {name = "[q4]Cristal resonador qiraji crepuscular", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[233358] = {name = "[q3]Tanque silítido domado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Emite un sonido de alta frecuencia que obliga a un tanque silítido a salir del lugar en el que habita, situado bajo el Templo de Ahn'Qiraj. El tanque silítido obedece a quien lo ha invocado y se puede utilizar como montura en el Templo de Ahn'Qiraj. Toda acción hostil contra su jinete obliga al tanque a volver bajo tierra. (3 Seg Reutilización)"},
