[233826] = {name = "[q4]Capucha vampírica", additional_info = "Se liga al equiparlo\n{Cabeza} {Tela}\n[q2]178 armadura\n+40 aguante\n+10 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, tiene un 20% de probabilidad de robarle 50 p. de vida al objetivo. (Probabilidad de que accione: 20%)\n[q2]Equipar: Aumenta 9 p. el índice de defensa."},
[233833] = {name = "[q4]Chal vampírico", additional_info = "Se liga al equiparlo\n{Hombro} {Tela}\n[q2]150 armadura\n+29 aguante\n+8 intelecto\nDurabilidad 60 / 60\nNecesitas ser de nivel 60\n[q2]Equipar: Cuando recibe un golpe en combate, tiene un 20% de probabilidad de robarle 40 p. de vida al objetivo. (Probabilidad de que accione: 20%)\n[q2]Equipar: Aumenta 7 p. el índice de defensa."},
