[234444] = {name = "Veneno oculto II", additional_info = "Clases: Pícaro\nNecesitas ser de nivel 60\n[q2]Uso: Cubre de veneno un arma durante 30 minutos. Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligirle 136 p. de daño de Naturaleza durante 12 s, y de hacer que reciba un 4% más de daño Arcano, de Fuego, de Escarcha, de Naturaleza y de las Sombras. Se acumula hasta 5 veces en un solo objetivo.\n\n Veneno oculto cuenta como Veneno mortal y se beneficia de todos los talentos y efectos que se activan con Veneno mortal o lo modifican. (Probabilidad de que accione: 30%)"},
[234445] = {name = "[q2]Patrón: madeja de seda qiraji", additional_info = "Se liga al recogerlo\nRequiere Sastrería (300)\nRequiereCírculo Cenarion\n: Amistoso\n[q2]Uso: Te enseña a confeccionar una madeja de seda qiraji.\nMadeja de seda qiraji\nRequiere Seda qiraji (5)"},
[234447] = {name = "[q3]Vara de transformación de Burbujas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te transforma en fúrbolg durante 5 min. (15 Min Reutilización)"},
[234458] = {name = "Diseño: escudo dentado de obsidiana", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereCírculo Cenarion\n: Reverenciado\n[q2]Uso: Te enseña a hacer un escudo dentado de obsidiana.\n[q4]Escudo dentado de obsidiana\nSe liga al equiparlo\n{Mano izquierda} {Escudo}\n2822 armadura\n52 bloqueo\n+12 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 14 p.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 20% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 20%, 20s de reutilización)\nRequiere Fragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Barra de torio encantado (8), Esencia de tierra (4)"},
[234459] = {name = "[q4]Escudo dentado de obsidiana", additional_info = "Se liga al equiparlo\n{Mano izquierda} {Escudo}\n2822 armadura\n52 bloqueo\n+12 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 14 p.\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 20% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 20%, 20s de reutilización)"},
[234460] = {name = "[q4]Guerrera de malla de obsidiana", additional_info = "Se liga al equiparlo\n{Pecho} {Malla}\n476 armadura\n+24 aguante\nDurabilidad 140 / 140\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 76 p. el poder de ataque.\n[q2]Equipar: Se reduce 40 p. el daño con hechizos recibido."},
[234461] = {name = "Diseño: guerrera de malla de obsidiana", additional_info = "Se liga al recogerlo\nRequiere Herrería (300)\nRequiereCírculo Cenarion\n: Exaltado\n[q2]Uso: Te enseña a hacer una guerrera de malla de obsidiana.\n[q4]Guerrera de malla de obsidiana\nSe liga al equiparlo\n{Pecho} {Malla}\n476 armadura\n+24 aguante\nDurabilidad 140 / 140\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 76 p. el poder de ataque.\n[q2]Equipar: Se reduce 40 p. el daño con hechizos recibido.\nRequiere Fragmento de obsidiana grande (15), Fragmento de obsidiana pequeño (36), Cuero encantado (12), Piedra guardián (10), Diamante de Azeroth (4)"},
[234462] = {name = "[q4]Golpe de tierra", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n[q2]Uso: Aumenta 328 p. tu poder de ataque cuerpo a cuerpo y a distancia. El efecto dura 20 s. (2 Min Reutilización)"},
[234463] = {name = "[q4]Cólera de Cenarius", additional_info = "Se liga al recogerlo\nÚnico\nDedo\n[q2]Equipar: Te otorga una probabilidad de que, cuando tus hechizos dañinos impacten, el daño de tus hechizos y efectos aumente hasta 193 p. durante 10 s. (Probabilidad de que accione: 5%)"},
[234464] = {name = "[q3]Vara de burbujas de Burbujas", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Te transformas en un naga durante 5 min. (15 Min Reutilización)"},
[234465] = {name = "[q4]Riendas del tigre espectral presto", additional_info = "Se liga al recogerlo\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un tigre espectral presto. Es una montura muy veloz."},
