[235282] = {name = "[q4]Antena de tonificación", additional_info = "Tocado por el Vacío\nSe liga al recogerlo\n{A distancia} {Varita}\n{107 - 199 p. de daño de Naturaleza} {Velocidad 1.60}\n(95.63 p. de daño por segundo)\n+4 intelecto\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 31 p. la sanación realizada y hasta 11 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Restaura 2 p. de maná cada 5 s."},
[235473] = {name = "[q4]Barricada de Gran mariscal", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n3000 armadura\n56 bloqueo\n+26 aguante\n+10 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 44 p. la sanación realizada y hasta 24 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Reduce un 5% todo el daño recibido de los jugadores y sus mascotas. Este efecto no se puede combinar de varias fuentes."},
[235474] = {name = "[q4]Barricada de Gran Señor de la Guerra", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n3000 armadura\n56 bloqueo\n+26 aguante\n+10 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 44 p. la sanación realizada y hasta 24 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Reduce un 5% todo el daño recibido de los jugadores y sus mascotas. Este efecto no se puede combinar de varias fuentes."},
[235476] = {name = "[q4]Rebanadora de Gran Señor de la Guerra", additional_info = "Se liga al recogerlo\n{Una mano} {Hacha}\n{89 - 134 p. de daño} {Velocidad 1.80}\n(61.94 p. de daño por segundo)\n+13 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 28 p. el poder de ataque.\n[q2]Equipar: Reduce un 5% todo el daño recibido de los jugadores y sus mascotas. Este efecto no se puede combinar de varias fuentes."},
