[235497] = {name = "Jarabe de las arenas", additional_info = "Se liga al recogerlo\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Aumenta todo el daño infligido contra objetivos en Silithus, Ahn'Qiraj, las Tierras de la Peste del Este y Naxxramas un 3%, y aumenta el daño crítico infligido contra objetivos en estas áreas un 3% más. (3 Seg Reutilización)"},
[235511] = {name = "[q4]Cristal resonador qiraji amarillo impecable", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[235512] = {name = "[q4]Cristal resonador qiraji verde impecable", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[235513] = {name = "[q4]Cristal resonador qiraji azul impecable", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[235514] = {name = "[q4]Cristal resonador qiraji rojo impecable", additional_info = "Se liga al recogerlo\nÚnico\nMontura\nNecesitas ser de nivel 60\n[q2]Uso: Invoca y retira a un Tanque de batalla qiraji que se puede montar. Es una montura muy veloz. (3 Seg Reutilización)"},
[235517] = {name = "Antorcha", additional_info = "Necesitas ser de nivel 60"},
[235526] = {name = "[q3]Fórmula: encantar brazales: poder de hechizos", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (300)\n[q2]Encanta de forma permanente un arma para que añada hasta 12 p. de daño a los hechizos.\n[q]\"Te enseña a encantar de forma permanente unos brazales para que añadan hasta 12 p. de daño a los hechizos.\""},
[235528] = {name = "[q3]Fórmula: encantar brazales: agilidad", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (300)\n[q2]Encanta de forma permanente unos brazales para que aumenten tu agilidad en 9 p.\n[q]\"Te enseña a encantar de forma permanente unos brazales para que aumenten tu agilidad en 9 p.\""},
[235529] = {name = "[q3]Mira de obsidiana", additional_info = "Necesitas ser de nivel 60\n[q2]Uso: Añade una mira permanente a un arco o arma de fuego que aumenta el daño que produce en 10 p."},
[235530] = {name = "[q3]Esquema: mira de obsidiana", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (300)\n[q]\"Te enseña a hacer una mira de obsidiana.\""},
[235597] = {name = "[q2]Notas de hechizo: Congelación profunda", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu yelmo con la runa Congelación profunda:\n\n\nAturde al objetivo durante 5 s. Solo se puede usar con objetivos congelados. Inflige de [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] a [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ] p. de daño a los objetivos inmunes de forma permanente al aturdimiento.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235598] = {name = "[q2]Notas de hechizo: Venas heladas", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tus pantalones con la runa Venas heladas:\n\n\nAcelera tu lanzamiento de hechizos, lo que aumenta la velocidad con la que lanzas hechizos un 20% y reduce un 100% el retraso sufrido por los ataques dañinos mientras lanzas hechizos. Dura 20 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235599] = {name = "[q2]Notas de hechizo: Anomalía temporal", additional_info = "Se liga al recogerlo\nÚnico\nClases: Mago\n[q2]Graba tu yelmo con la runa Anomalía temporal:\n\n\nLanza un orbe de energía temporal que avanza lentamente y, cada 2 s, otorga a todos los miembros del grupo cercanos un escudo que absorbe [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100] p. de daño durante 15 s. El valor de este escudo aumenta si los miembros del grupo se mantienen cerca del orbe.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235600] = {name = "[q2]Runa de Tormenta divina", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu pechera con la runa Tormenta divina:\n\n\nUn ataque instantáneo con arma que inflige un 110% de daño con arma a un máximo de 4 enemigos que se encuentren en un radio de 8 m. La Tormenta divina sana a hasta 3 miembros del grupo o banda con un total del 25% del daño infligido.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235601] = {name = "[q2]Runa de Fanatismo", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu yelmo con la runa Fanatismo:\n\n\nAumenta un 18% tu probabilidad de golpe crítico con hechizos Sagrados. Además, tus hechizos de sanación crítica sanan al objetivo un 60% de la cantidad sanada durante 12 s.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235602] = {name = "[q2]Runa de Martillo del honrado", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tus brazales con la runa Martillo del honrado:\n\n\nDa un martillazo al objetivo actual y a un máximo de 3 objetivos cercanos más, inflige 4 veces el daño por segundo de tu mano derecha como daño sagrado.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235603] = {name = "[q2]Runa de Venganza recta", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu capa con la runa Venganza recta:\n\n\nCuando tu Sentencia, Golpe de cruzado o Tormenta divina asesta un golpe crítico, tu objetivo recibirá un 30% más de daño durante hasta cancelación.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235604] = {name = "[q2]Runa de Escudo de rectitud", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu capa con la runa Escudo de rectitud:\n\n\nEmbiste al objetivo con tu escudo e inflige daño Sagrado basado en tu valor de bloqueo más [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100] p. extra.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235605] = {name = "[q2]Runa de Choque y terror", additional_info = "Se liga al recogerlo\nÚnico\nClases: Paladín\n[q2]Graba tu capa con la runa Choque y terror:\n\n\nObtienes un 200% de tu intelecto como daño con hechizos durante 1 min cuando lanzas Choque sagrado.\n[q]\"Te enseña una nueva habilidad de grabado.\""},
[235785] = {name = "\"Llave\" de jaula de Paso de la Muerte", additional_info = "Objeto de misión\nÚnico\n[q]\"Tus astutos poderes de observación te muestran que esta \"llave\" no es más que una roca afilada. Sospechas que con solo golpear la cerradura será suficiente para abrir la jaula.\""},
[235786] = {name = "[q2]Curiosidad de Karazhan", additional_info = "Se liga al recogerlo\nÚnico (99)"},
[235787] = {name = "Rama de maderaférrea antigua", additional_info = "Objeto de misión\nÚnico"},
[235788] = {name = "Fuego fatuo entusiasta", additional_info = "Objeto de misión\nÚnico\n[q]\"No hay forma de que esta cosa se quede quieta...\""},
[235789] = {name = "Llama de la vida", additional_info = "Objeto de misión\nÚnico"},
[235790] = {name = "[q2]Marca de fuego encantada", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Levanta la antorcha encantada e intenta disipar la oscuridad cerca de las Criptas de Karazhan. (15 Seg Reutilización)"},
[235825] = {name = "Jarabe de las arenas", additional_info = "Se liga al recogerlo\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Aumenta todo el daño infligido contra objetivos en Silithus, Ahn'Qiraj, las Tierras de la Peste del Este y Naxxramas un 2%, y aumenta el daño crítico infligido contra objetivos en estas áreas un 2% más. (3 Seg Reutilización)"},
[235852] = {name = "[q2]Cartera violeta", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\n[q]\"Esta cartera pequeña lleva la marca del Kirin Tor de Dalaran. Parece que contiene algunos objetos pequeños, pero curiosamente, notas que eres incapaz de abrirla para ver su contenido.\""},
[235867] = {name = "Trozo de papiro", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Parece que este trozo de papiro fue arrancado de un afiche o volante más grande. Parece que las únicas palabras que llegan a distinguirse refieren a un nombre... Archimago Tarsis Kir-Moldir\""},
[235868] = {name = "[q4]Baluarte de ira", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n3177 armadura\n61 bloqueo\n+14 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Inflige 100 p. de daño de las Sombras a los atacantes cuerpo a cuerpo. Genera el doble de amenaza que la cantidad de daño infligido.\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 3%.\n[q2]Equipar: Aumenta 10 p. el índice de defensa."},
[235869] = {name = "[q4]La capucha del maestro", additional_info = "Santificado\nSe liga al recogerlo\n{Cabeza} {Cuero}\n198 armadura\n+10 aguante\n+14 intelecto\n+10 espíritu\nDurabilidad 70 / 70\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 59 p. el daño y la sanación de los hechizos y efectos mágicos."},
[235870] = {name = "[q4]Yelmo de anillas ruidosas", additional_info = "Santificado\nSe liga al recogerlo\n{Cabeza} {Malla}\n430 armadura\n+15 agilidad\n+10 aguante\n+11 intelecto\n+9 resistencia a Escarcha\nDurabilidad 85 / 85\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 100 p. el poder de ataque."},
[235871] = {name = "[q4]Yelmo de la muerte ceñido", additional_info = "Santificado\nSe liga al recogerlo\n{Cabeza} {Placas}\n765 armadura\n+40 fuerza\n+25 agilidad\n+19 aguante\n+12 resistencia a Escarcha\nDurabilidad 100 / 100\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[235872] = {name = "[q4]Braciles de acechador", additional_info = "Santificado\nSe liga al recogerlo\nMuñeca Cuero\n107 armadura\n+28 agilidad\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 28 p. el poder de ataque."},
[235873] = {name = "[q4]Esposas de la cripta", additional_info = "Santificado\nSe liga al recogerlo\nMuñeca Placas\n412 armadura\n+12 intelecto\nDurabilidad 55 / 55\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 53 p. la sanación realizada y hasta 18 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q]\"Las esposas de ayer son la moda de hoy.\""},
[235874] = {name = "[q4]Manijas de cultista", additional_info = "Santificado\nSe liga al recogerlo\n{Manos} {Tela}\n81 armadura\n<Encantamiento aleatorio>\n+7 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta un 2% la velocidad de lanzamiento.\n[q2]Equipar: Aumenta hasta 37 p. el daño y la sanación de los hechizos y efectos mágicos."},
[235875] = {name = "[q4]Guantes de cavatumbas", additional_info = "Santificado\nSe liga al recogerlo\n{Manos} {Cuero}\n155 armadura\n<Encantamiento aleatorio>\n+32 agilidad\n+8 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 34 p. el poder de ataque."},
[235876] = {name = "[q4]Manoplas de pecador", additional_info = "Santificado\nSe liga al recogerlo\n{Manos} {Malla}\n338 armadura\n<Encantamiento aleatorio>\n+32 agilidad\n+8 aguante\nDurabilidad 50 / 50\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 34 p. el poder de ataque."},
[235877] = {name = "[q4]Guanteletes de fanático", additional_info = "Santificado\nSe liga al recogerlo\n{Manos} {Placas}\n602 armadura\n<Encantamiento aleatorio>\n+32 fuerza\n+17 agilidad\n+8 aguante\nDurabilidad 55 / 55\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[235878] = {name = "[q4]Cinturón maléfico", additional_info = "Santificado\nSe liga al recogerlo\n{Cintura} {Tela}\n72 armadura\n+10 aguante\n+13 espíritu\nDurabilidad 35 / 35\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 81 p. la sanación realizada y hasta 27 p. el daño que infligen todos los efectos y hechizos mágicos."},
[235879] = {name = "[q4]Anillas ágiles", additional_info = "Santificado\nSe liga al recogerlo\n{Piernas} {Malla}\n463 armadura\n+8 fuerza\n+35 aguante\n+9 intelecto\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: Restaura 138 p. de salud cada 5 s.\n[q2]Equipar: Aumenta hasta 27 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Aumenta 17 p. el índice de defensa."},
[235880] = {name = "[q4]Suelas indigentes", additional_info = "Santificado\nSe liga al recogerlo\n{Pies} {Tela}\n87 armadura\n+10 aguante\n+8 intelecto\n+14 resistencia a Escarcha\nDurabilidad 50 / 50\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 47 p. el daño y la sanación de los hechizos y efectos mágicos."},
[235881] = {name = "[q4]Botines aterradores", additional_info = "Santificado\nSe liga al recogerlo\n{Pies} {Cuero}\n168 armadura\n+9 intelecto\n+10 espíritu\nDurabilidad 60 / 60\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 88 p. la sanación realizada y hasta 30 p. el daño que infligen todos los efectos y hechizos mágicos."},
[235882] = {name = "[q4]Pasos traqueteantes", additional_info = "Santificado\nSe liga al recogerlo\n{Pies} {Malla}\n364 armadura\n+30 agilidad\n+8 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 40 p. el poder de ataque."},
[235883] = {name = "[q4]Escarpín de explorapozos", additional_info = "Santificado\nSe liga al recogerlo\n{Pies} {Placas}\n648 armadura\n+40 fuerza\n+3 aguante\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques."},
[235884] = {name = "[q4]Sello espectral", additional_info = "Santificado\nSe liga al recogerlo\nÚnico-Equipado\nDedo\n+7 aguante\n+8 intelecto\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 43 p. el daño que infligen los hechizos y efectos de las Sombras."},
[235885] = {name = "[q4]Anillo espantoso", additional_info = "Santificado\nSe liga al recogerlo\nÚnico-Equipado\nDedo\n+6 aguante\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 2% tu velocidad de ataque.\n[q2]Equipar: Aumenta 48 p. el poder de ataque."},
[235886] = {name = "[q4]Broche de Kaigy", additional_info = "Santificado\nSe liga al recogerlo\nCuello\n+26 agilidad\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 26 p. el poder de ataque.\n[q]\"Algunas llamas no necesitan arder con el doble de intensidad para durar la mitad.\""},
[235887] = {name = "[q4]Gargantilla de Barian", additional_info = "Santificado\nSe liga al recogerlo\nCuello\n+10 intelecto\n+8 espíritu\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 62 p. la sanación realizada y hasta 21 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q]\"La muerte es una oportunidad para aprender, no una falla del carácter personal.\""},
[235888] = {name = "[q4]Garrote aporreador", additional_info = "Se liga al recogerlo\n{Una mano} {Maza}\n{171 - 209 p. de daño} {Velocidad 2.80}\n(67.86 p. de daño por segundo)\n+10 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Mazas aumentadas +3 p.\n[q2]Equipar: Aumenta 10 p. el índice de defensa.\n[q2]Equipar: Reduce un 1% la probabilidad de que esquiven o paren tus ataques."},
[235889] = {name = "[q4]Cayado de sirviente", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{166 - 228 p. de daño} {Velocidad 3.60}\n(54.72 p. de daño por segundo)\n+25 agilidad\n+40 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: +423 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Equipar: Aumenta 13 p. el índice de defensa."},
[235890] = {name = "[q4]Aguja de tejesombras", additional_info = "Se liga al recogerlo\n{Mano derecha} {Daga}\n{36 - 104 p. de daño} {Velocidad 1.70}\n(41.18 p. de daño por segundo)\n+11 aguante\n+17 intelecto\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 96 p. el daño y la sanación de los hechizos y efectos mágicos."},
[235891] = {name = "[q4]Vieja confiable", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{290 - 355 p. de daño} {Velocidad 3.80}\n(84.87 p. de daño por segundo)\n+50 fuerza\n+12 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Uso: Destroza el cadáver de un amigo o enemigo caído e inflige 588 p. de daño a los enemigos cercanos. (2 Min Reutilización)\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q]\"Incluye una garantía para que nunca haya que excavar una tumba dos veces.\""},
[235892] = {name = "[q4]Columna de jinete oscuro", additional_info = "Se liga al recogerlo\n{A distancia} {Arco}\n{157 - 192 p. de daño} {Velocidad 3.30}\n(52.88 p. de daño por segundo)\n+5 agilidad\nDurabilidad 90 / 90\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta 26 p. el poder de ataque.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques."},
[235893] = {name = "[q4]Grimorio vinculasombras", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n+11 intelecto\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 43 p. el daño que infligen los hechizos y efectos de las Sombras.\n\n[q]Decreto de Kharon (0/2)\n[q0]Grimorio vinculasombras\nÓbito del orador del sino\n[q0](2) Conjunto : El daño infligido por Oscuridad espeluznante aumenta un 100%."},
[235894] = {name = "[q0]Óbito del orador del sino", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{153 - 188 p. de daño de Sombras} {Velocidad 1.50}\n(113.67 p. de daño por segundo)\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Los efectos de las sombras periódicos tienen una probabilidad de aplicar Oscuridad espeluznante hasta 5 veces. Los hechizos que infligen daño de las Sombras directamente detonan este efecto, lo que inflige 100 p. de daño por acumulación. (1.5s de reutilización)\n\n[q]Decreto de Kharon (0/2)\n[q0]Grimorio vinculasombras\nÓbito del orador del sino\n[q0](2) Conjunto : El daño infligido por Oscuridad espeluznante aumenta un 100%."},
