[236397] = {name = "[q4]Restos de valor", additional_info = "Se liga a la cuenta"},
[236398] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{130 - 243 p. de daño} {Velocidad 2.90}\n(64.31 p. de daño por segundo)\n+20 aguante\n+14 intelecto\n+30 espíritu\nDurabilidad 145 / 145\nClases: Brujo\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 3% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 150 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Aumenta un máximo de 33 p. el daño y la sanación de los efectos y hechizos mágicos de los miembros del grupo que están en un radio de 30 m. Las distintas fuentes de este efecto específico no se acumulan.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
[236399] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{130 - 243 p. de daño} {Velocidad 2.90}\n(64.31 p. de daño por segundo)\n+20 aguante\n+22 intelecto\n+24 espíritu\nDurabilidad 145 / 145\nClases: Sacerdote\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 3% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta un máximo de 62 p. la sanación realizada y un máximo de 19 p. el daño infligido de los efectos y hechizos mágicos de todos los miembros del grupo que están en un radio de 30. Las distintas fuentes de este efecto específico no se acumulan.\n[q2]Equipar: Aumenta hasta 300 p. la sanación realizada y hasta 150 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
[236400] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{129 - 242 p. de daño} {Velocidad 2.90}\n(63.97 p. de daño por segundo)\n+21 aguante\n+24 intelecto\n+23 espíritu\nDurabilidad 145 / 145\nClases: Mago\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 4% la velocidad de lanzamiento.\n[q2]Equipar: Aumenta hasta 150 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Aumenta un 2% la velocidad de lanzamiento de todos los miembros del grupo que están en un radio de 30 m. Las distintas fuentes de este efecto específico no se acumulan.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
[236401] = {name = "[q5]Atiesh, gran báculo del Guardián", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{129 - 242 p. de daño} {Velocidad 2.90}\n(63.97 p. de daño por segundo)\n+21 aguante\n+25 intelecto\n+20 espíritu\nDurabilidad 145 / 145\nClases: Druida\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 3% tu probabilidad de asestar un golpe crítico con hechizos.\n[q2]Equipar: Aumenta un 2% la probabilidad de golpe crítico de todos los miembros del grupo que están en un radio de 30 m. Las distintas fuentes de este efecto específico no se acumulan.\n[q2]Equipar: Aumenta hasta 300 p. la sanación realizada y hasta 150 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: +592 p. de poder de ataque solo en las formas felina, de oso y de oso temible.\n[q2]Uso: Crea un portal que teletransporta a los miembros del grupo que lo utilicen hasta Karazhan. (1 Min Reutilización)"},
[236414] = {name = "[q2]Cajón de suministros de Minahonda dañado", additional_info = "Se liga al recogerlo\nÚnico (10)\n[q]\"Este cajón raído y dañado parece haberse caído literalmente de un zepelín.\"\n[q2]<Click derecho para abrir>"},
[236417] = {name = "[q3]Alma del táctico", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del táctico:\n\nDespués de cargar actitudes, el costo de ira de tu próxima habilidad ofensiva se reduce 10 p."},
[236418] = {name = "[q3]Alma del veterano de guerra", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del veterano de guerra:\n\nDurante 15 s después de cambiar de actitud, puedes usar habilidades que requieren la actitud anterior como si aún la tuvieras."},
[236419] = {name = "[q3]Alma del augur de batalla", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el augur de batalla:\n\nDurante los primeros 15 s después de activar una actitud, puedes obtener un beneficio adicional:\n\n Actitud de batalla/Actitud de gladiador: aumenta un 5% el daño infligido.\n\n Actitud rabiosa: aumenta un 5% la probabilidad de golpe crítico.\n\n Actitud defensiva: reduce un 5% el daño físico recibido."},
[236420] = {name = "[q3]Alma del buscasangre", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del buscasangre:\n\nLos golpes críticos de Abrumar restablecen la duración máxima de Desgarrar en tu objetivo."},
[236421] = {name = "[q3]Alma del titán", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del titán:\n\nTus habilidades Golpe heroico, Embate y Abrumar infligen un 10 + (5 * ComboPoints)% más de daño."},
[236422] = {name = "[q3]Alma del destructor", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del destructor:\n\nTus golpes de Embate restablecen el tiempo de reutilización de tus habilidades Golpe mortal, Sed de sangre y Embate con escudo."},
[236423] = {name = "[q3]Alma del lazomortal", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del lazomortal:\n\nReduce un 50% el tiempo de reutilización de tu Deseo de muerte."},
[236424] = {name = "[q3]Alma del sanguinista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del sanguinista:\n\nInfliges un 15% más de daño mientras un enemigo cercano esté afectado por tu Desgarrar y tus Heridas profundas."},
[236425] = {name = "[q3]Alma del bloqueador prístino", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del bloqueador prístino:\n\nAumenta 30 p. el valor de bloqueo de tu escudo."},
[236426] = {name = "[q3]Alma del salvaje", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del salvaje:\n\nObtienes 1 p. más de ira cada vez que recibes o infliges daño con ataques automáticos."},
[236427] = {name = "[q3]Alma de animosidad", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma de animosidad:\n\nAumenta toda la amenaza que generas en actitud defensiva un 10% más y aumenta todo el daño que infliges en actitud de gladiador un 4%."},
[236428] = {name = "[q3]Alma del deflector", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del deflector:\n\nObtienes 10 p. de ira cada vez que paras un ataque o que alguien para uno de los tuyos."},
[236429] = {name = "[q3]Alma de revancha", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma de revancha:\n\nRevancha también te otorga Aluvión, lo que aumenta tu velocidad de ataque un 30% durante los siguientes 3 golpes."},
[236430] = {name = "[q3]Alma del incesante", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del incesante:\n\nCuando tu objetivo para un ataque, tomas Represalia de forma inmediata e infliges un 200% de daño con arma al objetivo. Represalia no se puede esquivar, bloquear ni parar, pero solo puede ocurrir una vez cada 30 s por objetivo."},
[236431] = {name = "[q3]Alma del portatruenos", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del portatruenos:\n\nReduce un 100% el tiempo de reutilización de Atronar."},
[236432] = {name = "[q3]Alma del centinela", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del centinela:\n\nTu Embate con escudo genera un 100% más de amenaza y su tiempo de reutilización se restablece si se esquiva, para o bloquea."},
[236433] = {name = "[q3]Alma del zurdo", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del zurdo:\n\nReduce 2 s el tiempo de reutilización de tu habilidad Embate con escudo."},
[236434] = {name = "[q3]Alma del gladiador", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Guerrero\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del gladiador:\n\nReduce 30 s el tiempo de reutilización de tu habilidad Ira sangrienta mientras estás en Actitud de gladiador."},
