[236439] = {name = "[q3]Alma del oportunista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del oportunista:\n\nTus ataques iniciales tienen un 100% de probabilidad de hacer que tu siguiente habilidad no cueste energía."},
[236440] = {name = "[q3]Alma del carnicero", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del carnicero:\n\nAumenta un 20% el daño que inflige el arma de tu mano derecha con habilidades que generan puntos de combo."},
[236441] = {name = "[q3]Alma del fantasma", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del fantasma:\n\nReduce el tiempo de reutilización de Esfumar a 1 min. No se puede combinar con Elusión."},
[236442] = {name = "[q3]Alma del ladronzuelo", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del ladronzuelo:\n\nAumenta un 20% el daño de Mutilar y Sablazo."},
[236443] = {name = "[q3]Alma del amante de la adrenalina", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del amante de la adrenalina:\n\nReduce el tiempo de reutilización de Subidón de adrenalina 4 min."},
[236444] = {name = "[q3]Alma del experto en puyazos", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del experto en puyazos:\n\nAumenta un 5% tu probabilidad de conseguir un golpe crítico con dagas."},
[236445] = {name = "[q3]Alma del acechador", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del acechador:\n\nAumenta un 30% la probabilidad de golpe crítico de tu habilidad Emboscada."},
[236446] = {name = "[q3]Alma del eficiente", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del eficiente:\n\nTus remates cuestan un 50% menos de energía."},
[236447] = {name = "[q3]Alma del malabarista de cuchillos", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del malabarista de cuchillos:\n\nMientras Heridas superficiales y Danza de hojas están activos, Tempestad carmesí, Trabuco y Abanico de cuchillos cuesta 20 p. menos de energía y genera un 100% más de amenaza."},
[236448] = {name = "[q3]Alma del maestro de las sombras", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del maestro de las sombras:\n\nEsfumarse ahora reduce todo el daño mágico que recibes un 50% durante su efecto, pero ya no otorga sigilo ni elimina los efectos de reducción de movimiento."},
[236449] = {name = "[q3]Alma del equilibrista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del equilibrista:\n\nTus remates tienen una probabilidad del 20% por punto de combo de que recibas un 20% menos de daño físico del próximo ataque cuerpo a cuerpo que recibas dentro de 10 s."},
[236450] = {name = "[q3]Alma del camorrista fogueado", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del camorrista fogueado:\n\nTu Bravura ante los golpes ahora también se activa cada vez que obtienes un punto de combo."},
[236451] = {name = "[q3]Alma del cinturón negro", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del cinturón negro:\n\nTu Bravura ante los golpes también aumenta un 20% la armadura que te otorgan los objetos por cada acumulación (hasta un máximo de 100%)."},
[236452] = {name = "[q3]Alma del esgrimista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del esgrimista:\n\nEl tiempo de reutilización de tu Daga de guardamano se restablece cada vez que tu objetivo esquiva o para un ataque."},
[236453] = {name = "[q3]Alma del espadachín", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del espadachín:\n\nTu Daga de guardamano ahora golpea a 1 objetivo cercano más y también hace que tu Golpe siniestro golpee a 1 objetivo cercano más durante 10 s. Estos golpes adicionales no se duplican con Aluvión de acero."},
[236454] = {name = "[q3]Alma del sanguinario", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Pícaro\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del sanguinario:\n\nMientras el efecto está activo, tu Daga de guardamano hace que te sanes por un 15% de todo el daño que inflige Golpe siniestro. La sanación excedente se convierte en una Barrera de sangre que absorbe daño equivalente a un máximo del 20% de tu salud máxima."},
[236455] = {name = "[q3]Alma del transfusionista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del transfusionista:\n\nTransfusión de vida genera un 50% más de maná y un 100% menos de amenaza."},
[236456] = {name = "[q3]Alma del refinamiento", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del refinamiento:\n\nAumenta un 2% tu probabilidad de conseguir un golpe crítico con hechizos y ataques."},
[236457] = {name = "[q3]Alma del exterminador", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del exterminador:\n\nTu talento Ocaso tiene un 4% más de probabilidad de activarse. Tu Incinerar tiene un 4% de probabilidad de activar tu Exterminación sin importar la salud del objetivo."},
[236458] = {name = "[q3]Alma del putrefaccionista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del putrefaccionista:\n\nAumenta el daño de tus hechizos periódicos y de tu mascota Guardia vil un 10 + (5 * ComboPoints)%."},
[236459] = {name = "[q3]Alma del malévolo", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del malévolo:\n\nEl daño periódico de tus hechizos Llama de las Sombras, Aflicción inestable y Maldición de agonía, y el daño infligido por tu Guardia vil tienen una probabilidad del 4% de otorgar el efecto Trance de las Sombras."},
[236460] = {name = "[q3]Alma del sombramante", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del sombramante:\n\nDescarga de las Sombras inflige un 10 + (5 * ComboPoints)% más de daño por cada uno de tus efectos sobre el objetivo, hasta un máximo de 30 + (5 * ComboPoints)%."},
[236461] = {name = "[q3]Alma del heraldo del caos", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del heraldo del caos:\n\nReduce un 50% el tiempo de reutilización de tu Descarga de caos y aumenta un 10% el daño infligido con Descarga de caos y Descarga de las sombras. Además, Descarga de caos ahora puede activar tu talento Descarga de las sombras mejorada y hace que tenga 26 cargas más (no se acumulan con las cargas adicionales de Llama de las Sombras)."},
[236462] = {name = "[q3]Alma del incendiario", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del incendiario:\n\nCada vez que golpeas a un objetivo con Conflagrar, obtienes un 5% más de daño de Fuego durante 20 s. Se acumula hasta 2 veces."},
[236463] = {name = "[q3]Alma del pastor infernal", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del pastor infernal:\n\nAumenta un 20% el poder de ataque y el daño con hechizos que tu mascota demoníaca obtiene de tus atributos."},
[236464] = {name = "[q3]Alma del señor demoníaco", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del señor demoníaco:\n\nAumenta un 50% los beneficios de tu talento Maestro demonólogo."},
[236465] = {name = "[q3]Alma del exorcista demoníaco", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del exorcista demoníaco:\n\nDesterrar ahora se lanza al instante y se puede lanzar sobre ti mismo mientras seas un demonio. No puedes Desterrarte a ti mismo mientras tienes Abstinencia, y si lo haces recibirás Abstinencia durante 1 min."},
[236466] = {name = "[q3]Alma del adolorido", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del adolorido:\n\nCada vez que recibes daño, tú y tu mascota obtienen una cantidad de maná equivalente al daño recibido, hasta un máximo de 420 p. de maná por evento. Solo puede ocurrir una vez cada pocos segundos."},
[236467] = {name = "[q3]Alma del ánima flamígera", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del ánima flamígera:\n\nTus golpes de Cuchilla de las Sombras tienen un 20% de probabilidad de otorgarte un fragmento de alma, restablecer el tiempo de reutilización de Fuego de alma y hacer que tu siguiente Fuego de alma en los próximos 10 s sea instantáneo."},
[236468] = {name = "[q3]Alma del devoracarnes", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del devoracarnes:\n\nMientras marcas como objetivo a un enemigo que esté en un radio de 30 m, Transfusión de vida te otorga maná a costa de la salud de tu objetivo, pero le inflige un 50 + (5 * ComboPoints)% menos de daño. No afecta el maná obtenido."},
[236469] = {name = "[q3]Alma del abisal", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del abisal:\n\nMientras Metamorfosis está activa, tus habilidades ofensivas e invocaciones demoníacas no cuestan fragmentos de alma. Además, sanas un 15% de tu salud máxima cuando dañas a un objetivo con Quemadura de las Sombras."},
[236470] = {name = "[q3]Alma del natovacío", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del natovacío:\n\nToda la sanación adicional que te infliges se convierte en un escudo que absorbe daño. Este escudo puede absorber hasta un 30 + (5 * ComboPoints)% de tu salud máxima y acumula múltiples sanaciones."},
[236471] = {name = "[q3]Alma de la hoja umbría", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma de la hoja umbría:\n\nReduce 1.5 s el tiempo de reutilización de tu Cuchilla de las Sombras."},
[236472] = {name = "[q3]Alma del ritualista", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del ritualista:\n\nLos efectos de tu Sacrificio demoníaco ahora persisten mientras tengas una mascota demoníaca activa, siempre y cuando no reinvoques a la mascota sacrificada. Solo puedes contar con un efecto de Sacrificio demoníaco activo a la vez."},
[236473] = {name = "[q3]Alma del propagador de dolor", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Brujo\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del propagador de dolor:\n\nDurante 6 s después de usar Cuchilla de las Sombras, tu Dolor abrasador golpea a 1 objetivo más que esté en un radio cuerpo a cuerpo."},
[236474] = {name = "[q3]Alma del líder del engaño", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del líder del engaño:\n\nGeneras un 100% más de amenaza durante 8 s después de usar Disparo de distracción."},
[236475] = {name = "[q3]Alma del buscapresas", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del buscapresas:\n\nMientras rastreas un tipo de criatura, infliges un 3% más de daño a ese tipo de criatura."},
[236476] = {name = "[q3]Alma del tirador certero", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del tirador certero:\n\nLa siguiente habilidad de Disparo que utilices en los próximos 12 s después de utilizar Disparo de puntería inflige un 20% más de daño."},
[236477] = {name = "[q3]Alma del asaltante agresivo", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del asaltante agresivo:\n\nTu Disparo de puntería inflige un 20% más de daño a los objetivos bajo los efectos de una de tus trampas."},
[236478] = {name = "[q3]Alma del alternador", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del alternador:\n\nTus habilidades de daño de Disparo infligen un 10% más de daño si el último Disparo de daño usado fue distinto al anterior."},
[236479] = {name = "[q3]Alma del toxinólogo", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del toxinólogo:\n\nEl daño de tu Picadura de serpiente aumenta un 25% de tu poder de ataque durante su duración normal."},
[236480] = {name = "[q3]Alma del cazarrecompensas", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del cazarrecompensas:\n\nAumenta un 10% el daño de Disparo mortal contra objetivos que no están controlados por jugadores."},
[236481] = {name = "[q3]Alma del as del gatillo", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del as del gatillo:\n\nReduce el tiempo de reutilización de Disparo mortal un 50%. Mientras Fuego rápido está activo con la runa Matanza rápida grabada, Disparo mortal no tiene tiempo de reutilización y, cuando se usa contra un objetivo que no está controlado por un jugador, hace 3 Disparos mortales más con un 30% del daño y con un alcance mínimo."},
[236482] = {name = "[q3]Alma del protector de bestias", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del protector de bestias:\n\nAumenta un 20% el poder de ataque que tu mascota bestia obtiene de tus atributos."},
[236483] = {name = "[q3]Alma del maestro de canes", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del maestro de canes:\n\nAumenta un 20% la regeneración de enfoque de tu mascota bestia."},
[236484] = {name = "[q3]Alma del domador alfa", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del domador alfa:\n\nAumenta un 100% la regeneración de enfoque de tus mascotas."},
[236485] = {name = "[q3]Alma del montero", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del montero:\n\nTu Mordedura de mangosta también reduce un 1% la probabilidad de esquivar de su objetivo y aumenta un 1% tu probabilidad de golpear durante 30 s."},
[236487] = {name = "[q3]Alma del retaliador", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del retaliador:\n\nMordedura de mangosta también se activa durante 5 s cuando tu objetivo para o bloquea, o cuando tus ataques cuerpo a cuerpo fallan."},
[236488] = {name = "[q3]Alma de ecos", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma de ecos:\n\nGolpe de raptor aumenta un 20% el daño que inflige tu próxima habilidad cuerpo a cuerpo diferente (excepto Cortar alas) en un período de 5 s."},
[236489] = {name = "[q3]Alma del azotador letal", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del azotador letal:\n\nAumenta un 20% el daño que inflige el arma de tu mano derecha con Golpe de raptor y Golpe de dracoleón."},
[236490] = {name = "[q3]Alma del cinético", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del cinético:\n\nTu daño periódico tiene un 5% de probabilidad de restablecer el tiempo de reutilización de una de tus habilidades de Golpe. Siempre se selecciona el Golpe con el mayor tiempo de reutilización restante."},
[236491] = {name = "[q3]Alma del estratega", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Cazador\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del estratega:\n\nAumenta el daño con el tiempo de Golpe de dracoleón un 50% y aumenta el enfoque máximo de tu mascota 50 p."},
