[236561] = {name = "[q3]Alma del empuñavorágine", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Chamán\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del empuñavorágine:\n\nCada vez que bloqueas un ataque, tienes una probabilidad del 50% de activar tu runa Arma vorágine."},
[236562] = {name = "[q3]Alma del zancalavas", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Chamán\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del zancalavas:\n\nDañar a un objetivo con Golpe de tormenta, Ráfaga de lava o Explosión de arrabio también reduce un 10% todo el daño que recibes durante 10 s."},
[236563] = {name = "[q3]Alma del alfa verdadero", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Chamán\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del alfa verdadero:\n\nCuando lanzas Espíritu del alfa sobre ti mismo, también aumenta tu salud un 5%, tu amenaza generada un 25%, y todo el daño que inflijas un 5%."},
