[236608] = {name = "[q3]Alma de la zarpa", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Druida\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma de la zarpa:\n\nAumenta 3 s la duración de Arañazo y un 10% su daño periódico."},
[236609] = {name = "[q3]Alma de la manada imponente", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Druida\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma de la manada imponente:\n\nTu probabilidad de golpe crítico aumenta un 15% cuando Furia del tigre está activa."},
[236610] = {name = "[q3]Alma del barbárico", additional_info = "Se liga al recogerlo\nÚnico (20)\nClases: Druida\nNecesitas ser de nivel 55\n[q2]Uso: Infunde tus hombreras permanentemente con el Alma del barbárico:\n\nTus habilidades Triturar, Mordedura feroz y Destrozar (felino) infligen un 10% más de daño por efecto de sangrado tuyo sobre el objetivo, hasta un máximo de un 20% más."},
