[238348] = {name = "[q4]El hacha de extirpación", additional_info = "Se liga al recogerlo\n{Dos manos} {Hacha}\n{69 - 105 p. de daño} {Velocidad 3.40}\n(25.59 p. de daño por segundo)\n+20 fuerza\nDurabilidad 105 / 105\nNecesitas ser de nivel 20"},
[238349] = {name = "[q4]Leotardos de piel de abominación", additional_info = "Se liga al recogerlo\n{Piernas} {Tela}\n41 armadura\n+7 aguante\n+8 intelecto\nDurabilidad 70 / 70\nNecesitas ser de nivel 20\n[q2]Equipar: Aumenta hasta 18 p. el daño y la sanación de los hechizos y efectos mágicos."},
[238350] = {name = "[q4]Daga focal de Desdén", additional_info = "Se liga al recogerlo\n{Mano derecha} {Daga}\n{27 - 51 p. de daño} {Velocidad 1.40}\n(27.86 p. de daño por segundo)\nDurabilidad 75 / 75\nNecesitas ser de nivel 30\n[q2]Equipar: Aumenta hasta 13 p. el daño y la sanación de los hechizos y efectos mágicos."},
[238351] = {name = "[q4]La garra helada", additional_info = "Se liga al recogerlo\n{Manos} {Malla}\n160 armadura\n+10 aguante\nDurabilidad 50 / 50\nNecesitas ser de nivel 30\n[q2]Equipar: Aumenta 32 p. el poder de ataque."},
[238352] = {name = "[q4]Gargantilla helada de Desdén", additional_info = "Se liga al recogerlo\nCuello\n+5 aguante\n+6 intelecto\nNecesitas ser de nivel 30\n[q2]Equipar: Aumenta hasta 13 p. el daño y la sanación de los hechizos y efectos mágicos."},
[238353] = {name = "[q4]Manto de Lady Falther'ess", additional_info = "Se liga al recogerlo\nEspalda\n32 armadura\n+9 intelecto\nNecesitas ser de nivel 36\n[q2]Equipar: Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos."},
[238354] = {name = "[q4]Dedo de Lady Falther'ess", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{40 - 75 p. de daño de Sombras} {Velocidad 1.30}\n(44.23 p. de daño por segundo)\nDurabilidad 65 / 65\nNecesitas ser de nivel 36\n[q2]Equipar: Aumenta hasta 14 p. el daño que infligen los hechizos y efectos de las Sombras."},
[238355] = {name = "[q4]Cadenas del Exánime", additional_info = "Se liga al recogerlo\nCuello\nNecesitas ser de nivel 55\n[q2]Equipar: Aumenta hasta 29 p. el daño y la sanación de los hechizos y efectos mágicos."},
[238356] = {name = "[q4]Pretina de Balzaphon", additional_info = "Se liga al recogerlo\n{Cintura} {Tela}\n52 armadura\n+13 aguante\n+14 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 55\n[q2]Equipar: Aumenta hasta 33 p. el daño que infligen los hechizos y efectos de Escarcha."},
[238357] = {name = "[q4]Bastón de Balzaphon", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{176 - 265 p. de daño} {Velocidad 3.90}\n(56.54 p. de daño por segundo)\n+8 aguante\n+10 intelecto\n+7 espíritu\nDurabilidad 120 / 120\nNecesitas ser de nivel 55\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 47 p. el daño que infligen los hechizos y efectos de Escarcha."},
[238358] = {name = "[q4]Muslo de Bosque Negro", additional_info = "Se liga al recogerlo\nSostener con la mano izquierda\n+12 aguante\n+13 espíritu\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta hasta 16 p. el daño y la sanación de los hechizos y efectos mágicos."},
[238360] = {name = "[q4]Rodela de Lord Bosque Negro", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n2362 armadura\n42 bloqueo\n+10 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 32 p."},
[238361] = {name = "[q4]Hoja de Lord Bosque Negro", additional_info = "Se liga al recogerlo\n{Una mano} {Espada}\n{40 - 76 p. de daño} {Velocidad 1.30}\n(44.62 p. de daño por segundo)\n+10 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta 9 p. el índice de defensa."},
[238362] = {name = "[q4]Brazales de alivio", additional_info = "Se liga al recogerlo\nMuñeca Tela\n42 armadura\n+5 aguante\n+8 intelecto\n+13 espíritu\nDurabilidad 35 / 35\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta hasta 33 p. la sanación realizada y hasta 11 p. el daño que infligen todos los efectos y hechizos mágicos."},
[238363] = {name = "[q4]La garra de las Sombras", additional_info = "Se liga al recogerlo\n{Manos} {Tela}\n60 armadura\n+14 aguante\n+14 intelecto\nDurabilidad 35 / 35\nNecesitas ser de nivel 57\n[q2]Equipar: Aumenta hasta 34 p. el daño que infligen los hechizos y efectos de las Sombras."},
[238364] = {name = "[q4]Capa de Revanchion", additional_info = "Se liga al recogerlo\nEspalda\n49 armadura\n+13 fuerza\n+13 agilidad\n+12 aguante\nNecesitas ser de nivel 58"},
[238637] = {name = "Filete de merodeador", additional_info = "Necesitas ser de nivel 55\n[q2]Uso: Restaura 2550 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 25 p. de fuerza y 10 p. de aguante durante 15 min."},
[238638] = {name = "Filete de lomo", additional_info = "Necesitas ser de nivel 55\n[q2]Uso: Restaura 2550 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 25 p. de agilidad y 10 p. de aguante durante 15 min."},
[238639] = {name = "Omelette madrugador", additional_info = "Necesitas ser de nivel 55\n[q2]Uso: Restaura 2550 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 29 p. de daño con hechizos, 55 p. de poder de sanación y 10 p. de aguante durante 15 min."},
[238641] = {name = "[q2]Festín de motaletas", additional_info = "Necesitas ser de nivel 55\n[q2]Uso: Sirve un banquete delicioso que dura 3 min, con porciones para un máximo de 40 jugadores.\n\n Comida\nRestaura 2550 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 40 p. de poder de ataque, 23 p. de daño con hechizos, 44 p. de poder de sanación y 10 p. de aguante durante 45 min. (5 Min Reutilización)"},
[238642] = {name = "[q2]Gran banquete de langostas", additional_info = "Necesitas ser de nivel 55\n[q2]Uso: Sirve un banquete delicioso que dura 3 min, con porciones para un máximo de 40 jugadores.\n\n Comida\nRestaura 2550 p. de salud durante 30 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado y ganarás 40 p. de poder de ataque, 23 p. de daño con hechizos, 44 p. de poder de sanación y 10 p. de aguante durante 45 min. (5 Min Reutilización)"},
[238645] = {name = "Receta: Filete de merodeador", additional_info = "Se liga al recogerlo\nRequiere Cocina (250)\n[q]\"Te enseña a cocinar un filete de merodeador.\""},
[238646] = {name = "Receta: Filete de lomo", additional_info = "Se liga al recogerlo\nRequiere Cocina (250)\n[q]\"Te enseña a cocinar un filete de lomo.\""},
[238647] = {name = "Receta: Omelette madrugador", additional_info = "Se liga al recogerlo\nRequiere Cocina (250)\n[q]\"Te enseña a cocinar un omelette madrugador.\""},
[238649] = {name = "Receta: Festín de motaletas", additional_info = "Se liga al recogerlo\nRequiere Cocina (280)\n[q]\"Te enseña a cocinar un festín de motaletas.\""},
[238650] = {name = "Receta: Gran banquete de langostas", additional_info = "Se liga al recogerlo\nRequiere Cocina (280)\n[q]\"Te enseña a cocinar un gran banquete de langostas.\""},
[238681] = {name = "Bolsa polvorienta", additional_info = "Se liga al recogerlo\nNecesitas ser de nivel 60\n[q2]<Click derecho para abrir>"},
[238687] = {name = "[q0]Maza de embate", additional_info = "{Dos manos} {Maza}\n{1 - 2 p. de daño} {Velocidad 2.00}\n(0.75 p. de daño por segundo)\nDurabilidad 20 / 20"},
[238734] = {name = "[q2]Caja de artilugios: Teletransporte", additional_info = "Necesitas ser de nivel 45\n[q2]Uso: Te teletransportas 20 m más adelante."},
[238735] = {name = "[q2]Caja de artilugios: Nitropropulsores", additional_info = "Necesitas ser de nivel 45\n[q2]Uso: Activa unos propulsores para aumentar tu velocidad de movimiento hasta un 160% durante un máximo de 8 s."},
[238736] = {name = "[q2]Caja de artilugios: Desplazamiento magnético", additional_info = "Necesitas ser de nivel 45\n[q2]Uso: Altera un campo magnético que se encuentra entre un objetivo enemigo cercano y tú y los repele.\n\n Solo puede afectar a objetivos de hasta 2 niveles por encima de ti. Algunos objetivos no pueden ser desplazados. Los objetivos solo pueden sufrir este efecto una vez cada 2 min."},
[238737] = {name = "Caja de artilugios", additional_info = "Material de profesión\n[q]\"Un módulo de control simple que utilizan los ingenieros para fabricar artilugios.\""},
[238781] = {name = "[q2]Transportador semiseguro: Nuevo Avalon", additional_info = "Se liga al usarlo\nAbalorio\nNecesitas ser de nivel 60\nRequiere Ingeniería (290)\n[q2]Uso: Deja a un lado la cautela y prueba un prototipo goblin de un dispositivo de teletransportación. Con suerte, llegarás a Nuevo Avalon en una pieza. (4 H Reutilización)"},
[238782] = {name = "Esquema: Caja de artilugios", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (250)\n[q]\"Te enseña a fabricar una caja de artilugios.\""},
[238783] = {name = "[q2]Esquema: Caja de artilugios: Teletransporte", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (260)\n[q]\"Te enseña a fabricar una caja de artilugios: Teletransporte.\""},
[238784] = {name = "[q2]Esquema: Caja de artilugios: Nitropropulsores", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (260)\n[q]\"Te enseña a fabricar una caja de artilugios: Nitropropulsores.\""},
[238785] = {name = "[q2]Esquema: Caja de artilugios: Desplazamiento magnético", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (260)\n[q]\"Te enseña a fabricar una caja de artilugios: Desplazamiento magnético.\""},
[238786] = {name = "[q3]Esquema: Artilugio: Teletransporte", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (280)\n[q2]Mejora tu cinturón para que otorgue el siguiente efecto:\n\nTe teletransportas 20 m más adelante.\n[q]\"Te enseña a fabricar un artilugio: Teletransporte.\""},
[238787] = {name = "[q3]Esquema: Artilugio: Nitropropulsores", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (280)\n[q2]Mejora tu cinturón para que otorgue el siguiente efecto:\n\nActiva unos propulsores para aumentar tu velocidad de movimiento hasta un 160% durante un máximo de 8 s.\n[q]\"Te enseña a fabricar un artilugio: Nitropropulsores.\""},
[238788] = {name = "[q3]Esquema: Artilugio: Desplazamiento magnético", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (280)\n[q2]Mejora tu cinturón para que otorgue el siguiente efecto:\n\nAltera un campo magnético que se encuentra entre un objetivo enemigo cercano y tú y los repele.\n\n Solo puede afectar a objetivos de hasta 2 niveles por encima de ti. Algunos objetivos no pueden ser desplazados. Los objetivos solo pueden sufrir este efecto una vez cada 2 min.\n[q]\"Te enseña a fabricar un artilugio: Desplazamiento magnético.\""},
[238789] = {name = "[q3]Esquema: Transportador semiseguro: Nuevo Avalon", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (300)\n[q]\"Te enseña a fabricar Transportador semiseguro: Nuevo Avalon.\""},
[238794] = {name = "Sobras poco apetitosas", additional_info = "Objeto de misión\n[q]\"Tal vez no sea tan malo pasar un poco de hambre.\""},
[238811] = {name = "Manzana jugosa", additional_info = "Objeto de misión\n[q]\"Recién recogida del campo.\""},
[238830] = {name = "Catalejo de manzanas", additional_info = "Objeto de misión\n[q2]Uso: Te permite ver a lo lejos para buscar manzanas.\n[q]\"Los granjeros más perezosos lo utilizan para monitorear sus cultivos desde la comodidad de su hogar.\""},
[238831] = {name = "Cuerda de manzanas", additional_info = "Objeto de misión\n[q2]Uso: Roba una manzana desde una distancia segura.\n[q]\"Una cuerda común y corriente.\""},
[238899] = {name = "Surtido de peces", additional_info = "Objeto de misión\n[q]\"No puedes identificar a la mayoría de estos peces con tu habilidad de pesca actual. Por suerte, ese no es tu problema.\""},
[238925] = {name = "[q4]Carcaj escarlata", additional_info = "Se liga al equiparlo\nCarcaj de 30 casillas\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la velocidad de ataque en un 15%."},
[238926] = {name = "[q4]Faltriquera de munición escarlata", additional_info = "Se liga al equiparlo\nBolsa de munición de 30 casillas\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta la velocidad de ataque en un 15%."},
[238927] = {name = "[q2]Patrón: Carcaj escarlata", additional_info = "Se liga al recogerlo\nRequiere Peletería (275)\n[q]\"Te enseña a fabricar un carcaj escarlata.\""},
[238928] = {name = "[q2]Patrón: Faltriquera de munición escarlata", additional_info = "Se liga al recogerlo\nRequiere Peletería (275)\n[q]\"Te enseña a fabricar una faltriquera de munición escarlata.\""},
[238935] = {name = "Carne ligeramente putrefacta", additional_info = "Objeto de misión\n[q]\"Si cortas las partes verdosas, ¿quién lo va a notar?\""},
[238945] = {name = "[q4]Caladroca", additional_info = "Se liga al recogerlo\n{Dos manos} {Maza}\n{334 - 501 p. de daño} {Velocidad 4.30}\n(97.09 p. de daño por segundo)\n+30 fuerza\n+10 agilidad\n+5 aguante\nDurabilidad 300 / 300\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Probabilidad al acertar: El peso de la Caladroca derriba a todos los enemigos cercanos durante 4 s.\n[q2]Equipar: La velocidad de movimiento se reduce un 10%.\n[q]\"La espada y la piedra\""},
[238960] = {name = "Cajón del intendente", additional_info = "Objeto de misión\n[q2]Uso: Guarda una pieza de equipo fabricado de la Cruzada Escarlata en el cajón. Esta acción destruirá el objeto para siempre."},
[238961] = {name = "[q4]Caladbolg", additional_info = "Se liga al recogerlo\n{Dos manos} {Espada}\n{339 - 509 p. de daño} {Velocidad 3.90}\n(108.72 p. de daño por segundo)\n+50 fuerza\n+15 agilidad\n+7 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 2% tu velocidad de ataque.\n[q2]Equipar: Reduce un 1% la probabilidad de que esquiven o paren tus ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Uso: La tierra vuelve a tragarse a Caladbolg durante 20 s, lo que reduce la velocidad de movimiento un 50%. Si estás en movimiento, tu velocidad aumenta cada 2 s. Chocar contra un enemigo inflige 300 to 2700 p. de daño de Fuego, repele a todos los jugadores enemigos cercanos y hace que termine este efecto. (2 Min Reutilización)\n[q]\"Una espada antigua que la Cruzada Escarlata guardó en secreto. Está un poco usada.\""},
[238985] = {name = "Cajón pesado", additional_info = "Objeto de misión\n[q]\"Llévaselo al intendente Escarlata para completar \"Demuestra tu valía\".\""},
[239010] = {name = "[q4]Empuñadura de la Crematoria", additional_info = "Se liga al recogerlo\nÚnico\n{Dos manos} {Espada}\n{99 - 162 p. de daño} {Velocidad 2.00}\n(65.25 p. de daño por segundo)\nDurabilidad 15 / 15\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Uso: Intenta ponerte en contacto con la Voluntad de la Crematoria. (4 Min Reutilización)"},
[239011] = {name = "[q5]Fragmento de luz cristalizada", additional_info = "Se liga al recogerlo"},
[239012] = {name = "[q5]Astilla de luz cristalizada", additional_info = "Se liga al recogerlo"},
[239013] = {name = "[q5]Hacha cristalina", additional_info = "Se liga al recogerlo\n[q]\"Unas auténticas hojas de luz.\""},
[239016] = {name = "Sales sagradas", additional_info = "Material de profesión\n[q]\"A menudo, los cruzados utilizan estas sales para ahuyentar la mala suerte. Casualmente, también son muy útiles para cocinar.\""},
[239017] = {name = "[q2]Especias exquisitas", additional_info = "Material de profesión\n[q]\"Un producto estrictamente controlado que no se puede comprar ni vender de forma directa sin sufrir las consecuencias. Codiciado por los chefs que desean preparar un festín.\""},
[239021] = {name = "Libro de cocina de Carrie", additional_info = "Se liga al recogerlo\nRequiere Cocina (280)\n[q2]Uso: Te enseña a cocinar las recetas de festín más deseadas de Carrie Fogata."},
[239060] = {name = "[q4]Voluntad de la montaña", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{169 - 316 p. de daño} {Velocidad 2.90}\n(83.62 p. de daño por segundo)\n+17 fuerza\n+5 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Reduce un 1% la probabilidad de que esquiven o paren tus ataques.\n[q2]Probabilidad al acertar: Invoca la Voluntad de la montaña, lo que aumenta un 5% el daño físico infligido, 500 p. la armadura y un 20% el tamaño durante 15 s.\n[q]\"En un pasado un poderoso martillo de herrería, esta alucinante obra de arte es incluso más inspiradora cuando la sostienes.\""},
[239092] = {name = "Sello postal peculiarmente en prosa", additional_info = "Objeto de misión\nÚnico\nEste objeto inicia una misión"},
[239097] = {name = "[q3]Llave de la catedral", additional_info = "Objeto mágico\nSe liga al recogerlo\nÚnico"},
[239117] = {name = "[q4]Cáliz de cruzado", additional_info = "Se liga al recogerlo\n[q]\"Llévaselo a Bryon Hoja de Acero en Nuevo Avalon junto con un objeto apropiado del conjunto fabricado de Cruzado Escarlata para intercambiarlos por un objeto de conjunto de clase.\""},
[239119] = {name = "Flecha sagrada", additional_info = "Objeto de misión\n[q]\"Bendita sea la flecha que derriba a nuestros enemigos.\""},
[239123] = {name = "[q0]Monster - BOW_1H_STANDARD_C_01 - Red", additional_info = "Se liga al recogerlo\n{A distancia} {Arco}\n{1 - 2 p. de daño} {Velocidad 2.00}\n(0.75 p. de daño por segundo)\nDurabilidad 18 / 18"},
[239147] = {name = "[q3]Morral de cruzado", additional_info = "Se liga al equiparlo\nBolsa de 24 casillas"},
[239148] = {name = "[q4]Bolsa tejida en alba carmesí", additional_info = "Se liga al equiparlo\nBolsa de 30 casillas"},
[239149] = {name = "[q3]Patrón: Morral de cruzado", additional_info = "Se liga al recogerlo\nRequiere Sastrería (250)\n[q]\"Te enseña a fabricar un morral de cruzado.\""},
[239150] = {name = "[q4]Patrón: Bolsa tejida en alba carmesí", additional_info = "Se liga al recogerlo\nRequiere Sastrería (290)\n[q]\"Te enseña a fabricar una bolsa tejida en alba carmesí.\""},
[239159] = {name = "[q2]S03 - Scarlet Enclave - Captains Shield", additional_info = "Se liga al equiparlo\n{Mano izquierda} {Escudo}\n1861 armadura\n35 bloqueo\n+3 fuerza\n+14 aguante\nDurabilidad 85 / 85\nNecesitas ser de nivel 56"},
[239196] = {name = "[q5]Hoja forjada con luz arruinada", additional_info = "Se liga al recogerlo\nEste objeto inicia una misión\nClases: Guerrero , Paladín , Cazador"},
[239197] = {name = "[q4]Hoja reforjada de la Crematoria", additional_info = "Se liga al recogerlo"},
[239215] = {name = "[q4]Emblema carbonizado", additional_info = "Se liga al recogerlo\nÚnico\nEste objeto inicia una misión\nNecesitas ser de nivel 60"},
[239216] = {name = "[q5]Hierro templeluz", additional_info = "Se liga al recogerlo\nClases: Guerrero , Paladín , Cazador"},
[239218] = {name = "[q5]Notas de Tallapiedras", additional_info = "Objeto de misión\nÚnico\n[q]\"Este documento está escrito de forma muy desprolija, pero, por lo que puedes descifrar, estas notas y diseños son obra de un artesano ilustre.\""},
[239219] = {name = "[q4]Emblema de la Crematoria", additional_info = "Se liga al recogerlo\nÚnico\nNecesitas ser de nivel 60\n[q2]Uso: Combina el emblema de la Crematoria, la hoja reforjada de la Crematoria y la empuñadura de la Crematoria."},
[239221] = {name = "[q0]Monster - Sword1H, Basic", additional_info = "{Mano derecha} {Espada}\n{1 - 2 p. de daño} {Velocidad 2.00}\n(0.75 p. de daño por segundo)\nDurabilidad 20 / 20"},
[239222] = {name = "[q3]Esquema: Arbusto falso", additional_info = "Se liga al recogerlo\nRequiere Ingeniería (250)\n[q]\"Te enseña a fabricar un arbusto falso.\""},
[239223] = {name = "Casa de utilería", additional_info = "Objeto de misión\n[q]\"Una utilería increíblemente convincente en el contexto de una obra o una ópera.\""},
[239225] = {name = "Pluma elegante", additional_info = "Objeto de misión\n[q]\"La satisfacción de escribir tu propio nombre con este instrumento invade tu mente.\""},
[239246] = {name = "Lista de compras de Fundefusibles", additional_info = "Se liga al recogerlo\nÚnico\n[q]\"Una lista de artículos cuyo autor fue escribiendo a las apuradas cada vez que recordaba algo más para agregar.\"\n[q2]<Click derecho para leer>"},
[239248] = {name = "[q4]Caja de trastos Escarlata", additional_info = "Se liga al recogerlo\n[q]\"Contiene la chatarra que haya quedado abandonada por ahí y, a veces, algo valioso de un aventurero imprudente.\"\n[q2]<Click derecho para abrir>"},
[239292] = {name = "Notas de Forjador", additional_info = "Objeto de misión\nÚnico\n[q]\"Contiene las reflexiones y las obras de Franclorn Forjador.\""},
[239301] = {name = "[q5]Crematoria corrupta", additional_info = "Santificado\nSe liga al recogerlo\nÚnico\n{Dos manos} {Espada}\n{357 - 536 p. de daño} {Velocidad 3.80}\n(117.50 p. de daño por segundo)\n+53 fuerza\n-30 aguante\nDurabilidad 145 / 145\nNecesitas ser de nivel 60\n[q2]Equipar: Inflige la voluntad de la Crematoria en quien la empuña.\n[q2]Equipar: Mejora un 3% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Reduce un 2% la probabilidad de que esquiven o paren tus ataques.\n[q2]Probabilidad al acertar: Roba 475 to 525 p. de vida de un máximo de 5 enemigos, lo que otorga 30 p. de fuerza y agilidad por cada enemigo drenado. Se acumula un máximo de 5 veces.\n[q]\"Espada del Alto Señor Escarlata\""},
[239302] = {name = "Cinturón de uniforme Escarlata", additional_info = "Objeto de misión\n[q]\"Una correa gruesa de cuero con un broche pesado de acero. Este cinturón es una verdadera obra maestra, lista para que unas manos imprudentes la arruinen.\""},
[239316] = {name = "Churumbele de triangulación", additional_info = "Objeto de misión\nRequiere Ingeniería (1)\n[q2]Uso: Utiliza el dispositivo en un punto de triangulación designado para ayudar a Fundefusibles a calibrar su teletransportador. (10 Seg Reutilización)"},
[239512] = {name = "[q4]Muñequeras de rompeluz", additional_info = "Santificado\nSe liga al recogerlo\nMuñeca Placas\n477 armadura\n+29 fuerza\n+10 agilidad\n+13 aguante\nDurabilidad 55 / 55\nClases: Guerrero\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta un 1% tu velocidad de ataque.\n\n[q]Placa de guerra de rompeluz (0/8)\n[q0]Gran yelmo de rompeluz\nSobrehombros de rompeluz\nLoriga de rompeluz\nCinturón de rompeluz\nEscarcelas de rompeluz\nGrebas de rompeluz\nMuñequeras de rompeluz\nMandiletes de rompeluz\n[q0](2) Conjunto : Aumenta el daño de tu Golpe heroico, Rajar y Golpe rápido un 20% en Actitud de batalla o Actitud rabiosa. Tus golpes de Rajar golpean a 1 objetivo más y pueden activar Oleada de sangre.\n(4) Conjunto : Cada vez que golpeas a un objetivo con Torbellino, Golpe heroico, Golpe rápido o Rajar, el daño de tu próximo Embate aumenta un 20%. Se acumula un máximo de 5 veces.\n(6) Conjunto : Cada vez que Heridas profundas inflige daño, reduce 3 s el tiempo de reutilización restante de tu Torbellino. Torbellino inflige un 100% más de daño a los objetivos afectados por tu Heridas profundas."},
