[241001] = {name = "[q4]La caída de Tyr", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{39 - 160 p. de daño} {Velocidad 2.40}\n(41.46 p. de daño por segundo)\n+9 aguante\n+17 intelecto\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 169 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Infligir daño periódico tiene un 5% de probabilidad de otorgar 120 p. de daño con hechizos y sanación durante 15 s. (Probabilidad de que accione: 5%)"},
[241002] = {name = "[q4]Restos del rojo", additional_info = "Se liga al recogerlo\n{Mano derecha} {Espada}\n{39 - 160 p. de daño} {Velocidad 2.40}\n(41.46 p. de daño por segundo)\n+5 aguante\n+10 intelecto\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta un 2% la velocidad de lanzamiento.\n[q2]Equipar: Aumenta hasta 169 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Infligir daño de Fuego no periódico tiene un 5% de probabilidad de aumentar un 5% el daño de Fuego que infliges durante 15 s. (Probabilidad de que accione: 5%)"},
[241003] = {name = "[q4]Espejismo, Vara de ilusión", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{200 - 279 p. de daño} {Velocidad 3.60}\n(66.53 p. de daño por segundo)\n+12 aguante\n+28 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 2% la velocidad de lanzamiento.\n[q2]Equipar: Mejora un 3% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 169 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: Cuando asestas un hechizo que inflige daño, hay una probabilidad de crear un espejismo sobre tu objetivo que inflige daño Arcano a los enemigos cercanos durante 30 s. (Probabilidad de que accione: 10%, 30s de reutilización)\n[q2]Uso: Intercambia lugares con tu espejismo. (2 Min Reutilización)"},
[241004] = {name = "[q4]Enigma", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{159 - 296 p. de daño de Sagrado} {Velocidad 1.50}\n(151.67 p. de daño por segundo)\n-10 aguante\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 30 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q2]Equipar: El alcance de tu Tortura mental, Explosión de Fuego y Drenar vida aumenta 10 m, pero Tortura mental ya no ralentiza a los enemigos."},
[241006] = {name = "[q4]Aguja de sacrificio", additional_info = "Se liga al recogerlo\n{Mano derecha} {Maza}\n{39 - 160 p. de daño} {Velocidad 2.40}\n(41.46 p. de daño por segundo)\n+7 aguante\nDurabilidad 105 / 105\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 2% la velocidad de lanzamiento.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 317 p. la sanación realizada y hasta 106 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Uso: Mientras tienes más de un 30% de salud, tu sanación aumenta 200 p., pero tus sanaciones hacen que sacrifiques un 5% de tu salud total con cada lanzamiento. Mientras estás bajo este efecto, solo puedes recibir sanaciones con objetivo directo no periódicas. (Efecto de activación y desactivación). (10 Seg Reutilización)"},
[241008] = {name = "[q4]Condenación", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{187 - 263 p. de daño} {Velocidad 3.60}\n(62.50 p. de daño por segundo)\n+20 aguante\n+30 intelecto\n+21 espíritu\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 3% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 317 p. la sanación realizada y hasta 106 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Los lanzamientos de hechizos que infligen daño en enemigos los condenan durante 20 s. Cada vez que infligen daño, su objetivo sana un 3% de su salud máxima. Dura 20 s o hasta 10 golpes. (60 s de tiempo de reutilización) (1m de reutilización)"},
[241011] = {name = "[q4]Gran bastón de lealtad", additional_info = "Se liga al recogerlo\n{Dos manos} {Bastón}\n{200 - 279 p. de daño} {Velocidad 3.60}\n(66.53 p. de daño por segundo)\n+16 aguante\n+20 intelecto\n+30 espíritu\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 4% la velocidad de lanzamiento.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 317 p. la sanación realizada y hasta 106 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Si no hay enemigos en un radio de 20 m a tu alrededor, sana 125 p. cada 3 s a todos los miembros del grupo en un radio de 20 m. Un grupo solo puede jurar lealtad a un jugador a la vez."},
[241012] = {name = "[q4]Varita de reanimación", additional_info = "Se liga al recogerlo\n{A distancia} {Varita}\n{159 - 296 p. de daño de Sagrado} {Velocidad 1.50}\n(151.67 p. de daño por segundo)\n+6 intelecto\nDurabilidad 75 / 75\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta hasta 46 p. la sanación realizada y hasta 16 p. el daño que infligen todos los efectos y hechizos mágicos."},
[241015] = {name = "[q4]Égida del Bastión Escarlata", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n3637 armadura\n74 bloqueo\n+10 fuerza\n+20 aguante\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta la probabilidad de bloquear ataques con un escudo un 2%.\n[q2]Equipar: Aumenta el valor de bloqueo de tu escudo 27 p.\n[q2]Equipar: Aumenta 16 p. el índice de defensa.\n[q2]Uso: Aumenta un 20% el daño que absorbe tu escudo durante 15 s. (1 Min, 30 Seg Reutilización)"},
[241017] = {name = "[q4]Locura de demonio", additional_info = "Se liga al recogerlo\n{Mano izquierda} {Escudo}\n3425 armadura\n68 bloqueo\n+7 aguante\n+22 intelecto\nDurabilidad 120 / 120\nNecesitas ser de nivel 60\n[q2]Equipar: Aumenta un 1% la velocidad de lanzamiento.\n[q2]Equipar: Aumenta hasta 23 p. el daño y la sanación de los hechizos y efectos mágicos."},
