[241191] = {name = "[q3]Fórmula: encantar arma: gran cruzado", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (280)\n[q2]Encanta de forma permanente un arma de combate cuerpo a cuerpo para que, al atacar cuerpo a cuerpo, a menudo sane 350 to 450 p. de salud y aumente 120 p. la fuerza durante 20 s.\n[q]\"Te enseña a encantar de forma permanente un arma para que ocasionalmente bendiga al portador con fuerza increíble.\""},
[241195] = {name = "[q3]Fórmula: encantar arma 2M: gran arcanista", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (280)\n[q2]Encanta de forma permanente un arma de dos manos de combate cuerpo a cuerpo para que, al atacar con un hechizo, a menudo restaure 350 to 450 p. de maná y aumente 140 p. el poder con hechizos durante 20 s.\n[q]\"Te enseña a encantar de forma permanente un arma cuerpo a cuerpo de dos manos para que ocasionalmente bendiga al portador con poder con hechizos potenciado.\""},
[241201] = {name = "[q3]Fórmula: encantar arma: gran hechicero", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (280)\n[q2]Encanta de forma permanente un arma de combate cuerpo a cuerpo para que, al atacar con un hechizo, a menudo restaure 350 to 450 p. de maná y aumente 70 p. el poder con hechizos durante 20 s.\n[q]\"Te enseña a encantar de forma permanente un arma cuerpo a cuerpo para que ocasionalmente bendiga al portador con poder con hechizos potenciado.\""},
[241212] = {name = "[q4]Cañón cacareador", additional_info = "Se liga al recogerlo\n{A distancia} {Arma de fuego}\n{142 - 265 p. de daño} {Velocidad 3.50}\n(58.14 p. de daño por segundo)\n+10 aguante\nDurabilidad 90 / 90\nNecesitas ser de nivel 60"},
[241241] = {name = "[q4]Doblón de la suerte", additional_info = "Se liga al recogerlo\nÚnico-Equipado\nAbalorio\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 2% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Uso: Tira el Doblón de la suerte. Si sale cara, el tiempo de reutilización de Doblón de la suerte se restablece y tu probabilidad de golpe crítico con todos los hechizos y ataques aumenta un 5% durante 15 s. Este efecto se acumula hasta 5 veces. Si sale cruz, se eliminan todas las acumulaciones de Doblón de la suerte. (Debes estar en combate.) (30 Seg Reutilización)\n[q]\"Doble o nada.\""},
[241613] = {name = "[q3]Ya no se usa", additional_info = "Se liga al recogerlo"},
[241629] = {name = "[q4]Bala de cañón Escarlata", additional_info = "Objeto mágico\nÚnico\nDuración: 10 min"},
[241649] = {name = "[q2]Guanteletes de la Guardia de Trabalomas", additional_info = "Se liga al equiparlo\n{Manos} {Placas}\n345 armadura\n+15 fuerza\n+12 aguante\nDurabilidad 40 / 40\nNecesitas ser de nivel 53"},
[241650] = {name = "Poción de sanación sublime descolorida", additional_info = "Necesitas ser de nivel 60\n[q2]Uso: Restaura 3750 to 4250 p. de salud al instante, pero también recibes daño equivalente a un 75% de esa cantidad con el tiempo.\n\n Los síntomas de este efecto pueden manifestarse tanto como un envenenamiento de 6 s o una enfermedad de 12 s. (2 Min Reutilización)"},
[241651] = {name = "[q2]Receta: poción de sanación sublime descolorida", additional_info = "Se liga al recogerlo\nRequiere Alquimia (250)\n[q]\"Te enseña a hacer una poción de sanación sublime descolorida.\""},
[241652] = {name = "Corazón de bestia descolorido", additional_info = nil},
[241653] = {name = "[q4]Hoja caliente", additional_info = "Se liga al recogerlo\nÚnico\n[q2]Uso: Enfría la hoja en las aguas del Pozo de la Eternidad."},
[241654] = {name = "[q4]Crematoria inerte", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Usa las llamas antiguas creadas con las ramas de Nordrassil para calentar la hoja.\n[q]\"No es más que una espada en su forma actual...\""},
[241655] = {name = "Poción de sanación maltratada", additional_info = "Este objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Una poción verdaderamente repugnante.\""},
[241656] = {name = "Poción de sanación maltratada", additional_info = "Este objeto inicia una misión\nNecesitas ser de nivel 60\n[q]\"Una poción verdaderamente repugnante.\""},
[241657] = {name = "[q4]Espada templada", additional_info = "Objeto de misión\nÚnico\n[q2]Uso: Intenta ponerte en contacto con la Voluntad de la Crematoria. (4 Min Reutilización)"},
[242018] = {name = "Corazón sangrante de las Tierras de la Peste", additional_info = "Objeto de misión\n[q]\"Una flor de una belleza inusual gracias a la región de la que es nativa. Es capaz de florecer incluso a pesar de la plaga.\""},
[242224] = {name = "Cesta de corazones", additional_info = "Objeto de misión\n[q]\"Probablemente no sea la mejor forma de guardarlos.\""},
[242256] = {name = "Cartera de bombas incendiarias", additional_info = "Objeto de misión\nÚnico\nNecesitas ser de nivel 60\n[q2]Uso: Arroja la bomba incendiaria a una balista cercana. (1 Min Reutilización)"},
[242257] = {name = "Muestra alquímica misteriosa", additional_info = "Objeto de misión"},
[242258] = {name = "Notas de investigación", additional_info = "Objeto de misión\nÚnico\n[q]\"Notas sobre experimentos y datos de pruebas vinculadas con distintas variaciones de plagas que se tomaron de Naxxramas.\"\n[q2]<Click derecho para leer>"},
[242266] = {name = "[q2]Los mil y un resguardos", additional_info = "Se liga al recogerlo\n[q]\"Repleto de la primera hasta la última página con documentación exhaustiva de todo lo relacionado con los resguardos mágicos. Curiosamente, el libro despide un resplandor sutil.\""},
[242267] = {name = "[q2]De arcanista a archimago", additional_info = "Se liga al recogerlo\n[q]\"Una autobiografía de autobombo puro escrita por un autor demasiado irrelevante para ser nombrado. Lo interesante es que el libro además libera un hechizo de búsqueda de atención.\""},
[242268] = {name = "[q2]Si le das un encantamiento a un cruzado", additional_info = "Se liga al recogerlo\n[q]\"Un entretenido cuento que rápidamente desciende a la locura antes de culminar con el antagonista recibiendo todo lo que quiere. Irónicamente, el libro brilla con intensidad y poder.\""},
[242269] = {name = "[q3]Brillantez del gran hechicero", additional_info = "Se liga al recogerlo\nRequiere Encantamiento (280)\n[q2]Uso: Combina 15 polvos de ilusión y 1 orbe recto en una mota de posibilidad en busca de un nuevo descubrimiento."},
