[242310] = {name = "[q3]Mano de la justicia renacida", additional_info = "Se liga al recogerlo\nÚnico-Equipado: [Hand of Justice] (1)\nAbalorio\nNecesitas ser de nivel 60\n[q2]Equipar: Los golpes cuerpo a cuerpo o a distancia tienen un 2% de probabilidad de obtener 1 ataque más. (Probabilidad de que accione: 2%, 2s de reutilización)\n[q2]Equipar: Aumenta 52 p. el poder de ataque."},
[242311] = {name = "[q3]Amuleto de Leonid", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+20 aguante\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 14 p. el índice de defensa."},
[242312] = {name = "[q3]Sello de la familia Barthalomew", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\n+10 intelecto\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 48 p. la sanación realizada y hasta 16 p. el daño que infligen todos los efectos y hechizos mágicos.\n[q2]Equipar: Restaura 5 p. de maná cada 5 s."},
[242313] = {name = "[q3]Diario de los venerados", additional_info = "Se liga al recogerlo\nÚnico\nAbalorio\nNecesitas ser de nivel 60\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 30 p. el daño y la sanación de los hechizos y efectos mágicos.\n[q]\"¿Qué tiene que hacer un pobre no-muerto para llegar a Exaltado?\""},
[242314] = {name = "[q4]Cenicilla del cruzado caído", additional_info = "Santificado\nSe liga al recogerlo\nÚnico\nAbalorio\n[q2]Equipar: Aumenta un 3% tu velocidad de ataque.\n[q2]Equipar: Mejora un 2% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta 24 p. el poder de ataque."},
[242315] = {name = "[q4]Cenizas de arrogancia", additional_info = "Santificado\nSe liga al recogerlo\nÚnico\nAbalorio\n[q2]Equipar: Aumenta un 3% la velocidad de lanzamiento.\n[q2]Equipar: Mejora un 2% tu probabilidad de obtener un golpe crítico con todos tus hechizos y ataques.\n[q2]Equipar: Mejora un 1% tu probabilidad de golpear con todos tus hechizos y ataques.\n[q2]Equipar: Aumenta hasta 14 p. el daño y la sanación de los hechizos y efectos mágicos."},
